--

CREATE FUNCTION public.audit_events_chain() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_prev text;
begin
  perform pg_advisory_xact_lock(hashtext('audit_events_chain'));
  select row_hash into v_prev from audit_events order by seq desc limit 1;
  new.prev_hash := v_prev;
  new.row_hash := audit_row_hash(v_prev, new);
  return new;
end $$;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: audit_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.audit_events (
    seq bigint NOT NULL,
    audit_id uuid DEFAULT gen_random_uuid() NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    actor_type text NOT NULL,
    actor_id text NOT NULL,
    actor_display text,
    on_behalf_of uuid,
    action text NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    business_reference text,
    before_state jsonb,
    after_state jsonb,
    approval_id uuid,
    external_reference text,
    reason text,
    correlation_id uuid,
    workflow_run_id uuid,
    prev_hash text,
    row_hash text DEFAULT ''::text NOT NULL,
    CONSTRAINT audit_events_actor_type_check CHECK ((actor_type = ANY (ARRAY['USER'::text, 'SYSTEM'::text, 'AI'::text, 'INTEGRATION'::text, 'WORKFLOW'::text])))
);

--
-- Name: audit_row_hash(text, public.audit_events); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_row_hash(p_prev text, a public.audit_events) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select encode(sha256(convert_to(
    -- occurred_at rendered in UTC so the hash does not depend on the session time zone
    coalesce(p_prev, '') || '|' || a.audit_id || '|' ||
    to_char(a.occurred_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US') || '|' || a.actor_type || '|' ||
    a.actor_id || '|' || a.action || '|' || a.entity_type || '|' || a.entity_id || '|' ||
    coalesce(a.before_state::text, '') || '|' || coalesce(a.after_state::text, '') || '|' ||
    coalesce(a.approval_id::text, '') || '|' || coalesce(a.external_reference, '') || '|' ||
    coalesce(a.reason, ''), 'UTF8')), 'hex')
$$;

--
-- Name: business_days_between(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_days_between(p_from date, p_to date) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when p_to >= p_from then
    (select count(*)::int from generate_series(p_from + 1, p_to, interval '1 day') d where extract(isodow from d) < 6)
  else
    -(select count(*)::int from generate_series(p_to + 1, p_from, interval '1 day') d where extract(isodow from d) < 6)
  end
$$;

--
-- Name: checklist_apply_change(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checklist_apply_change(p_id uuid, p_item text, p_value text, p_note text, p_actor text, p_event_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p projects; ci project_checklist_items; v_to text; v_emp employees; v_final text;
  v_field text := case p_item when 'COMPLETION_PHOTOS' then 'Completion Photos' when 'COMPLIANCE_CERTIFICATE' then 'Compliance Certificate'
                             when 'SWMS_SIGNED' then 'SWMS Signed' when 'MATERIALS_REVIEWED' then 'Materials Reviewed' else initcap(replace(lower(p_item), '_', ' ')) end;
begin
  -- AC-13B: the project row is locked first, the same lock a project update takes, so a checklist change and a Scheduled -> In
  -- Progress transition on the same job serialise (the gate reads the items the other side has just written).
  select * into p from projects where id = p_id for update;
  v_to := case btrim(coalesce(p_value, '')) when 'To do' then 'OPEN' when 'Done' then 'DONE' when 'Waived' then 'WAIVED' when 'Not applicable' then 'NOT_APPLICABLE' end;
  if v_to is null then return format('"%s" is not a checklist value (use To do, Done, Waived or Not applicable)', coalesce(p_value, 'blank')); end if;
  select * into ci from project_checklist_items where project_id = p_id and item_code = p_item for update;
  if ci.id is null then
    return format('%s has no %s item (not required for this project)', p.project_number, v_field);
  end if;
  if ci.status = v_to then return null; end if;
  if p.status in ('CLOSED', 'CANCELLED') then
    return format('the checklist is locked: %s is %s', p.project_number, lower(sm_label('project', p.status)));
  end if;
  -- AC-13B: the pre-start checklist is the gate into In Progress; once work has started it is history, not editable.
  if ci.stage = 'PRE_START' and (p.actual_start_date is not null or p.status in ('IN_PROGRESS', 'COMPLETED')) then
    return format('the pre-start checklist is locked: work on %s has started (%s)', p.project_number, lower(sm_label('project', p.status)));
  end if;
  select string_agg(invoice_number, ', ') into v_final from invoices where project_id = p_id and invoice_type = 'FINAL' and status <> 'VOIDED';
  if v_final is not null then
    return format('the completion checklist is locked: final invoice %s already exists', v_final);
  end if;
  if exists (select 1 from approvals where entity_id = p_id and action_type = 'CREATE_INVOICE' and status in ('APPROVED', 'EXECUTING')) then
    return 'the completion checklist is locked: the final invoice is being created in Xero right now';
  end if;
  -- AC-13B: a pre-start item may be Done while the job is still Scheduled; every other item keeps the rule it had.
  if v_to = 'DONE' and ci.stage <> 'PRE_START' and p.actual_start_date is null then
    return format('work has not started on %s; a completion item can be Done only once the job is In Progress', p.project_number);
  end if;
  if not state_transition_allowed('checklist_item', ci.status, v_to) then
    return format('%s → %s is not an allowed change; set it back to To do first', checklist_at_label(ci.status), checklist_at_label(v_to));
  end if;
  select e.* into v_emp from employee_external_identities x join employees e on e.id = x.employee_id
   where x.provider = 'AIRTABLE' and x.external_id = p_actor and e.is_active;
  if v_emp.id is null then
    return case when p_actor = 'reconciliation'
      then 'a missed Airtable change has no Airtable user, so it cannot be attributed; set it again in Airtable'
      else format('Airtable user %s is not mapped to a RoofOps employee; checklist changes must be attributable', p_actor) end;
  end if;
  -- AC-13B: some items may never be waived or marked not applicable (business rule; setting checklist.not_waivable).
  if v_to in ('WAIVED', 'NOT_APPLICABLE') and p_item = any (string_to_array(replace(coalesce((select value from app_settings where key = 'checklist.not_waivable'), ''), ' ', ''), ',')) then
    return format('%s cannot be waived or marked not applicable; it must be Done', v_field);
  end if;
  if v_to in ('WAIVED', 'NOT_APPLICABLE') and p_note is null then
    return format('%s needs a reason in %s Note', checklist_at_label(v_to), v_field);
  end if;
  update project_checklist_items set status = v_to,
    completed_on = case when v_to = 'DONE' then app_today() end,
    completed_by = case when v_to = 'DONE' then v_emp.id end,
    waived_reason = case when v_to in ('WAIVED', 'NOT_APPLICABLE') then p_note end
  where id = ci.id;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
  values ('USER', p_actor, 'project.checklist.changed', 'project', p_id, p.project_number,
          jsonb_build_object('item', p_item, 'status', ci.status),
          jsonb_build_object('item', p_item, 'status', v_to, 'employee', v_emp.employee_code, 'reason', p_note),
          coalesce(p_note, v_field || ' set to ' || checklist_at_label(v_to) || ' in Airtable') || ' [' || p_event_key || ']');
  return null;
end $$;

--
-- Name: checklist_apply_note(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checklist_apply_note(p_id uuid, p_item text, p_note text, p_actor text, p_event_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p projects; ci project_checklist_items; v_emp employees; v_final text; v_refuse text;
  v_field text := case p_item when 'COMPLETION_PHOTOS' then 'Completion Photos Note' when 'COMPLIANCE_CERTIFICATE' then 'Compliance Certificate Note'
                              when 'SWMS_SIGNED' then 'SWMS Signed Note' when 'MATERIALS_REVIEWED' then 'Materials Reviewed Note' end;
begin
  -- The same lock order as checklist_apply_change: the project row, then the item.
  select * into p from projects where id = p_id for update;
  select * into ci from project_checklist_items where project_id = p_id and item_code = p_item for update;
  if ci.id is null or ci.status not in ('WAIVED', 'NOT_APPLICABLE') or p_note is not distinct from ci.waived_reason then
    return jsonb_build_object('status', 'IGNORED');
  end if;
  if p.status in ('CLOSED', 'CANCELLED') then
    v_refuse := format('the checklist is locked: %s is %s', p.project_number, lower(sm_label('project', p.status)));
  elsif ci.stage = 'PRE_START' and (p.actual_start_date is not null or p.status in ('IN_PROGRESS', 'COMPLETED')) then
    v_refuse := format('the pre-start checklist is locked: work on %s has started (%s)', p.project_number, lower(sm_label('project', p.status)));
  else
    select string_agg(invoice_number, ', ') into v_final from invoices where project_id = p_id and invoice_type = 'FINAL' and status <> 'VOIDED';
    if v_final is not null then
      v_refuse := format('the completion checklist is locked: final invoice %s already exists', v_final);
    elsif exists (select 1 from approvals where entity_id = p_id and action_type = 'CREATE_INVOICE' and status in ('APPROVED', 'EXECUTING')) then
      v_refuse := 'the completion checklist is locked: the final invoice is being created in Xero right now';
    elsif p_note is null then
      v_refuse := format('%s needs a reason in %s', checklist_at_label(ci.status), v_field);
    else
      select e.* into v_emp from employee_external_identities x join employees e on e.id = x.employee_id
       where x.provider = 'AIRTABLE' and x.external_id = p_actor and e.is_active;
      if v_emp.id is null then
        v_refuse := format('Airtable user %s is not mapped to a RoofOps employee; checklist changes must be attributable', p_actor);
      end if;
    end if;
  end if;
  if v_refuse is not null then
    return jsonb_build_object('status', 'REJECTED', 'field', v_field, 'attempted', p_note, 'kept', ci.waived_reason, 'reason', v_refuse);
  end if;
  update project_checklist_items set waived_reason = p_note where id = ci.id;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
  values ('USER', p_actor, 'project.checklist.changed', 'project', p_id, p.project_number,
          jsonb_build_object('item', p_item, 'status', ci.status, 'reason', ci.waived_reason),
          jsonb_build_object('item', p_item, 'status', ci.status, 'employee', v_emp.employee_code, 'reason', p_note),
          p_note || ' [' || p_event_key || ']');
  return jsonb_build_object('status', 'APPLIED', 'field', v_field, 'from', ci.waived_reason, 'to', p_note);
end $$;

--
-- Name: checklist_at_label(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checklist_at_label(p_status text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p_status when 'OPEN' then 'To do' when 'DONE' then 'Done' when 'WAIVED' then 'Waived' when 'NOT_APPLICABLE' then 'Not applicable' end
$$;

--
-- Name: customer_lookalikes(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_lookalikes(p_name text, p_email text, p_phone text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('customer_number', c.customer_number, 'display_name', c.display_name,
           'reasons', to_jsonb(array_remove(array[
             case when nullif(regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g'), '') = c.phone_normalised then 'same phone' end,
             case when lower(btrim(coalesce(p_email, ''))) <> '' and lower(btrim(p_email)) = lower(c.email) then 'same email' end,
             case when lower(btrim(coalesce(p_name, ''))) = lower(c.display_name) then 'same name' end], null)))
           order by c.customer_number), '[]'::jsonb)
    from customers c
   where c.status = 'ACTIVE'
     and (nullif(regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g'), '') = c.phone_normalised
          or (lower(btrim(coalesce(p_email, ''))) <> '' and lower(btrim(p_email)) = lower(c.email))
          or lower(btrim(coalesce(p_name, ''))) = lower(c.display_name))
$$;

--
-- Name: derive_invoice_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derive_invoice_totals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v numeric; s record;
begin
  select coalesce(sum(line_amount), 0) into v from invoice_lines where invoice_id = new.id;
  s := gst_split(v, new.line_amount_type, new.gst_rate);
  new.subtotal_ex_gst := s.subtotal_ex_gst; new.gst_amount := s.gst_amount; new.total_inc_gst := s.total_inc_gst;
  return new;
end $$;

--
-- Name: derive_purchase_order_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derive_purchase_order_totals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v numeric; s record;
begin
  select coalesce(sum(line_amount), 0) into v from purchase_order_lines where purchase_order_id = new.id;
  s := gst_split(v, new.line_amount_type, new.gst_rate);
  new.subtotal_ex_gst := s.subtotal_ex_gst; new.gst_amount := s.gst_amount; new.total_inc_gst := s.total_inc_gst;
  return new;
end $$;

--
-- Name: derive_quote_version_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derive_quote_version_totals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v numeric; s record;
begin
  select coalesce(sum(line_amount), 0) into v from quote_version_lines where quote_version_id = new.id;
  s := gst_split(v, new.line_amount_type, new.gst_rate);
  new.subtotal_ex_gst := s.subtotal_ex_gst; new.gst_amount := s.gst_amount; new.total_inc_gst := s.total_inc_gst;
  return new;
end $$;

--
-- Name: drive_error_reason(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.drive_error_reason(p_body jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(p_body #>> '{error,errors,0,reason}',
                  (select d ->> 'reason' from jsonb_array_elements(case when jsonb_typeof(p_body #> '{error,details}') = 'array' then p_body #> '{error,details}' else '[]'::jsonb end) d
                    where d ->> '@type' like '%ErrorInfo' limit 1))
$$;

--
-- Name: enforce_state_machine(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_state_machine() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_from text := to_jsonb(old) ->> tg_argv[1]; v_to text := to_jsonb(new) ->> tg_argv[1]; v_reason text;
begin
  if v_from is distinct from v_to then
    if not state_transition_allowed(tg_argv[0], v_from, v_to) then
      raise exception 'state machine check failed: illegal % transition % -> %', tg_argv[0], v_from, v_to using errcode = 'check_violation';
    end if;
    if tg_argv[0] = 'project' then
      v_reason := project_transition_guard(old, v_to);
      if v_reason is not null then
        raise exception 'state machine check failed: project % -> % refused: %', v_from, v_to, v_reason using errcode = 'check_violation';
      end if;
    end if;
  end if;
  return new;
end $$;

--
-- Name: gst_line_tax(jsonb, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_line_tax(p_lines jsonb, p_gst numeric, p_rate numeric DEFAULT 0.1) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare v_count int := jsonb_array_length(coalesce(p_lines, '[]'::jsonb)); v_cents int; v_out jsonb;
begin
  if v_count = 0 then return '[]'::jsonb; end if;
  with l as (
    select e.value v, e.ordinality n,
           round((e.value ->> 'quantity')::numeric * (e.value ->> 'unit_amount')::numeric, 2) * p_rate / (1 + p_rate) exact
      from jsonb_array_elements(p_lines) with ordinality e
  ), b as (select v, n, exact, floor(exact * 100) / 100 base from l)
  select round((p_gst - sum(base)) * 100)::int into v_cents from b;
  if v_cents < 0 or v_cents > v_count then
    raise exception 'GST % cannot be split over % line(s) within a cent each (% cents left over)', p_gst, v_count, v_cents using errcode = 'check_violation';
  end if;
  with l as (
    select e.value v, e.ordinality n,
           round((e.value ->> 'quantity')::numeric * (e.value ->> 'unit_amount')::numeric, 2) * p_rate / (1 + p_rate) exact
      from jsonb_array_elements(p_lines) with ordinality e
  ), b as (select v, n, exact, floor(exact * 100) / 100 base from l),
  r as (select v, n, base, row_number() over (order by exact - base desc, n) rk from b)
  select jsonb_agg(v || jsonb_build_object('tax_amount', round(base + case when rk <= v_cents then 0.01 else 0 end, 2)) order by n) into v_out from r;
  return v_out;
end $$;

--
-- Name: gst_split(numeric, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_split(p_lines numeric, p_type text, p_rate numeric, OUT subtotal_ex_gst numeric, OUT gst_amount numeric, OUT total_inc_gst numeric) RETURNS record
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_type when 'INCLUSIVE' then p_lines - round(p_lines * p_rate / (1 + p_rate), 2) else p_lines end,
         case p_type when 'EXCLUSIVE' then round(p_lines * p_rate, 2)
                     when 'INCLUSIVE' then round(p_lines * p_rate / (1 + p_rate), 2) else 0 end,
         case p_type when 'EXCLUSIVE' then p_lines + round(p_lines * p_rate, 2) else p_lines end
$$;

--
-- Name: integrity_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.integrity_check() RETURNS TABLE(entity text, check_key text, status text, failing integer, detail text, refs text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_refs text[]; v_mode text; v_override text;
begin
  return query select c.* from integrity_check_before_release_blockers() c where c.check_key <> 'done_has_proof';

  -- done_has_proof, now failing closed: a DONE side effect whose topic has no rule here is a FAIL, not a pass.
  select array_agg(o.topic || ':' || coalesce(o.payload ->> 'invoice_number', o.payload ->> 'quote_number', o.payload ->> 'project_number', o.aggregate_id::text))
    into v_refs from outbox o
   where o.status = 'DONE' and not case o.topic
     when 'drive.ensure_project_folder' then exists (select 1 from external_links l where l.provider = 'GOOGLE_DRIVE' and l.entity_type = 'project'
                                                       and l.external_type = 'Folder' and l.entity_id = o.aggregate_id and l.verified_at is not null)
     when 'airtable.project_writeback' then exists (select 1 from external_links l where l.provider = 'AIRTABLE' and l.entity_type = 'project'
                                                      and l.external_type = 'Record' and l.entity_id = o.aggregate_id and l.verified_at is not null)
     when 'xero.create_draft_invoice' then o.id <> (select c.id from outbox_current('xero.create_draft_invoice', o.aggregate_id) c)
                                          or exists (select 1 from invoices i where i.id = o.aggregate_id and i.sync_status = 'SYNCED')
     when 'airtable.quote_publish' then (select count(*) from external_links l
                                          where l.provider = 'AIRTABLE' and l.external_type = 'Record' and l.verified_at is not null
                                            and ((l.entity_type = 'quote' and l.entity_id = o.aggregate_id)
                                              or (l.entity_type = 'customer' and l.entity_id::text = o.payload ->> 'customer_id')
                                              or (l.entity_type = 'property' and l.entity_id::text = o.payload ->> 'property_id'))) = 3
     else false end;
  entity := 'side_effect'; check_key := 'done_has_proof';
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Every DONE side effect has verified proof (Drive folder, Airtable project or quote/customer/property records, Xero draft for its current generation); a topic without a rule fails'; return next;

  -- A worker claimed it and never reported back (crashed or cut off): nothing else re-drives Drive/Airtable writes.
  select array_agg(o.topic || ':' || coalesce(o.payload ->> 'invoice_number', o.payload ->> 'quote_number', o.payload ->> 'project_number', o.aggregate_id::text) order by o.locked_until)
    into v_refs from outbox o where o.status = 'DISPATCHING' and o.locked_until < now() - interval '15 minutes';
  entity := 'side_effect'; check_key := 'claimed_and_abandoned';
  status := case when v_refs is null then 'PASS' else 'WARNING' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Side effects claimed by a worker whose lease ran out more than 15 minutes ago without a result; re-drive or investigate them'; return next;

  select upper(btrim(coalesce(value, 'REAL'))) into v_mode from app_settings where key = 'business_date_mode';
  v_mode := coalesce(v_mode, 'REAL');
  select btrim(coalesce(value, '')) into v_override from app_settings where key = 'business_date_override';
  entity := 'settings'; check_key := 'business_date';
  if v_mode = 'SYNTHETIC' then
    status := 'WARNING'; failing := 1; refs := array['synthetic ' || coalesce(v_override, '?'), 'real ' || app_date_at(now())::text];
    detail := 'The business date is SYNTHETIC: invoices, quotes, tasks and overdue rules use the configured demo date, not today';
  elsif coalesce(v_override, '') <> '' then
    status := 'WARNING'; failing := 1; refs := array['ignored override ' || v_override];
    detail := 'business_date_override is set but business_date_mode is REAL, so it is ignored; clear it to avoid confusion';
  else
    status := 'PASS'; failing := 0; refs := null;
    detail := 'The business date is the real date in Brisbane';
  end if;
  return next;

  -- AC-13B: a job that has started passed the pre-start gate.
  select array_agg(x.project_number || ' (' || x.items || ')' order by x.project_number) into v_refs
    from (select p.project_number, string_agg(ci.label, ', ' order by ci.sort_order) items from projects p join project_checklist_items ci on ci.project_id = p.id
           where (p.actual_start_date is not null or p.status in ('IN_PROGRESS', 'COMPLETED', 'CLOSED')) and ci.stage = 'PRE_START' and ci.is_required
             and ci.status not in ('DONE', 'WAIVED', 'NOT_APPLICABLE') group by p.project_number) x;
  entity := 'project'; check_key := 'started_with_pre_start_open';
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'No started job has a required pre-start item (SWMS signed, materials reviewed) still open'; return next;

  -- AC-15: a cancelled job is never fully billed (its bills would be a receivable on a cancelled job).
  select array_agg(p.project_number || ' (billed ' || (x.b ->> 'billed') || ' of ' || (x.b ->> 'entitlement') || ')' order by p.project_number) into v_refs
    from projects p cross join lateral (select project_billing(p.id) b) x
   where p.status = 'CANCELLED' and (x.b ->> 'billed')::numeric > 0 and (x.b ->> 'remaining')::numeric <= 0;
  entity := 'project'; check_key := 'cancelled_job_fully_billed';
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'No cancelled job is fully billed (a fully billed job is not cancelled, whatever its invoices are typed)'; return next;

  -- A cancelled or closed job holds no crew: none of its site visits is still booked.
  select array_agg(j.job_number || ' (' || p.project_number || ', ' || lower(replace(j.status, '_', ' ')) || ')' order by j.job_number) into v_refs
    from jobs j join projects p on p.id = j.project_id
   where p.status in ('CANCELLED', 'CLOSED') and j.status in ('SCHEDULED', 'WEATHER_DELAYED');
  entity := 'job'; check_key := 'closed_job_has_booked_visit';
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'No cancelled or closed job still has a booked site visit (its crew would stay held)'; return next;
end $$;

--
-- Name: integrity_check_before_release_blockers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.integrity_check_before_release_blockers() RETURNS TABLE(entity text, check_key text, status text, failing integer, detail text, refs text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_refs text[];
begin
  return query select c.* from integrity_check_core() c where c.check_key not in ('done_has_proof', 'xero_link_only_when_synced');
  -- P2-H1: an invoice brought back from VOIDED on a reissue approval carries the generation that approval queued.
  select array_agg(i.invoice_number || ' (' || a.approval_number || ' ' || lower(a.status) || ')' order by i.invoice_number) into v_refs
    from invoices i join approvals a on a.id = i.approval_id and a.action_type = 'REISSUE_INVOICE'
   where i.status <> 'VOIDED'
     and not (a.status = 'EXECUTED'
              and exists (select 1 from invoice_xero_draft_generations g join outbox o on o.idempotency_key = g.outbox_idempotency_key
                           where g.invoice_id = i.id and g.approval_id = a.id and g.generation >= 2
                             and o.topic = 'xero.create_draft_invoice' and o.aggregate_id = i.id and o.generation = g.generation
                             and o.payload ->> 'approval_number' = a.approval_number
                             and o.payload @> (a.action_payload -> 'draft') and o.payload ->> 'reissue_preview_hash' = a.payload_hash));
  entity := 'invoice'; check_key := 'reissue_transition_bound';
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'An invoice reissued from VOIDED is bound to an executed reissue approval and the generation it queued, whose payload is exactly the approved draft (only ops_reissue_decide reissues)'; return next;
  select array_agg(i.invoice_number order by i.invoice_number) into v_refs from invoices i
    left join outbox o on o.topic = 'xero.create_draft_invoice' and o.aggregate_id = i.id
   where i.status = 'VOIDED' and i.record_origin = 'ROOFOPS'
     and (i.sync_status in ('PENDING', 'UNKNOWN', 'SYNCED') or o.status in ('DISPATCHING', 'DONE')
          or exists (select 1 from external_links l where l.provider = 'XERO' and l.external_type = 'Invoice' and l.entity_id = i.id))
     and not exists (select 1 from xero_invoice_observations x
                      where x.invoice_id = i.id and x.verdict = 'VERIFIED' and x.settlement in ('VOIDED', 'DELETED')
                        and x.tenant_id = o.payload ->> 'xero_tenant_id'
                        and x.xero_invoice_id = (select l.external_id from external_links l where l.provider = 'XERO' and l.external_type = 'Invoice' and l.entity_id = i.id)
                        and not exists (select 1 from xero_invoice_observations y
                                         where y.invoice_id = x.invoice_id and y.verdict = 'VERIFIED' and y.xero_invoice_id = x.xero_invoice_id
                                           and y.settlement not in ('VOIDED', 'DELETED') and (y.observed_at, y.id) > (x.observed_at, x.id)));
  entity := 'invoice'; check_key := 'voided_invoice_has_no_xero_write';
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'No Xero draft is created, pending, ambiguous or linked for a voided invoice, unless the exact linked Xero invoice was verified VOIDED or DELETED in the tenant its write is bound to'; return next;
  -- AC-09: once a final invoice exists, everything validly billed equals the entitlement (short = under-billed).
  select array_agg(x.project_number || ' (' || (x.b ->> 'remaining') || ' left)' order by x.project_number) into v_refs
    from (select p.project_number, project_billing(p.id) b from projects p
           where exists (select 1 from invoices i where i.project_id = p.id and i.invoice_type = 'FINAL' and i.status not in ('VOIDED', 'DRAFT', 'PENDING_APPROVAL'))) x
   where (x.b ->> 'remaining')::numeric > 0;
  entity := 'invoice'; check_key := 'final_invoice_settles_entitlement';
  status := case when v_refs is null then 'PASS' else 'WARNING' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'After the final invoice, quote + approved/invoiced variations - everything billed = 0 (left over means under-billed; a variation approved later needs its own invoice)'; return next;
  -- AC-13A: a CLOSED project is settled: nothing left to bill, nothing over-billed, everything paid, completion gate satisfied.
  select array_agg(p.project_number order by p.project_number) into v_refs from projects p
   where p.status = 'CLOSED' and ((project_billing(p.id) ->> 'remaining')::numeric <> 0
      or exists (select 1 from invoices i where i.project_id = p.id and not (invoice_financial_state(i.id, false) ->> 'settled')::boolean)
      or exists (select 1 from v_projects_missing_completion_docs v where v.id = p.id));
  entity := 'project'; check_key := 'closed_project_settled';
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Closed projects have nothing left to bill, nothing over-billed, every invoice paid or voided, and their completion items done or waived'; return next;
  -- AC-13A: completed jobs held only by open completion items (staff set them in Airtable: Completion Photos / Compliance Certificate).
  select array_agg(x.project_number || ' (' || x.items || ')' order by x.project_number) into v_refs
    from (select v.project_number, string_agg(v.label, ', ' order by v.label) items from v_projects_missing_completion_docs v join projects p on p.id = v.id
           where p.status = 'COMPLETED' group by v.project_number) x;
  entity := 'project'; check_key := 'completed_awaiting_completion_items';
  status := case when v_refs is null then 'PASS' else 'WARNING' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Completed jobs whose completion items are still To do in Airtable (Completion Photos / Compliance Certificate); no final invoice until they are Done, Waived or Not applicable'; return next;
  -- AC-14: every Xero-linked invoice was last read successfully, and RoofOps shows the state Xero verified.
  select array_agg(i.invoice_number || ' (' || case when x.id is null then 'never read from Xero'
                                                   when x.verdict <> 'VERIFIED' then 'last Xero check: ' || lower(replace(x.verdict, '_', ' '))
                                                   else 'Xero ' || lower(replace(x.settlement, '_', ' ')) || ', RoofOps ' || lower(i.status) end || ')' order by i.invoice_number) into v_refs
    from invoices i join external_links l on l.provider = 'XERO' and l.external_type = 'Invoice' and l.entity_id = i.id and l.verified_at is not null
    left join lateral (select * from xero_invoice_observations o where o.invoice_id = i.id and o.xero_invoice_id = l.external_id
                        order by o.observed_at desc, o.id desc limit 1) x on true
   where i.sync_status = 'SYNCED' and (x.id is null or x.verdict <> 'VERIFIED' or i.status is distinct from xero_settlement_status(x.settlement));
  entity := 'invoice'; check_key := 'xero_invoice_state_verified';
  status := case when v_refs is null then 'PASS' else 'WARNING' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Every Xero-linked invoice was last read from its own Xero tenant and RoofOps shows the state Xero verified (a repair run applies it)'; return next;
  -- AC-04, generation-aware (see above): the link must match the invoice's sync state, except that a superseded
  -- generation's document may stay linked while its replacement is queued - that link is history.
  select array_agg(i.invoice_number order by i.invoice_number) into v_refs
    from invoices i join external_links l on l.provider = 'XERO' and l.external_type = 'Invoice' and l.entity_id = i.id
   where i.sync_status <> 'SYNCED'
     and not exists (select 1 from invoice_xero_draft_generations g
                      where g.invoice_id = i.id and g.superseded_at is not null and g.xero_invoice_id = l.external_id);
  entity := 'invoice'; check_key := 'xero_link_only_when_synced';
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'No Xero link on an invoice RoofOps does not consider synced (the document of a superseded generation is history, not the current link)'; return next;
  -- done_has_proof, generation-aware (see above): the same rule for every topic, except that only the CURRENT draft
  -- write of an invoice must match its sync_status; an earlier DONE generation is history.
  select array_agg(o.topic || ':' || o.aggregate_id) into v_refs from outbox o
   where o.status = 'DONE' and not case o.topic
     when 'drive.ensure_project_folder' then exists (select 1 from external_links l where l.provider = 'GOOGLE_DRIVE' and l.entity_type = 'project'
                                                       and l.external_type = 'Folder' and l.entity_id = o.aggregate_id and l.verified_at is not null)
     when 'airtable.project_writeback' then exists (select 1 from external_links l where l.provider = 'AIRTABLE' and l.entity_type = 'project'
                                                      and l.external_type = 'Record' and l.entity_id = o.aggregate_id and l.verified_at is not null)
     when 'xero.create_draft_invoice' then o.id <> (select c.id from outbox_current('xero.create_draft_invoice', o.aggregate_id) c)
                                          or exists (select 1 from invoices i where i.id = o.aggregate_id and i.sync_status = 'SYNCED')
     else true end;
  entity := 'side_effect'; check_key := 'done_has_proof';
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Every DONE side effect (Drive folder, Airtable write-back, Xero draft) has verified proof; for a Xero draft that means its CURRENT generation is the one that is DONE'; return next;
end $$;

--
-- Name: integrity_check_core(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.integrity_check_core() RETURNS TABLE(entity text, check_key text, status text, failing integer, detail text, refs text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_refs text[]; v_n bigint;
begin
  entity := 'project'; check_key := 'cancelled_never_ready_to_invoice';
  select array_agg(d.project_number order by d.project_number) into v_refs from v_dashboard_projects d
   where d.status in ('CANCELLED', 'CLOSED') and d.invoice_status in ('READY_TO_INVOICE', 'AWAITING_APPROVAL');
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'A cancelled or closed project is never ready to invoice and has no invoice awaiting approval'; return next;

  check_key := 'only_completed_can_be_prepared';
  select array_agg(p.project_number order by p.project_number) into v_refs from projects p
   where p.status <> 'COMPLETED' and (invoice_final_preview(p.id) ->> 'ok')::boolean;
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Only a COMPLETED project yields an invoice preview (cancelled ones cannot be prepared)'; return next;

  check_key := 'completed_has_finish_date';
  select array_agg(p.project_number order by p.project_number) into v_refs from projects p
   where p.status in ('COMPLETED', 'CLOSED') and p.actual_completion_date is null;
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Completed/closed projects have an actual completion date'; return next;

  check_key := 'started_has_start_date';
  select array_agg(p.project_number order by p.project_number) into v_refs from projects p
   where p.status in ('IN_PROGRESS', 'COMPLETED', 'CLOSED') and p.actual_start_date is null;
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Started projects have an actual start date'; return next;

  check_key := 'reason_recorded';
  select array_agg(p.project_number order by p.project_number) into v_refs from projects p
   where (p.status = 'CANCELLED' and p.cancellation_reason is null) or (p.status = 'ON_HOLD' and p.on_hold_reason is null);
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Cancelled / on-hold projects carry a reason'; return next;

  check_key := 'created_from_accepted_quote';
  select array_agg(p.project_number order by p.project_number) into v_refs from projects p join quotes q on q.id = p.quote_id where q.status <> 'ACCEPTED';
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Every project comes from an ACCEPTED quote'; return next;

  check_key := 'cancelled_has_no_open_work';
  select array_agg(distinct p.project_number) into v_refs from projects p
   where p.status = 'CANCELLED' and (exists (select 1 from tasks t where t.project_id = p.id and t.status in ('OPEN', 'IN_PROGRESS'))
      or exists (select 1 from approvals a where a.entity_id = p.id and a.action_type = 'CREATE_INVOICE' and a.status in ('PENDING', 'APPROVED')));
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'A cancelled project has no open tasks and no pending invoice approval'; return next;

  check_key := 'cancelled_open_purchase_orders';
  select array_agg(distinct p.project_number) into v_refs from projects p join purchase_orders po on po.project_id = p.id
   where p.status = 'CANCELLED' and po.status in ('APPROVED', 'SENT', 'ACKNOWLEDGED', 'PARTIALLY_DELIVERED');
  status := case when v_refs is null then 'PASS' else 'WARNING' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Cancelled projects with supplier orders still open (cancel or re-assign them)'; return next;

  check_key := 'dashboard_status_is_canonical';
  select array_agg(d.project_number) into v_refs from v_dashboard_projects d join projects p on p.id = d.id where d.status is distinct from p.status;
  select count(*) into v_n from projects p where not exists (select 1 from v_dashboard_projects d where d.id = p.id);
  status := case when v_refs is null and v_n = 0 then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0) + v_n::int; refs := v_refs;
  detail := 'Dashboard status is read from canonical projects.status for every project'; return next;

  entity := 'quote'; check_key := 'accepted_at_most_one_project';
  select array_agg(q.quote_number) into v_refs from quotes q where (select count(*) from projects p where p.quote_id = q.id) > 1;
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'An accepted quote has at most one project'; return next;

  check_key := 'accepted_has_project';
  select array_agg(q.quote_number order by q.quote_number) into v_refs from quotes q
   where q.status = 'ACCEPTED' and not exists (select 1 from projects p where p.quote_id = q.id);
  status := case when v_refs is null then 'PASS' else 'WARNING' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Accepted quotes without a project (acceptance not yet processed)'; return next;

  entity := 'invoice'; check_key := 'one_final_per_project';
  select array_agg(p.project_number) into v_refs from projects p
   where (select count(*) from invoices i where i.project_id = p.id and i.invoice_type = 'FINAL' and i.status <> 'VOIDED') > 1;
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'At most one non-void FINAL invoice per project'; return next;

  check_key := 'xero_synced_has_verified_link';
  select array_agg(i.invoice_number) into v_refs from invoices i where i.sync_status = 'SYNCED'
     and not exists (select 1 from external_links l where l.provider = 'XERO' and l.external_type = 'Invoice' and l.entity_id = i.id and l.verified_at is not null);
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Xero sync DONE only with a read-back-verified Xero invoice link'; return next;

  check_key := 'xero_link_only_when_synced';
  select array_agg(i.invoice_number) into v_refs from invoices i join external_links l on l.provider = 'XERO' and l.external_type = 'Invoice' and l.entity_id = i.id
   where i.sync_status <> 'SYNCED';
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'No Xero link on an invoice RoofOps does not consider synced'; return next;

  check_key := 'xero_synced_approval_executed';
  select array_agg(i.invoice_number) into v_refs from invoices i left join approvals a on a.id = i.approval_id
   where i.record_origin = 'ROOFOPS' and i.sync_status = 'SYNCED' and a.status is distinct from 'EXECUTED';
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Every invoice in Xero came from an EXECUTED human approval'; return next;

  entity := 'approval'; check_key := 'executed_by_valid_approver';
  select array_agg(a.approval_number) into v_refs from approvals a left join employees e on e.id = a.decided_by
   where a.status in ('EXECUTING', 'EXECUTED', 'EXECUTION_FAILED', 'APPROVED') and a.action_type = 'CREATE_INVOICE'
     and (e.id is null or not (e.role = any (string_to_array((select value from app_settings where key = 'invoice.approver_roles'), ','))));
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Approved/executed invoice approvals were decided by an authorised approver'; return next;

  check_key := 'pending_preview_current';
  select array_agg(a.approval_number) into v_refs from approvals a
   cross join lateral (select invoice_final_preview(a.entity_id) as x) pv
   where a.status = 'PENDING' and a.action_type = 'CREATE_INVOICE' and a.expires_at > now()
     and (case when (pv.x ->> 'ok')::boolean then invoice_preview_hash(pv.x -> 'preview') end) is distinct from a.payload_hash;
  status := case when v_refs is null then 'PASS' else 'WARNING' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Pending previews still match the invoice RoofOps would create (a stale one is refused at approval)'; return next;

  entity := 'side_effect'; check_key := 'done_has_proof';
  select array_agg(o.topic || ':' || o.aggregate_id) into v_refs from outbox o
   where o.status = 'DONE' and not case o.topic
     when 'drive.ensure_project_folder' then exists (select 1 from external_links l where l.provider = 'GOOGLE_DRIVE' and l.entity_type = 'project'
                                                       and l.external_type = 'Folder' and l.entity_id = o.aggregate_id and l.verified_at is not null)
     when 'airtable.project_writeback' then exists (select 1 from external_links l where l.provider = 'AIRTABLE' and l.entity_type = 'project'
                                                      and l.external_type = 'Record' and l.entity_id = o.aggregate_id and l.verified_at is not null)
     when 'xero.create_draft_invoice' then exists (select 1 from invoices i where i.id = o.aggregate_id and i.sync_status = 'SYNCED')
     else true end;
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Every DONE side effect (Drive folder, Airtable write-back, Xero draft) has verified proof'; return next;

  check_key := 'dead_letters';
  select array_agg(o.topic || ':' || o.aggregate_id) into v_refs from outbox o where o.status = 'FAILED' and o.next_attempt_at = 'infinity';
  status := case when v_refs is null then 'PASS' else 'WARNING' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Side effects that stopped after their retry budget (each has an open exception)'; return next;

  entity := 'state_machine'; check_key := 'every_status_is_a_known_state';
  select array_agg(u.x) into v_refs from (
    select 'project:' || t.status as x from projects t where not exists (select 1 from state_machine_states s where s.machine = 'project' and s.state = t.status)
    union all select 'quote:' || t.status from quotes t where not exists (select 1 from state_machine_states s where s.machine = 'quote' and s.state = t.status)
    union all select 'po:' || t.status from purchase_orders t where not exists (select 1 from state_machine_states s where s.machine = 'purchase_order' and s.state = t.status)
    union all select 'invoice:' || t.status from invoices t where not exists (select 1 from state_machine_states s where s.machine = 'invoice' and s.state = t.status)
    union all select 'approval:' || t.status from approvals t where not exists (select 1 from state_machine_states s where s.machine = 'approval' and s.state = t.status)) u;
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Every stored status is a state of its machine'; return next;

  check_key := 'transition_enforcement_installed';
  select array_agg(t.n) into v_refs from unnest(array['projects_state_machine','quotes_state_machine','purchase_orders_state_machine','invoices_state_machine',
      'invoices_sync_state_machine','approvals_state_machine','workflow_exceptions_state_machine','tasks_state_machine','checklist_state_machine',
      'outbox_state_machine']) as t(n)
   where not exists (select 1 from pg_trigger g where g.tgname = t.n and g.tgenabled <> 'D');
  status := case when v_refs is null then 'PASS' else 'FAIL' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'State-machine triggers are installed and enabled'; return next;

  entity := 'audit'; check_key := 'hash_chain_intact';
  v_n := verify_audit_chain();
  status := case when v_n is null then 'PASS' else 'FAIL' end; failing := case when v_n is null then 0 else 1 end;
  refs := case when v_n is null then null else array['seq ' || v_n] end;
  detail := 'The audit trail hash chain verifies end to end'; return next;

  entity := 'airtable'; check_key := 'drift';
  select array_agg(distinct d.business_key || ' ' || d.field || ': Airtable "' || coalesce(d.airtable_value, 'blank') || '" vs RoofOps "'
                   || coalesce(d.canonical_value, 'blank') || '"') into v_refs from v_state_drift d;
  status := case when v_refs is null then 'PASS' else 'WARNING' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Last observed Airtable values match canonical state'; return next;

  check_key := 'every_project_linked';
  select array_agg(p.project_number) into v_refs from projects p
   where not exists (select 1 from external_links l where l.provider = 'AIRTABLE' and l.entity_type = 'project' and l.external_type = 'Record' and l.entity_id = p.id);
  status := case when v_refs is null then 'PASS' else 'WARNING' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Every project has its Airtable record'; return next;

  entity := 'reconciliation'; check_key := 'recent';
  select extract(epoch from now() - max(r.finished_at))::bigint into v_n from reconciliation_runs r where r.status = 'COMPLETED';
  status := case when v_n is null or v_n > 26 * 3600 then 'WARNING' else 'PASS' end; failing := case when status = 'PASS' then 0 else 1 end;
  refs := null; detail := case when v_n is null then 'No reconciliation has completed yet' else format('Last reconciliation finished %s minutes ago', v_n / 60) end;
  return next;

  entity := 'workflow_exception'; check_key := 'open';
  select array_agg(w.exception_number || ' ' || coalesce(w.business_reference, '') order by w.exception_number) into v_refs from workflow_exceptions w
   where w.resolution_status in ('OPEN', 'RETRY_QUEUED');
  status := case when v_refs is null then 'PASS' else 'WARNING' end; failing := coalesce(cardinality(v_refs), 0); refs := v_refs;
  detail := 'Open exceptions waiting for a person'; return next;
end $$;

--
-- Name: invoice_decision_refused(jsonb, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_decision_refused(p_event jsonb, p_worker text, p_project uuid, p_class text, p_message text, p_approval text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare e record; v_exc text; v_prj text := p_event -> 'payload' ->> 'project_number';
begin
  select * into e from wf_invoice_log_event(p_event, p_event ->> 'event_type', p_worker);
  v_exc := wf_open_invoice_rejection(e.event_id, p_project, coalesce((select project_number from projects where id = p_project), v_prj), p_class, p_message);
  update automation_events set status = 'REJECTED', error_class = p_class, metadata = metadata || jsonb_build_object('reason', p_message)
   where event_id = e.event_id;
  return jsonb_strip_nulls(jsonb_build_object('outcome', 'INVALID_STATE', 'error_class', p_class, 'message', p_message, 'exception_number', v_exc,
    'approval_number', p_approval, 'project_number', coalesce((select project_number from projects where id = p_project), v_prj), 'nothing_approved', true));
end $$;

--
-- Name: invoice_final_preview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_final_preview(p_project uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  p projects; c customers; pr properties; qv quote_versions; q quotes;
  v_billed numeric(12,2); v_var numeric(12,2); v_amount numeric(12,2); v_gst numeric(12,2);
  v_blocking text; v_billed_list jsonb; v_lines jsonb; v_rate numeric := 0.1; v_over jsonb; v_bill jsonb; v_unbilled numeric(12,2); v_invoiced numeric(12,2);
  v_today date := app_today(); v_terms int := (select value::int from app_settings where key = 'invoice.payment_terms_days');
  v_inv_prefix text := (select value from app_settings where key = 'xero.invoice_number_prefix');
  v_con_prefix text := (select value from app_settings where key = 'xero.contact_number_prefix');
begin
  select * into p from projects where id = p_project;
  if not found then return jsonb_build_object('ok', false, 'error_class', 'NOT_FOUND', 'message', 'Project does not exist'); end if;
  if p.status <> 'COMPLETED' then
    return jsonb_build_object('ok', false, 'error_class', 'INVALID_STATE',
      'message', format('%s is %s; only a COMPLETED project can be final-invoiced', p.project_number, p.status));
  end if;
  if exists (select 1 from invoices where project_id = p.id and invoice_type = 'FINAL' and status <> 'VOIDED') then
    return jsonb_build_object('ok', false, 'error_class', 'INVALID_STATE', 'already_invoiced', true,
      'message', format('%s already has a final invoice (%s)', p.project_number,
        (select string_agg(invoice_number, ', ') from invoices where project_id = p.id and invoice_type = 'FINAL' and status <> 'VOIDED')));
  end if;
  -- AC-05: one FINAL invoice per project, ever. After a void a person decides how to replace it: never "ready" again.
  if exists (select 1 from invoices where project_id = p.id and invoice_type = 'FINAL' and status = 'VOIDED') then
    return jsonb_build_object('ok', false, 'error_class', 'INVALID_STATE', 'final_voided', true,
      'message', format('%s: final invoice %s was voided (%s); a replacement final invoice needs a person (one final invoice per project)', p.project_number,
        (select string_agg(invoice_number, ', ' order by invoice_number) from invoices where project_id = p.id and invoice_type = 'FINAL' and status = 'VOIDED'),
        (select string_agg(coalesce(voided_reason, 'no reason given'), '; ') from invoices where project_id = p.id and invoice_type = 'FINAL' and status = 'VOIDED')));
  end if;
  select string_agg(invoice_number || ' (' || status || ')', ', ' order by invoice_number) into v_blocking
    from invoices where project_id = p.id and status in ('DRAFT', 'PENDING_APPROVAL');
  if v_blocking is not null then
    return jsonb_build_object('ok', false, 'error_class', 'INVALID_STATE',
      'message', format('%s has unapproved invoices %s; resolve them before the final invoice', p.project_number, v_blocking));
  end if;

  select * into qv from quote_versions where id = p.accepted_quote_version_id;
  select * into q from quotes where id = qv.quote_id;
  if qv.line_amount_type <> 'INCLUSIVE' then
    return jsonb_build_object('ok', false, 'error_class', 'SCHEMA_MISMATCH', 'message', 'accepted quote is not GST-inclusive; not supported yet');
  end if;
  select * into c from customers where id = p.customer_id;
  select * into pr from properties where id = p.property_id;

  -- AC-09: the one billing calculation (entitlement = quote + APPROVED/INVOICED variations; billed = valid invoices).
  v_bill := project_billing(p.id);
  v_billed := (v_bill ->> 'billed')::numeric; v_billed_list := v_bill -> 'billed_invoices';
  v_var := (v_bill ->> 'variations')::numeric; v_unbilled := (v_bill ->> 'approved_variations')::numeric; v_invoiced := (v_bill ->> 'invoiced_variations')::numeric;
  -- AC-08: billed more than quote + approved/invoiced variations is over-billing, never "nothing left to invoice".
  v_over := project_over_billing(p.id);
  if v_over is not null then
    return jsonb_build_object('ok', false, 'error_class', 'ARITHMETIC_MISMATCH', 'over_billed', true, 'over_billed_by', v_over -> 'excess',
      'billed_inc_gst', v_over -> 'billed', 'entitled_inc_gst', v_over -> 'entitled', 'message', v_over ->> 'message');
  end if;
  v_amount := (v_bill ->> 'remaining')::numeric;
  if v_amount <= 0 then
    return jsonb_build_object('ok', false, 'error_class', 'ARITHMETIC_MISMATCH',
      'message', format('%s: quote %s + variations %s - billed %s = %s; nothing left to invoice', p.project_number,
        qv.total_inc_gst, v_var, v_billed, v_amount));
  end if;
  -- AC-13A: the completion gate, satisfied only through Airtable (Completion Photos / Compliance Certificate).
  if exists (select 1 from v_projects_missing_completion_docs v where v.id = p.id) then
    return jsonb_build_object('ok', false, 'error_class', 'MISSING_DOCUMENT',
      'message', format('%s is missing completion documents (%s); set them to Done in Airtable (Completion Photos / Compliance Certificate), or Waived / Not applicable with a reason in the Note, then invoice', p.project_number,
        (select string_agg(label, ', ' order by label) from v_projects_missing_completion_docs v where v.id = p.id)));
  end if;
  v_gst := round(v_amount * v_rate / (1 + v_rate), 2);

  v_lines := jsonb_build_array(jsonb_build_object('line_no', 1,
      'description', format('Final invoice %s: %s roofing works at %s, %s (quote %s v%s, total %s inc GST, %sless %s already invoiced)',
                            p.project_number, initcap(replace(q.job_type, '_', ' ')), pr.address_line1, pr.suburb, q.quote_number, qv.version_number,
                            qv.total_inc_gst, case when v_invoiced <> 0 then format('plus variations already invoiced %s, ', v_invoiced) else '' end, v_billed),
      -- Line 1 + the not-yet-invoiced approved variations = remaining, exactly.
      'quantity', 1, 'unit_amount', v_amount - v_unbilled, 'variation_id', null))
    || coalesce((select jsonb_agg(jsonb_build_object('line_no', 1 + v.rn, 'description', 'Variation ' || v.variation_number || ': ' || v.description,
                                         'quantity', 1, 'unit_amount', v.amount_inc_gst, 'variation_id', v.id) order by v.rn)
       from (select *, row_number() over (order by variation_number) rn from variations where project_id = p.id and status = 'APPROVED') v), '[]'::jsonb);

  -- FIN-GST-01: Xero calculates tax per line. Until n8n 05 sends each line's tax amount (xero.line_tax_amounts = on), a
  -- final with variation lines is stopped here, before any approval or Xero call, instead of failing after the draft exists.
  if jsonb_array_length(v_lines) > 1 and coalesce((select value from app_settings where key = 'xero.line_tax_amounts'), 'off') <> 'on' then
    return jsonb_build_object('ok', false, 'error_class', 'SCHEMA_MISMATCH', 'multi_line', true,
      'message', format('%s: a final invoice with variation lines (%s lines) cannot go to Xero yet (Xero rounds GST per line and the draft could differ by a cent). Create it by hand in Xero, or wait until per-line GST is enabled', p.project_number, jsonb_array_length(v_lines)));
  end if;
  v_lines := gst_line_tax(v_lines, v_gst, v_rate);   -- each line carries its share of the GST; the shares add up to v_gst exactly

  return jsonb_build_object('ok', true, 'preview', jsonb_build_object(
    'project_id', p.id, 'project_number', p.project_number, 'project_record_version', p.record_version,
    'customer_id', c.id, 'customer_number', c.customer_number, 'customer_name', btrim(c.display_name), 'customer_email', c.email,
    'quote_number', q.quote_number, 'quote_version', qv.version_number, 'quote_total_inc_gst', qv.total_inc_gst,
    'approved_variations_inc_gst', v_var, 'billed_to_date_inc_gst', v_billed, 'billed_invoices', v_billed_list,
    'amount_inc_gst', v_amount, 'gst_amount', v_gst, 'amount_ex_gst', v_amount - v_gst, 'currency', 'AUD', 'line_amount_type', 'INCLUSIVE',
    'lines', v_lines, 'invoice_date', v_today, 'due_date', v_today + v_terms,
    'reference', p.project_number,
    'xero_contact_number', v_con_prefix || c.customer_number,
    'xero_contact_name', btrim(c.display_name) || ' [' || c.customer_number || ']',
    'xero_account_code', (select value from app_settings where key = 'xero.sales_account_code'),
    'xero_tax_type', (select value from app_settings where key = 'xero.sales_tax_type'),
    'xero_invoice_number_prefix', v_inv_prefix,
    'xero_tenant_name', (select value from app_settings where key = 'xero.demo_tenant_name')));
end $$;

--
-- Name: invoice_financial_state(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_financial_state(p_invoice uuid, p_fresh boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare i invoices; v_linked text; o xero_invoice_observations; v xero_invoice_observations; v_paid numeric;
  v_age interval := make_interval(hours => coalesce((select value::int from app_settings where key = 'xero.settlement_max_age_hours'), 36));
begin
  select * into i from invoices where id = p_invoice;
  if i.id is null then return jsonb_build_object('settled', false, 'state', 'UNKNOWN', 'reason', 'no such invoice'); end if;
  if i.sync_status in ('PENDING', 'UNKNOWN') then
    return jsonb_build_object('settled', false, 'state', 'XERO_WRITE_OPEN', 'reason', 'its Xero write is still in flight or uncertain');
  end if;
  select external_id into v_linked from external_links where provider = 'XERO' and external_type = 'Invoice' and entity_id = i.id and verified_at is not null;
  if v_linked is null then
    if i.status = 'VOIDED' then return jsonb_build_object('settled', true, 'state', 'VOIDED', 'reason', 'voided'); end if;
    if i.status = 'PAID' and i.record_origin = 'IMPORT' then
      select coalesce(sum(amount), 0) into v_paid from payments where invoice_id = i.id and source = 'IMPORT';
      if v_paid >= i.total_inc_gst then return jsonb_build_object('settled', true, 'state', 'PAID', 'reason', 'paid (imported payments)'); end if;
      return jsonb_build_object('settled', false, 'state', 'UNVERIFIED', 'reason', format('marked paid but its imported payments cover only %s of %s', v_paid, i.total_inc_gst));
    end if;
    if i.status = 'PAID' then
      return jsonb_build_object('settled', false, 'state', 'UNVERIFIED', 'reason', 'marked paid locally but not verified in Xero');
    end if;
    return jsonb_build_object('settled', false, 'state', i.status, 'reason', lower(replace(i.status, '_', ' ')));
  end if;
  select * into o from xero_invoice_observations where invoice_id = i.id and xero_invoice_id = v_linked order by observed_at desc, id desc limit 1;
  if o.id is null then
    return jsonb_build_object('settled', false, 'state', 'UNVERIFIED', 'reason', 'not verified in Xero yet; reconciliation reads it');
  end if;
  if o.verdict <> 'VERIFIED' then
    return jsonb_build_object('settled', false, 'state', 'AMBIGUOUS', 'reason',
      format('the last Xero check failed (%s, %s); RoofOps does not assume it is paid', lower(replace(o.verdict, '_', ' ')), to_char(o.observed_at, 'YYYY-MM-DD HH24:MI')));
  end if;
  if o.settlement in ('PAID', 'VOIDED', 'DELETED') and i.status = xero_settlement_status(o.settlement) then
    if p_fresh and o.observed_at < now() - v_age then
      return jsonb_build_object('settled', false, 'state', 'STALE', 'reason',
        format('Xero verified it %s at %s, older than %s hours; run reconciliation to verify it again', lower(o.settlement), to_char(o.observed_at, 'YYYY-MM-DD HH24:MI'),
               extract(epoch from v_age)::int / 3600));
    end if;
    return jsonb_build_object('settled', true, 'state', o.settlement, 'reason',
      case when o.settlement = 'DELETED' then format('deleted in Xero and voided in RoofOps (verified %s); a replacement invoice has not been raised', to_char(o.observed_at, 'YYYY-MM-DD HH24:MI'))
           else lower(o.settlement) || ' (verified in Xero)' end, 'verified_at', o.observed_at);
  end if;
  return jsonb_build_object('settled', false, 'state', o.settlement, 'reason',
    case o.settlement when 'NOT_ISSUED' then 'not issued in Xero yet'
                      when 'UNPAID' then 'unpaid in Xero'
                      when 'PARTIALLY_PAID' then format('partially paid in Xero, %s still due', o.amount_due)
                      when 'DELETED' then 'deleted in Xero; a person decides'
                      else format('Xero verified %s but RoofOps still shows %s; a repair run applies it', lower(o.settlement), lower(i.status)) end
    || format(' (verified %s)', to_char(o.observed_at, 'YYYY-MM-DD HH24:MI')));
end $$;

--
-- Name: approvals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approvals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    approval_number text NOT NULL,
    action_type text NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    business_reference text,
    requested_by_actor_type text NOT NULL,
    requested_by_employee_id uuid,
    requested_via_invocation_id uuid,
    required_permission text NOT NULL,
    action_payload jsonb NOT NULL,
    payload_hash text NOT NULL,
    expected_record_version integer NOT NULL,
    idempotency_key text NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_reason text,
    expires_at timestamp with time zone NOT NULL,
    executed_at timestamp with time zone,
    execution_result jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    record_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT approvals_action_type_check CHECK ((action_type = ANY (ARRAY['SEND_PURCHASE_ORDER'::text, 'APPROVE_PURCHASE_ORDER'::text, 'CREATE_INVOICE'::text, 'SYNC_INVOICE_TO_XERO'::text, 'CANCEL_PROJECT'::text, 'CHANGE_APPROVED_MATERIALS'::text, 'REISSUE_INVOICE'::text]))),
    CONSTRAINT approvals_check CHECK (((status <> ALL (ARRAY['APPROVED'::text, 'REJECTED'::text, 'EXECUTING'::text, 'EXECUTED'::text, 'EXECUTION_FAILED'::text])) OR ((decided_by IS NOT NULL) AND (decided_at IS NOT NULL)))),
    CONSTRAINT approvals_check1 CHECK (((status <> 'REJECTED'::text) OR (decision_reason IS NOT NULL))),
    CONSTRAINT approvals_check2 CHECK (((status <> ALL (ARRAY['EXECUTED'::text, 'EXECUTION_FAILED'::text])) OR ((executed_at IS NOT NULL) AND (execution_result IS NOT NULL)))),
    CONSTRAINT approvals_check3 CHECK (((requested_by_actor_type <> 'AI'::text) OR (requested_via_invocation_id IS NOT NULL))),
    CONSTRAINT approvals_requested_by_actor_type_check CHECK ((requested_by_actor_type = ANY (ARRAY['USER'::text, 'AI'::text, 'WORKFLOW'::text]))),
    CONSTRAINT approvals_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'APPROVED'::text, 'REJECTED'::text, 'EXPIRED'::text, 'EXECUTING'::text, 'EXECUTED'::text, 'EXECUTION_FAILED'::text, 'CANCELLED'::text])))
);

--
-- Name: invoice_preview_amount_line(public.approvals); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_preview_amount_line(p_approval public.approvals) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  select 'Amount: ' || to_char((p_approval.action_payload ->> 'amount_inc_gst')::numeric, 'FM$999,999,990.00') || ' inc GST'
$_$;

--
-- Name: invoice_preview_hash(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_preview_hash(p_preview jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select encode(sha256(convert_to((p_preview - 'project_record_version')::text, 'UTF8')), 'hex')
$$;

--
-- Name: invoice_preview_marker(public.approvals); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_preview_marker(p_approval public.approvals) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select 'PREVIEW ' || p_approval.approval_number || ' · #' || left(p_approval.payload_hash, 16)
$$;

--
-- Name: invoice_preview_shows(text, public.approvals); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_preview_shows(p_text text, p_approval public.approvals) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(position(invoice_preview_marker(p_approval) in p_text) > 0 and position(invoice_preview_amount_line(p_approval) in p_text) > 0, false)
$$;

--
-- Name: invoice_projection_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_projection_fields() RETURNS TABLE(field_id text, airtable_name text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select airtable_field_id, airtable_name from field_contract
   where entity = 'project' and field_key in ('invoice_status', 'invoice_amount', 'invoice_preview') order by airtable_name
$$;

--
-- Name: invoice_reissue_check(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_reissue_check(p_invoice uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  i invoices; p projects; v_pin text; v_bound text; v_link text; v_last xero_invoice_observations; v_void xero_invoice_observations;
  v_gen int; v_paid numeric; v_credited numeric; v_live int;
begin
  select * into i from invoices where id = p_invoice;
  if i.id is null then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', coalesce(p_invoice::text, 'no invoice') || ' does not exist');
  end if;
  if i.record_origin <> 'ROOFOPS' or i.invoice_type <> 'FINAL'
     or i.idempotency_key is distinct from 'invoice:final:' || i.project_id::text then
    return jsonb_build_object('ok', false, 'code', 'NOT_FINAL_INVOICE',
      'detail', format('%s is not the canonical RoofOps-origin FINAL invoice of its project (%s, %s, key %s); a reissue replaces that one invoice row, never an imported or non-final one',
        i.invoice_number, i.record_origin, i.invoice_type, coalesce(i.idempotency_key, 'none')));
  end if;
  select * into p from projects where id = i.project_id;
  if p.status = 'CLOSED' then
    return jsonb_build_object('ok', false, 'code', 'PROJECT_CLOSED', 'detail', format('%s is CLOSED; a closed project is not reopened by a reissue', p.project_number));
  elsif p.status = 'CANCELLED' then
    return jsonb_build_object('ok', false, 'code', 'PROJECT_CANCELLED', 'detail', format('%s is CANCELLED; nothing is invoiced for it any more', p.project_number));
  elsif p.status <> 'COMPLETED' then
    return jsonb_build_object('ok', false, 'code', 'PROJECT_NOT_COMPLETED', 'detail', format('%s is %s; only a COMPLETED project has a final invoice to reissue', p.project_number, p.status));
  end if;
  v_pin := (select nullif(value, '') from app_settings where key = 'xero.demo_tenant_id');
  if v_pin is null then
    return jsonb_build_object('ok', false, 'code', 'TENANT_NOT_PINNED',
      'detail', 'No Xero Demo Company tenant is pinned (app_settings xero.demo_tenant_id); refusing to queue a Xero write');
  end if;
  v_bound := (select o.payload ->> 'xero_tenant_id' from outbox_current('xero.create_draft_invoice', i.id) o);
  if v_bound is null or v_bound <> v_pin then
    return jsonb_build_object('ok', false, 'code', 'TENANT_MISMATCH',
      'detail', format('%s: the draft write is bound to tenant %s but the pinned tenant is %s; a reissue never writes to another tenant', i.invoice_number, coalesce(v_bound, 'none'), v_pin));
  end if;
  v_link := (select l.external_id from external_links l where l.provider = 'XERO' and l.external_type = 'Invoice'
               and l.entity_type = 'invoice' and l.entity_id = i.id);
  if i.status <> 'VOIDED' then
    return jsonb_build_object('ok', false, 'code', 'INVOICE_NOT_VOIDED',
      'detail', format('%s is %s; only a voided invoice is reissued (a live invoice is settled normally)', i.invoice_number, i.status));
  end if;
  -- Observation semantics: only reads of the exact linked InvoiceID, in the bound tenant, count.
  select * into v_last from xero_invoice_observations x
   where x.invoice_id = i.id and x.xero_invoice_id is not distinct from v_link
   order by x.observed_at desc, x.id desc limit 1;
  select * into v_void from xero_invoice_observations x
   where x.invoice_id = i.id and x.xero_invoice_id is not distinct from v_link and x.verdict = 'VERIFIED'
     and x.settlement in ('VOIDED', 'DELETED')
   order by x.observed_at desc, x.id desc limit 1;
  if v_last.id is not null and v_last.tenant_id is not null and v_last.tenant_id is distinct from v_bound then
    return jsonb_build_object('ok', false, 'code', 'TENANT_MISMATCH',
      'detail', format('%s: the latest read of linked Xero invoice %s came from tenant %s, but the write is bound to %s; that read is not trusted',
        i.invoice_number, v_link, v_last.tenant_id, v_bound));
  end if;
  if v_last.id is not null and v_last.verdict in ('LOOKUP_FAILED', 'MISMATCH', 'INCONSISTENT')
     and (v_void.id is null or (v_last.observed_at, v_last.id) > (v_void.observed_at, v_void.id)) then
    return jsonb_build_object('ok', false, 'code', 'OBSERVATION_AMBIGUOUS',
      'detail', format('%s: the latest read of linked Xero invoice %s is %s and no verified void came after it (%s); a reissue needs a settled void',
        i.invoice_number, coalesce(v_link, 'none'), v_last.verdict, coalesce(v_last.detail, 'no detail')));
  end if;
  if v_void.id is not null and exists (
      select 1 from xero_invoice_observations x where x.invoice_id = i.id and x.xero_invoice_id is not distinct from v_link
        and x.verdict = 'VERIFIED' and x.settlement not in ('VOIDED', 'DELETED')
        and (x.observed_at, x.id) > (v_void.observed_at, v_void.id)) then
    return jsonb_build_object('ok', false, 'code', 'OBSERVATION_CONTRADICTED',
      'detail', format('%s: a later verified read of linked Xero invoice %s says the document is not voided any more; a person must check Xero before a reissue',
        i.invoice_number, v_link));
  end if;
  if v_void.id is null then
    return jsonb_build_object('ok', false, 'code', 'VOID_NOT_VERIFIED',
      'detail', format('%s is voided in RoofOps but no verified Xero read of linked invoice %s says it was voided or deleted%s; a reissue needs that proof',
        i.invoice_number, coalesce(v_link, '(no Xero link)'),
        case when v_link is null then '' else ' (a read of another InvoiceID, or a read that is not void-family, is not proof)' end));
  end if;
  -- Money: any verified payment or credit, here or in Xero, means a person must look before a reissue.
  if exists (select 1 from payments where invoice_id = i.id) then
    return jsonb_build_object('ok', false, 'code', 'PAYMENT_EXISTS',
      'detail', format('%s has %s local payment row(s); money moved on it, so a void or deletion is not a reissue trigger', i.invoice_number,
        (select count(*) from payments where invoice_id = i.id)));
  end if;
  select max(x.amount_paid) into v_paid from xero_invoice_observations x
   where x.invoice_id = i.id and x.verdict = 'VERIFIED' and coalesce(x.amount_paid, 0) > 0;
  if v_paid is not null then
    return jsonb_build_object('ok', false, 'code', 'PAYMENT_EXISTS',
      'detail', format('%s: Xero verified a payment of %s on it; a person must check the customer account before a reissue', i.invoice_number, v_paid));
  end if;
  select max(x.amount_credited) into v_credited from xero_invoice_observations x
   where x.invoice_id = i.id and x.verdict = 'VERIFIED' and coalesce(x.amount_credited, 0) > 0;
  if v_credited is not null then
    return jsonb_build_object('ok', false, 'code', 'CREDIT_EXISTS',
      'detail', format('%s: Xero verified a credit of %s on it; a person must check the customer account before a reissue', i.invoice_number, v_credited));
  end if;
  -- Write state: no live draft write (a queued or retrying one can still create a document) and nothing ambiguous.
  select count(*) into v_live from outbox o
   where o.topic = 'xero.create_draft_invoice' and o.aggregate_id = i.id
     and (o.status in ('PENDING', 'DISPATCHING') or (o.status = 'FAILED' and o.next_attempt_at <> 'infinity'));
  if v_live > 0 then
    return jsonb_build_object('ok', false, 'code', 'WRITE_IN_FLIGHT',
      'detail', format('%s has %s live Xero draft write(s) (%s); a reissue cannot start while a generation may still create a document',
        i.invoice_number, v_live, (select string_agg(o.generation::text || ':' || o.status, ', ' order by o.generation) from outbox o
          where o.topic = 'xero.create_draft_invoice' and o.aggregate_id = i.id
            and (o.status in ('PENDING', 'DISPATCHING') or (o.status = 'FAILED' and o.next_attempt_at <> 'infinity')))));
  end if;
  if i.sync_status = 'UNKNOWN' or exists (select 1 from invoice_xero_draft_generations g where g.invoice_id = i.id and g.status = 'UNKNOWN') then
    return jsonb_build_object('ok', false, 'code', 'PRIOR_WRITE_UNKNOWN',
      'detail', format('%s has an UNKNOWN Xero write (sync %s); settle it with reconciliation before a reissue - nothing is assumed', i.invoice_number, i.sync_status));
  end if;
  -- FIN-GST-01 (FIN-08): the rule invoice_final_preview applies to a new final holds for its reissue too. Xero rounds GST per
  -- line; until n8n 05 sends each line's tax amount (xero.line_tax_amounts = on), a multi-line invoice is not reissued, so a
  -- replacement draft can never differ from RoofOps by a cent after it exists.
  if (select count(*) from invoice_lines l where l.invoice_id = i.id) > 1
     and coalesce((select value from app_settings where key = 'xero.line_tax_amounts'), 'off') <> 'on' then
    return jsonb_build_object('ok', false, 'code', 'MULTI_LINE_GST',
      'detail', format('%s has %s lines: a reissue cannot go to Xero yet (Xero rounds GST per line and the draft could differ by a cent). Create it by hand in Xero, or wait until per-line GST is enabled',
        i.invoice_number, (select count(*) from invoice_lines l where l.invoice_id = i.id)));
  end if;
  v_gen := invoice_reissue_generation(i.id);
  return jsonb_build_object('ok', true, 'invoice_id', i.id, 'invoice_number', i.invoice_number, 'project_id', p.id, 'project_number', p.project_number,
    'linked_xero_invoice_id', v_link, 'bound_tenant_id', v_bound, 'pinned_tenant_id', v_pin,
    'current_generation', v_gen, 'target_generation', v_gen + 1,
    'void_observation_id', v_void.id, 'void_settlement', v_void.settlement, 'invoice_record_version', i.record_version);
end $$;

--
-- Name: invoice_reissue_generation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_reissue_generation(p_invoice uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(coalesce((select max(g.generation) from invoice_xero_draft_generations g where g.invoice_id = p_invoice), 0),
                  coalesce((select max(o.generation) from outbox o
                             where o.topic = 'xero.create_draft_invoice' and o.aggregate_id = p_invoice), 0))
$$;

--
-- Name: invoice_reissue_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_reissue_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  a approvals; v_bound text; v_link text; v_obs xero_invoice_observations; v_target int; v_bound_ok boolean;
begin
  select * into a from approvals where id = new.approval_id;
  -- First the evidence (unchanged): a matching reissue approval that is live, the void proof, no money moved, no live
  -- write of an older generation. Then (audit P2-H1) the binding: only the ops_reissue_decide transaction itself.
  if a.id is null or a.action_type <> 'REISSUE_INVOICE' or a.entity_type <> 'invoice' or a.entity_id <> new.id
     or not (a.status in ('APPROVED', 'EXECUTING') or (a.status = 'PENDING' and a.expires_at > now())) then
    raise exception 'invoice % cannot go back to APPROVED without a matching REISSUE_INVOICE approval attached (a supervised reissue decides that, not raw SQL; only ops_reissue_decide may make this transition)',
      new.invoice_number using errcode = 'check_violation';
  end if;
  v_bound := (select o.payload ->> 'xero_tenant_id' from outbox_current('xero.create_draft_invoice', new.id) o);
  v_link := (select l.external_id from external_links l where l.provider = 'XERO' and l.external_type = 'Invoice'
               and l.entity_type = 'invoice' and l.entity_id = new.id);
  select * into v_obs from xero_invoice_observations x
   where x.invoice_id = new.id and x.xero_invoice_id is not distinct from v_link and x.verdict = 'VERIFIED'
   order by x.observed_at desc, x.id desc limit 1;
  if v_obs.id is null or v_obs.settlement not in ('VOIDED', 'DELETED') or v_obs.tenant_id is distinct from v_bound then
    raise exception 'invoice % cannot go back to APPROVED without a verified void or deletion of its linked Xero invoice % in the bound tenant % (the last verified read is %); raw SQL is not a recovery path',
      new.invoice_number, coalesce(v_link, '(none)'), coalesce(v_bound, '(none)'), coalesce(v_obs.settlement || ' in ' || v_obs.tenant_id, 'none')
      using errcode = 'check_violation';
  end if;
  if exists (select 1 from payments where invoice_id = new.id)
     or exists (select 1 from xero_invoice_observations x where x.invoice_id = new.id and x.verdict = 'VERIFIED'
                  and (coalesce(x.amount_paid, 0) > 0 or coalesce(x.amount_credited, 0) > 0)) then
    raise exception 'invoice % cannot go back to APPROVED: money moved on it (a payment or a credit exists); a person must check the customer account',
      new.invoice_number using errcode = 'check_violation';
  end if;
  -- The reissue opens exactly one new generation in this transaction; that write is the guard's own target (the newest
  -- generation row). A live write of an older generation is still a refusal.
  v_target := (select max(g.generation) from invoice_xero_draft_generations g where g.invoice_id = new.id);
  if exists (select 1 from outbox o where o.topic = 'xero.create_draft_invoice' and o.aggregate_id = new.id
               and (o.status in ('PENDING', 'DISPATCHING') or (o.status = 'FAILED' and o.next_attempt_at <> 'infinity'))
               and o.generation is distinct from v_target) then
    raise exception 'invoice % cannot go back to APPROVED while an older generation''s Xero draft write is still live (target generation %); let it finish or fail first',
      new.invoice_number, coalesce(v_target::text, 'none') using errcode = 'check_violation';
  end if;
  -- P2-H1: a valid request (even a fresh PENDING one) is evidence, not the act. The act is ops_reissue_decide's own
  -- transaction, and only it leaves this exact state behind before its invoice update: the approval EXECUTING and its
  -- one-time consumption claim still PROCESSING, the previous generation SUPERSEDED, and the next generation's ledger
  -- row PENDING with its draft write PENDING, both bound to this approval. Anything else (raw SQL with a pending,
  -- approved, executed or forged approval) is refused, so the transition cannot happen without the replacement.
  v_bound_ok := a.status = 'EXECUTING' and v_target >= 2
    and exists (select 1 from processed_events pe where pe.consumer = 'invoice.reissue:' || a.approval_number
                   and pe.idempotency_key = a.approval_number and pe.status = 'PROCESSING')
    and exists (select 1 from invoice_xero_draft_generations g where g.invoice_id = new.id and g.generation = v_target
                   and g.approval_id = a.id and g.superseded_at is null and g.status = 'PENDING'
                   and g.outbox_idempotency_key = xero_draft_outbox_key(new.id, v_target))
    and exists (select 1 from invoice_xero_draft_generations g where g.invoice_id = new.id and g.generation = v_target - 1 and g.superseded_at is not null)
    and exists (select 1 from outbox o where o.topic = 'xero.create_draft_invoice' and o.aggregate_id = new.id and o.generation = v_target
                   and o.idempotency_key = xero_draft_outbox_key(new.id, v_target) and o.status = 'PENDING'
                   and o.payload ->> 'approval_number' = a.approval_number
                   and o.payload @> (a.action_payload -> 'draft') and o.payload ->> 'reissue_preview_hash' = a.payload_hash);
  if not coalesce(v_bound_ok, false) then
    raise exception 'invoice % cannot go back to APPROVED here: only ops_reissue_decide may make this transition (approval % is %, and generation % must be queued and bound to it in the same decision)',
      new.invoice_number, a.approval_number, a.status, coalesce((v_target + case when a.status = 'EXECUTING' then 0 else 1 end)::text, '2')
      using errcode = 'check_violation';
  end if;
  return new;
end $$;

--
-- Name: invoice_reissue_preview(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_reissue_preview(p_invoice uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  i invoices; p projects; v_link text; v_bound text; v_obs xero_invoice_observations; v_gen int;
begin
  select * into i from invoices where id = p_invoice;
  if i.id is null then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', coalesce(p_invoice::text, 'no invoice') || ' does not exist');
  end if;
  select * into p from projects where id = i.project_id;
  v_link := (select l.external_id from external_links l where l.provider = 'XERO' and l.external_type = 'Invoice'
               and l.entity_type = 'invoice' and l.entity_id = i.id);
  v_bound := (select o.payload ->> 'xero_tenant_id' from outbox_current('xero.create_draft_invoice', i.id) o);
  select * into v_obs from xero_invoice_observations x
   where x.invoice_id = i.id and x.xero_invoice_id is not distinct from v_link and x.verdict = 'VERIFIED'
     and x.settlement in ('VOIDED', 'DELETED')
   order by x.observed_at desc, x.id desc limit 1;
  v_gen := invoice_reissue_generation(i.id);
  return jsonb_build_object('ok', true, 'preview', jsonb_build_object(
    'invoice_id', i.id, 'invoice_number', i.invoice_number,
    'xero_invoice_number', coalesce((select o.payload ->> 'xero_invoice_number' from outbox_current('xero.create_draft_invoice', i.id) o), ''),
    'invoice_type', i.invoice_type, 'record_origin', i.record_origin,
    'invoice_status', i.status, 'invoice_sync_status', i.sync_status, 'voided_reason', i.voided_reason,
    'invoice_record_version', i.record_version,
    'project_id', i.project_id, 'project_number', p.project_number, 'project_status', p.status,
    'total_inc_gst', i.total_inc_gst, 'gst_amount', i.gst_amount,
    'line_count', (select count(*) from invoice_lines l where l.invoice_id = i.id),
    'lines_hash', (select md5(coalesce(string_agg(l.line_no::text || '|' || l.description || '|' || l.quantity::text || '|' || l.unit_price::text,
                                                E'\n' order by l.line_no), '')) from invoice_lines l where l.invoice_id = i.id),
    'linked_xero_invoice_id', v_link,
    'void_evidence', case when v_obs.id is null then null else jsonb_build_object(
      'observation_id', v_obs.id, 'settlement', v_obs.settlement, 'tenant_id', v_obs.tenant_id,
      'observed_at', to_char(v_obs.observed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'), 'run_id', v_obs.run_id) end,
    'current_generation', v_gen, 'target_generation', v_gen + 1,
    'tenant', jsonb_build_object('tenant_id', v_bound, 'tenant_name', (select value from app_settings where key = 'xero.demo_tenant_name')),
    'requested_reason', btrim(coalesce(p_reason, '')),
    -- P2-H2: the exact Xero draft the reissue will queue, generated from canonical truth now (not copied from the
    -- previous generation); the approval's hash covers it, so what is approved is what is written.
    'draft', xero_draft_payload(i.id, v_bound)));
end $$;

--
-- Name: invoice_reissue_preview_hash(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_reissue_preview_hash(p_preview jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select encode(sha256(convert_to((p_preview - 'invoice_record_version')::text, 'UTF8')), 'hex')
$$;

--
-- Name: invoice_void_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_void_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare o outbox; v_live int;
begin
  select * into o from outbox_current('xero.create_draft_invoice', new.id);
  if o.id is null then return new; end if;
  select count(*) into v_live from outbox w where w.topic = 'xero.create_draft_invoice' and w.aggregate_id = new.id
     and (w.status in ('PENDING', 'DISPATCHING') or (w.status = 'FAILED' and w.next_attempt_at <> 'infinity'));
  -- AC-14 / AC-14C / AC-14C B2: voided or deleted in Xero, verified by reconciliation (the linked invoice, in its bound
  -- tenant), and nothing is still writing: RoofOps follows Xero. A deletion with no money movement is the same business
  -- state as a void.
  if v_live = 0 and new.sync_status <> 'UNKNOWN'
     and not exists (select 1 from invoice_xero_draft_generations g where g.invoice_id = new.id and g.status = 'UNKNOWN')
     and exists (select 1 from xero_invoice_observations x
                  where x.id = (select id from xero_invoice_observations where invoice_id = new.id order by observed_at desc, id desc limit 1)
                    and x.verdict = 'VERIFIED' and x.settlement in ('VOIDED', 'DELETED') and x.tenant_id = o.payload ->> 'xero_tenant_id'
                    and x.xero_invoice_id = (select external_id from external_links where provider = 'XERO' and external_type = 'Invoice' and entity_id = new.id)) then
    return new;
  end if;
  if o.status = 'DISPATCHING' then
    raise exception '% cannot be voided: its Xero draft is being created right now. Try again when that has finished', old.invoice_number using errcode = 'check_violation';
  end if;
  -- AC-14C B2: the supervised reissue window - the invoice is APPROVED with a replacement generation queued and the
  -- superseded generation's document still linked. That is a queued write like any other; the replacement must finish
  -- (or fail) before a person can void again.
  if exists (select 1 from invoice_xero_draft_generations g where g.invoice_id = new.id and g.superseded_at is null
               and g.generation > 1 and g.status = 'PENDING') then
    raise exception '% cannot be voided: its Xero draft is queued (replacement generation % not started yet). Let the reissue finish, or void it after the write has failed',
      old.invoice_number, (select max(g.generation) from invoice_xero_draft_generations g where g.invoice_id = new.id and g.superseded_at is null)
      using errcode = 'check_violation';
  end if;
  if old.sync_status = 'SYNCED' or o.status = 'DONE'
     or exists (select 1 from external_links where provider = 'XERO' and external_type = 'Invoice' and entity_id = new.id) then
    raise exception '% cannot be voided: its Xero draft exists (%). Void or delete it in Xero first', old.invoice_number,
      coalesce(o.payload ->> 'xero_invoice_number', 'see the Xero link') using errcode = 'check_violation';
  end if;
  if old.sync_status = 'UNKNOWN' then
    raise exception '% cannot be voided: an earlier attempt may already exist in Xero. Run reconciliation (npm run reconcile) to settle it first', old.invoice_number
      using errcode = 'check_violation';
  end if;
  if o.status = 'PENDING' or (o.status = 'FAILED' and o.next_attempt_at <> 'infinity') then
    raise exception '% cannot be voided: its Xero draft is queued (%). Void it after the draft exists in Xero (then void it there first) or after the write has failed',
      old.invoice_number, case when o.status = 'PENDING' then 'not started yet' else 'retry scheduled' end using errcode = 'check_violation';
  end if;
  return new;   -- dead-lettered: nothing was created in Xero
end $$;

--
-- Name: invoice_voided_needs_person(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_voided_needs_person() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform wf_open_sync_exception('project_to_invoice', 'project', new.project_id, (select project_number from projects where id = new.project_id), 'INVALID_STATE',
    format('Final invoice %s was voided (%s): a replacement final invoice needs a person, because RoofOps allows one final invoice per project',
           new.invoice_number, coalesce(new.voided_reason, 'no reason given')));
  return new;
end $$;

--
-- Name: invoice_xero_draft_generations_backfill(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_xero_draft_generations_backfill() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_n int;
begin
  insert into invoice_xero_draft_generations (invoice_id, generation, status, outbox_idempotency_key, xero_invoice_id,
                                              xero_invoice_number, tenant_id, approval_id, opened_by, created_at, updated_at)
  select o.aggregate_id, o.generation, xero_draft_ledger_status(o.status, i.sync_status), o.idempotency_key,
         (select l.external_id from external_links l where l.provider = 'XERO' and l.external_type = 'Invoice'
            and l.entity_id = o.aggregate_id and l.verified_at is not null),
         o.payload ->> 'xero_invoice_number', o.payload ->> 'xero_tenant_id', i.approval_id,
         case when o.generation = 1 then 'workflow' else coalesce(o.payload ->> 'opened_by', 'operator') end,
         o.created_at, o.created_at
    from outbox o left join invoices i on i.id = o.aggregate_id
   where o.topic = 'xero.create_draft_invoice'
  on conflict do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

--
-- Name: invoice_xero_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_xero_state(p_invoice uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
           'invoice_id', i.id, 'invoice_number', i.invoice_number, 'status', i.status, 'sync_status', i.sync_status,
           'total_inc_gst', i.total_inc_gst,
           'xero_invoice_id', (select external_id from external_links where provider = 'XERO' and entity_type = 'invoice'
                                  and external_type = 'Invoice' and entity_id = i.id and verified_at is not null),
           'xero_invoice_number', (select payload ->> 'xero_invoice_number' from outbox_current('xero.create_draft_invoice', i.id)),
           'xero_contact_id', (select external_id from external_links where provider = 'XERO' and entity_type = 'customer'
                                  and external_type = 'Contact' and entity_id = i.customer_id and verified_at is not null),
           'xero_tenant_name', (select value from app_settings where key = 'xero.demo_tenant_name'))
  from invoices i where i.id = p_invoice
$$;

--
-- Name: lead_won_on_quote_accepted(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_won_on_quote_accepted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'ACCEPTED' and old.status is distinct from 'ACCEPTED' and new.lead_id is not null then
    update leads set status = 'WON', lost_reason = null where id = new.lead_id and status <> 'WON';
  -- Its last open quote marked Lost or Expired in Airtable (n8n 06): the enquiry is lost too, for the same reason, so the
  -- pipeline never keeps it "Quoted". (Also how a quote sent to the wrong customer is closed before re-entering it.)
  elsif new.status in ('LOST', 'EXPIRED') and old.status is distinct from new.status and new.lead_id is not null
        and not exists (select 1 from quotes o where o.lead_id = new.lead_id and o.id <> new.id and o.status in ('DRAFT', 'SENT', 'ACCEPTED')) then
    update leads set status = 'LOST', record_version = record_version + 1, updated_at = now(),
           lost_reason = coalesce(nullif(btrim(new.lost_reason), ''), format('Quote %s %s', new.quote_number, lower(new.status)))
     where id = new.lead_id and status = 'QUOTED';
  end if;
  return new;
end $$;

--
-- Name: next_friendly_id(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_friendly_id(p_prefix text, p_year integer DEFAULT NULL::integer, p_width integer DEFAULT 4) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare v integer;
begin
  insert into id_counters (counter_key, year, last_value)
  values (p_prefix, coalesce(p_year, 0), 1)
  on conflict (counter_key, year) do update set last_value = id_counters.last_value + 1
  returning last_value into v;
  if p_year is null then
    return p_prefix || '-' || lpad(v::text, p_width, '0');
  end if;
  return p_prefix || '-' || p_year || '-' || lpad(v::text, p_width, '0');
end $$;

--
-- Name: ops_reissue_decide(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ops_reissue_decide(p_approval_number text, p_employee_code text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_ap approvals; v_emp employees;
begin
  if coalesce((select value from app_settings where key = 'invoice.reissue_requires_second_person'), 'true') <> 'false' then
    select * into v_ap from approvals where approval_number = p_approval_number and action_type = 'REISSUE_INVOICE';
    select * into v_emp from employees where employee_code = p_employee_code;
    if v_ap.status = 'PENDING' and v_emp.id is not null and v_ap.requested_by_employee_id = v_emp.id then
      return jsonb_build_object('ok', false, 'code', 'SAME_PERSON',
        'detail', format('%s was requested by %s; a second person in a reissue role (%s) must approve it, so no one replaces a final invoice alone. Nothing was changed',
                         v_ap.approval_number, v_emp.employee_code,
                         coalesce((select value from app_settings where key = 'invoice.reissue_roles'), 'none configured')));
    end if;
  end if;
  return ops_reissue_decide_core(p_approval_number, p_employee_code, p_note);
end $$;

--
-- Name: FUNCTION ops_reissue_decide(p_approval_number text, p_employee_code text, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ops_reissue_decide(p_approval_number text, p_employee_code text, p_note text) IS 'Decide a REISSUE_INVOICE approval: a second person (not the requester) unless invoice.reissue_requires_second_person = false';

--
-- Name: ops_reissue_decide_core(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ops_reissue_decide_core(p_approval_number text, p_employee_code text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_emp employees; v_ap approvals; i invoices; v_check jsonb; v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_key text; v_claimed boolean; v_pe processed_events; v_event uuid; v_preview jsonb; v_hash text;
  v_gen int; v_draft jsonb; v_corr uuid; v_okey text; v_code text; v_detail text; v_res jsonb; v_reason text;
begin
  select * into v_emp from employees where employee_code = p_employee_code;
  if v_emp.id is null or not v_emp.is_active
     or not (v_emp.role = any (string_to_array((select value from app_settings where key = 'invoice.reissue_roles'), ','))) then
    return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED',
      'detail', format('%s is not an active RoofOps employee in a role that may reissue a final invoice (%s)',
        coalesce(nullif(p_employee_code, ''), 'no employee code'), coalesce((select value from app_settings where key = 'invoice.reissue_roles'), 'no roles configured')));
  end if;
  -- Row lock: concurrent decisions on one approval serialise here, and the loser sees the committed status below.
  select * into v_ap from approvals where approval_number = p_approval_number for update;
  if v_ap.id is null or v_ap.action_type <> 'REISSUE_INVOICE' then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND',
      'detail', coalesce(nullif(p_approval_number, ''), 'no approval number') || ' is not a reissue request');
  end if;
  -- Consumption guard: one decision per approval, however many times it is delivered.
  v_key := v_ap.approval_number;
  v_event := wf_log_event('invoice.reissue:' || v_ap.approval_number, stable_uuid('correlation', 'invoice.reissue:' || v_ap.approval_number), null,
    'invoice.reissue_decided', 'invoice', v_ap.entity_id, v_ap.approval_number, 'USER', v_emp.employee_code, 'ops', 'INFO', null,
    jsonb_build_object('approval_number', v_ap.approval_number, 'note', v_note), null);
  insert into processed_events (consumer, idempotency_key, first_event_id, request_hash, status, locked_by, lease_expires_at)
  values ('invoice.reissue:' || v_ap.approval_number, v_key, v_event, md5(v_ap.payload_hash), 'PROCESSING', 'ops_reissue_decide', now() + interval '5 minutes')
  on conflict do nothing returning true into v_claimed;
  if v_claimed is null then
    select * into v_pe from processed_events where consumer = 'invoice.reissue:' || v_ap.approval_number and idempotency_key = v_key for update;
    update processed_events set delivery_count = delivery_count + 1, last_seen_at = now() where consumer = v_pe.consumer and idempotency_key = v_key;
    return coalesce(v_pe.result, '{}'::jsonb) || jsonb_build_object('ok', false, 'code', 'ALREADY_PROCESSED', 'duplicate', true,
      'delivery_count', v_pe.delivery_count + 1,
      'detail', format('%s was already decided; nothing was created', v_ap.approval_number));
  end if;
  -- The full battery again (state, money, void proof, write state) - the request's evidence is re-verified, not trusted.
  v_check := invoice_reissue_check(v_ap.entity_id);
  if not (v_check ->> 'ok')::boolean then
    delete from processed_events where consumer = 'invoice.reissue:' || v_ap.approval_number and idempotency_key = v_key;
    return v_check || jsonb_build_object('approval_number', v_ap.approval_number);
  end if;
  if v_ap.status <> 'PENDING' then
    delete from processed_events where consumer = 'invoice.reissue:' || v_ap.approval_number and idempotency_key = v_key;
    return jsonb_build_object('ok', false, 'code', 'APPROVAL_NOT_PENDING', 'approval_number', v_ap.approval_number,
      'detail', format('%s is %s; only a PENDING request can be decided', v_ap.approval_number, v_ap.status));
  end if;
  if v_ap.expires_at <= now() then
    update approvals set status = 'EXPIRED' where id = v_ap.id;
    delete from processed_events where consumer = 'invoice.reissue:' || v_ap.approval_number and idempotency_key = v_key;
    return jsonb_build_object('ok', false, 'code', 'APPROVAL_EXPIRED', 'approval_number', v_ap.approval_number,
      'detail', format('%s expired at %s; request a fresh reissue', v_ap.approval_number, v_ap.expires_at));
  end if;
  -- Drift: generation, then record version, then preview hash (the hash covers the generation).
  select * into i from invoices where id = v_ap.entity_id;
  v_gen := (v_check ->> 'current_generation')::int;
  v_preview := invoice_reissue_preview(i.id, v_ap.action_payload ->> 'requested_reason') -> 'preview';
  v_hash := invoice_reissue_preview_hash(v_preview);
  if v_ap.action_payload ->> 'target_generation' is distinct from (v_gen + 1)::text then
    v_code := 'GENERATION_CHANGED';
    v_detail := format('%s was requested for generation %s but the current generation of %s is %s', v_ap.approval_number, v_ap.action_payload ->> 'target_generation', i.invoice_number, v_gen);
  elsif v_ap.expected_record_version is distinct from i.record_version then
    v_code := 'RECORD_VERSION_CHANGED';
    v_detail := format('%s was bound to %s record version %s but it is now %s; request a fresh reissue', v_ap.approval_number, i.invoice_number, v_ap.expected_record_version, i.record_version);
  elsif v_hash is distinct from v_ap.payload_hash then
    v_code := 'PREVIEW_CHANGED';
    v_detail := format('%s is stale: %s changed since the request (hash %s, now %s); request a fresh reissue', v_ap.approval_number, i.invoice_number, v_ap.payload_hash, v_hash);
  end if;
  -- P2-H2: the replacement keeps the Xero document's identity (same invoice number) - the draft must agree with it.
  v_draft := v_preview -> 'draft';
  if v_code is null and (v_draft is null or v_draft ->> 'xero_invoice_number' is distinct from v_preview ->> 'xero_invoice_number') then
    v_code := 'INVOICE_NUMBER_CHANGED';
    v_detail := format('%s: the canonical Xero invoice number %s differs from the generation being replaced (%s); a person must decide', v_ap.approval_number,
      coalesce(v_draft ->> 'xero_invoice_number', 'none'), coalesce(v_preview ->> 'xero_invoice_number', 'none'));
  end if;
  if v_code is not null then
    update approvals set status = 'CANCELLED', decision_reason = v_detail where id = v_ap.id;
    delete from processed_events where consumer = 'invoice.reissue:' || v_ap.approval_number and idempotency_key = v_key;
    return jsonb_build_object('ok', false, 'code', v_code, 'approval_number', v_ap.approval_number, 'detail', v_detail);
  end if;
  -- From here the act is committed as one transaction. The approval moves to EXECUTING first (the guard accepts it),
  -- then to EXECUTED at the end with the generation it queued.
  update approvals set status = 'EXECUTING', decided_by = v_emp.id, decided_at = now(), decision_reason = v_note where id = v_ap.id;
  v_reason := v_ap.action_payload ->> 'requested_reason';
  v_okey := xero_draft_outbox_key(i.id, v_gen + 1);
  select o.correlation_id into v_corr from outbox_current('xero.create_draft_invoice', i.id) o;
  -- a. supersede the current generation (history: the row, its Xero InvoiceID and its keys stay).
  update invoice_xero_draft_generations
     set status = 'SUPERSEDED', superseded_at = now(), updated_at = now(),
         superseded_reason = coalesce(v_note || ' | ', '') || 'Reissue ' || v_ap.approval_number || ' by ' || v_emp.employee_code || ': ' || v_reason
   where invoice_id = i.id and superseded_at is null;
  -- b. open the new generation row (before its write, so the ledger never lags the outbox).
  insert into invoice_xero_draft_generations (invoice_id, generation, status, outbox_idempotency_key, xero_invoice_number, tenant_id, approval_id, opened_by)
  values (i.id, v_gen + 1, 'PENDING', v_okey, v_draft ->> 'xero_invoice_number',
          v_check ->> 'bound_tenant_id', v_ap.id, 'operator:' || v_emp.employee_code);
  -- c. queue exactly one new draft write, with new keys (generation >= 2) and the same bound tenant.
  insert into outbox (topic, aggregate_type, aggregate_id, correlation_id, idempotency_key, payload, generation)
  values ('xero.create_draft_invoice', 'invoice', i.id, v_corr, v_okey,
          v_draft || jsonb_build_object(
            'generation', v_gen + 1, 'xero_idempotency_key', xero_draft_provider_key(i.id, v_gen + 1),
            'approval_number', v_ap.approval_number, 'approved_by', v_emp.full_name, 'opened_by', 'operator:' || v_emp.employee_code,
            'reissued_from_generation', v_gen, 'reissued_by', v_emp.employee_code, 'reissue_reason', v_reason,
            'reissue_preview_hash', v_hash), v_gen + 1);
  -- d. the invoice, in a single statement: VOIDED -> APPROVED and SYNCED -> PENDING, bound to the reissue approval.
  update invoices set status = 'APPROVED', sync_status = 'PENDING', approval_id = v_ap.id where id = i.id;
  -- e. the approval executed, with the generation it queued.
  update approvals set status = 'EXECUTED', executed_at = now(),
         execution_result = jsonb_build_object('outcome', 'REISSUE_QUEUED', 'invoice_id', i.id, 'invoice_number', i.invoice_number,
           'generation', v_gen + 1, 'superseded_generation', v_gen, 'outbox_idempotency_key', v_okey, 'decided_by', v_emp.employee_code)
   where id = v_ap.id;
  -- f. one audit event for the whole act.
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
  values ('USER', v_emp.employee_code, 'invoice.reissued', 'invoice', i.id, i.invoice_number,
          jsonb_build_object('status', 'VOIDED', 'sync_status', i.sync_status, 'generation', v_gen,
            'superseded_xero_invoice_id', (select g.xero_invoice_id from invoice_xero_draft_generations g where g.invoice_id = i.id and g.generation = v_gen),
            'void_observation_id', v_check ->> 'void_observation_id', 'void_settlement', v_check ->> 'void_settlement'),
          jsonb_build_object('status', 'APPROVED', 'sync_status', 'PENDING', 'generation', v_gen + 1, 'approval_number', v_ap.approval_number,
            'outbox_idempotency_key', v_okey, 'payload_hash', v_ap.payload_hash, 'bound_tenant_id', v_check ->> 'bound_tenant_id'),
          coalesce(v_note || ' | ', '') || v_reason);
  v_res := jsonb_build_object('ok', true, 'code', 'REISSUE_QUEUED', 'approval_number', v_ap.approval_number,
    'invoice_id', i.id, 'invoice_number', i.invoice_number, 'generation', v_gen + 1, 'superseded_generation', v_gen,
    'outbox_idempotency_key', v_okey, 'xero_idempotency_key', xero_draft_provider_key(i.id, v_gen + 1),
    'detail', format('%s: %s queued generation %s for %s (superseded generation %s, Xero invoice %s)',
      v_ap.approval_number, v_okey, v_gen + 1, i.invoice_number, v_gen, coalesce(v_check ->> 'linked_xero_invoice_id', 'none')));
  update processed_events set status = 'COMPLETED', completed_at = now(), result = v_res, lease_expires_at = null
   where consumer = 'invoice.reissue:' || v_ap.approval_number and idempotency_key = v_key;
  return v_res;
end $$;

--
-- Name: ops_reissue_request(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ops_reissue_request(p_invoice uuid, p_employee_code text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_emp employees; v_reason text := btrim(coalesce(p_reason, '')); v_check jsonb; i invoices;
  v_open approvals; v_cycle int; v_preview jsonb; v_hash text; v_apr approvals; v_ttl int;
begin
  select * into v_emp from employees where employee_code = p_employee_code;
  if v_emp.id is null or not v_emp.is_active
     or not (v_emp.role = any (string_to_array((select value from app_settings where key = 'invoice.reissue_roles'), ','))) then
    return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED',
      'detail', format('%s is not an active RoofOps employee in a role that may reissue a final invoice (%s)',
        coalesce(nullif(p_employee_code, ''), 'no employee code'), coalesce((select value from app_settings where key = 'invoice.reissue_roles'), 'no roles configured')));
  end if;
  if length(v_reason) < 10 then
    return jsonb_build_object('ok', false, 'code', 'REASON_REQUIRED',
      'detail', 'a reissue needs a reason saying why (at least 10 characters)');
  end if;
  v_check := invoice_reissue_check(p_invoice);
  if not (v_check ->> 'ok')::boolean then return v_check; end if;
  select * into i from invoices where id = p_invoice;
  select * into v_open from approvals a where a.action_type = 'REISSUE_INVOICE' and a.entity_id = i.id
     and a.status in ('PENDING', 'APPROVED', 'EXECUTING') order by a.created_at desc limit 1 for update;
  if v_open.id is not null and v_open.status = 'PENDING' and v_open.expires_at <= now() then
    update approvals set status = 'CANCELLED', decision_reason = 'Expired before it was decided; the next request replaces it' where id = v_open.id;
    v_open := null;
  end if;
  if v_open.id is not null then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_PENDING', 'approval_number', v_open.approval_number,
      'detail', format('%s already has an open reissue request %s (%s, expires %s)', i.invoice_number, v_open.approval_number, v_open.status, v_open.expires_at));
  end if;
  select count(*) into v_cycle from approvals a where a.action_type = 'REISSUE_INVOICE' and a.entity_id = i.id;
  v_preview := invoice_reissue_preview(i.id, v_reason) -> 'preview';
  v_hash := invoice_reissue_preview_hash(v_preview);
  v_ttl := (select value::int from app_settings where key = 'invoice.approval_ttl_hours');
  begin
    insert into approvals (approval_number, action_type, entity_type, entity_id, business_reference, requested_by_actor_type,
                           requested_by_employee_id, required_permission, action_payload, payload_hash, expected_record_version,
                           idempotency_key, expires_at, status)
    values (next_friendly_id('APR', extract(year from app_today())::int), 'REISSUE_INVOICE', 'invoice', i.id, i.invoice_number, 'USER',
            v_emp.id, 'invoice.approve', v_preview, v_hash, i.record_version,
            'reissue:request:' || i.id::text || ':' || v_cycle::text, now() + make_interval(hours => v_ttl), 'PENDING')
    returning * into v_apr;
  exception when unique_violation then
    -- The partial unique index (or the per-cycle idempotency key) says a request is already open: the database wins.
    select * into v_apr from approvals a where a.action_type = 'REISSUE_INVOICE' and a.entity_id = i.id
       and a.status in ('PENDING', 'APPROVED', 'EXECUTING') order by a.created_at desc limit 1;
    return jsonb_build_object('ok', false, 'code', 'REISSUE_PENDING', 'approval_number', v_apr.approval_number,
      'detail', format('%s already has an open reissue request %s (%s); only one is open at a time', i.invoice_number, v_apr.approval_number, v_apr.status));
  end;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
  values ('USER', v_emp.employee_code, 'invoice.reissue_requested', 'invoice', i.id, i.invoice_number,
          jsonb_build_object('status', i.status, 'sync_status', i.sync_status, 'generation', (v_check ->> 'current_generation')::int,
            'record_version', i.record_version, 'voided_reason', i.voided_reason),
          jsonb_build_object('approval_number', v_apr.approval_number, 'payload_hash', v_hash, 'target_generation', (v_check ->> 'target_generation')::int,
            'linked_xero_invoice_id', v_check ->> 'linked_xero_invoice_id', 'void_observation_id', v_check ->> 'void_observation_id',
            'void_settlement', v_check ->> 'void_settlement', 'bound_tenant_id', v_check ->> 'bound_tenant_id'),
          v_reason);
  return jsonb_build_object('ok', true, 'code', 'REISSUE_REQUESTED', 'approval_number', v_apr.approval_number,
    'invoice_number', i.invoice_number, 'invoice_id', i.id, 'expires_at', v_apr.expires_at, 'payload_hash', v_hash,
    'target_generation', (v_check ->> 'target_generation')::int,
    'detail', format('%s: reissue of %s requested, target generation %s (voided %s, verified by observation %s)',
      v_apr.approval_number, i.invoice_number, v_check ->> 'target_generation', v_check ->> 'void_settlement', v_check ->> 'void_observation_id'));
end $$;

--
-- Name: ops_resolve_exception(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ops_resolve_exception(p_exception text, p_employee_code text, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare x workflow_exceptions; v_emp employees; v_note text := btrim(coalesce(p_note, ''));
begin
  if length(v_note) < 10 then
    return jsonb_build_object('resolved', false, 'reason', 'a resolution needs a note saying why (at least 10 characters)');
  end if;
  select * into v_emp from employees where employee_code = p_employee_code;
  if v_emp.id is null then
    return jsonb_build_object('resolved', false, 'reason', coalesce(p_employee_code, 'no employee') || ' is not a RoofOps employee');
  end if;
  if not v_emp.is_active then
    return jsonb_build_object('resolved', false, 'reason', v_emp.employee_code || ' is not active');
  end if;
  if not (v_emp.role = any (string_to_array((select value from app_settings where key = 'exception.resolver_roles'), ','))) then
    return jsonb_build_object('resolved', false, 'reason', format('%s (%s) may not resolve exceptions', v_emp.employee_code, v_emp.role));
  end if;
  select * into x from workflow_exceptions where exception_number = p_exception for update;
  if x.id is null then
    return jsonb_build_object('resolved', false, 'reason', coalesce(p_exception, 'no exception number') || ' does not exist');
  end if;
  if x.resolution_status <> 'OPEN' then
    return jsonb_build_object('resolved', false, 'already_resolved', x.resolution_status in ('RESOLVED', 'IGNORED'),
      'reason', format('%s is already %s%s', x.exception_number, x.resolution_status,
                       case when x.resolved_by is not null then ' by ' || (select employee_code from employees where id = x.resolved_by)
                            when x.resolved_by_system is not null then ' by ' || x.resolved_by_system else '' end));
  end if;
  update workflow_exceptions set resolution_status = 'RESOLVED', resolved_by = v_emp.id, resolved_at = now(), resolution_note = v_note
   where id = x.id;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
  values ('USER', v_emp.employee_code, 'exception.resolved', 'workflow_exception', x.id, x.exception_number,
          jsonb_build_object('resolution_status', x.resolution_status, 'error_class', x.error_class, 'reference', x.business_reference),
          jsonb_build_object('resolution_status', 'RESOLVED', 'resolved_by', v_emp.employee_code), v_note);
  return jsonb_build_object('resolved', true, 'exception_number', x.exception_number, 'resolved_by', v_emp.employee_code,
                            'resolved_at', now(), 'reference', x.business_reference);
end $$;

--
-- Name: ops_staff_set_password(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ops_staff_set_password(p_employee_code text, p_login text, p_password text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare v_emp employees; v_login text := lower(btrim(coalesce(p_login, '')));
begin
  select * into v_emp from employees where employee_code = p_employee_code;
  if v_emp.id is null or not v_emp.is_active then
    return jsonb_build_object('ok', false, 'reason', coalesce(nullif(p_employee_code, ''), 'no employee code') || ' is not an active RoofOps employee');
  end if;
  if length(coalesce(p_password, '')) < 12 then
    return jsonb_build_object('ok', false, 'reason', 'a password needs at least 12 characters');
  end if;
  if octet_length(p_password) > 72 then   -- bcrypt ignores everything after 72 bytes: refuse rather than silently truncate
    return jsonb_build_object('ok', false, 'reason', 'a password can be at most 72 bytes');
  end if;
  if length(v_login) < 3 then return jsonb_build_object('ok', false, 'reason', 'a login needs at least 3 characters'); end if;
  if exists (select 1 from staff_accounts where login = v_login and employee_id <> v_emp.id) then
    return jsonb_build_object('ok', false, 'reason', 'that login belongs to another employee');
  end if;
  insert into staff_accounts (employee_id, login, password_hash)
  values (v_emp.id, v_login, crypt(p_password, gen_salt('bf', 10)))
  on conflict (employee_id) do update set login = excluded.login, password_hash = excluded.password_hash,
    failed_attempts = 0, locked_until = null, password_set_at = now();
  update staff_sessions set revoked_at = now() where employee_id = v_emp.id and revoked_at is null;   -- a reset signs them out
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
  values ('SYSTEM', 'ops:staff', 'staff.password_set', 'employee', v_emp.id, v_emp.employee_code,
          jsonb_build_object('login', v_login), 'Dashboard login set by the owner (password not recorded)');
  return jsonb_build_object('ok', true, 'employee_code', v_emp.employee_code, 'login', v_login);
end $$;

--
-- Name: outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    topic text NOT NULL,
    aggregate_type text NOT NULL,
    aggregate_id uuid NOT NULL,
    correlation_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    payload jsonb NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_until timestamp with time zone,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    dispatched_at timestamp with time zone,
    result jsonb,
    generation integer DEFAULT 1 NOT NULL,
    CONSTRAINT outbox_generation_positive CHECK ((generation >= 1)),
    CONSTRAINT outbox_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'DISPATCHING'::text, 'DONE'::text, 'FAILED'::text])))
);

--
-- Name: outbox_current(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outbox_current(p_topic text, p_aggregate_id uuid) RETURNS public.outbox
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select * from outbox where topic = p_topic and aggregate_id = p_aggregate_id
   order by generation desc, created_at desc, id desc limit 1
$$;

--
-- Name: po_apply_change(uuid, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.po_apply_change(p_id uuid, p_field text, p_value text, p_current jsonb, p_actor text, p_event_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare po purchase_orders; v_to text; v_emp uuid; v_date date; v_job projects;
begin
  select * into po from purchase_orders where id = p_id;
  -- AC-21: an order follows its job. Once the job is Cancelled or Closed, nothing on its orders moves forward.
  select * into v_job from projects where id = po.project_id;
  if p_field = 'status' then
    v_to := sm_state('purchase_order', p_value);
    if v_to is null then return format('"%s" is not a purchase-order status RoofOps knows', p_value); end if;
    if not state_transition_allowed('purchase_order', po.status, v_to) then
      return format('%s → %s is not an allowed purchase-order change%s', sm_label('purchase_order', po.status), sm_label('purchase_order', v_to),
                    case when po.status in ('DELIVERED', 'CANCELLED') then ' (' || sm_label('purchase_order', po.status) || ' is final)' else '' end);
    end if;
    if v_job.status in ('CANCELLED', 'CLOSED') and v_to <> 'CANCELLED' then
      return format('%s is %s: an order for it can only be cancelled', v_job.project_number, lower(sm_label('project', v_job.status)));
    end if;
    select ei.employee_id into v_emp from employee_external_identities ei join employees e on e.id = ei.employee_id
     where ei.provider = 'AIRTABLE' and ei.external_id = p_actor and e.is_active;
    -- AC-21: an approval made now is a RoofOps decision, whoever created the order; ADR-015's IMPORT exemption covers only
    -- the historical approvals that came with the import.
    if v_to = 'APPROVED' and v_emp is null then
      return 'only a RoofOps approver can approve a purchase order';
    end if;
    update purchase_orders set status = v_to,
      approved_at = case when v_to in ('APPROVED','SENT','ACKNOWLEDGED','PARTIALLY_DELIVERED','DELIVERED') then coalesce(approved_at, now()) else approved_at end,
      approved_by = case when v_to in ('APPROVED','SENT','ACKNOWLEDGED','PARTIALLY_DELIVERED','DELIVERED') then coalesce(approved_by, v_emp) else approved_by end,
      sent_at = case when v_to in ('SENT','ACKNOWLEDGED','PARTIALLY_DELIVERED','DELIVERED') then coalesce(sent_at, now()) else sent_at end,
      acknowledged_at = case when v_to in ('ACKNOWLEDGED','PARTIALLY_DELIVERED','DELIVERED') and po.status in ('SENT','ACKNOWLEDGED')
                             then coalesce(acknowledged_at, now()) else acknowledged_at end,
      cancelled_reason = case when v_to = 'CANCELLED' then coalesce(cancelled_reason, 'Cancelled in Airtable by ' || p_actor) else cancelled_reason end
    where id = p_id;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
    values ('USER', p_actor, 'purchase_order.status.changed', 'purchase_order', p_id, po.po_number,
            jsonb_build_object('status', po.status), jsonb_build_object('status', v_to), 'Changed in Airtable [' || p_event_key || ']');
    return null;
  elsif p_field = 'expected_delivery_date' then
    if po.status in ('DELIVERED', 'CANCELLED') then return 'the delivery date is locked once an order is ' || lower(sm_label('purchase_order', po.status)); end if;
    if v_job.status in ('CANCELLED', 'CLOSED') then
      return format('the delivery date is locked: %s is %s', v_job.project_number, lower(sm_label('project', v_job.status)));
    end if;
    begin v_date := p_value::date; exception when others then return format('"%s" is not a date', p_value); end;
    if v_date is not null and v_date < po.po_date then return format('Expected Delivery %s would be before the PO Date %s', v_date, po.po_date); end if;
    update purchase_orders set expected_delivery_date = v_date where id = p_id;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
    values ('USER', p_actor, 'purchase_order.expected_delivery_date.changed', 'purchase_order', p_id, po.po_number,
            jsonb_build_object('expected_delivery_date', po.expected_delivery_date), jsonb_build_object('expected_delivery_date', v_date), 'Changed in Airtable [' || p_event_key || ']');
    return null;
  elsif p_field = 'supplier_reference' then
    update purchase_orders set supplier_reference = nullif(btrim(coalesce(p_value, '')), '') where id = p_id;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
    values ('USER', p_actor, 'purchase_order.supplier_reference.changed', 'purchase_order', p_id, po.po_number,
            jsonb_build_object('supplier_reference', po.supplier_reference), jsonb_build_object('supplier_reference', p_value), 'Changed in Airtable [' || p_event_key || ']');
    return null;
  end if;
  return 'this field cannot be changed from Airtable';
end $$;

--
-- Name: project_apply_change(uuid, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_apply_change(p_id uuid, p_field text, p_value text, p_current jsonb, p_actor text, p_event_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p projects; v_to text; v_reason text; v_date date; v_emp employees; v_note text; v_n int; v_v int;
begin
  select * into p from projects where id = p_id;
  if p_field = 'status' then
    v_to := sm_state('project', p_value);
    if v_to is null then return format('"%s" is not a project status RoofOps knows', p_value); end if;
    if not state_transition_allowed('project', p.status, v_to) then
      return format('%s → %s is not an allowed status change%s', sm_label('project', p.status), sm_label('project', v_to),
                    case when p.status in ('CANCELLED', 'CLOSED') then ' (' || sm_label('project', p.status) || ' is final)' else '' end);
    end if;
    v_reason := project_transition_guard(p, v_to);
    if v_reason is not null then return v_reason; end if;
    v_note := nullif(btrim(p_current ->> 'fld5MhzMBtA4CBUHo'), '');
    update projects set status = v_to,
      actual_start_date = case when v_to = 'IN_PROGRESS' then coalesce(actual_start_date, app_today()) else actual_start_date end,
      actual_completion_date = case when v_to = 'COMPLETED' then greatest(coalesce(actual_completion_date, app_today()), actual_start_date) else actual_completion_date end,
      on_hold_reason = case when v_to = 'ON_HOLD' then coalesce(v_note, 'Put on hold in Airtable by ' || p_actor) else on_hold_reason end,
      cancellation_reason = case when v_to = 'CANCELLED' then coalesce(v_note, 'Cancelled in Airtable by ' || p_actor) else cancellation_reason end
    where id = p_id;
    if v_to = 'CANCELLED' then
      -- Nothing may be invoiced or worked on for a cancelled job: withdraw pending previews, cancel open tasks.
      with w as (update approvals set status = 'CANCELLED', decision_reason = 'Project cancelled'
                  where entity_id = p_id and action_type = 'CREATE_INVOICE' and status = 'PENDING' returning id, approval_number)
      insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, approval_id, before_state, after_state, reason)
      select 'SYSTEM', 'project_transition', 'approval.withdrawn', 'approval', w.id, w.approval_number, w.id, '{"status":"PENDING"}', '{"status":"CANCELLED"}',
             p.project_number || ' was cancelled' from w;
      update tasks set status = 'CANCELLED' where project_id = p_id and status in ('OPEN', 'IN_PROGRESS');
      get diagnostics v_n = row_count;
      -- Its booked site visits are cancelled too, so the crew is free. A visit already under way is left for the crew to
      -- complete (owner decision), and web_visit_update lets them.
      with b as (select id, job_number, status from jobs where project_id = p_id and status in ('SCHEDULED', 'WEATHER_DELAYED') for update),
           c as (update jobs j set status = 'CANCELLED', status_reason = 'Project cancelled', record_version = j.record_version + 1, updated_at = now()
                   from b where j.id = b.id returning j.id, b.job_number, b.status as was)
      insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
      select 'SYSTEM', 'project_transition', 'job.cancel', 'job', c.id, p.project_number, jsonb_build_object('job_number', c.job_number, 'status', c.was),
             jsonb_build_object('job_number', c.job_number, 'status', 'CANCELLED'), p.project_number || ' was cancelled' from c;
      get diagnostics v_v = row_count;
    end if;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
    values ('USER', p_actor, 'project.status.changed', 'project', p_id, p.project_number,
            jsonb_build_object('status', p.status), jsonb_build_object('status', v_to, 'tasks_cancelled', coalesce(v_n, 0), 'visits_cancelled', coalesce(v_v, 0)),
            coalesce(v_note, 'Changed in Airtable') || ' [' || p_event_key || ']');
    return null;
  elsif p_field in ('planned_start_date', 'planned_completion_date') then
    if p.status in ('COMPLETED', 'CLOSED', 'CANCELLED') then
      return 'the schedule is locked once a job is ' || lower(sm_label('project', p.status));
    end if;
    begin v_date := p_value::date; exception when others then return format('"%s" is not a date', p_value); end;
    if v_date is null and p.status in ('SCHEDULED', 'IN_PROGRESS', 'ON_HOLD') and p_field = 'planned_start_date' then
      return 'a scheduled job needs a Planned Start';
    end if;
    if p_field = 'planned_start_date' and v_date is not null and p.planned_completion_date is not null and v_date > p.planned_completion_date then
      return format('Planned Start %s would be after Planned Completion %s', v_date, p.planned_completion_date);
    end if;
    if p_field = 'planned_completion_date' and v_date is not null and p.planned_start_date is not null and v_date < p.planned_start_date then
      return format('Planned Completion %s would be before Planned Start %s', v_date, p.planned_start_date);
    end if;
    if p_field = 'planned_start_date' then update projects set planned_start_date = v_date where id = p_id;
    else update projects set planned_completion_date = v_date where id = p_id; end if;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
    values ('USER', p_actor, 'project.' || p_field || '.changed', 'project', p_id, p.project_number,
            jsonb_build_object(p_field, case when p_field = 'planned_start_date' then p.planned_start_date else p.planned_completion_date end),
            jsonb_build_object(p_field, v_date), 'Changed in Airtable [' || p_event_key || ']');
    return null;
  elsif p_field = 'project_manager' then
    select * into v_emp from employees where lower(full_name) = lower(btrim(coalesce(p_value, ''))) and role = 'PROJECT_MANAGER' and is_active;
    if v_emp.id is null then
      return format('"%s" is not an active project manager (use: %s)', coalesce(p_value, ''),
                    (select string_agg(full_name, ', ' order by full_name) from employees where role = 'PROJECT_MANAGER' and is_active));
    end if;
    update projects set project_manager_id = v_emp.id where id = p_id;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
    values ('USER', p_actor, 'project.project_manager.changed', 'project', p_id, p.project_number,
            jsonb_build_object('project_manager', (select full_name from employees where id = p.project_manager_id)),
            jsonb_build_object('project_manager', v_emp.full_name), 'Changed in Airtable [' || p_event_key || ']');
    return null;
  elsif p_field in ('swms_signed', 'materials_reviewed') then
    -- AC-13B: the pre-start gate's supported path (Airtable → 06 → here); the note is read with the change.
    return checklist_apply_change(p_id, upper(p_field), p_value,
      nullif(btrim(p_current ->> case p_field when 'swms_signed' then 'fldNcsIgH6TfQFfaU' else 'fldEtAmAokIvtzJdn' end), ''), p_actor, p_event_key);
  elsif p_field in ('completion_photos', 'compliance_certificate') then
    -- AC-13A: the completion gate's supported path (Airtable → 06 → here); the note is read with the change.
    return checklist_apply_change(p_id, upper(p_field), p_value,
      nullif(btrim(p_current ->> case p_field when 'completion_photos' then 'fldA77ad94yUmvnu3' else 'fldLi9FkGDFAbf0QB' end), ''), p_actor, p_event_key);
  end if;
  return 'this field cannot be changed from Airtable';
end $$;

--
-- Name: project_billing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_billing(p_project uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with x as (
    select p.project_number, qv.total_inc_gst as quote,
           coalesce((select sum(v.amount_inc_gst) from variations v where v.project_id = p.id and v.status = 'APPROVED'), 0)::numeric(12,2) as approved_variations,
           coalesce((select sum(v.amount_inc_gst) from variations v where v.project_id = p.id and v.status = 'INVOICED'), 0)::numeric(12,2) as invoiced_variations,
           coalesce((select sum(i.total_inc_gst) from invoices i where i.project_id = p.id and i.status in ('APPROVED', 'ISSUED', 'PARTIALLY_PAID', 'PAID')), 0)::numeric(12,2) as billed,
           (select string_agg(i.invoice_number, ', ' order by i.invoice_number) from invoices i
             where i.project_id = p.id and i.status in ('APPROVED', 'ISSUED', 'PARTIALLY_PAID', 'PAID')) as invoices,
           coalesce((select jsonb_agg(jsonb_build_object('invoice', i.invoice_number, 'status', i.status, 'total', i.total_inc_gst) order by i.invoice_number)
                       from invoices i where i.project_id = p.id and i.status in ('APPROVED', 'ISSUED', 'PARTIALLY_PAID', 'PAID')), '[]'::jsonb) as billed_invoices
      from projects p join quote_versions qv on qv.id = p.accepted_quote_version_id
     where p.id = p_project)
  select jsonb_build_object('project_number', project_number, 'quote', quote,
           'approved_variations', approved_variations, 'invoiced_variations', invoiced_variations,
           'variations', approved_variations + invoiced_variations, 'entitlement', quote + approved_variations + invoiced_variations,
           'billed', billed, 'invoices', invoices, 'billed_invoices', billed_invoices,
           'remaining', quote + approved_variations + invoiced_variations - billed)
    from x
$$;

--
-- Name: project_left_to_bill_after_final(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_left_to_bill_after_final(p_project uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('remaining', (b ->> 'remaining')::numeric, 'final', f.numbers,
           'message', format('%s left to bill after the final invoice %s (for example a variation approved later); it needs its own invoice before the job can close',
                             b ->> 'remaining', f.numbers))
    from (select project_billing(p_project) b) x,
         (select string_agg(invoice_number, ', ' order by invoice_number) numbers from invoices
           where project_id = p_project and invoice_type = 'FINAL' and status <> 'VOIDED') f
   where f.numbers is not null and (b ->> 'remaining')::numeric > 0
$$;

--
-- Name: project_over_billing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_over_billing(p_project uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('billed', b -> 'billed', 'quote', b -> 'quote', 'variations', b -> 'variations', 'entitled', b -> 'entitlement',
           'excess', -(b ->> 'remaining')::numeric, 'invoices', b ->> 'invoices',
           'message', format('%s is over-billed: billed %s (%s) against quote %s + approved variations %s = %s; over by %s. Correct the billing before it can be closed (for example void the unpaid duplicate invoice)',
                             b ->> 'project_number', b ->> 'billed', b ->> 'invoices', b ->> 'quote', b ->> 'variations', b ->> 'entitlement', -(b ->> 'remaining')::numeric))
    from (select project_billing(p_project) b) x
   where (b ->> 'remaining')::numeric < 0
$$;

--
-- Name: projects; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.projects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_number text NOT NULL,
    quote_id uuid NOT NULL,
    accepted_quote_version_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    property_id uuid NOT NULL,
    project_manager_id uuid,
    status text DEFAULT 'PLANNING'::text NOT NULL,
    planned_start_date date,
    planned_completion_date date,
    actual_start_date date,
    actual_completion_date date,
    pm_risk_flag text DEFAULT 'LOW'::text NOT NULL,
    delay_reason text,
    on_hold_reason text,
    cancellation_reason text,
    created_by_event_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    record_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT projects_check CHECK (((planned_completion_date IS NULL) OR (planned_start_date IS NULL) OR (planned_completion_date >= planned_start_date))),
    CONSTRAINT projects_check1 CHECK (((actual_completion_date IS NULL) OR (actual_start_date IS NULL) OR (actual_completion_date >= actual_start_date))),
    CONSTRAINT projects_check2 CHECK (((status <> ALL (ARRAY['COMPLETED'::text, 'CLOSED'::text])) OR (actual_completion_date IS NOT NULL))),
    CONSTRAINT projects_check3 CHECK (((status <> ALL (ARRAY['IN_PROGRESS'::text, 'COMPLETED'::text, 'CLOSED'::text])) OR (actual_start_date IS NOT NULL))),
    CONSTRAINT projects_check4 CHECK (((pm_risk_flag = 'LOW'::text) OR (delay_reason IS NOT NULL))),
    CONSTRAINT projects_check5 CHECK (((status <> 'ON_HOLD'::text) OR (on_hold_reason IS NOT NULL))),
    CONSTRAINT projects_check6 CHECK (((status <> 'CANCELLED'::text) OR (cancellation_reason IS NOT NULL))),
    CONSTRAINT projects_pm_risk_flag_check CHECK ((pm_risk_flag = ANY (ARRAY['LOW'::text, 'HIGH'::text]))),
    CONSTRAINT projects_status_check CHECK ((status = ANY (ARRAY['PLANNING'::text, 'MATERIALS_PENDING'::text, 'SCHEDULED'::text, 'IN_PROGRESS'::text, 'ON_HOLD'::text, 'COMPLETED'::text, 'CLOSED'::text, 'CANCELLED'::text])))
);

--
-- Name: project_transition_guard(public.projects, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_transition_guard(p public.projects, p_to text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_final text; v_over jsonb; v_bill jsonb; v_open text;
begin
  -- AC-08: an over-billed job is never closed; a person corrects the billing first (no credit-note model).
  if p_to = 'CLOSED' then
    v_over := project_over_billing(p.id);
    if v_over is not null then
      return format('%s cannot be closed: it is over-billed by %s (billed %s against %s: %s). Correct the billing first, for example void the unpaid duplicate invoice',
        p.project_number, v_over ->> 'excess', v_over ->> 'billed', v_over ->> 'entitled', v_over ->> 'invoices');
    end if;
  end if;
  if p_to = 'IN_PROGRESS' and p.status = 'SCHEDULED' and p.planned_start_date is null then
    return 'set a Planned Start before marking the job In Progress';
  end if;
  if p_to = 'IN_PROGRESS' and p.status = 'ON_HOLD' and p.actual_start_date is null then
    return 'this job never started; move it back to Scheduled instead of In Progress';
  end if;
  -- AC-13B: every required pre-start item Done, or Waived / Not applicable with a reason where allowed, before work starts.
  -- Keyed on the status, not on Actual Start, so a direct update of Actual Start cannot skip the gate, also on resuming an
  -- On Hold job (AC-13C): a job that really started passes, its items were satisfied and are locked when work began.
  if p_to = 'IN_PROGRESS' and p.status in ('SCHEDULED', 'ON_HOLD') then
    select string_agg(label, ', ' order by sort_order) into v_open from project_checklist_items
     where project_id = p.id and stage = 'PRE_START' and is_required and status not in ('DONE', 'WAIVED', 'NOT_APPLICABLE');
    if v_open is not null then
      return format('pre-start items are still open (%s); set them in Airtable (SWMS Signed / Materials Reviewed) before the job starts', v_open);
    end if;
  end if;
  if p.status = 'COMPLETED' and p_to = 'CANCELLED' then
    select string_agg(invoice_number, ', ') into v_final from invoices where project_id = p.id and invoice_type = 'FINAL' and status <> 'VOIDED';
    if v_final is not null then
      return format('a final invoice (%s) already exists; void it first, then cancel', v_final);
    end if;
    if exists (select 1 from approvals where entity_id = p.id and action_type = 'CREATE_INVOICE' and status in ('EXECUTING', 'APPROVED')) then
      return 'a final invoice is being created in Xero right now; wait for it to finish';
    end if;
  end if;
  -- AC-15B: every transition into Cancelled, from any state, as the integrity check cancelled_job_fully_billed reads it
  -- (a guard never allows a state the integrity check fails). A partly billed job may still be cancelled from any state.
  if p_to = 'CANCELLED' then
    -- AC-15: imported invoices carry no type, so whether the job was finally billed is also read from its bills. A job
    -- whose valid bills reach what it is entitled to (AC-09 project_billing) was billed in full and is not cancelled:
    -- fully billed is billed, whatever the paperwork (as AC-13A reads it for closing). A partly billed job still may be.
    v_bill := project_billing(p.id);
    if (v_bill ->> 'billed')::numeric > 0 and (v_bill ->> 'remaining')::numeric <= 0 then
      return format('%s is fully billed (billed %s against %s: %s); a fully billed job is not cancelled: void the final bill first, then cancel',
        p.project_number, v_bill ->> 'billed', v_bill ->> 'entitlement', v_bill ->> 'invoices');
    end if;
  end if;
  if p.status = 'COMPLETED' and p_to = 'CLOSED' then
    -- AC-14: settled only on verified state (Xero for a Xero-linked invoice; the import's payments for an imported one).
    select string_agg(i.invoice_number || ' (' || (f ->> 'reason') || ')', ', ' order by i.invoice_number) into v_final
      from invoices i cross join lateral (select invoice_financial_state(i.id) f) s
     where i.project_id = p.id and not (f ->> 'settled')::boolean;
    if v_final is not null then return format('not every invoice is paid yet: %s', v_final); end if;
    -- AC-13A: closed means settled: everything entitled is billed (AC-09 project_billing; over-billing is refused above).
    v_bill := project_billing(p.id);
    if (v_bill ->> 'remaining')::numeric > 0 then
      select string_agg(invoice_number, ', ') into v_final from invoices where project_id = p.id and invoice_type = 'FINAL' and status <> 'VOIDED';
      return case when v_final is null then format('%s left to bill: the final invoice has not been raised yet', v_bill ->> 'remaining')
                  else format('%s left to bill after final invoice %s (for example a variation approved later); invoice it before closing', v_bill ->> 'remaining', v_final) end;
    end if;
    select string_agg(label, ', ' order by label) into v_open from v_projects_missing_completion_docs v where v.id = p.id;
    if v_open is not null then
      return format('completion items are still open (%s); set them in Airtable (Completion Photos / Compliance Certificate) before closing', v_open);
    end if;
    if exists (select 1 from approvals where entity_id = p.id and action_type = 'CREATE_INVOICE' and status = 'PENDING') then
      return 'a final invoice preview is awaiting approval; approve or withdraw it first';
    end if;
    -- AC-04 semantics: never close while a Xero write is in flight or uncertain.
    select string_agg(invoice_number || ' (' || lower(sync_status) || ')', ', ' order by invoice_number) into v_final
      from invoices where project_id = p.id and sync_status in ('PENDING', 'UNKNOWN');
    if v_final is not null or exists (select 1 from approvals where entity_id = p.id and action_type = 'CREATE_INVOICE' and status in ('APPROVED', 'EXECUTING')) then
      return format('a Xero write is still in flight or uncertain%s; wait until Xero confirms it', coalesce(': ' || v_final, ''));
    end if;
  end if;
  return null;
end $$;

--
-- Name: quote_apply_change(uuid, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quote_apply_change(p_id uuid, p_field text, p_value text, p_current jsonb, p_actor text, p_event_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare q quotes; v_to text; v_lost text := nullif(btrim(p_current ->> 'fld1sZibwdMVnI4Hd'), '');
begin
  select * into q from quotes where id = p_id;
  if p_field = 'status' then
    v_to := sm_state('quote', p_value);
    if v_to is null then return format('"%s" is not a quote status RoofOps knows', p_value); end if;
    if v_to = 'ACCEPTED' and q.status = 'SENT' then return 'DEFERRED'; end if;   -- the Quote Accepted → Project workflow owns acceptance
    if not state_transition_allowed('quote', q.status, v_to) then
      return format('%s → %s is not an allowed quote change%s', sm_label('quote', q.status), sm_label('quote', v_to),
                    case when q.status in ('ACCEPTED', 'LOST', 'EXPIRED') then ' (' || sm_label('quote', q.status) || ' is final)' else '' end);
    end if;
    update quotes set status = v_to,
      sent_on = case when v_to = 'SENT' then coalesce(sent_on, greatest(app_today(), created_on)) else sent_on end,
      lost_reason = case when v_to = 'LOST' then coalesce(v_lost, lost_reason, 'Marked lost in Airtable by ' || p_actor) else lost_reason end
    where id = p_id;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
    values ('USER', p_actor, 'quote.status.changed', 'quote', p_id, q.quote_number, jsonb_build_object('status', q.status),
            jsonb_build_object('status', v_to), 'Changed in Airtable [' || p_event_key || ']');
    return null;
  elsif p_field = 'lost_reason' then
    if q.status = 'LOST' and nullif(btrim(coalesce(p_value, '')), '') is null then return 'a lost quote needs a Lost Reason'; end if;
    update quotes set lost_reason = nullif(btrim(coalesce(p_value, '')), '') where id = p_id;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
    values ('USER', p_actor, 'quote.lost_reason.changed', 'quote', p_id, q.quote_number, jsonb_build_object('lost_reason', q.lost_reason),
            jsonb_build_object('lost_reason', p_value), 'Changed in Airtable [' || p_event_key || ']');
    return null;
  end if;
  return 'this field cannot be changed from Airtable';
end $$;

--
-- Name: quote_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.quote_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    quote_id uuid NOT NULL,
    version_number integer NOT NULL,
    line_amount_type text DEFAULT 'INCLUSIVE'::text NOT NULL,
    gst_rate numeric(5,4) DEFAULT 0.1000 NOT NULL,
    subtotal_ex_gst numeric(12,2) DEFAULT 0 NOT NULL,
    gst_amount numeric(12,2) DEFAULT 0 NOT NULL,
    total_inc_gst numeric(12,2) DEFAULT 0 NOT NULL,
    scope_summary text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT quote_versions_check CHECK (
CASE line_amount_type
    WHEN 'EXCLUSIVE'::text THEN ((gst_amount = round((subtotal_ex_gst * gst_rate), 2)) AND (total_inc_gst = (subtotal_ex_gst + gst_amount)))
    WHEN 'INCLUSIVE'::text THEN ((gst_amount = round(((total_inc_gst * gst_rate) / ((1)::numeric + gst_rate)), 2)) AND (subtotal_ex_gst = (total_inc_gst - gst_amount)))
    ELSE ((gst_amount = (0)::numeric) AND (total_inc_gst = subtotal_ex_gst))
END),
    CONSTRAINT quote_versions_gst_rate_check CHECK (((gst_rate >= (0)::numeric) AND (gst_rate <= (1)::numeric))),
    CONSTRAINT quote_versions_line_amount_type_check CHECK ((line_amount_type = ANY (ARRAY['EXCLUSIVE'::text, 'INCLUSIVE'::text, 'NO_TAX'::text]))),
    CONSTRAINT quote_versions_version_number_check CHECK ((version_number >= 1))
);

--
-- Name: quote_insert_version(uuid, integer, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quote_insert_version(p_quote uuid, p_version integer, p_amount_type text, p_scope text, p_lines jsonb, p_by uuid) RETURNS public.quote_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v quote_versions; x jsonb; n int := 0;
begin
  insert into quote_versions (quote_id, version_number, line_amount_type, gst_rate, scope_summary, created_by)
  values (p_quote, p_version, p_amount_type, 0.1000, p_scope, p_by) returning * into v;
  for x in select * from jsonb_array_elements(p_lines) loop
    n := n + 1;
    insert into quote_version_lines (quote_version_id, line_no, line_kind, product_id, description, quantity, unit, unit_price)
    values (v.id, n, x ->> 'line_kind', (select p.id from products p where p.product_code = upper(btrim(coalesce(x ->> 'product_code', '')))),
            btrim(x ->> 'description'), (x ->> 'quantity')::numeric, btrim(x ->> 'unit'), round((x ->> 'unit_price')::numeric, 2));
  end loop;
  select * into v from quote_versions where id = v.id;   -- totals re-derived by the line trigger
  return v;
end $$;

--
-- Name: quote_lines_problem(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quote_lines_problem(p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare x jsonb; n int := 0; v_qty numeric; v_price numeric;
begin
  if jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) = 0 then return jsonb_build_object('code', 'INVALID', 'detail', 'add at least one line'); end if;
  if jsonb_array_length(p_lines) > 50 then return jsonb_build_object('code', 'INVALID', 'detail', 'at most 50 lines'); end if;
  for x in select * from jsonb_array_elements(p_lines) loop
    n := n + 1;
    if coalesce(x ->> 'line_kind', '') not in ('MATERIAL', 'LABOUR', 'EQUIPMENT', 'OTHER') then return jsonb_build_object('code', 'INVALID', 'detail', format('line %s: choose material, labour, equipment or other', n)); end if;
    if length(btrim(coalesce(x ->> 'description', ''))) not between 2 and 500 then return jsonb_build_object('code', 'INVALID', 'detail', format('line %s: describe it', n)); end if;
    if length(btrim(coalesce(x ->> 'unit', ''))) not between 1 and 20 then return jsonb_build_object('code', 'INVALID', 'detail', format('line %s: give the unit (e.g. m², LM, EA, hrs)', n)); end if;
    begin v_qty := (x ->> 'quantity')::numeric; v_price := (x ->> 'unit_price')::numeric;
    exception when others then return jsonb_build_object('code', 'INVALID', 'detail', format('line %s: quantity and price are numbers', n)); end;
    if v_qty is null or v_qty <= 0 or v_qty > 100000 then return jsonb_build_object('code', 'INVALID', 'detail', format('line %s: the quantity must be more than 0', n)); end if;
    if v_price is null or v_price < 0 or v_price > 1000000 then return jsonb_build_object('code', 'INVALID', 'detail', format('line %s: the price cannot be negative', n)); end if;
    if x ->> 'line_kind' = 'MATERIAL' and not exists (select 1 from products p where p.product_code = upper(btrim(coalesce(x ->> 'product_code', ''))) and p.is_active) then
      return jsonb_build_object('code', 'INVALID', 'detail', format('line %s: pick the product for a material line', n));
    end if;
  end loop;
  return null;
end $$;

--
-- Name: quote_publish_payload(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quote_publish_payload(p_quote uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('quote_number', q.quote_number, 'quote_id', q.id, 'customer_number', c.customer_number, 'customer_id', c.id,
    'property_number', pr.property_number, 'property_id', pr.id,
    'customer_fields', jsonb_strip_nulls(jsonb_build_object('fldzmWSHtLVZ4OTmZ', c.customer_number, 'fldI46VewtlNRnwui', c.display_name, 'fldNcSkEiFnb8m4XP', c.email,
      'fldvBKPgd3UeIDYO4', c.phone, 'fldisVgB2WysksjwW', at_title(c.customer_type),
      'fldfNc5n8m2kjiRcB', case when c.preferred_contact = 'SMS' then 'SMS' else at_title(c.preferred_contact) end, 'fldNu4bbDXjMbwmZ8', c.customer_since::text, 'fldDClu1e0ffwnojn', c.id::text)),
    'property_fields', jsonb_strip_nulls(jsonb_build_object('fldIy8ab7Ky67jL31', pr.property_number, 'fldu0CsGG5uPOVbRN', pr.address_line1, 'fldl6gKbKuZSF9MJG', pr.suburb,
      'fldYjfr3STs04XDZr', pr.state, 'flduw5J4VyRoOqEE2', pr.postcode, 'fldMH8wYXmkAYXCxe', at_title(pr.property_type), 'fldhsHUPCZ0pMbXeV', pr.storeys,
      'fldP4PWGxdLZrA5ge', pr.access_notes, 'fldm6rtleyV6yp8ZS', pr.id::text)),
    'quote_fields', jsonb_strip_nulls(jsonb_build_object('fldyP20HNafS614d5', q.quote_number, 'fldQpTa5tvrzlNg1h', sm_label('quote', q.status),
      'fldEjEqlzE8Y0M1nf', qv.version_number, 'fldbfUE8DVh1Dwjfs', qv.total_inc_gst,
      'fldOaXGsOgYHuWFYg', case q.job_type when 'FULL_REROOF' then 'Full Re-roof' else at_title(q.job_type) end,
      'fldhY6d0ikMnsc7D3', at_title(i.roof_type), 'fldLjvBaV1EFB5RMG', i.roof_area_sqm, 'fld5Bz9FDhJSPibPk', est.full_name, 'flduF4QFGUWbkuR2d', at_title(q.lead_source),
      'fldHSFkvwuVLfAS7J', q.created_on::text, 'fldMnoHiondm5jBWv', q.sent_on::text, 'fldVUpqZkVKid3Fyy', q.id::text)))
  from quotes q join customers c on c.id = q.customer_id join properties pr on pr.id = q.property_id
  join lateral (select * from quote_versions v where v.quote_id = q.id order by version_number desc limit 1) qv on true
  left join inspections i on i.id = q.inspection_id left join employees est on est.id = q.estimator_id
  where q.id = p_quote
$$;

--
-- Name: quote_version_lines_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quote_version_lines_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_version uuid := coalesce(new.quote_version_id, old.quote_version_id);
begin
  if exists (select 1 from quotes where accepted_version_id = v_version) then
    raise exception 'quote version % is accepted and immutable; record a variation instead', v_version
      using errcode = 'check_violation';
  end if;
  update quote_versions set gst_rate = gst_rate where id = v_version;   -- re-derive header
  return null;
end $$;

--
-- Name: reconciliation_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reconciliation_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_key text NOT NULL,
    trigger text NOT NULL,
    mode text NOT NULL,
    status text DEFAULT 'RUNNING'::text NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    scope jsonb,
    CONSTRAINT reconciliation_runs_mode_check CHECK ((mode = ANY (ARRAY['observe'::text, 'repair'::text]))),
    CONSTRAINT reconciliation_runs_status_check CHECK ((status = ANY (ARRAY['RUNNING'::text, 'COMPLETED'::text, 'FAILED'::text]))),
    CONSTRAINT reconciliation_runs_trigger_check CHECK ((trigger = ANY (ARRAY['schedule'::text, 'manual'::text, 'test'::text])))
);

--
-- Name: COLUMN reconciliation_runs.scope; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reconciliation_runs.scope IS 'null: the whole base. {kind: invoice_projection_reset, project, record_id, project_id}: one row''s invoice fields';

--
-- Name: reconcile_invoice_projection_reset(public.reconciliation_runs, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_invoice_projection_reset(p_run public.reconciliation_runs, p_table_id text, p_records jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_rec text := p_run.scope ->> 'record_id'; v_fields jsonb; v_corr jsonb := '{}'; f record; v_n int := 0;
begin
  if p_table_id <> 'tblvUPIoebC3zoacv' then
    return jsonb_build_object('ok', true, 'table_id', p_table_id, 'records', 0, 'fields_checked', 0, 'drift', 0, 'corrections', '[]'::jsonb);
  end if;
  select y -> 'fields' into v_fields from jsonb_array_elements(coalesce(p_records, '[]'::jsonb)) y where y ->> 'id' = v_rec limit 1;
  if v_fields is null then
    return jsonb_build_object('ok', false, 'table_id', p_table_id, 'reason', 'the scoped row ' || v_rec || ' was not in the read');
  end if;
  -- Re-checked under the run: a preview prepared since the run started keeps its projection.
  if exists (select 1 from approvals where entity_id = (p_run.scope ->> 'project_id')::uuid and action_type = 'CREATE_INVOICE' and status = 'PENDING')
     or exists (select 1 from invoices where project_id = (p_run.scope ->> 'project_id')::uuid and invoice_type = 'FINAL' and status <> 'VOIDED') then
    return jsonb_build_object('ok', true, 'table_id', p_table_id, 'records', 1, 'fields_checked', 0, 'drift', 0, 'corrections', '[]'::jsonb,
                              'note', 'a preview or invoice appeared: nothing reset');
  end if;
  for f in select * from invoice_projection_fields() loop
    if coalesce(at_norm(v_fields -> f.field_id), '') <> '' then
      v_n := v_n + 1;
      v_corr := v_corr || jsonb_build_object(f.field_id, null);
      insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, field, expected, actual, classification, action, detail)
      values (p_run.id, 'AIRTABLE', 'project', p_run.scope ->> 'project', v_rec, f.airtable_name, null, left(at_norm(v_fields -> f.field_id), 500),
              'SAFE_AUTO_REPAIR', 'REPAIRED_AIRTABLE', 'demo:reset: the withdrawn invoice preview is removed from Airtable (no preview in flight, no invoice)');
    end if;
  end loop;
  if v_n > 0 then
    perform airtable_record_writes('reconcile:' || p_run.run_key, p_table_id, v_rec, v_corr, v_fields, 'reconcile:' || p_run.run_key);
  end if;
  return jsonb_build_object('ok', true, 'table_id', p_table_id, 'records', 1, 'fields_checked', 3, 'drift', v_n,
    'corrections', case when v_n > 0 then jsonb_build_array(jsonb_build_object('id', v_rec, 'fields', v_corr)) else '[]'::jsonb end);
end $$;

--
-- Name: reject_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception '% is append-only (% rejected)', tg_table_name, tg_op using errcode = 'insufficient_privilege';
end $$;

--
-- Name: sm_label(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sm_label(p_machine text, p_state text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce((select label from state_machine_states where machine = p_machine and state = p_state), p_state)
$$;

--
-- Name: sm_state(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sm_state(p_machine text, p_label text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select state from state_machine_states where machine = p_machine and (lower(label) = lower(btrim(p_label)) or state = upper(btrim(p_label)))
$$;

--
-- Name: stable_uuid(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stable_uuid(p_kind text, p_key text) RETURNS uuid
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  select (substr(h, 1, 12) || '8' || substr(h, 14, 3) ||
          substr('89ab', (get_byte(decode(substr(h, 17, 2), 'hex'), 0) % 4) + 1, 1) ||
          substr(h, 18, 15))::uuid
    from (select md5('roofops:' || p_kind || ':' || p_key) as h) s
$$;

--
-- Name: employees; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.employees (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_code text NOT NULL,
    full_name text NOT NULL,
    email text NOT NULL,
    role text NOT NULL,
    auth_user_id uuid,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    record_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT employees_email_check CHECK ((email ~* '^[^@]+@[^@]+\.[^@]+$'::text)),
    CONSTRAINT employees_role_check CHECK ((role = ANY (ARRAY['ADMIN'::text, 'OPERATIONS_MANAGER'::text, 'PROJECT_MANAGER'::text, 'ESTIMATOR'::text, 'PURCHASING'::text, 'FINANCE'::text, 'FIELD_CREW'::text, 'VIEWER'::text])))
);

--
-- Name: staff_role_allowed(public.employees, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_role_allowed(p_emp public.employees, p_setting text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_emp.id is not null and p_emp.is_active
     and p_emp.role = any (string_to_array(coalesce((select value from app_settings where key = p_setting), ''), ','))
$$;

--
-- Name: staff_session_employee(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_session_employee(p_token text) RETURNS public.employees
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
  select e.* from staff_sessions s join employees e on e.id = s.employee_id
   where s.token_sha256 = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
     and s.revoked_at is null and s.expires_at > now() and e.is_active
$$;

--
-- Name: state_transition_allowed(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.state_transition_allowed(p_machine text, p_from text, p_to text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_from is not distinct from p_to
      or exists (select 1 from state_transitions where machine = p_machine and from_state = p_from and to_state = p_to)
$$;

--
-- Name: touch_invoice_from_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_invoice_from_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  update invoices set gst_rate = gst_rate where id = coalesce(new.invoice_id, old.invoice_id);
  return null;
end $$;

--
-- Name: touch_purchase_order_from_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_purchase_order_from_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  update purchase_orders set gst_rate = gst_rate where id = coalesce(new.purchase_order_id, old.purchase_order_id);
  return null;
end $$;

--
-- Name: touch_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_row() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at := now();
  if tg_op = 'UPDATE' then
    new.record_version := old.record_version + 1;
  end if;
  return new;
end $$;

--
-- Name: verify_audit_chain(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_audit_chain() RETURNS bigint
    LANGUAGE plpgsql STABLE
    AS $$
declare r audit_events; v_prev text := null;
begin
  for r in select * from audit_events order by seq loop
    if r.prev_hash is distinct from v_prev or r.row_hash <> audit_row_hash(v_prev, r) then
      return r.seq;
    end if;
    v_prev := r.row_hash;
  end loop;
  return null;
end $$;

--
-- Name: visit_crew_conflict(uuid[], timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.visit_crew_conflict(p_crew uuid[], p_start timestamp with time zone, p_end timestamp with time zone, p_except uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('employee', e.employee_code, 'name', e.full_name, 'job_number', j.job_number,
                            'from', j.scheduled_start, 'to', j.scheduled_end)
    from job_assignments a join jobs j on j.id = a.job_id join employees e on e.id = a.employee_id
   where a.employee_id = any (p_crew) and j.id is distinct from p_except
     and j.status in ('SCHEDULED', 'IN_PROGRESS')
     and j.scheduled_start < p_end and j.scheduled_end > p_start
   order by j.scheduled_start limit 1
$$;

--
-- Name: visit_times_problem(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.visit_times_problem(p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when p_start is null or p_end is null then jsonb_build_object('code', 'INVALID_TIMES', 'detail', 'a visit needs a start and an end')
    when p_end <= p_start then jsonb_build_object('code', 'INVALID_TIMES', 'detail', 'the end must be after the start')
    when (p_start at time zone 'Australia/Brisbane')::date < app_today() then
      jsonb_build_object('code', 'IN_PAST', 'detail', format('the start is before today (%s)', to_char(app_today(), 'DD Mon YYYY')))
    when p_end - p_start > make_interval(days => coalesce((select value::int from app_settings where key = 'schedule.max_visit_days'), 14)) then
      jsonb_build_object('code', 'TOO_LONG', 'detail', format('a visit can be at most %s days; schedule longer work as several visits',
        coalesce((select value from app_settings where key = 'schedule.max_visit_days'), '14')))
  end
$$;

--
-- Name: web_customer_correct_contact(text, text, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_customer_correct_contact(p_token text, p_customer text, p_expected_version integer, p_phone text, p_email text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $_$
declare
  v_emp employees := staff_session_employee(p_token); c customers; v_before jsonb;
  v_email text := nullif(lower(btrim(coalesce(p_email, ''))), ''); v_phone text := nullif(btrim(regexp_replace(coalesce(p_phone, ''), '\s+', ' ', 'g')), '');
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if not staff_role_allowed(v_emp, 'customer.correction_roles') then
    return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED', 'detail', format('%s (%s) may not correct customer details', v_emp.employee_code, v_emp.role));
  end if;
  select * into c from customers where customer_number = upper(btrim(coalesce(p_customer, ''))) for update;
  if c.id is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', coalesce(p_customer, 'no customer')); end if;
  if p_expected_version is distinct from c.record_version then
    return jsonb_build_object('ok', false, 'code', 'STALE', 'detail', format('%s changed since you opened it; reload and check it again', c.customer_number));
  end if;
  if v_phone is null and v_email is null then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'keep a phone number or an email address'); end if;
  if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'the email address does not look right'); end if;
  if v_phone is not null and length(regexp_replace(v_phone, '[^0-9]', '', 'g')) not between 8 and 15 then
    return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'the phone number needs 8 to 15 digits');
  end if;
  if length(v_reason) not between 5 and 500 then return jsonb_build_object('ok', false, 'code', 'REASON_REQUIRED', 'detail', 'say why (a few words)'); end if;
  if c.phone is not distinct from v_phone and c.email is not distinct from v_email then
    return jsonb_build_object('ok', true, 'unchanged', true, 'customer_number', c.customer_number, 'record_version', c.record_version);
  end if;
  v_before := jsonb_build_object('phone', c.phone, 'email', c.email);
  update customers set phone = v_phone, email = v_email where id = c.id returning * into c;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
  values ('USER', v_emp.employee_code, 'customer.contact_corrected', 'customer', c.id, c.customer_number, v_before,
          jsonb_build_object('phone', c.phone, 'email', c.email), v_reason);
  return jsonb_build_object('ok', true, 'customer_number', c.customer_number, 'record_version', c.record_version, 'phone', c.phone, 'email', c.email);
end $_$;

--
-- Name: web_inspection_book(text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_inspection_book(p_token text, p_lead text, p_inspector text, p_when timestamp with time zone, p_request_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare v_emp employees := staff_session_employee(p_token); l leads; i inspections; a employees;
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if not staff_role_allowed(v_emp, 'sales.roles') then return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED', 'detail', format('%s (%s) may not book inspections', v_emp.employee_code, v_emp.role)); end if;
  if length(coalesce(p_request_key, '')) not between 8 and 100 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'missing request key'); end if;
  select * into i from inspections where request_key = p_request_key;
  if i.id is not null then return jsonb_build_object('ok', true, 'duplicate', true, 'inspection_number', i.inspection_number); end if;
  select * into l from leads where lead_number = upper(btrim(coalesce(p_lead, ''))) for update;
  if l.id is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', coalesce(p_lead, 'no enquiry')); end if;
  if l.property_id is null then return jsonb_build_object('ok', false, 'code', 'NOT_CONVERTED', 'detail', 'record the customer and the site first'); end if;
  if l.status not in ('CONTACTED', 'INSPECTION_BOOKED', 'NEW') then return jsonb_build_object('ok', false, 'code', 'INVALID_TRANSITION', 'detail', format('%s is %s', l.lead_number, lower(replace(l.status, '_', ' ')))); end if;
  if exists (select 1 from inspections x where x.lead_id = l.id and x.status = 'SCHEDULED') then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_BOOKED', 'detail', 'an inspection is already booked for this enquiry; record or cancel it first');
  end if;
  select * into a from employees where employee_code = upper(btrim(coalesce(p_inspector, ''))) and is_active;
  if a.id is null or not staff_role_allowed(a, 'sales.inspector_roles') then
    return jsonb_build_object('ok', false, 'code', 'INSPECTOR_UNKNOWN', 'detail', format('%s cannot inspect (an estimator or a manager inspects)', coalesce(nullif(p_inspector, ''), 'nobody')));
  end if;
  if p_when is null or (p_when at time zone 'Australia/Brisbane')::date < app_today() then
    return jsonb_build_object('ok', false, 'code', 'IN_PAST', 'detail', format('pick a time from today (%s)', to_char(app_today(), 'DD Mon YYYY')));
  end if;
  if exists (select 1 from inspections x where x.inspector_id = a.id and x.status = 'SCHEDULED' and abs(extract(epoch from x.scheduled_for - p_when)) < 3600) then
    return jsonb_build_object('ok', false, 'code', 'INSPECTOR_BUSY', 'detail', format('%s already has an inspection within an hour of that time', a.full_name));
  end if;
  insert into inspections (inspection_number, property_id, lead_id, inspector_id, status, scheduled_for, request_key)
  values (next_friendly_id('INS', extract(year from app_today())::int), l.property_id, l.id, a.id, 'SCHEDULED', p_when, p_request_key) returning * into i;
  update leads set status = 'INSPECTION_BOOKED', record_version = record_version + 1, updated_at = now() where id = l.id;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
  values ('USER', v_emp.employee_code, 'inspection.booked', 'inspection', i.id, l.lead_number,
          jsonb_build_object('inspection', i.inspection_number, 'inspector', a.employee_code, 'when', p_when), format('Inspection %s booked with %s', i.inspection_number, a.full_name));
  return jsonb_build_object('ok', true, 'inspection_number', i.inspection_number, 'record_version', i.record_version);
end $$;

--
-- Name: web_inspection_record(text, text, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_inspection_record(p_token text, p_inspection text, p_expected_version integer, p_action text, p_findings jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare
  v_emp employees := staff_session_employee(p_token); i inspections; v_area numeric; v_pitch numeric; l leads;
  v_roof text := nullif(p_findings ->> 'roof_type', ''); v_method text := nullif(p_findings ->> 'measurement_method', '');
  v_notes text := nullif(btrim(coalesce(p_findings ->> 'findings', '')), '');
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if not staff_role_allowed(v_emp, 'sales.roles') then return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED', 'detail', format('%s (%s) may not record inspections', v_emp.employee_code, v_emp.role)); end if;
  select * into i from inspections where inspection_number = upper(btrim(coalesce(p_inspection, ''))) for update;
  if i.id is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', coalesce(p_inspection, 'no inspection')); end if;
  if p_expected_version is distinct from i.record_version then return jsonb_build_object('ok', false, 'code', 'STALE', 'detail', format('%s changed since you opened it; reload and check it again', i.inspection_number)); end if;
  if i.status <> 'SCHEDULED' then return jsonb_build_object('ok', false, 'code', 'INVALID_TRANSITION', 'detail', format('%s is %s', i.inspection_number, lower(i.status))); end if;
  select * into l from leads where id = i.lead_id for update;
  if p_action = 'cancel' then
    if length(coalesce(v_notes, '')) < 5 then return jsonb_build_object('ok', false, 'code', 'REASON_REQUIRED', 'detail', 'say why (a few words)'); end if;
    update inspections set status = 'CANCELLED', findings = v_notes, record_version = record_version + 1, updated_at = now() where id = i.id returning * into i;
    update leads set status = 'CONTACTED', record_version = record_version + 1, updated_at = now() where id = l.id and status = 'INSPECTION_BOOKED';
  elsif p_action = 'complete' then
    if v_roof is null or v_roof not in ('TILE', 'TERRACOTTA_TILE', 'METAL', 'COLORBOND', 'ZINCALUME', 'OTHER') then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'choose the roof type'); end if;
    begin v_area := nullif(p_findings ->> 'roof_area_sqm', '')::numeric; v_pitch := nullif(p_findings ->> 'pitch_degrees', '')::numeric;
    exception when others then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'area and pitch are numbers'); end;
    if v_area is not null and (v_area <= 0 or v_area > 100000) then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'the roof area must be more than 0 m²'); end if;
    if v_pitch is not null and (v_pitch < 0 or v_pitch > 75) then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'the pitch is 0 to 75 degrees'); end if;
    if v_area is not null and (v_method is null or v_method not in ('TAPE', 'DRONE', 'AERIAL_IMAGERY', 'PLAN_TAKEOFF')) then
      return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'say how the area was measured');
    end if;
    if length(coalesce(v_notes, '')) < 5 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'write what you found (a few words at least)'); end if;
    update inspections set status = 'COMPLETED', inspected_on = app_today(), roof_type = v_roof, roof_area_sqm = round(v_area, 1), pitch_degrees = round(v_pitch, 1),
                           measurement_method = case when v_area is null then null else v_method end, findings = v_notes, inspector_id = coalesce(inspector_id, v_emp.id),
                           record_version = record_version + 1, updated_at = now() where id = i.id returning * into i;
    update properties set roof_type = v_roof, updated_at = now() where id = i.property_id and roof_type is distinct from v_roof;
  else
    return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'unknown action');
  end if;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
  values ('USER', v_emp.employee_code, 'inspection.' || case when p_action = 'cancel' then 'cancelled' else 'completed' end, 'inspection', i.id, coalesce(l.lead_number, i.inspection_number),
          jsonb_build_object('inspection', i.inspection_number, 'roof_type', i.roof_type, 'roof_area_sqm', i.roof_area_sqm), v_notes);
  return jsonb_build_object('ok', true, 'inspection_number', i.inspection_number, 'status', i.status, 'record_version', i.record_version);
end $$;

--
-- Name: web_invoice_decide(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_invoice_decide(p_token text, p_approval text, p_payload_hash text, p_decision text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare
  v_emp employees := staff_session_employee(p_token); v_ap approvals; p projects; v_event text; v_res jsonb; o outbox; i invoices;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if p_decision not in ('approve', 'reject') then return jsonb_build_object('ok', false, 'code', 'INVALID_DECISION'); end if;
  if not (v_emp.role = any (string_to_array((select value from app_settings where key = 'invoice.approver_roles'), ','))) then
    return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED', 'detail', format('%s (%s) may not approve invoices', v_emp.employee_code, v_emp.role));
  end if;
  select * into v_ap from approvals where approval_number = p_approval and action_type = 'CREATE_INVOICE';
  if v_ap.id is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND'); end if;
  select * into p from projects where id = v_ap.entity_id for update;          -- the same lock the Airtable path takes
  select * into v_ap from approvals where id = v_ap.id for update;
  if v_ap.status <> 'PENDING' then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_PROCESSED', 'detail', format('%s is %s', v_ap.approval_number, v_ap.status));
  end if;
  if p_payload_hash is distinct from v_ap.payload_hash then
    return jsonb_build_object('ok', false, 'code', 'PREVIEW_CHANGED', 'detail', 'the preview changed since you opened it; reload and check it again');
  end if;
  if p_decision = 'approve' then
    -- Two people, both proven: the requester must be a signed-in employee too (prepared in the dashboard). A preview from
    -- Airtable names the shared account's identity (or nobody), which proves no individual.
    if v_ap.requested_by_employee_id is null or v_ap.idempotency_key not like 'approval:dashboard:%' then
      return jsonb_build_object('ok', false, 'code', 'REQUESTER_UNKNOWN',
        'detail', 'it was not prepared by a signed-in person (it came from the shared Airtable account), so two people cannot be proven. Reject it here and prepare it again from the dashboard (or approve it in Airtable)');
    end if;
    if v_ap.requested_by_employee_id = v_emp.id then
      return jsonb_build_object('ok', false, 'code', 'SAME_PERSON', 'detail', 'you prepared it, so someone else must approve it');
    end if;
  end if;
  v_event := 'dashboard:decide:' || v_ap.approval_number || ':' || gen_random_uuid();
  v_res := wf_invoice_decide_core(jsonb_build_object('event_id', v_event, 'correlation_id', v_event,
             'event_type', case p_decision when 'approve' then 'invoice.approved' else 'invoice.rejected' end,
             'source', 'roofops-dashboard', 'actor_id', v_emp.employee_code, 'actor_name', v_emp.full_name, 'occurred_at', now(),
             'payload', jsonb_build_object('project_number', p.project_number, 'approval_number', v_ap.approval_number,
                                           'payload_hash', v_ap.payload_hash, 'reason', v_note)),
           'dashboard:' || v_emp.employee_code, v_emp.id);
  if v_res ->> 'outcome' = 'APPROVED' then
    select * into o from outbox where idempotency_key = v_res ->> 'xero_key';
    select * into i from invoices where id = o.aggregate_id;
    insert into xero_dispatch_requests (invoice_id, generation, xero_key, payload_sha256, requested_by, reason)
    values (i.id, o.generation, o.idempotency_key, xero_payload_sha256(o.payload), v_emp.id, 'approved in the dashboard by ' || v_emp.employee_code)
    on conflict do nothing;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
    values ('USER', v_emp.employee_code, 'xero.dispatch_requested', 'invoice', i.id, i.invoice_number,
            jsonb_build_object('generation', o.generation, 'xero_key', o.idempotency_key), 'Approved in the dashboard: create the Xero draft');
  end if;
  return v_res || jsonb_build_object('ok', v_res ->> 'outcome' in ('APPROVED', 'REJECTED_BY_APPROVER'),
    'invoice_number', (select invoice_number from invoices where approval_id = v_ap.id));
end $$;

--
-- Name: web_invoice_overview(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_invoice_overview(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare v_emp employees := staff_session_employee(p_token);
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  return jsonb_build_object('ok', true,
    'me', jsonb_build_object('employee_code', v_emp.employee_code, 'name', v_emp.full_name, 'role', v_emp.role,
      'may_prepare', v_emp.role = any (string_to_array((select value from app_settings where key = 'invoice.prepare_roles'), ',')),
      'may_approve', v_emp.role = any (string_to_array((select value from app_settings where key = 'invoice.approver_roles'), ',')),
      'may_dispatch', v_emp.role = any (string_to_array((select value from app_settings where key = 'xero.dispatch_roles'), ','))),
    'pending', coalesce((
      select jsonb_agg(jsonb_build_object('approval_number', a.approval_number, 'project_number', a.business_reference,
               'payload_hash', a.payload_hash, 'preview', a.action_payload, 'requested_at', a.created_at, 'expires_at', a.expires_at,
               'requested_by', re.full_name, 'i_requested_it', a.requested_by_employee_id = v_emp.id,
               'requested_via', case when a.idempotency_key like 'approval:dashboard:prepare:%' then 'dashboard'
                                     when a.idempotency_key like 'approval:dashboard:%' then 'copilot' else 'airtable' end)
             order by a.created_at)
        from approvals a left join employees re on re.id = a.requested_by_employee_id
       where a.action_type = 'CREATE_INVOICE' and a.status = 'PENDING' and a.expires_at > now()), '[]'::jsonb),
    'drafts', coalesce((
      select jsonb_agg(x.d order by x.d ->> 'invoice_number')
        from (select xero_draft_progress(i.id) d from invoices i
               where i.invoice_type = 'FINAL' and i.status <> 'VOIDED'   -- a voided final is handled under Invoice reissues
                 and exists (select 1 from outbox o where o.topic = 'xero.create_draft_invoice' and o.aggregate_id = i.id)) x
       where x.d is not null and (x.d ->> 'state' <> 'CREATED' or exists (select 1 from outbox o where o.idempotency_key = xero_draft_outbox_key(
               (select id from invoices where invoice_number = x.d ->> 'invoice_number'), (x.d ->> 'generation')::int) and o.dispatched_at > now() - interval '2 days'))), '[]'::jsonb));
end $$;

--
-- Name: web_invoice_prepare(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_invoice_prepare(p_token text, p_project text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare v_emp employees := staff_session_employee(p_token); v_event text; v_res jsonb;
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if not (v_emp.role = any (string_to_array((select value from app_settings where key = 'invoice.prepare_roles'), ','))) then
    return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED', 'detail', format('%s (%s) may not prepare invoices', v_emp.employee_code, v_emp.role));
  end if;
  v_event := 'dashboard:prepare:' || coalesce(p_project, '') || ':' || gen_random_uuid();
  v_res := wf_invoice_prepare(jsonb_build_object('event_id', v_event, 'correlation_id', v_event, 'event_type', 'invoice.prepare_requested',
             'source', 'roofops-dashboard', 'actor_id', v_emp.employee_code, 'actor_name', v_emp.full_name, 'occurred_at', now(),
             'payload', jsonb_build_object('project_number', p_project)), 'dashboard:' || v_emp.employee_code);
  if v_res ->> 'outcome' = 'PREVIEW_READY' then
    update approvals set requested_by_employee_id = v_emp.id, requested_by_actor_type = 'USER'
     where approval_number = v_res ->> 'approval_number' and status = 'PENDING' and requested_by_employee_id is null;
  end if;
  return v_res || jsonb_build_object('ok', v_res ->> 'outcome' in ('PREVIEW_READY', 'ALREADY_PENDING'));
end $$;

--
-- Name: web_lead_convert(text, text, integer, text, jsonb, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_lead_convert(p_token text, p_lead text, p_expected_version integer, p_customer_number text, p_customer jsonb, p_property jsonb, p_confirm_new boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $_$
declare
  v_emp employees := staff_session_employee(p_token); l leads; c customers; pr properties; v_look jsonb; v_new boolean := false;
  v_line1 text := btrim(regexp_replace(coalesce(p_property ->> 'address_line1', ''), '\s+', ' ', 'g'));
  v_suburb text := initcap(btrim(regexp_replace(coalesce(p_property ->> 'suburb', ''), '\s+', ' ', 'g'))); v_state text := upper(btrim(coalesce(p_property ->> 'state', '')));
  v_post text := btrim(coalesce(p_property ->> 'postcode', '')); v_ptype text := coalesce(p_property ->> 'property_type', 'DETACHED_HOUSE');
  v_storeys int; v_ctype text := coalesce(p_customer ->> 'customer_type', 'RESIDENTIAL');
  v_cname text := btrim(regexp_replace(coalesce(p_customer ->> 'display_name', ''), '\s+', ' ', 'g'));
  v_cemail text := nullif(lower(btrim(coalesce(p_customer ->> 'email', ''))), ''); v_cphone text := nullif(btrim(coalesce(p_customer ->> 'phone', '')), '');
  v_other customers;
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if not staff_role_allowed(v_emp, 'sales.roles') then return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED', 'detail', format('%s (%s) may not create customers', v_emp.employee_code, v_emp.role)); end if;
  select * into l from leads where lead_number = upper(btrim(coalesce(p_lead, ''))) for update;
  if l.id is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', coalesce(p_lead, 'no enquiry')); end if;
  if l.customer_id is not null and l.property_id is not null then
    return jsonb_build_object('ok', true, 'duplicate', true, 'lead_number', l.lead_number,
      'customer_number', (select customer_number from customers where id = l.customer_id), 'property_number', (select property_number from properties where id = l.property_id));
  end if;
  if p_expected_version is distinct from l.record_version then return jsonb_build_object('ok', false, 'code', 'STALE', 'detail', format('%s changed since you opened it; reload and check it again', l.lead_number)); end if;
  if l.status in ('LOST', 'DISQUALIFIED', 'WON') then return jsonb_build_object('ok', false, 'code', 'INVALID_TRANSITION', 'detail', format('%s is %s', l.lead_number, lower(l.status))); end if;

  -- The site first (validation before anything is written).
  if length(v_line1) not between 3 and 200 or length(v_suburb) not between 2 and 80 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'enter the street address and suburb'); end if;
  if v_state not in ('QLD', 'NSW', 'VIC', 'TAS', 'SA', 'WA', 'NT', 'ACT') then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'choose the state'); end if;
  if v_post !~ '^[0-9]{4}$' then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'the postcode has 4 digits'); end if;
  if v_ptype not in ('DETACHED_HOUSE', 'TOWNHOUSE', 'SMALL_COMMERCIAL', 'INDUSTRIAL', 'STRATA_COMPLEX') then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'choose the kind of building'); end if;
  begin v_storeys := coalesce(nullif(p_property ->> 'storeys', '')::int, 1); exception when others then v_storeys := 0; end;
  if v_storeys not between 1 and 6 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'storeys: 1 to 6'); end if;

  -- Sales reliability: a site has one active owner (reconciliation shows one in Airtable). A site another customer owns
  -- is never given a second owner here, and ownership is never moved: a tenant, a property manager or a new owner after
  -- a sale is a decision for a person. Checked before anything is written.
  select * into pr from properties where lower(address_line1) = lower(v_line1) and upper(suburb) = upper(v_suburb) and state = v_state and postcode = v_post;
  if pr.id is not null then
    select x.* into v_other from customer_properties cp join customers x on x.id = cp.customer_id
     where cp.property_id = pr.id and cp.relationship = 'OWNER' and cp.valid_to is null;
    if v_other.id is not null and (nullif(btrim(coalesce(p_customer_number, '')), '') is null or v_other.customer_number <> upper(btrim(p_customer_number))) then
      return jsonb_build_object('ok', false, 'code', 'SITE_OWNED_BY_ANOTHER_CUSTOMER', 'property_number', pr.property_number,
        'owner', jsonb_build_object('customer_number', v_other.customer_number, 'display_name', v_other.display_name),
        'detail', format('%s is owned by %s (%s). If this job is theirs, pick that customer. A tenant, property manager or new owner after a sale needs an admin decision; nothing was changed',
                         pr.property_number, v_other.display_name, v_other.customer_number));
    end if;
  end if;
  pr := null; v_other := null;

  if nullif(btrim(coalesce(p_customer_number, '')), '') is not null then
    select * into c from customers where customer_number = upper(btrim(p_customer_number)) and status = 'ACTIVE';
    if c.id is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', format('%s is not an active customer', p_customer_number)); end if;
  else
    if length(v_cname) not between 2 and 120 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'enter the customer''s name'); end if;
    if v_ctype not in ('RESIDENTIAL', 'COMMERCIAL', 'BUILDER', 'STRATA') then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'choose the kind of customer'); end if;
    if v_cemail is null and v_cphone is null then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'enter a phone number or an email address'); end if;
    if v_cemail is not null and v_cemail !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'the email address does not look right'); end if;
    v_look := customer_lookalikes(v_cname, v_cemail, v_cphone);
    if jsonb_array_length(v_look) > 0 and not coalesce(p_confirm_new, false) then
      return jsonb_build_object('ok', false, 'code', 'POSSIBLE_DUPLICATE', 'lookalikes', v_look,
        'detail', format('%s already looks like %s; pick that customer, or confirm this is someone else', v_cname,
                         (select string_agg((x ->> 'display_name') || ' (' || (x ->> 'customer_number') || ')', ', ') from jsonb_array_elements(v_look) x)));
    end if;
    insert into customers (customer_number, customer_type, display_name, email, phone, preferred_contact, customer_since)
    values (next_friendly_id('CUST'), v_ctype, v_cname, v_cemail, v_cphone, case when v_cphone is not null then 'PHONE' else 'EMAIL' end, app_today())
    returning * into c;
    v_new := true;
    for v_other in select x.* from customers x join jsonb_array_elements(v_look) j on j ->> 'customer_number' = x.customer_number loop
      insert into customer_match_candidates (customer_id, candidate_customer_id, match_score, match_reasons)
      values (least(c.id, v_other.id), greatest(c.id, v_other.id), 0.700,
              (select j -> 'reasons' from jsonb_array_elements(v_look) j where j ->> 'customer_number' = v_other.customer_number))
      on conflict do nothing;
    end loop;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
    values ('USER', v_emp.employee_code, 'customer.created', 'customer', c.id, c.customer_number,
            jsonb_build_object('from_lead', l.lead_number, 'confirmed_not_duplicate_of', v_look), format('Customer %s from enquiry %s', v_cname, l.lead_number));
  end if;

  select * into pr from properties where lower(address_line1) = lower(v_line1) and upper(suburb) = upper(v_suburb) and state = v_state and postcode = v_post for update;
  -- The same rule under the site's lock (two conversions at once): never a second owner, even if the check above raced.
  if pr.id is not null and exists (select 1 from customer_properties cp where cp.property_id = pr.id and cp.relationship = 'OWNER'
                                     and cp.valid_to is null and cp.customer_id <> c.id) then
    raise exception '% is owned by another customer; nothing was changed', pr.property_number using errcode = 'unique_violation';
  end if;
  if pr.id is null then
    insert into properties (property_number, address_line1, address_line2, suburb, state, postcode, property_type, storeys, access_notes)
    values (next_friendly_id('PROP'), v_line1, nullif(btrim(coalesce(p_property ->> 'address_line2', '')), ''), v_suburb, v_state, v_post, v_ptype, v_storeys,
            nullif(btrim(coalesce(p_property ->> 'access_notes', '')), ''))
    returning * into pr;
  end if;
  insert into customer_properties (customer_id, property_id, relationship, valid_from) values (c.id, pr.id, 'OWNER', app_today())
  on conflict (customer_id, property_id, relationship) do nothing;   -- only "already this customer's"; a second owner raises
  update leads set customer_id = c.id, property_id = pr.id, status = case when status = 'NEW' then 'CONTACTED' else status end,
                   contacted_at = coalesce(contacted_at, now()), record_version = record_version + 1, updated_at = now() where id = l.id returning * into l;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
  values ('USER', v_emp.employee_code, 'lead.converted', 'lead', l.id, l.lead_number,
          jsonb_build_object('customer', c.customer_number, 'new_customer', v_new, 'property', pr.property_number),
          format('%s is %s at %s', l.lead_number, c.display_name, pr.property_number));
  return jsonb_build_object('ok', true, 'lead_number', l.lead_number, 'customer_number', c.customer_number, 'new_customer', v_new,
                            'property_number', pr.property_number, 'record_version', l.record_version);
end $_$;

--
-- Name: web_lead_create(text, text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_lead_create(p_token text, p_contact_name text, p_phone text, p_email text, p_address text, p_source text, p_notes text, p_request_key text, p_confirm boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $_$
declare
  v_emp employees := staff_session_employee(p_token); l leads;
  v_name text := btrim(regexp_replace(coalesce(p_contact_name, ''), '\s+', ' ', 'g'));
  v_email text := nullif(lower(btrim(coalesce(p_email, ''))), ''); v_phone text := nullif(btrim(coalesce(p_phone, '')), '');
  v_digits text; v_similar jsonb;
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if not staff_role_allowed(v_emp, 'sales.roles') then
    return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED', 'detail', format('%s (%s) may not record enquiries', v_emp.employee_code, v_emp.role));
  end if;
  if length(coalesce(p_request_key, '')) not between 8 and 100 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'missing request key'); end if;
  select * into l from leads where request_key = p_request_key;
  if l.id is not null then return jsonb_build_object('ok', true, 'duplicate', true, 'lead_number', l.lead_number); end if;
  if length(v_name) not between 2 and 120 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'enter the person''s name'); end if;
  if v_phone is null and v_email is null then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'enter a phone number or an email address'); end if;
  if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'the email address does not look right'); end if;
  if v_phone is not null and length(regexp_replace(v_phone, '[^0-9]', '', 'g')) not between 8 and 15 then
    return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'the phone number needs 8 to 15 digits');
  end if;
  if coalesce(p_source, '') not in ('GOOGLE_ADS', 'ORGANIC_SEARCH', 'REFERRAL', 'FACEBOOK', 'REPEAT_CUSTOMER', 'BUILDER_REFERRAL', 'LOCAL_SIGNAGE', 'WEBSITE_FORM', 'PHONE', 'OTHER') then
    return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'choose where the enquiry came from');
  end if;
  if length(coalesce(p_notes, '')) > 4000 or length(coalesce(p_address, '')) > 300 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'too long'); end if;
  v_digits := nullif(regexp_replace(coalesce(v_phone, ''), '[^0-9]', '', 'g'), '');
  if v_digits is not null then perform pg_advisory_xact_lock(hashtext('lead:phone:' || v_digits)); end if;   -- always phone, then email
  if v_email is not null then perform pg_advisory_xact_lock(hashtext('lead:email:' || v_email)); end if;
  select jsonb_agg(jsonb_build_object('lead_number', o.lead_number, 'contact_name', o.contact_name, 'status', o.status,
           'received', to_char(o.received_at at time zone 'Australia/Brisbane', 'YYYY-MM-DD'),
           'reasons', to_jsonb(array_remove(array[
             case when v_digits is not null and regexp_replace(coalesce(o.phone, ''), '[^0-9]', '', 'g') = v_digits then 'same phone' end,
             case when v_email is not null and lower(o.email) = v_email then 'same email' end,
             case when lower(o.contact_name) = lower(v_name) then 'same name' end], null))) order by o.received_at desc)
    into v_similar from leads o
   where o.status not in ('LOST', 'DISQUALIFIED', 'WON')
     and ((v_digits is not null and regexp_replace(coalesce(o.phone, ''), '[^0-9]', '', 'g') = v_digits)
          or (v_email is not null and lower(o.email) = v_email) or lower(o.contact_name) = lower(v_name));
  if v_similar is not null and not coalesce(p_confirm, false) then
    return jsonb_build_object('ok', false, 'code', 'POSSIBLE_DUPLICATE_ENQUIRY', 'similar_enquiries', v_similar,
      'lookalikes', customer_lookalikes(v_name, v_email, v_phone),
      'detail', format('%s open enquir%s for this person already (%s); open it instead, or confirm this is a separate job',
                       jsonb_array_length(v_similar), case when jsonb_array_length(v_similar) = 1 then 'y' else 'ies' end,
                       (select string_agg(e ->> 'lead_number', ', ') from jsonb_array_elements(v_similar) e)));
  end if;
  insert into leads (lead_number, source, status, contact_name, email, phone, property_address_text, notes, request_key, created_by, received_at)
  values (next_friendly_id('LEAD', extract(year from app_today())::int), p_source, 'NEW', v_name, v_email, v_phone,
          nullif(btrim(coalesce(p_address, '')), ''), nullif(btrim(coalesce(p_notes, '')), ''), p_request_key, v_emp.id, now())
  returning * into l;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
  values ('USER', v_emp.employee_code, 'lead.created', 'lead', l.id, l.lead_number, jsonb_build_object('source', p_source, 'confirmed_separate_from', case when coalesce(p_confirm, false) then v_similar end),
          format('Enquiry from %s', v_name) || case when coalesce(p_confirm, false) and v_similar is not null then ' (confirmed as separate from an open enquiry)' else '' end);
  return jsonb_build_object('ok', true, 'lead_number', l.lead_number, 'record_version', l.record_version,
                            'lookalikes', customer_lookalikes(v_name, v_email, v_phone),
                            'confirmed_separate', coalesce(p_confirm, false) and v_similar is not null);
end $_$;

--
-- Name: web_lead_update(text, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_lead_update(p_token text, p_lead text, p_action text, p_expected_version integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare v_emp employees := staff_session_employee(p_token); l leads; v_to text; v_reason text := nullif(btrim(coalesce(p_reason, '')), ''); v_from text;
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if not staff_role_allowed(v_emp, 'sales.roles') then return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED', 'detail', format('%s (%s) may not update enquiries', v_emp.employee_code, v_emp.role)); end if;
  select * into l from leads where lead_number = upper(btrim(coalesce(p_lead, ''))) for update;
  if l.id is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', coalesce(p_lead, 'no enquiry')); end if;
  if p_expected_version is distinct from l.record_version then
    return jsonb_build_object('ok', false, 'code', 'STALE', 'detail', format('%s changed since you opened it; reload and check it again', l.lead_number));
  end if;
  v_from := l.status;
  v_to := case
    when p_action = 'contacted' and l.status = 'NEW' then 'CONTACTED'
    when p_action = 'lost' and l.status in ('NEW', 'CONTACTED', 'INSPECTION_BOOKED') then 'LOST'
    when p_action = 'disqualify' and l.status in ('NEW', 'CONTACTED', 'INSPECTION_BOOKED') then 'DISQUALIFIED' end;
  if v_to is null then
    return jsonb_build_object('ok', false, 'code', 'INVALID_TRANSITION', 'detail', format('%s is %s', l.lead_number, lower(replace(l.status, '_', ' '))));
  end if;
  if v_to in ('LOST', 'DISQUALIFIED') and length(coalesce(v_reason, '')) < 5 then
    return jsonb_build_object('ok', false, 'code', 'REASON_REQUIRED', 'detail', 'say why (a few words)');
  end if;
  if v_to in ('LOST', 'DISQUALIFIED') then
    update inspections set status = 'CANCELLED', updated_at = now(), record_version = record_version + 1 where lead_id = l.id and status = 'SCHEDULED';
  end if;
  update leads set status = v_to, lost_reason = case when v_to in ('LOST', 'DISQUALIFIED') then v_reason else lost_reason end,
                   contacted_at = case when v_to = 'CONTACTED' then now() else contacted_at end,
                   record_version = record_version + 1, updated_at = now() where id = l.id returning * into l;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
  values ('USER', v_emp.employee_code, 'lead.' || p_action, 'lead', l.id, l.lead_number, jsonb_build_object('status', v_from), jsonb_build_object('status', l.status),
          coalesce(v_reason, format('%s %s', l.lead_number, lower(l.status))));
  return jsonb_build_object('ok', true, 'lead_number', l.lead_number, 'status', l.status, 'record_version', l.record_version);
end $$;

--
-- Name: web_quote_save(text, text, text, integer, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_quote_save(p_token text, p_lead text, p_quote text, p_expected_version integer, p_job_type text, p_amount_type text, p_scope text, p_lines jsonb, p_request_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare
  v_emp employees := staff_session_employee(p_token); l leads; q quotes; v quote_versions; v_problem jsonb; v_next int; ins inspections;
  v_scope text := nullif(btrim(coalesce(p_scope, '')), '');
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if not staff_role_allowed(v_emp, 'sales.roles') then return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED', 'detail', format('%s (%s) may not prepare quotes', v_emp.employee_code, v_emp.role)); end if;
  if length(coalesce(p_request_key, '')) not between 8 and 100 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'missing request key'); end if;
  if coalesce(p_job_type, '') not in ('LEAK_REPAIR', 'ROOF_RESTORATION', 'ROOF_REPLACEMENT', 'FULL_REROOF', 'EXTENSION_ROOF', 'STORM_DAMAGE_REPAIR') then
    return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'choose the kind of job');
  end if;
  -- Only prices that include GST: the invoice and Xero path is GST-inclusive end to end (invoice_final_preview refuses
  -- anything else, but only at invoicing, after the job is done). Refusing here keeps an unsupported quote out of the
  -- financial process entirely.
  if coalesce(p_amount_type, '') <> 'INCLUSIVE' then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'prices must include GST (GST-exclusive and GST-free quotes cannot be invoiced yet)'); end if;
  if length(coalesce(v_scope, '')) > 4000 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'the scope is too long'); end if;
  v_problem := quote_lines_problem(p_lines);
  if v_problem is not null then return jsonb_build_object('ok', false) || v_problem; end if;

  if nullif(btrim(coalesce(p_quote, '')), '') is null then   -- a new quote from an enquiry
    select * into q from quotes where request_key = p_request_key;
    if q.id is not null then return jsonb_build_object('ok', true, 'duplicate', true, 'quote_number', q.quote_number); end if;
    select * into l from leads where lead_number = upper(btrim(coalesce(p_lead, ''))) for update;
    if l.id is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', coalesce(p_lead, 'no enquiry')); end if;
    if l.customer_id is null or l.property_id is null then return jsonb_build_object('ok', false, 'code', 'NOT_CONVERTED', 'detail', 'record the customer and the site first'); end if;
    if l.status in ('LOST', 'DISQUALIFIED', 'WON') then return jsonb_build_object('ok', false, 'code', 'INVALID_TRANSITION', 'detail', format('%s is %s', l.lead_number, lower(l.status))); end if;
    if exists (select 1 from quotes x where x.lead_id = l.id and x.status in ('DRAFT', 'SENT')) then
      return jsonb_build_object('ok', false, 'code', 'ALREADY_QUOTED', 'detail', 'this enquiry already has an open quote; revise that one');
    end if;
    select * into ins from inspections where lead_id = l.id and status = 'COMPLETED' order by inspected_on desc, created_at desc limit 1;
    insert into quotes (quote_number, customer_id, property_id, inspection_id, lead_id, lead_source, estimator_id, job_type, status, created_on, request_key)
    values (next_friendly_id('Q', extract(year from app_today())::int), l.customer_id, l.property_id, ins.id, l.id, l.source, v_emp.id, p_job_type, 'DRAFT', app_today(), p_request_key)
    returning * into q;
    v := quote_insert_version(q.id, 1, p_amount_type, v_scope, p_lines, v_emp.id);
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
    values ('USER', v_emp.employee_code, 'quote.drafted', 'quote', q.id, q.quote_number,
            jsonb_build_object('lead', l.lead_number, 'version', 1, 'total_inc_gst', v.total_inc_gst), format('Quote %s drafted for %s', q.quote_number, l.lead_number));
  else   -- a revision: a new version of a draft quote
    select * into q from quotes where quote_number = upper(btrim(p_quote)) for update;
    if q.id is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', p_quote); end if;
    if exists (select 1 from audit_events a where a.action = 'quote.revised' and a.entity_id = q.id and a.after_state ->> 'request_key' = p_request_key) then
      return jsonb_build_object('ok', true, 'duplicate', true, 'quote_number', q.quote_number);
    end if;
    if p_expected_version is distinct from q.record_version then return jsonb_build_object('ok', false, 'code', 'STALE', 'detail', format('%s changed since you opened it; reload and check it again', q.quote_number)); end if;
    if q.status not in ('DRAFT', 'SENT') then return jsonb_build_object('ok', false, 'code', 'INVALID_TRANSITION', 'detail', format('%s is %s: it cannot change', q.quote_number, lower(q.status))); end if;
    -- Quote publishing lifecycle (20261017060000): a SENT quote is final. It went to the customer and to Airtable as one
    -- version; Airtable cannot refuse a stale write, so a second version of the same Airtable record could be overwritten
    -- by (or overwrite) the first. A different price is a new quote (new number, new Airtable record).
    if q.status = 'SENT' then
      return jsonb_build_object('ok', false, 'code', 'QUOTE_SENT_FINAL', 'detail', format('%s was sent and cannot change. For a different price, mark it Lost in Airtable and record a new enquiry for the customer', q.quote_number));
    end if;
    select coalesce(max(version_number), 0) + 1 into v_next from quote_versions where quote_id = q.id;
    v := quote_insert_version(q.id, v_next, p_amount_type, v_scope, p_lines, v_emp.id);
    update quotes set job_type = p_job_type, record_version = record_version + 1, updated_at = now() where id = q.id returning * into q;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
    values ('USER', v_emp.employee_code, 'quote.revised', 'quote', q.id, q.quote_number,
            jsonb_build_object('version', v_next, 'total_inc_gst', v.total_inc_gst, 'request_key', p_request_key, 'republished', q.status = 'SENT'),
            format('Quote %s version %s', q.quote_number, v_next) || case when q.status = 'SENT' then ' (sent again to Airtable)' else '' end);
  end if;
  return jsonb_build_object('ok', true, 'quote_number', q.quote_number, 'version', v.version_number, 'status', q.status,
                            'total_inc_gst', v.total_inc_gst, 'gst_amount', v.gst_amount, 'record_version', q.record_version);
end $$;

--
-- Name: web_quote_send(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_quote_send(p_token text, p_quote text, p_expected_version integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $_$
declare v_emp employees := staff_session_employee(p_token); q quotes; v_key text;
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if not staff_role_allowed(v_emp, 'sales.roles') then return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED', 'detail', format('%s (%s) may not send quotes', v_emp.employee_code, v_emp.role)); end if;
  select * into q from quotes where quote_number = upper(btrim(coalesce(p_quote, ''))) for update;
  if q.id is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', coalesce(p_quote, 'no quote')); end if;
  if q.status = 'SENT' then return jsonb_build_object('ok', true, 'duplicate', true, 'quote_number', q.quote_number, 'status', q.status); end if;
  if p_expected_version is distinct from q.record_version then return jsonb_build_object('ok', false, 'code', 'STALE', 'detail', format('%s changed since you opened it; reload and check it again', q.quote_number)); end if;
  if q.status <> 'DRAFT' then return jsonb_build_object('ok', false, 'code', 'INVALID_TRANSITION', 'detail', format('%s is %s', q.quote_number, lower(q.status))); end if;
  if (select total_inc_gst from quote_versions where quote_id = q.id order by version_number desc limit 1) <= 0 then
    return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'a quote of $0 cannot be sent');
  end if;
  update quotes set status = 'SENT', sent_on = coalesce(sent_on, app_today()),
                    valid_until = coalesce(valid_until, app_today() + coalesce((select value::int from app_settings where key = 'quote.validity_days'), 30)),
                    record_version = record_version + 1, updated_at = now() where id = q.id returning * into q;
  update leads set status = 'QUOTED', record_version = record_version + 1, updated_at = now() where id = q.lead_id and status in ('NEW', 'CONTACTED', 'INSPECTION_BOOKED');
  v_key := 'airtable:quote-publish:' || q.id;
  if not exists (select 1 from external_links l where l.provider = 'AIRTABLE' and l.entity_type = 'quote' and l.entity_id = q.id and l.verified_at is not null) then
    insert into outbox (topic, aggregate_type, aggregate_id, correlation_id, idempotency_key, payload)
    values ('airtable.quote_publish', 'quote', q.id, gen_random_uuid(), v_key, quote_publish_payload(q.id))
    on conflict (idempotency_key) do nothing;
  end if;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
  values ('USER', v_emp.employee_code, 'quote.sent', 'quote', q.id, q.quote_number, jsonb_build_object('status', 'DRAFT'),
          jsonb_build_object('status', 'SENT', 'sent_on', q.sent_on, 'valid_until', q.valid_until), format('Quote %s sent to the customer', q.quote_number));
  return jsonb_build_object('ok', true, 'quote_number', q.quote_number, 'status', q.status, 'valid_until', q.valid_until, 'record_version', q.record_version,
                            'airtable_key', v_key);
end $_$;

--
-- Name: web_reissue_decide(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_reissue_decide(p_token text, p_approval_number text, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare v_emp employees := staff_session_employee(p_token); v_ap approvals;
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT', 'detail', 'Your sign-in has ended. Sign in again as yourself.'); end if;
  select * into v_ap from approvals where approval_number = p_approval_number and action_type = 'REISSUE_INVOICE';
  if v_ap.id is not null and v_ap.requested_by_employee_id = v_emp.id and v_ap.status = 'PENDING' then
    return jsonb_build_object('ok', false, 'code', 'SAME_PERSON',
      'detail', format('You requested %s, so a second person must approve it: someone else in a reissue role (%s). Nothing was changed',
                       v_ap.approval_number, coalesce((select value from app_settings where key = 'invoice.reissue_roles'), 'none configured')));
  end if;
  return ops_reissue_decide(p_approval_number, v_emp.employee_code, p_note);
end $$;

--
-- Name: FUNCTION web_reissue_decide(p_token text, p_approval_number text, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.web_reissue_decide(p_token text, p_approval_number text, p_note text) IS 'Dashboard reissue decision as the session employee; the requester can never approve (always a second person here)';

--
-- Name: web_reissue_overview(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_reissue_overview(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare v_emp employees := staff_session_employee(p_token); v_roles text[];
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'reason', 'Sign in as yourself to see invoice reissues.'); end if;
  v_roles := string_to_array(coalesce((select value from app_settings where key = 'invoice.reissue_roles'), ''), ',');
  return jsonb_build_object('ok', true,
    'me', jsonb_build_object('employee_code', v_emp.employee_code, 'name', v_emp.full_name, 'role', v_emp.role, 'may_reissue', v_emp.role = any (v_roles)),
    'roles', array_to_string(v_roles, ', '),
    'items', coalesce((select jsonb_agg(x order by x ->> 'sort' desc) from (
      select jsonb_build_object(
        'sort', coalesce((select max(a.created_at) from approvals a where a.entity_id = i.id and a.action_type = 'REISSUE_INVOICE'), i.updated_at)::text,
        'invoice_number', i.invoice_number, 'project_number', p.project_number, 'customer', c.display_name,
        'status', i.status, 'total_inc_gst', i.total_inc_gst, 'gst_amount', i.gst_amount, 'voided_reason', i.voided_reason,
        'check', case when i.status = 'VOIDED' then invoice_reissue_check(i.id) end,
        'pending', (select jsonb_build_object('approval_number', a.approval_number, 'requested_at', a.created_at, 'expires_at', a.expires_at,
                      'requested_by', re.employee_code, 'requested_by_name', re.full_name, 'reason', a.action_payload ->> 'requested_reason',
                      'xero_invoice_number', a.action_payload -> 'draft' ->> 'xero_invoice_number',
                      'amount_inc_gst', a.action_payload -> 'draft' ->> 'amount_inc_gst', 'gst_amount', a.action_payload -> 'draft' ->> 'gst_amount',
                      'contact', a.action_payload -> 'draft' ->> 'xero_contact_name', 'tenant', a.action_payload -> 'draft' ->> 'xero_tenant_name',
                      'target_generation', a.action_payload ->> 'target_generation',
                      'i_requested_it', a.requested_by_employee_id = v_emp.id)
                    from approvals a left join employees re on re.id = a.requested_by_employee_id
                    where a.entity_id = i.id and a.action_type = 'REISSUE_INVOICE' and a.status = 'PENDING' and a.expires_at > now()
                    order by a.created_at desc limit 1),
        'latest_decided', (select jsonb_build_object('approval_number', a.approval_number, 'status', a.status, 'decided_at', a.decided_at,
                      'decided_by', de.full_name, 'requested_by', re.full_name, 'generation', g.generation, 'generation_status', g.status,
                      'xero_invoice_id', g.xero_invoice_id, 'write_status', o.status, 'write_attempts', o.attempts)
                    from approvals a
                    left join employees de on de.id = a.decided_by
                    left join employees re on re.id = a.requested_by_employee_id
                    left join invoice_xero_draft_generations g on g.approval_id = a.id
                    left join outbox o on o.idempotency_key = g.outbox_idempotency_key
                    where a.entity_id = i.id and a.action_type = 'REISSUE_INVOICE' and a.status in ('EXECUTED', 'EXECUTING', 'REJECTED', 'CANCELLED')
                    order by coalesce(a.decided_at, a.created_at) desc limit 1)
      ) x
      from invoices i join projects p on p.id = i.project_id join customers c on c.id = i.customer_id
      where i.invoice_type = 'FINAL'
        and (i.status = 'VOIDED' or exists (select 1 from approvals a where a.entity_id = i.id and a.action_type = 'REISSUE_INVOICE'))
    ) t), '[]'::jsonb));
end $$;

--
-- Name: web_reissue_request(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_reissue_request(p_token text, p_invoice_number text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare v_emp employees := staff_session_employee(p_token); v_inv uuid;
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT', 'detail', 'Your sign-in has ended. Sign in again as yourself.'); end if;
  select id into v_inv from invoices where invoice_number = p_invoice_number;
  if v_inv is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', coalesce(p_invoice_number, 'no invoice') || ' is not an invoice'); end if;
  return ops_reissue_request(v_inv, v_emp.employee_code, p_reason);
end $$;

