-- Name: web_resolve_exception(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_resolve_exception(p_token text, p_exception text, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare v_emp employees := staff_session_employee(p_token);
begin
  if v_emp.id is null then
    return jsonb_build_object('resolved', false, 'reason', 'Your sign-in has ended. Sign in again as yourself to resolve this.');
  end if;
  return ops_resolve_exception(p_exception, v_emp.employee_code, p_note);
end $$;

--
-- Name: web_staff_session(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_staff_session(p_token text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
  select case when e.id is null then null
              else jsonb_build_object('employee_code', e.employee_code, 'name', e.full_name, 'role', e.role,
                     'may_resolve_exceptions', e.role = any (string_to_array((select value from app_settings where key = 'exception.resolver_roles'), ',')))
         end
    from (select (staff_session_employee(p_token)).*) e
$$;

--
-- Name: web_staff_sign_in(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_staff_sign_in(p_login text, p_password text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare a staff_accounts; v_emp employees; v_token text; v_hours int;
  -- One answer for every refusal (unknown login, wrong password, locked, inactive): nothing tells a login exists.
  v_fail constant text := 'That login and password did not match. After 5 wrong attempts a login is locked for 10 minutes.';
begin
  select * into a from staff_accounts where login = lower(btrim(coalesce(p_login, ''))) for update;
  if a.employee_id is null then
    perform crypt(coalesce(p_password, ''), gen_salt('bf', 10));   -- same work as a real check: no login enumeration by timing
    return jsonb_build_object('ok', false, 'reason', v_fail);
  end if;
  if a.locked_until > now() then
    perform crypt(coalesce(p_password, ''), gen_salt('bf', 10));   -- same work and answer as any refusal
    return jsonb_build_object('ok', false, 'reason', v_fail);
  end if;
  select * into v_emp from employees where id = a.employee_id;
  if crypt(coalesce(p_password, ''), a.password_hash) <> a.password_hash or not v_emp.is_active then
    if a.failed_attempts + 1 >= 5 then
      update staff_accounts set failed_attempts = 0, locked_until = now() + interval '10 minutes' where employee_id = a.employee_id;
      insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, reason)
      values ('SYSTEM', 'web:sign-in', 'staff.login_locked', 'employee', v_emp.id, v_emp.employee_code, '5 failed sign-ins: locked for 10 minutes');
    else
      update staff_accounts set failed_attempts = failed_attempts + 1 where employee_id = a.employee_id;
    end if;
    return jsonb_build_object('ok', false, 'reason', v_fail);
  end if;
  v_hours := coalesce((select value::int from app_settings where key = 'staff.session_hours'), 12);
  v_token := encode(gen_random_bytes(32), 'hex');
  update staff_accounts set failed_attempts = 0, locked_until = null where employee_id = a.employee_id;
  delete from staff_sessions where expires_at < now() - interval '30 days';   -- housekeeping: ended sessions are not kept forever
  insert into staff_sessions (token_sha256, employee_id, expires_at)
  values (encode(digest(v_token, 'sha256'), 'hex'), v_emp.id, now() + make_interval(hours => v_hours));
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, reason)
  values ('USER', v_emp.employee_code, 'staff.signed_in', 'employee', v_emp.id, v_emp.employee_code, 'Dashboard sign-in');
  return jsonb_build_object('ok', true, 'token', v_token, 'employee_code', v_emp.employee_code, 'name', v_emp.full_name,
                            'role', v_emp.role, 'expires_at', now() + make_interval(hours => v_hours));
end $$;

--
-- Name: web_staff_sign_out(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_staff_sign_out(p_token text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
  update staff_sessions set revoked_at = now() where token_sha256 = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex') and revoked_at is null
$$;

--
-- Name: web_task_create(text, text, text, text, text, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_task_create(p_token text, p_project text, p_type text, p_title text, p_assignee text, p_due date, p_description text, p_request_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare
  v_emp employees := staff_session_employee(p_token); p projects; a employees; t tasks;
  v_title text := btrim(regexp_replace(coalesce(p_title, ''), '\s+', ' ', 'g')); v_desc text := nullif(btrim(coalesce(p_description, '')), '');
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if not staff_role_allowed(v_emp, 'task.manager_roles') then
    return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED', 'detail', format('%s (%s) may not create tasks', v_emp.employee_code, v_emp.role));
  end if;
  if length(coalesce(p_request_key, '')) not between 8 and 100 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'missing request key'); end if;
  select * into t from tasks where dedupe_key = 'web:' || p_request_key;
  if t.id is not null then return jsonb_build_object('ok', true, 'duplicate', true, 'task_number', t.task_number); end if;
  if length(v_title) not between 3 and 200 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'give the task a short title (3 to 200 characters)'); end if;
  if length(coalesce(v_desc, '')) > 2000 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'the description is too long'); end if;
  if coalesce(p_type, '') not in ('MATERIAL_REVIEW', 'SCHEDULE_JOB', 'SUPPLIER_FOLLOW_UP', 'COMPLIANCE_DOCS', 'CUSTOMER_FOLLOW_UP', 'INVOICE_REVIEW', 'EXCEPTION_REVIEW', 'GENERAL') then
    return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'choose the kind of task');
  end if;
  if nullif(btrim(coalesce(p_project, '')), '') is not null then
    select * into p from projects where project_number = upper(btrim(p_project)) for update;
    if p.id is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', p_project); end if;
    if p.status in ('CLOSED', 'CANCELLED') then
      return jsonb_build_object('ok', false, 'code', 'PROJECT_CLOSED', 'detail', format('%s is %s', p.project_number, lower(sm_label('project', p.status))));
    end if;
  end if;
  if nullif(btrim(coalesce(p_assignee, '')), '') is not null then
    select * into a from employees where employee_code = upper(btrim(p_assignee)) and is_active and role <> 'VIEWER';
    if a.id is null then return jsonb_build_object('ok', false, 'code', 'ASSIGNEE_UNKNOWN', 'detail', format('%s is not an active employee', p_assignee)); end if;
  end if;
  if p_due is not null and p_due < app_today() then
    return jsonb_build_object('ok', false, 'code', 'IN_PAST', 'detail', format('the due date is before today (%s)', to_char(app_today(), 'DD Mon YYYY')));
  end if;
  if exists (select 1 from tasks x where x.project_id is not distinct from p.id and lower(x.title) = lower(v_title) and x.status in ('OPEN', 'IN_PROGRESS')) then
    return jsonb_build_object('ok', false, 'code', 'DUPLICATE_OPEN_TASK', 'detail', format('an open task "%s" already exists%s', v_title, coalesce(' on ' || p.project_number, '')));
  end if;
  insert into tasks (project_id, task_type, title, description, assignee_id, status, due_on, dedupe_key, task_number, created_by)
  values (p.id, p_type, v_title, v_desc, a.id, 'OPEN', p_due, 'web:' || p_request_key, next_friendly_id('TASK'), v_emp.id)
  returning * into t;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
  values ('USER', v_emp.employee_code, 'task.created', 'task', t.id, coalesce(p.project_number, t.task_number),
          jsonb_build_object('task_number', t.task_number, 'title', v_title, 'assignee', a.employee_code, 'due_on', p_due),
          format('Task %s: %s', t.task_number, v_title));
  return jsonb_build_object('ok', true, 'task_number', t.task_number, 'status', t.status, 'record_version', t.record_version);
end $$;

--
-- Name: web_task_update(text, text, text, integer, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_task_update(p_token text, p_task text, p_action text, p_expected_version integer, p_assignee text, p_due date, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare
  v_emp employees := staff_session_employee(p_token); t tasks; a employees; v_manager boolean; v_mine boolean; v_to text; v_from text;
  v_note text := nullif(btrim(coalesce(p_note, '')), ''); v_ref text;
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if coalesce(p_action, '') not in ('start', 'done', 'cancel', 'reassign', 'due') then
    return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'unknown action');
  end if;
  select * into t from tasks where task_number = upper(btrim(coalesce(p_task, ''))) for update;
  if t.id is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', coalesce(p_task, 'no task')); end if;
  v_manager := staff_role_allowed(v_emp, 'task.manager_roles');
  v_mine := v_emp.is_active and t.assignee_id = v_emp.id;
  if not (v_manager or (v_mine and p_action in ('start', 'done'))) then
    return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED',
      'detail', case when v_mine then 'only a manager may do this' else format('%s is not assigned to %s', v_emp.employee_code, t.task_number) end);
  end if;
  if p_expected_version is distinct from t.record_version then
    return jsonb_build_object('ok', false, 'code', 'STALE', 'detail', format('%s changed since you opened it (now %s); reload and check it again', t.task_number, lower(replace(t.status, '_', ' '))));
  end if;
  if length(coalesce(v_note, '')) > 2000 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'the note is too long'); end if;
  v_from := t.status;
  v_to := case
    when p_action = 'start' and t.status = 'OPEN' then 'IN_PROGRESS'
    when p_action = 'done' and t.status in ('OPEN', 'IN_PROGRESS') then 'DONE'
    when p_action = 'cancel' and t.status in ('OPEN', 'IN_PROGRESS') then 'CANCELLED'
    when p_action in ('reassign', 'due') and t.status in ('OPEN', 'IN_PROGRESS') then t.status end;
  if v_to is null then
    return jsonb_build_object('ok', false, 'code', 'INVALID_TRANSITION', 'detail', format('%s is %s', t.task_number, lower(replace(t.status, '_', ' '))));
  end if;
  if p_action = 'cancel' and length(coalesce(v_note, '')) < 5 then
    return jsonb_build_object('ok', false, 'code', 'REASON_REQUIRED', 'detail', 'say why it is no longer needed (a few words)');
  end if;
  if p_action = 'reassign' then
    select * into a from employees where employee_code = upper(btrim(coalesce(p_assignee, ''))) and is_active and role <> 'VIEWER';
    if a.id is null then return jsonb_build_object('ok', false, 'code', 'ASSIGNEE_UNKNOWN', 'detail', format('%s is not an active employee', coalesce(nullif(p_assignee, ''), 'nobody'))); end if;
  end if;
  if p_action = 'due' and (p_due is null or p_due < app_today()) then
    return jsonb_build_object('ok', false, 'code', 'IN_PAST', 'detail', format('pick a due date from today (%s)', to_char(app_today(), 'DD Mon YYYY')));
  end if;
  update tasks set status = v_to,
         assignee_id = case when p_action = 'reassign' then a.id else assignee_id end,
         due_on = case when p_action = 'due' then p_due else due_on end,
         completed_at = case when v_to = 'DONE' then now() else completed_at end,
         completed_by = case when v_to = 'DONE' then v_emp.id else completed_by end,
         status_note = coalesce(v_note, status_note), record_version = record_version + 1, updated_at = now()
   where id = t.id returning * into t;
  select project_number into v_ref from projects where id = t.project_id;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
  values ('USER', v_emp.employee_code, 'task.' || p_action, 'task', t.id, coalesce(v_ref, t.task_number), jsonb_build_object('task_number', t.task_number, 'status', v_from),
          jsonb_build_object('task_number', t.task_number, 'status', t.status, 'assignee', (select employee_code from employees where id = t.assignee_id), 'due_on', t.due_on),
          coalesce(v_note, format('Task %s %s', t.task_number, lower(replace(t.status, '_', ' ')))));
  return jsonb_build_object('ok', true, 'task_number', t.task_number, 'status', t.status, 'record_version', t.record_version);
end $$;

--
-- Name: web_visit_schedule(text, text, text, timestamp with time zone, timestamp with time zone, text[], text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_visit_schedule(p_token text, p_project text, p_type text, p_start timestamp with time zone, p_end timestamp with time zone, p_crew text[], p_leading_hand text, p_note text, p_request_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare
  v_emp employees := staff_session_employee(p_token); p projects; j jobs; v_problem jsonb; v_ids uuid[]; v_codes text[];
  v_lead text; v_bad text; v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if not staff_role_allowed(v_emp, 'schedule.planner_roles') then
    return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED', 'detail', format('%s (%s) may not schedule site visits', v_emp.employee_code, v_emp.role));
  end if;
  if length(coalesce(p_request_key, '')) not between 8 and 100 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'missing request key'); end if;
  select * into j from jobs where request_key = p_request_key;
  if j.id is not null then   -- the same form submitted twice: the first visit, nothing new
    return jsonb_build_object('ok', true, 'duplicate', true, 'job_number', j.job_number, 'status', j.status);
  end if;
  select * into p from projects where project_number = upper(btrim(coalesce(p_project, ''))) for update;
  if p.id is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', coalesce(p_project, 'no project')); end if;
  if p.status in ('CLOSED', 'CANCELLED') then
    return jsonb_build_object('ok', false, 'code', 'PROJECT_CLOSED', 'detail', format('%s is %s', p.project_number, lower(sm_label('project', p.status))));
  end if;
  if coalesce(p_type, '') not in ('INSTALL', 'STRIP_AND_REPLACE', 'RESTORATION', 'REPAIR', 'MAKE_SAFE', 'RETURN_VISIT') then
    return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'choose the kind of visit');
  end if;
  if p.status = 'COMPLETED' and p_type not in ('RETURN_VISIT', 'MAKE_SAFE') then
    return jsonb_build_object('ok', false, 'code', 'PROJECT_COMPLETED', 'detail', format('%s is completed: only a return visit or a make-safe can be scheduled', p.project_number));
  end if;
  v_problem := visit_times_problem(p_start, p_end);
  if v_problem is not null then return jsonb_build_object('ok', false) || v_problem; end if;
  if length(coalesce(v_note, '')) > 2000 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'the note is too long'); end if;

  -- In the order given (the first is the leading hand unless one is named), each person once.
  select array_agg(c order by ord) into v_codes from (
    select distinct on (upper(btrim(c))) upper(btrim(c)) c, ord from unnest(coalesce(p_crew, '{}')) with ordinality u(c, ord)
     where btrim(coalesce(c, '')) <> '' order by upper(btrim(c)), ord) x;
  if coalesce(cardinality(v_codes), 0) = 0 then return jsonb_build_object('ok', false, 'code', 'NO_CREW', 'detail', 'pick at least one person'); end if;
  if cardinality(v_codes) > 8 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'at most 8 people on one visit'); end if;
  select string_agg(c, ', ') into v_bad from unnest(v_codes) c
   where not exists (select 1 from employees e where e.employee_code = c and e.is_active and e.role <> 'VIEWER');
  if v_bad is not null then return jsonb_build_object('ok', false, 'code', 'CREW_UNKNOWN', 'detail', format('%s cannot be put on a visit (not an active employee)', v_bad)); end if;
  v_lead := coalesce(nullif(upper(btrim(coalesce(p_leading_hand, ''))), ''), v_codes[1]);
  if not (v_lead = any (v_codes)) then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'the leading hand must be on the crew'); end if;

  -- Lock the crew (in a fixed order) so two planners cannot book the same person into overlapping visits at once.
  select array_agg(id order by id) into v_ids from (select id from employees where employee_code = any (v_codes) order by id for update) x;
  v_problem := visit_crew_conflict(v_ids, p_start, p_end);
  if v_problem is not null then
    return jsonb_build_object('ok', false, 'code', 'CREW_CONFLICT', 'conflict', v_problem,
      'detail', format('%s is already on %s (%s to %s)', v_problem ->> 'name', v_problem ->> 'job_number',
        to_char((v_problem ->> 'from')::timestamptz at time zone 'Australia/Brisbane', 'DD Mon HH24:MI'),
        to_char((v_problem ->> 'to')::timestamptz at time zone 'Australia/Brisbane', 'DD Mon HH24:MI')));
  end if;

  insert into jobs (job_number, project_id, job_type, status, scheduled_start, scheduled_end, request_key, notes, created_by)
  values (next_friendly_id('JOB', extract(year from app_today())::int), p.id, p_type, 'SCHEDULED', p_start, p_end, p_request_key, v_note, v_emp.id)
  returning * into j;
  insert into job_assignments (job_id, employee_id, crew_role)
  select j.id, e.id, case when e.employee_code = v_lead then 'LEADING_HAND' else 'CREW' end from employees e where e.employee_code = any (v_codes);
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
  values ('USER', v_emp.employee_code, 'job.scheduled', 'job', j.id, p.project_number,
          jsonb_build_object('job_number', j.job_number, 'type', p_type, 'start', p_start, 'end', p_end, 'crew', v_codes, 'leading_hand', v_lead),
          format('Site visit %s scheduled', j.job_number));
  return jsonb_build_object('ok', true, 'job_number', j.job_number, 'status', j.status, 'record_version', j.record_version);
end $$;

--
-- Name: web_visit_update(text, text, text, integer, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_visit_update(p_token text, p_job text, p_action text, p_expected_version integer, p_reason text, p_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare
  v_emp employees := staff_session_employee(p_token); j jobs; p projects; v_planner boolean; v_crew boolean; v_to text; v_problem jsonb;
  v_ids uuid[]; v_reason text := nullif(btrim(coalesce(p_reason, '')), ''); v_from text;
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if coalesce(p_action, '') not in ('start', 'complete', 'weather_delay', 'reschedule', 'cancel') then
    return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'unknown action');
  end if;
  select * into j from jobs where job_number = upper(btrim(coalesce(p_job, ''))) for update;
  if j.id is null then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'detail', coalesce(p_job, 'no visit')); end if;
  select * into p from projects where id = j.project_id;
  v_planner := staff_role_allowed(v_emp, 'schedule.planner_roles');
  v_crew := v_emp.is_active and exists (select 1 from job_assignments a where a.job_id = j.id and a.employee_id = v_emp.id);
  if not (v_planner or (v_crew and p_action in ('start', 'complete', 'weather_delay'))) then
    return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED',
      'detail', case when p_action in ('reschedule', 'cancel') then 'only a planner (admin, operations manager, project manager) may do this'
                     else format('%s is not on the crew of %s', v_emp.employee_code, j.job_number) end);
  end if;
  if p_expected_version is distinct from j.record_version then
    return jsonb_build_object('ok', false, 'code', 'STALE', 'detail', format('%s changed since you opened it (now %s); reload and check it again', j.job_number, lower(replace(j.status, '_', ' '))));
  end if;
  -- A cancelled or closed job's visits are not started, moved or delayed; one already under way can still be completed, so
  -- it is never stranded.
  if p.status in ('CANCELLED', 'CLOSED') and p_action in ('start', 'reschedule', 'weather_delay') then
    return jsonb_build_object('ok', false, 'code', 'PROJECT_CLOSED', 'detail', format('%s is %s: its visits cannot be %s', p.project_number,
      lower(sm_label('project', p.status)), case p_action when 'start' then 'started' when 'reschedule' then 'rescheduled' else 'delayed' end));
  end if;
  v_from := j.status;
  v_to := case
    when p_action = 'start' and j.status = 'SCHEDULED' then 'IN_PROGRESS'
    when p_action = 'complete' and j.status = 'IN_PROGRESS' then 'COMPLETED'
    when p_action = 'weather_delay' and j.status in ('SCHEDULED', 'IN_PROGRESS') then 'WEATHER_DELAYED'
    when p_action = 'reschedule' and j.status in ('SCHEDULED', 'WEATHER_DELAYED') then 'SCHEDULED'
    when p_action = 'cancel' and j.status in ('SCHEDULED', 'WEATHER_DELAYED') then 'CANCELLED' end;
  if v_to is null then
    return jsonb_build_object('ok', false, 'code', 'INVALID_TRANSITION', 'detail', format('%s is %s: it cannot be %s', j.job_number, lower(replace(j.status, '_', ' ')),
      case p_action when 'start' then 'started' when 'complete' then 'completed (start it first)' when 'weather_delay' then 'delayed'
                    when 'reschedule' then 'rescheduled' else 'cancelled' end));
  end if;
  if p_action in ('weather_delay', 'cancel') and length(coalesce(v_reason, '')) < 5 then
    return jsonb_build_object('ok', false, 'code', 'REASON_REQUIRED', 'detail', 'say why (a few words), so the office and the customer can be told');
  end if;
  if length(coalesce(v_reason, '')) > 2000 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'detail', 'the note is too long'); end if;
  if p_action = 'reschedule' then
    v_problem := visit_times_problem(p_start, p_end);
    if v_problem is not null then return jsonb_build_object('ok', false) || v_problem; end if;
    select array_agg(id order by id) into v_ids from (select e.id from employees e join job_assignments a on a.employee_id = e.id
                                                       where a.job_id = j.id order by e.id for update of e) x;
    v_problem := visit_crew_conflict(v_ids, p_start, p_end, j.id);
    if v_problem is not null then
      return jsonb_build_object('ok', false, 'code', 'CREW_CONFLICT', 'conflict', v_problem,
        'detail', format('%s is already on %s at that time', v_problem ->> 'name', v_problem ->> 'job_number'));
    end if;
    update jobs set scheduled_start = p_start, scheduled_end = p_end, actual_start = null, actual_end = null, status = 'SCHEDULED',
                    status_reason = v_reason, record_version = record_version + 1, updated_at = now() where id = j.id returning * into j;
  else
    update jobs set status = v_to, status_reason = coalesce(v_reason, status_reason),
                    actual_start = case when v_to = 'IN_PROGRESS' then now() else actual_start end,
                    actual_end = case when v_to = 'COMPLETED' then now() else actual_end end,
                    record_version = record_version + 1, updated_at = now() where id = j.id returning * into j;
  end if;
  -- A delay or a completion note is also a site note (the job's progress log; the Copilot reads site notes).
  if v_reason is not null and p_action in ('weather_delay', 'complete') then
    insert into site_notes (note_number, project_id, job_id, author_id, note_type, body, noted_at)
    values (next_friendly_id('NOTE'), p.id, j.id, v_emp.id, case when p_action = 'weather_delay' then 'WEATHER' else 'GENERAL' end, v_reason, now());
  end if;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
  values ('USER', v_emp.employee_code, 'job.' || p_action, 'job', j.id, p.project_number, jsonb_build_object('job_number', j.job_number, 'status', v_from),
          jsonb_build_object('job_number', j.job_number, 'status', j.status, 'start', j.scheduled_start, 'end', j.scheduled_end),
          coalesce(v_reason, format('Site visit %s %s', j.job_number, lower(replace(j.status, '_', ' ')))));
  return jsonb_build_object('ok', true, 'job_number', j.job_number, 'status', j.status, 'record_version', j.record_version);
end $$;

--
-- Name: web_xero_dispatch_request(text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.web_xero_dispatch_request(p_token text, p_invoice text, p_generation integer, p_payload_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $$
declare v_emp employees := staff_session_employee(p_token); v_problem jsonb; i invoices; o outbox; r xero_dispatch_requests;
begin
  if v_emp.id is null then return jsonb_build_object('ok', false, 'code', 'SIGNED_OUT'); end if;
  if not (v_emp.role = any (string_to_array((select value from app_settings where key = 'xero.dispatch_roles'), ','))) then
    return jsonb_build_object('ok', false, 'code', 'ACTOR_UNAUTHORIZED', 'detail', format('%s (%s) may not send invoices to Xero', v_emp.employee_code, v_emp.role));
  end if;
  if coalesce(p_payload_sha256, '') = '' then return jsonb_build_object('ok', false, 'code', 'CHECK_REQUIRED', 'detail', 'open the draft and check it first'); end if;
  perform xero_dispatch_settle_claims();
  select * into i from invoices where invoice_number = p_invoice for update;
  v_problem := xero_dispatch_problem(p_invoice, p_generation, p_payload_sha256);
  if v_problem is not null then return jsonb_build_object('ok', false) || v_problem; end if;
  select * into o from outbox where idempotency_key = xero_draft_outbox_key(i.id, p_generation);
  insert into xero_dispatch_requests (invoice_id, generation, xero_key, payload_sha256, requested_by, reason)
  values (i.id, p_generation, o.idempotency_key, p_payload_sha256, v_emp.id,
          case when o.attempts > 0 then 'retry requested by ' else 'requested by ' end || v_emp.employee_code)
  on conflict do nothing returning * into r;
  if r.id is null then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_QUEUED', 'detail', 'it is already waiting to be sent');
  end if;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
  values ('USER', v_emp.employee_code, 'xero.dispatch_requested', 'invoice', i.id, i.invoice_number,
          jsonb_build_object('generation', p_generation, 'xero_key', o.idempotency_key), r.reason);
  return jsonb_build_object('ok', true, 'code', 'QUEUED', 'invoice_number', i.invoice_number, 'generation', p_generation);
end $$;

--
-- Name: wf_airtable_change(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_airtable_change(p_event jsonb, p_worker text DEFAULT 'n8n'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_res jsonb := wf_airtable_change_before_notes(p_event, p_worker);
  v_key text := p_event ->> 'event_id'; v_table text := p_event ->> 'table_id'; v_changes jsonb := p_event -> 'changes';
  v_actor text := coalesce(nullif(p_event ->> 'actor_id', ''), 'unknown'); v_id uuid; v_at timestamptz; n record; r jsonb;
  v_applied jsonb := '[]'; v_rejected jsonb := '[]'; v_stale jsonb := '[]'; v_corr jsonb := '{}'; v_sync text; v_lines text;
  v_all_applied jsonb; v_all_rejected jsonb; v_all_stale jsonb; v_outcome text;
begin
  -- Only a first delivery from Airtable to a Projects record RoofOps knows (the reconciler never sends a Note: Notes are not compared).
  if coalesce(nullif(p_event ->> 'source', ''), 'airtable') <> 'airtable' or v_table is distinct from 'tblvUPIoebC3zoacv'
     or jsonb_typeof(v_changes) <> 'object' or coalesce((v_res ->> 'duplicate')::boolean, false)
     or v_res ->> 'entity' is distinct from 'project' or v_res ->> 'entity_id' is null then
    return v_res;
  end if;
  v_id := (v_res ->> 'entity_id')::uuid;
  begin v_at := coalesce((p_event ->> 'occurred_at')::timestamptz, now()); exception when others then v_at := now(); end;
  for n in select * from (values
             ('fldNcsIgH6TfQFfaU', 'fldM6kgPz6QZagPAC', 'SWMS_SIGNED', 'swms_signed_note', 'SWMS Signed Note'),
             ('fldEtAmAokIvtzJdn', 'fldozWSCU877wEZHq', 'MATERIALS_REVIEWED', 'materials_reviewed_note', 'Materials Reviewed Note'),
             ('fldA77ad94yUmvnu3', 'fldbbksVL3dT6cqyS', 'COMPLETION_PHOTOS', 'completion_photos_note', 'Completion Photos Note'),
             ('fldLi9FkGDFAbf0QB', 'fldf7iJiyHFxOQgUy', 'COMPLIANCE_CERTIFICATE', 'compliance_certificate_note', 'Compliance Certificate Note'))
             as t(note_fid, item_fid, item_code, field_key, field_name)
            -- A Note that changed with its own item was already read with that item by the handler.
            where v_changes ? t.note_fid and not v_changes ? t.item_fid
  loop
    -- An older Note edit delivered after a newer one is ignored (the handler's rule for every field).
    if exists (select 1 from external_field_versions x where x.entity_type = 'project' and x.entity_id = v_id
                 and x.field_key = n.field_key and x.last_source_at > v_at) then
      v_stale := v_stale || jsonb_build_object('field', n.field_name, 'value', v_changes -> n.note_fid -> 'current');
      continue;
    end if;
    r := checklist_apply_note(v_id, n.item_code, nullif(btrim(v_changes -> n.note_fid ->> 'current'), ''), v_actor, v_key);
    if r ->> 'status' = 'APPLIED' then
      v_applied := v_applied || jsonb_build_object('field', r ->> 'field', 'from', r -> 'from', 'to', r -> 'to');
      insert into external_field_versions (entity_type, entity_id, field_key, last_source, last_source_at, last_event_key, last_value)
      values ('project', v_id, n.field_key, 'airtable', v_at, v_key, r ->> 'to')
      on conflict (entity_type, entity_id, field_key) do update set last_source = excluded.last_source,
        last_source_at = greatest(external_field_versions.last_source_at, excluded.last_source_at), last_event_key = excluded.last_event_key,
        last_value = excluded.last_value, applied_at = now();
    elsif r ->> 'status' = 'REJECTED' then
      v_rejected := v_rejected || (r - 'status');
      v_corr := v_corr || jsonb_build_object(n.note_fid, r -> 'kept');                  -- Airtable shows the recorded reason again
    end if;
  end loop;
  if jsonb_array_length(v_applied) + jsonb_array_length(v_rejected) + jsonb_array_length(v_stale) = 0 then
    return v_res;
  end if;

  v_lines := concat_ws(E'\n',
    (select string_agg(format('✓ %s: %s → %s applied', a ->> 'field', coalesce(a ->> 'from', 'blank'), coalesce(a ->> 'to', 'blank')), E'\n') from jsonb_array_elements(v_applied) a),
    (select string_agg(format('✗ %s: "%s" not applied: %s. Kept "%s".', x ->> 'field', coalesce(x ->> 'attempted', 'blank'), x ->> 'reason', coalesce(x ->> 'kept', 'blank')), E'\n') from jsonb_array_elements(v_rejected) x),
    (select string_agg(format('• %s: an older change arrived late and was ignored.', s ->> 'field'), E'\n') from jsonb_array_elements(v_stale) s));
  -- As in the handler: a plain accepted edit needs no Airtable write; a refusal does, and RoofOps Sync says why.
  if jsonb_array_length(v_rejected) > 0 then
    select airtable_field_id into v_sync from field_contract where airtable_table_id = v_table and field_key = 'roofops_sync';
    if v_sync is not null then
      v_corr := v_corr || jsonb_build_object(v_sync, coalesce((v_res -> 'corrections' ->> v_sync) || E'\n',
                                                              to_char(now() at time zone 'Australia/Brisbane', 'YYYY-MM-DD HH24:MI') || E'\n') || v_lines);
    end if;
  end if;
  v_all_applied := coalesce(v_res -> 'applied', '[]') || v_applied;
  v_all_rejected := coalesce(v_res -> 'rejected', '[]') || v_rejected;
  v_all_stale := coalesce(v_res -> 'stale', '[]') || v_stale;
  v_outcome := case when jsonb_array_length(v_all_applied) > 0 and jsonb_array_length(v_all_rejected) + jsonb_array_length(coalesce(v_res -> 'reverted', '[]')) = 0 then 'APPLIED'
                    when jsonb_array_length(v_all_applied) > 0 then 'PARTIALLY_APPLIED'
                    when jsonb_array_length(v_all_rejected) > 0 then 'REJECTED'
                    when jsonb_array_length(coalesce(v_res -> 'reverted', '[]')) > 0 then 'REVERTED'
                    when jsonb_array_length(v_all_stale) > 0 then 'STALE'
                    when jsonb_array_length(coalesce(v_res -> 'deferred', '[]')) > 0 then 'DEFERRED'
                    else 'NO_CHANGE' end;
  v_res := v_res || jsonb_build_object('outcome', v_outcome, 'applied', v_all_applied, 'rejected', v_all_rejected, 'stale', v_all_stale,
                                       'corrections', coalesce(v_res -> 'corrections', '{}') || v_corr,
                                       'note', nullif(concat_ws(E'\n', v_res ->> 'note', nullif(v_lines, '')), ''));
  update processed_events set result = v_res
   where consumer = 'airtable_change@1' and idempotency_key = v_key and status = 'COMPLETED' and not coalesce((result ->> 'duplicate')::boolean, false);
  update automation_events set
         status = case when v_outcome in ('REJECTED', 'REVERTED') then 'REJECTED' when v_outcome = 'STALE' then 'DUPLICATE_IGNORED'
                       when v_outcome in ('NO_CHANGE', 'DEFERRED') then 'INFO' else 'SUCCEEDED' end,
         error_class = case when v_outcome = 'REJECTED' then 'ILLEGAL_TRANSITION' when v_outcome = 'REVERTED' then 'UNAUTHORIZED_EDIT'
                            when v_outcome = 'STALE' then 'STALE_EVENT' end,
         metadata = metadata || jsonb_build_object('outcome', v_outcome, 'reason', v_res ->> 'note')
   where event_id = (select first_event_id from processed_events where consumer = 'airtable_change@1' and idempotency_key = v_key);
  -- No airtable_writes row: a Note and RoofOps Sync are not compared fields, so their echoes are no-ops (a Note that
  -- comes back equal to the recorded reason changes nothing).
  return v_res;
end $$;

--
-- Name: wf_airtable_change_before_notes(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_airtable_change_before_notes(p_event jsonb, p_worker text DEFAULT 'n8n'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_event jsonb := p_event; v_changes jsonb := p_event -> 'changes';
  v_table text := p_event ->> 'table_id'; v_rec text := p_event ->> 'record_id'; v_key text := p_event ->> 'event_id';
  v_src text := coalesce(nullif(p_event ->> 'source', ''), 'airtable'); v_at timestamptz;
  -- Airtable's actionMetadata.source, passed on by n8n 06: 'client' is a person in the Airtable UI, 'publicApi' an API
  -- client (RoofOps's own PATCHes arrive as 'publicApi'). Absent from events sent by older versions of 06.
  v_origin text := nullif(p_event ->> 'origin', '');
  v_link external_links; v_exp jsonb; v_exp_after jsonb; k text; v jsonb; w airtable_writes;
  v_echoes jsonb := '{}'; v_based text[] := '{}'; v_res jsonb; v_corr jsonb; v_sync text; v_note text;
begin
  -- AC-02: every date as the Brisbane business day it denotes.
  if jsonb_typeof(v_changes) = 'object' then
    v_event := jsonb_set(v_event, '{changes}', coalesce((
      select jsonb_object_agg(k2, case when jsonb_typeof(v2) = 'object' and exists (select 1 from field_contract c where c.airtable_field_id = k2 and c.value_type = 'date')
                                      then v2 || jsonb_strip_nulls(jsonb_build_object('current', at_business_date(v2 -> 'current'), 'previous', at_business_date(v2 -> 'previous')))
                                      else v2 end)
        from jsonb_each(v_changes) as t(k2, v2)), '{}'::jsonb));
  end if;
  if jsonb_typeof(p_event -> 'current') = 'object' then
    v_event := jsonb_set(v_event, '{current}', at_normalize_fields(p_event -> 'current'));
  end if;
  v_changes := v_event -> 'changes';

  -- AC-10: only for a well-formed change to a record RoofOps knows (anything else is the handler's to reject).
  select * into v_link from external_links where provider = 'AIRTABLE' and external_type = 'Record' and external_id = v_rec;
  if jsonb_typeof(v_changes) = 'object' and v_link.id is not null
     and not exists (select 1 from processed_events where consumer = 'airtable_change@1' and idempotency_key = v_key) then
    begin v_at := coalesce((p_event ->> 'occurred_at')::timestamptz, now()); exception when others then v_at := now(); end;
    -- Same lock order as the handler: decide against canonical as it is once no one else can change it.
    case v_link.entity_type
      when 'project' then perform 1 from projects where id = v_link.entity_id for update;
      when 'quote' then perform 1 from quotes where id = v_link.entity_id for update;
      when 'purchase_order' then perform 1 from purchase_orders where id = v_link.entity_id for update;
      when 'customer' then perform 1 from customers where id = v_link.entity_id for update;
      when 'property' then perform 1 from properties where id = v_link.entity_id for update;
      when 'supplier' then perform 1 from suppliers where id = v_link.entity_id for update;
      else null;
    end case;
    select expected into v_exp from v_airtable_expected where table_id = v_table and record_id = v_rec;
    for k, v in select key, value from jsonb_each(v_changes) loop
      continue when jsonb_typeof(v) <> 'object';
      -- 1. RoofOps's own write coming back (the webhook echo of n8n's PATCH, or the reconciler reading it before then).
      -- An edit made in the Airtable UI (or by a form or automation) is never an echo: RoofOps writes only through the API.
      w := null;
      if v_src = 'reconciler' or v_origin is null or v_origin = 'publicApi' then
        select * into w from airtable_writes
         where table_id = v_table and record_id = v_rec and field_id = k and echoed_at is null
           and value is not distinct from at_norm(v -> 'current')
           -- An echo is stamped when n8n's PATCH landed: seconds after the write was issued (retries take under a minute).
           -- 5 minutes of clock skew between Airtable and Postgres is tolerated. The reconciler reads whatever is there.
           and case when v_src = 'reconciler' then issued_at > now() - interval '7 days'
                    else v_at between issued_at - interval '5 minutes' and issued_at + interval '30 minutes'
                         -- The execution that issued a write PATCHes only after applying its whole batch, so nothing in
                         -- that batch can be its echo: it is a person choosing that value.
                         and issued_by is distinct from p_worker end
         order by issued_at limit 1 for update;
      end if;
      if w.id is not null then
        if v_src = 'airtable' then
          -- Seen: this write can not echo again, and older writes of the same field can no longer arrive after it.
          update airtable_writes set echoed_at = now()
           where table_id = v_table and record_id = v_rec and field_id = k and echoed_at is null and issued_at <= w.issued_at;
        end if;
        if at_norm(at_repair_value(v_exp -> k)) is distinct from at_norm(v -> 'current') then
          v_echoes := v_echoes || jsonb_build_object(k, v -> 'current');
          v_changes := v_changes - k;          -- never a staff edit: not applied, not compared
        end if;
        continue;
      end if;
      -- 2. A staff edit made against the value Airtable showed while a RoofOps correction had not landed yet.
      if v_src = 'airtable' and coalesce((v ->> 'has_previous')::boolean, v ? 'previous')
         and at_norm(v -> 'previous') is distinct from at_norm(v_exp -> k)
         and exists (select 1 from airtable_writes x where x.table_id = v_table and x.record_id = v_rec and x.field_id = k
                      and x.echoed_at is null and x.issued_at > now() - interval '7 days'
                      and x.replaces is not null and x.replaces = at_norm(v -> 'previous')) then
        v_changes := jsonb_set(v_changes, array[k], v || jsonb_build_object('previous', v_exp -> k, 'previous_in_airtable', v -> 'previous'));
        v_based := v_based || k;
      end if;
    end loop;
    v_event := jsonb_set(v_event, '{changes}', v_changes);
  end if;

  v_res := wf_airtable_change_core(v_event, p_worker);

  -- Airtable shows an overtaken RoofOps write: put it back to canonical, and say why.
  if v_echoes <> '{}'::jsonb then
    select expected into v_exp_after from v_airtable_expected where table_id = v_table and record_id = v_rec;
    v_corr := coalesce(v_res -> 'corrections', '{}'::jsonb);
    select coalesce(v_corr, '{}'::jsonb) || coalesce(jsonb_object_agg(e.key, at_repair_value(v_exp_after -> e.key)), '{}'::jsonb) into v_corr
      from jsonb_each(v_echoes) e where at_norm(at_repair_value(v_exp_after -> e.key)) is distinct from at_norm(e.value);
    select airtable_field_id into v_sync from field_contract where airtable_table_id = v_table and field_key = 'roofops_sync';
    select string_agg(format('↺ %s: an earlier RoofOps correction arrived after a newer edit; "%s" is kept.', c.airtable_name,
                             coalesce(at_norm(at_repair_value(v_exp_after -> c.airtable_field_id)), 'blank')), E'\n')
      into v_note from field_contract c where c.airtable_table_id = v_table and v_echoes ? c.airtable_field_id;
    if v_sync is not null and v_note is not null and not (v_corr ? v_sync) then
      v_corr := v_corr || jsonb_build_object(v_sync, to_char(now() at time zone 'Australia/Brisbane', 'YYYY-MM-DD HH24:MI') || E'\n' || v_note);
    end if;
    v_res := v_res || jsonb_build_object('corrections', v_corr,
      'own_writes_ignored', (select jsonb_agg(c.airtable_name order by c.airtable_name) from field_contract c where c.airtable_table_id = v_table and v_echoes ? c.airtable_field_id));
    update processed_events set result = v_res where consumer = 'airtable_change@1' and idempotency_key = v_key and status = 'COMPLETED'
       and not coalesce((result ->> 'duplicate')::boolean, false);
  end if;
  if cardinality(v_based) > 0 then
    v_res := v_res || jsonb_build_object('edited_before_correction_landed', to_jsonb(v_based));
  end if;
  perform airtable_record_writes(v_key, v_table, v_rec, v_res -> 'corrections', v_event -> 'current', p_worker);
  return v_res;
end $$;

--
-- Name: wf_airtable_change_core(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_airtable_change_core(p_event jsonb, p_worker text DEFAULT 'n8n'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_key text := p_event ->> 'event_id'; v_table text := p_event ->> 'table_id'; v_rec text := p_event ->> 'record_id';
  v_src text := coalesce(nullif(p_event ->> 'source', ''), 'airtable'); v_actor text := coalesce(nullif(p_event ->> 'actor_id', ''), 'unknown');
  v_changes jsonb := coalesce(p_event -> 'changes', '{}'::jsonb); v_current jsonb := coalesce(p_event -> 'current', '{}'::jsonb);
  v_at timestamptz; v_entity text; v_id uuid; v_ref text; v_evid uuid; v_claimed boolean; v_pe processed_events;
  f record; v_new text; v_prev text; v_canon text; v_reason text; v_exp jsonb; v_exp_after jsonb; v_status_applied boolean := false;
  v_applied jsonb := '[]'; v_rejected jsonb := '[]'; v_reverted jsonb := '[]'; v_stale jsonb := '[]'; v_deferred jsonb := '[]';
  v_corr jsonb := '{}'::jsonb; v_note text := ''; v_res jsonb; v_outcome text; v_exc text; v_sync_field text;
begin
  -- 1. Validate the envelope.
  if coalesce(v_key, '') = '' or length(v_key) > 300 or coalesce(v_table, '') !~ '^tbl[A-Za-z0-9]{14}$' or coalesce(v_rec, '') !~ '^rec[A-Za-z0-9]{14}$'
     or jsonb_typeof(v_changes) <> 'object' then
    return jsonb_build_object('outcome', 'INVALID_EVENT', 'message', 'event_id, table_id, record_id and changes are required');
  end if;
  begin v_at := coalesce((p_event ->> 'occurred_at')::timestamptz, now());
  exception when others then return jsonb_build_object('outcome', 'INVALID_EVENT', 'message', 'occurred_at must be an ISO timestamp'); end;
  select min(entity) into v_entity from field_contract where airtable_table_id = v_table;
  if v_entity is null then return jsonb_build_object('outcome', 'INVALID_EVENT', 'message', 'table is not managed by RoofOps'); end if;
  select airtable_field_id into v_sync_field from field_contract where airtable_table_id = v_table and field_key = 'roofops_sync';

  -- 2. Transport idempotency: the same Airtable transaction is processed once, whatever the delivery count.
  v_evid := wf_log_event(v_key, stable_uuid('correlation', v_key), null, 'airtable.record_changed', v_entity, null, null,
                         case when v_src = 'reconciler' then 'SYSTEM' else 'USER' end, v_actor, v_src, 'RECEIVED', null,
                         jsonb_build_object('record_id', v_rec, 'table_id', v_table, 'worker', p_worker), p_event);
  insert into processed_events (consumer, idempotency_key, first_event_id, request_hash, status, locked_by, lease_expires_at)
  values ('airtable_change@1', v_key, v_evid, md5(p_event::text), 'PROCESSING', p_worker, now() + interval '5 minutes')
  on conflict do nothing returning true into v_claimed;
  if v_claimed is null then
    select * into v_pe from processed_events where consumer = 'airtable_change@1' and idempotency_key = v_key for update;
    update processed_events set delivery_count = delivery_count + 1, last_seen_at = now() where consumer = v_pe.consumer and idempotency_key = v_key;
    -- Corrections already written and read back are not written again. Unverified ones (the first delivery failed
    -- before its Airtable write-back) are re-issued, recomputed from canonical state as it is NOW.
    if coalesce((v_pe.result ->> 'writeback_verified')::boolean, false) or coalesce(v_pe.result -> 'corrections', '{}'::jsonb) = '{}'::jsonb then
      v_corr := '{}'::jsonb;
    else
      select coalesce(jsonb_object_agg(k, coalesce(at_repair_value(x.expected -> k), v_pe.result -> 'corrections' -> k)), '{}'::jsonb) into v_corr
        from jsonb_object_keys(v_pe.result -> 'corrections') k
        left join v_airtable_expected x on x.table_id = v_table and x.record_id = v_rec;
    end if;
    return coalesce(v_pe.result, '{}'::jsonb) || jsonb_build_object('duplicate', true, 'delivery_count', v_pe.delivery_count + 1, 'corrections', v_corr);
  end if;

  -- 3. Identity: the record link recorded by RoofOps (never names).
  select entity_id into v_id from external_links where provider = 'AIRTABLE' and entity_type = v_entity and external_type = 'Record' and external_id = v_rec;
  if v_id is null then
    v_exc := wf_open_sync_exception('airtable_sync', v_entity, null, v_rec, 'NOT_FOUND',
               format('Airtable %s record %s is not linked to any RoofOps record (created directly in Airtable?). RoofOps ignored its changes.', v_entity, v_rec));
    v_res := jsonb_build_object('outcome', 'UNKNOWN_RECORD', 'record_id', v_rec, 'exception_number', v_exc, 'corrections', '{}'::jsonb);
    update automation_events set status = 'REJECTED', error_class = 'NOT_FOUND', metadata = metadata || jsonb_build_object('reason', 'unknown record') where event_id = v_evid;
    update processed_events set status = 'COMPLETED', completed_at = now(), result = v_res, lease_expires_at = null where consumer = 'airtable_change@1' and idempotency_key = v_key;
    return v_res;
  end if;

  -- 4. One writer per record: everything below is evaluated against the row as it is *after* any concurrent change commits.
  case v_entity
    when 'project' then select project_number into v_ref from projects where id = v_id for update;
    when 'quote' then select quote_number into v_ref from quotes where id = v_id for update;
    when 'purchase_order' then select po_number into v_ref from purchase_orders where id = v_id for update;
    when 'customer' then select customer_number into v_ref from customers where id = v_id for update;
    when 'property' then select property_number into v_ref from properties where id = v_id for update;
    when 'supplier' then select supplier_code into v_ref from suppliers where id = v_id for update;
  end case;
  select expected into v_exp from v_airtable_expected where table_id = v_table and entity_id = v_id;
  v_current := v_current || (select coalesce(jsonb_object_agg(k, v -> 'current'), '{}'::jsonb) from jsonb_each(v_changes) as x(k, v));

  -- 5. Each changed field, by its owner.
  for f in select c.*, ch.key as fid, ch.value as chv from jsonb_each(v_changes) ch
             join field_contract c on c.airtable_table_id = v_table and c.airtable_field_id = ch.key
            where c.reconcile in ('APPLY_VIA_HANDLER', 'REPAIR_AIRTABLE') order by (c.field_key = 'status') desc, c.field_key
  loop
    v_new := at_norm(f.chv -> 'current');
    v_canon := at_norm(v_exp -> f.fid);
    if v_new is not distinct from v_canon then continue; end if;          -- no change, or our own write echoing back
    if f.owner <> 'AIRTABLE_EDIT' then
      v_reverted := v_reverted || jsonb_build_object('field', f.airtable_name, 'attempted', v_new, 'kept', v_canon);
      insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
      values ('SYSTEM', 'airtable_sync', 'airtable.edit_reverted', v_entity, v_id, v_ref, jsonb_build_object(f.field_key, v_new),
              jsonb_build_object(f.field_key, v_canon), f.airtable_name || ' is managed by RoofOps [' || v_key || ']');
      continue;
    end if;
    -- Delayed / out-of-order delivery: a newer change to this field was already applied.
    if v_src = 'airtable' and exists (select 1 from external_field_versions x where x.entity_type = v_entity and x.entity_id = v_id
                                        and x.field_key = f.field_key and x.last_source_at > v_at) then
      v_stale := v_stale || jsonb_build_object('field', f.airtable_name, 'value', v_new);
      continue;
    end if;
    -- Compare-and-set: the edit was made against a value RoofOps no longer holds (concurrent change) → refuse, do not guess.
    if v_src = 'airtable' and coalesce((f.chv ->> 'has_previous')::boolean, f.chv ? 'previous')
       and at_norm(f.chv -> 'previous') is distinct from v_canon then
      v_rejected := v_rejected || jsonb_build_object('field', f.airtable_name, 'attempted', v_new, 'kept', v_canon,
        'reason', format('it was changed from "%s", but RoofOps already had "%s" (someone else changed it at the same time); please re-apply if still intended',
                         coalesce(at_norm(f.chv -> 'previous'), 'blank'), coalesce(v_canon, 'blank')), 'conflict', true);
      continue;
    end if;
    v_reason := case v_entity
      when 'project' then project_apply_change(v_id, f.field_key, v_new, v_current, v_actor, v_key)
      when 'purchase_order' then po_apply_change(v_id, f.field_key, v_new, v_current, v_actor, v_key)
      when 'quote' then quote_apply_change(v_id, f.field_key, v_new, v_current, v_actor, v_key)
      else 'this field cannot be changed from Airtable' end;
    if v_reason is null then
      v_applied := v_applied || jsonb_build_object('field', f.airtable_name, 'from', v_canon, 'to', v_new);
      if f.field_key = 'status' then v_status_applied := true; end if;
      insert into external_field_versions (entity_type, entity_id, field_key, last_source, last_source_at, last_event_key, last_value)
      values (v_entity, v_id, f.field_key, v_src, v_at, v_key, v_new)
      on conflict (entity_type, entity_id, field_key) do update set last_source = excluded.last_source,
        last_source_at = greatest(external_field_versions.last_source_at, excluded.last_source_at), last_event_key = excluded.last_event_key,
        last_value = excluded.last_value, applied_at = now();
    elsif v_reason = 'DEFERRED' then
      v_deferred := v_deferred || jsonb_build_object('field', f.airtable_name, 'to', v_new, 'handled_by', 'Quote Accepted → Project workflow');
    else
      v_rejected := v_rejected || jsonb_build_object('field', f.airtable_name, 'attempted', v_new, 'kept', v_canon, 'reason', v_reason);
    end if;
  end loop;

  -- 6. Corrections: every checked field Airtable now shows differently from canonical (except deferred acceptance).
  select expected into v_exp_after from v_airtable_expected where table_id = v_table and entity_id = v_id;
  select coalesce(jsonb_object_agg(e.key, at_repair_value(e.value)), '{}'::jsonb) into v_corr
    from jsonb_each(v_exp_after) e
    join field_contract c on c.airtable_table_id = v_table and c.airtable_field_id = e.key and c.reconcile in ('APPLY_VIA_HANDLER', 'REPAIR_AIRTABLE')
   where (v_changes ? e.key or (v_status_applied and c.field_key in ('actual_start_date', 'actual_completion_date', 'sent_on')))
     and not at_matches(e.value, v_current -> e.key)
     and not exists (select 1 from jsonb_array_elements(v_deferred || v_stale) d where d ->> 'field' = c.airtable_name);

  v_note := concat_ws(E'\n',
    (select string_agg(format('✓ %s: %s → %s applied', a ->> 'field', coalesce(a ->> 'from', 'blank'), coalesce(a ->> 'to', 'blank')), E'\n') from jsonb_array_elements(v_applied) a),
    (select string_agg(format('✗ %s: "%s" not applied: %s. Kept "%s".', r ->> 'field', coalesce(r ->> 'attempted', 'blank'), r ->> 'reason', coalesce(r ->> 'kept', 'blank')), E'\n') from jsonb_array_elements(v_rejected) r),
    (select string_agg(format('↺ %s is managed by RoofOps; "%s" was reverted to "%s".', r ->> 'field', coalesce(r ->> 'attempted', 'blank'), coalesce(r ->> 'kept', 'blank')), E'\n') from jsonb_array_elements(v_reverted) r),
    (select string_agg(format('• %s: an older change arrived late and was ignored.', s ->> 'field'), E'\n') from jsonb_array_elements(v_stale) s));
  -- Airtable API calls are scarce (Free plan): a plain accepted edit needs no write-back; a refusal, a revert or a derived
  -- field does, and then the note says why.
  if v_note <> '' and v_sync_field is not null and (v_corr <> '{}'::jsonb or jsonb_array_length(v_rejected) + jsonb_array_length(v_reverted) > 0) then
    v_corr := v_corr || jsonb_build_object(v_sync_field, to_char(now() at time zone 'Australia/Brisbane', 'YYYY-MM-DD HH24:MI') || E'\n' || v_note);
  end if;

  v_outcome := case when jsonb_array_length(v_applied) > 0 and jsonb_array_length(v_rejected) + jsonb_array_length(v_reverted) = 0 then 'APPLIED'
                    when jsonb_array_length(v_applied) > 0 then 'PARTIALLY_APPLIED'
                    when jsonb_array_length(v_rejected) > 0 then 'REJECTED'
                    when jsonb_array_length(v_reverted) > 0 then 'REVERTED'
                    when jsonb_array_length(v_stale) > 0 then 'STALE'
                    when jsonb_array_length(v_deferred) > 0 then 'DEFERRED'
                    else 'NO_CHANGE' end;
  v_res := jsonb_build_object('outcome', v_outcome, 'entity', v_entity, 'business_key', v_ref, 'entity_id', v_id, 'record_id', v_rec, 'table_id', v_table,
                              'applied', v_applied, 'rejected', v_rejected, 'reverted', v_reverted, 'stale', v_stale, 'deferred', v_deferred,
                              'corrections', v_corr, 'note', nullif(v_note, ''));
  update automation_events set entity_id = v_id, business_reference = v_ref,
         status = case when v_outcome in ('REJECTED', 'REVERTED') then 'REJECTED' when v_outcome = 'STALE' then 'DUPLICATE_IGNORED'
                       when v_outcome in ('NO_CHANGE', 'DEFERRED') then 'INFO' else 'SUCCEEDED' end,
         error_class = case when v_outcome = 'REJECTED' then 'ILLEGAL_TRANSITION' when v_outcome = 'REVERTED' then 'UNAUTHORIZED_EDIT'
                            when v_outcome = 'STALE' then 'STALE_EVENT' end,
         metadata = metadata || jsonb_build_object('outcome', v_outcome, 'reason', nullif(v_note, ''))
   where event_id = v_evid;
  update processed_events set status = 'COMPLETED', completed_at = now(), result = v_res, lease_expires_at = null
   where consumer = 'airtable_change@1' and idempotency_key = v_key;
  -- What RoofOps now believes Airtable shows (after the corrections n8n is about to write).
  insert into airtable_observations (table_id, record_id, field_id, value, observed_at, source)
  select v_table, v_rec, k, at_norm(coalesce(v_corr -> k, v_current -> k)), now(), v_src
    from jsonb_object_keys(v_current) k where exists (select 1 from field_contract c where c.airtable_field_id = k and c.reconcile <> 'IGNORE'
                                                        and not exists (select 1 from jsonb_array_elements(v_stale) st where st ->> 'field' = c.airtable_name))
  on conflict (table_id, record_id, field_id) do update set value = excluded.value, observed_at = excluded.observed_at, source = excluded.source;
  return v_res;
end $_$;

--
-- Name: wf_airtable_cursor(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_airtable_cursor(p_webhook_id text) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce((select cursor_value from integration_cursors where provider = 'AIRTABLE' and cursor_key = p_webhook_id), 1)
$$;

--
-- Name: wf_airtable_cursor_advance(text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_airtable_cursor_advance(p_webhook_id text, p_cursor bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v bigint;
begin
  if coalesce(p_webhook_id, '') !~ '^ach[A-Za-z0-9]{14}$' then
    raise exception 'invalid Airtable webhook id %', p_webhook_id using errcode = 'check_violation';
  end if;
  insert into integration_cursors (provider, cursor_key, cursor_value) values ('AIRTABLE', p_webhook_id, p_cursor)
  on conflict (provider, cursor_key) do update
    set cursor_value = greatest(integration_cursors.cursor_value, excluded.cursor_value), updated_at = now()
  returning cursor_value into v;
  return v;
end $_$;

--
-- Name: wf_airtable_ping_cursor(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_airtable_ping_cursor(p_webhook_id text, p_body text, p_mac text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $_$
declare
  v_key bytea; v_expected text; v_verdict text; v_accept boolean;
  v_mode text := case (select value from app_settings where key = 'airtable.ping_mac') when 'log' then 'log' else 'enforce' end;
begin
  if coalesce(p_webhook_id, '') !~ '^ach[A-Za-z0-9]{14}$' then
    raise exception 'invalid Airtable webhook id %', p_webhook_id using errcode = 'check_violation';
  end if;
  select mac_secret into v_key from integration_webhook_secrets where provider = 'AIRTABLE' and webhook_id = p_webhook_id;
  if v_key is null then
    v_verdict := 'NO_SECRET';
  elsif coalesce(p_mac, '') = '' then
    v_verdict := 'MAC_MISSING';
  else
    v_expected := 'hmac-sha256=' || encode(hmac(convert_to(coalesce(p_body, ''), 'UTF8'), v_key, 'sha256'), 'hex');
    -- Compare digests of both values, so how long the comparison takes says nothing about the expected MAC.
    v_verdict := case when digest(v_expected, 'sha256') = digest(p_mac, 'sha256') then 'VALID' else 'MAC_MISMATCH' end;
  end if;
  v_accept := v_verdict = 'VALID' or v_mode = 'log';
  insert into airtable_ping_checks (webhook_id, verdict, mode, accepted) values (p_webhook_id, v_verdict, v_mode, v_accept);
  delete from airtable_ping_checks where checked_at < now() - interval '7 days';
  if not v_accept then
    return null;
  end if;
  return wf_airtable_cursor(p_webhook_id);
end $_$;

--
-- Name: wf_airtable_sign_ping(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_airtable_sign_ping(p_webhook_id text, p_body text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $_$
declare v_ping jsonb; v_key bytea;
begin
  begin
    v_ping := p_body::jsonb;
  exception when others then
    v_ping := null;
  end;
  if coalesce(p_webhook_id, '') !~ '^ach[A-Za-z0-9]{14}$' or v_ping is null or jsonb_typeof(v_ping) <> 'object'
     or (v_ping #>> '{webhook,id}') is distinct from p_webhook_id then
    raise exception 'not a ping for %', coalesce(p_webhook_id, 'no webhook') using errcode = 'check_violation';
  end if;
  select mac_secret into v_key from integration_webhook_secrets where provider = 'AIRTABLE' and webhook_id = p_webhook_id;
  if v_key is null then
    return null;
  end if;
  return 'hmac-sha256=' || encode(hmac(convert_to(p_body, 'UTF8'), v_key, 'sha256'), 'hex');
end $_$;

--
-- Name: wf_airtable_webhook_created(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_airtable_webhook_created(p_webhook_id text, p_notification_url text, p_mac_secret_base64 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'public', 'pg_temp'
    AS $_$
declare v_key bytea; v_id uuid;
begin
  if coalesce(p_webhook_id, '') !~ '^ach[A-Za-z0-9]{14}$' then
    return jsonb_build_object('stored', false, 'reason', 'NO_WEBHOOK');
  end if;
  if not exists (select 1 from unnest(string_to_array((select value from app_settings where key = 'airtable.expected_webhooks'), ',')) u
                  where btrim(u) = p_notification_url) then
    raise exception 'unexpected Airtable notification URL for webhook %', p_webhook_id using errcode = 'check_violation';
  end if;
  begin
    v_key := decode(p_mac_secret_base64, 'base64');
  exception when others then
    v_key := null;
  end;
  if v_key is null or length(v_key) < 16 then
    raise exception 'invalid Airtable MAC secret for webhook %', p_webhook_id using errcode = 'check_violation';
  end if;
  delete from integration_webhook_secrets
   where provider = 'AIRTABLE' and (webhook_id = p_webhook_id or notification_url = p_notification_url);
  insert into integration_webhook_secrets (provider, webhook_id, notification_url, mac_secret)
  values ('AIRTABLE', p_webhook_id, p_notification_url, v_key) returning id into v_id;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
  values ('WORKFLOW', 'n8n:webhook-maintenance', 'integration.webhook_secret_stored', 'integration_webhook_secret', v_id, p_webhook_id,
          jsonb_build_object('notification_url', p_notification_url), 'Airtable returned the webhook MAC secret at creation (ADR-041)');
  return jsonb_build_object('stored', true, 'webhook_id', p_webhook_id);
end $_$;

--
-- Name: wf_airtable_writeback_verified(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_airtable_writeback_verified(p_event_key text, p_table_id text, p_record_id text, p_readback jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_rb jsonb := at_normalize_fields(p_readback); v_exp jsonb; v_landed jsonb := '[]'; v_res jsonb; k text;
begin
  select expected into v_exp from v_airtable_expected where table_id = p_table_id and record_id = p_record_id;
  for k in select jsonb_object_keys(coalesce(v_rb, '{}'::jsonb)) loop
    if not at_matches(v_exp -> k, v_rb -> k) and exists (
         select 1 from airtable_writes w where w.table_id = p_table_id and w.record_id = p_record_id and w.field_id = k
            and w.issued_at > now() - interval '7 days'
            and (w.source_key = p_event_key or w.source_key like p_event_key || ':%')
            and w.value is not distinct from at_norm(v_rb -> k)) then
      v_landed := v_landed || to_jsonb(k);
    end if;
  end loop;
  update airtable_writes w set verified_at = coalesce(w.verified_at, now())
   where w.table_id = p_table_id and w.record_id = p_record_id and (w.source_key = p_event_key or w.source_key like p_event_key || ':%')
     and v_rb ? w.field_id and w.value is not distinct from at_norm(v_rb -> w.field_id);
  -- What Airtable shows for overtaken fields is still recorded, so the brief divergence is visible until the echo fixes it.
  insert into airtable_observations (table_id, record_id, field_id, value, observed_at, source)
  select p_table_id, p_record_id, x, at_norm(v_rb -> x), now(), 'readback' from jsonb_array_elements_text(v_landed) x
  on conflict (table_id, record_id, field_id) do update set value = excluded.value, observed_at = excluded.observed_at, source = excluded.source;
  v_res := wf_airtable_writeback_verified_core(p_event_key, p_table_id, p_record_id,
             (select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) from jsonb_each(coalesce(v_rb, '{}'::jsonb)) where not (v_landed ? key)));
  if jsonb_array_length(v_landed) > 0 then
    v_res := v_res || jsonb_build_object('overtaken_fields', v_landed);
  end if;
  return v_res;
end $$;

--
-- Name: wf_airtable_writeback_verified_core(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_airtable_writeback_verified_core(p_event_key text, p_table_id text, p_record_id text, p_readback jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_exp jsonb; v_bad jsonb;
begin
  select expected into v_exp from v_airtable_expected where table_id = p_table_id and record_id = p_record_id;
  select coalesce(jsonb_agg(e.key), '[]'::jsonb) into v_bad from jsonb_each(coalesce(v_exp, '{}'::jsonb)) e
   join field_contract c on c.airtable_field_id = e.key and c.reconcile in ('APPLY_VIA_HANDLER', 'REPAIR_AIRTABLE')
   where p_readback ? e.key and not at_matches(e.value, p_readback -> e.key);
  perform wf_log_event(p_event_key || ':writeback', stable_uuid('correlation', p_event_key), stable_uuid('event', p_event_key), 'airtable.writeback.verified',
                       null, null, p_record_id, 'INTEGRATION', 'airtable', 'airtable', case when jsonb_array_length(v_bad) = 0 then 'SUCCEEDED' else 'FAILED' end,
                       case when jsonb_array_length(v_bad) = 0 then null else 'RECONCILIATION_MISMATCH' end, jsonb_build_object('mismatched_fields', v_bad), null);
  if jsonb_array_length(v_bad) = 0 then
    update processed_events set result = result || '{"writeback_verified": true}'::jsonb
     where consumer = 'airtable_change@1' and idempotency_key = p_event_key and status = 'COMPLETED';
  end if;
  insert into airtable_observations (table_id, record_id, field_id, value, observed_at, source)
  select p_table_id, p_record_id, k, at_norm(p_readback -> k), now(), 'readback' from jsonb_object_keys(p_readback) k
   where exists (select 1 from field_contract c where c.airtable_field_id = k and c.reconcile <> 'IGNORE')
  on conflict (table_id, record_id, field_id) do update set value = excluded.value, observed_at = excluded.observed_at, source = excluded.source;
  return jsonb_build_object('verified', jsonb_array_length(v_bad) = 0, 'mismatched_fields', v_bad);
end $$;

--
-- Name: wf_claim_side_effect(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_claim_side_effect(p_key text, p_worker text, p_lease_seconds integer DEFAULT 120) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare o outbox; v_inv invoices; v_pin text; v_problem text; v_res jsonb;
begin
  select * into o from outbox where idempotency_key = p_key;
  if o.topic = 'xero.create_draft_invoice' then
    select * into v_inv from invoices where id = o.aggregate_id;
    if v_inv.status = 'VOIDED' then
      return jsonb_build_object('claimed', false, 'key', o.idempotency_key, 'topic', o.topic, 'status', 'INVOICE_VOIDED',
        'message', format('%s was voided: no Xero draft is created for it', v_inv.invoice_number));
    end if;
    -- AC-14C P2-D2: a generation >= 2 write is claimed only as the proven supervised reissue (xero_reissue_proof).
    if o.status <> 'DONE' and o.generation >= 2 then
      v_problem := xero_reissue_proof(o);
      if v_problem is not null then
        perform wf_open_sync_exception('project_to_invoice', 'invoice', v_inv.id, v_inv.invoice_number, 'RECONCILIATION_MISMATCH',
          format('%s: the generation %s Xero draft write was not claimed: %s. Nothing was sent to Xero; a person must check the reissue', v_inv.invoice_number, o.generation, v_problem));
        return jsonb_build_object('claimed', false, 'key', o.idempotency_key, 'topic', o.topic, 'status', 'REISSUE_NOT_PROVEN', 'message', v_problem);
      end if;
    end if;
    if o.status <> 'DONE' then
      -- A pin change in progress makes this wait (then it sees the new pin); a claim in progress makes a change wait.
      perform pg_advisory_xact_lock_shared(hashtextextended('roofops:xero.demo_tenant_id', 0));
      select value into v_pin from app_settings where key = 'xero.demo_tenant_id';
      v_problem := xero_write_tenant_problem(o, v_pin);
      if v_problem is not null then
        perform wf_open_sync_exception('project_to_invoice', 'project', v_inv.project_id,
          (select project_number from projects where id = v_inv.project_id), 'PERMISSION_DENIED', v_problem);
        return jsonb_build_object('claimed', false, 'key', o.idempotency_key, 'topic', o.topic, 'message', v_problem,
          'status', case when coalesce(o.payload ->> 'xero_tenant_id', '') = '' then 'TENANT_MISSING'
                         when coalesce(v_pin, '') = '' then 'TENANT_NOT_PINNED' else 'TENANT_CHANGED' end);
      end if;
    end if;
  end if;
  v_res := wf_claim_side_effect_core(p_key, p_worker, p_lease_seconds);
  -- AC-14C P2-D2: 05 needs the superseded Xero InvoiceIDs of a proven reissue so a stale document never controls it.
  -- Generation 1's claim result is unchanged.
  if o.topic = 'xero.create_draft_invoice' and o.generation >= 2 and coalesce((v_res ->> 'claimed')::boolean, false) then
    v_res := v_res || jsonb_build_object('generation', o.generation,
      'superseded_xero_invoice_ids', coalesce((select jsonb_agg(g.xero_invoice_id order by g.generation) from invoice_xero_draft_generations g
                                                where g.invoice_id = o.aggregate_id and g.superseded_at is not null and g.xero_invoice_id is not null), '[]'::jsonb),
      'reissue_approval_number', o.payload ->> 'approval_number');
  end if;
  return v_res;
end $$;

--
-- Name: wf_claim_side_effect_core(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_claim_side_effect_core(p_key text, p_worker text, p_lease_seconds integer DEFAULT 120) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare o outbox; v_dep outbox;
begin
  select * into o from outbox where idempotency_key = p_key;
  if not found then
    return jsonb_build_object('claimed', false, 'status', 'UNKNOWN_KEY');
  end if;
  if o.topic = 'airtable.project_writeback' then
    select * into v_dep from outbox where aggregate_id = o.aggregate_id and topic = 'drive.ensure_project_folder';
    if found and v_dep.status <> 'DONE' then
      return jsonb_build_object('claimed', false, 'key', o.idempotency_key, 'topic', o.topic, 'status', 'WAITING_ON_DEPENDENCY',
        'depends_on', v_dep.idempotency_key, 'dependency_status', v_dep.status);
    end if;
  end if;

  update outbox set status = 'DISPATCHING', attempts = attempts + 1, locked_until = now() + make_interval(secs => p_lease_seconds),
         last_error = null
   where idempotency_key = p_key
     and ((status in ('PENDING','FAILED') and next_attempt_at <= now()) or (status = 'DISPATCHING' and locked_until < now()))
  returning * into o;
  if found then
    return jsonb_build_object('claimed', true, 'key', o.idempotency_key, 'topic', o.topic, 'attempt', o.attempts, 'worker', p_worker,
      'payload', o.payload || case when v_dep.idempotency_key is not null then jsonb_build_object('drive_folder', v_dep.result) else '{}'::jsonb end);
  end if;
  select * into o from outbox where idempotency_key = p_key;
  return jsonb_build_object('claimed', false, 'key', o.idempotency_key, 'topic', o.topic, 'status', o.status,
    'result', o.result, 'retry_at', case when o.status = 'FAILED' then o.next_attempt_at end, 'locked_until', o.locked_until,
    'attempts', o.attempts, 'last_error', o.last_error);
end $$;

--
-- Name: wf_complete_side_effect(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_complete_side_effect(p_key text, p_result jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare o outbox; v_inv invoices; v_pin text; v_bound text; v_draft text; v_from text;
begin
  select * into o from outbox where idempotency_key = p_key;
  if o.topic = 'xero.create_draft_invoice' then
    select * into v_inv from invoices where id = o.aggregate_id;
    if v_inv.status = 'VOIDED' then
      -- Refused like any bad proof: 05 records the failure (dead letter + exception) and tells Airtable nothing was linked.
      raise exception '% is voided: the Xero draft % was not linked. Void or delete it in Xero', v_inv.invoice_number,
        coalesce(p_result ->> 'invoice_number', o.payload ->> 'xero_invoice_number') using errcode = 'check_violation';
    end if;
    if o.status <> 'DONE' then
      select value into v_pin from app_settings where key = 'xero.demo_tenant_id';
      v_bound := nullif(o.payload ->> 'xero_tenant_id', '');
      v_draft := coalesce(p_result ->> 'invoice_number', o.payload ->> 'xero_invoice_number');
      v_from := coalesce(left(p_result ->> 'tenant_id', 8) || '…', 'an unnamed tenant');
      if v_bound is null then
        raise exception '% carries no Xero tenant: the Xero draft % read back from tenant % was not linked. A person must check it in that tenant',
          v_inv.invoice_number, v_draft, v_from using errcode = 'check_violation';
      elsif coalesce(v_pin, '') = '' then
        raise exception '%: no Xero tenant is pinned now (it was approved for tenant %…): the Xero draft % read back from tenant % was not linked. A person must check it in that tenant',
          v_inv.invoice_number, left(v_bound, 8), v_draft, v_from using errcode = 'check_violation';
      elsif v_pin <> v_bound then
        raise exception '%: the pinned Xero tenant changed from %… to %… while the draft was written: the Xero draft % read back from tenant % was not linked. A person must check it in that tenant',
          v_inv.invoice_number, left(v_bound, 8), left(v_pin, 8), v_draft, v_from using errcode = 'check_violation';
      end if;
      -- A proof from another tenant than the bound (and pinned) one is refused by the core check.
      -- AC-14C P2-D2: a generation >= 2 draft is linked only as the proven reissue, and never to a superseded InvoiceID.
      if o.generation >= 2 then
        v_from := xero_reissue_proof(o);
        if v_from is not null then
          raise exception '%: the generation % Xero draft % was not linked: %', v_inv.invoice_number, o.generation, v_draft, v_from using errcode = 'check_violation';
        end if;
        if exists (select 1 from invoice_xero_draft_generations g where g.invoice_id = o.aggregate_id and g.superseded_at is not null
                      and g.xero_invoice_id = p_result ->> 'invoice_id') then
          raise exception '%: % is a superseded Xero invoice (an earlier generation); it cannot be linked as generation %',
            v_inv.invoice_number, p_result ->> 'invoice_id', o.generation using errcode = 'check_violation';
        end if;
      end if;
    end if;
  end if;
  -- Quote publishing lifecycle (20261017060000): the report must come from the attempt that holds the hand-off now (a
  -- worker whose lease ran out and whose hand-off was claimed again is late: it records nothing), and Airtable must hold
  -- exactly one record for the quote, with a valid Status. The record checks themselves are in the core.
  if o.topic = 'airtable.quote_publish' and o.status = 'DISPATCHING' then
    if coalesce(p_result ->> 'attempt', '') !~ '^[0-9]{1,9}$' or (p_result ->> 'attempt')::int <> o.attempts then
      raise exception 'quote hand-off % is held by attempt %; a report from attempt % is late and records nothing', p_key, o.attempts,
        coalesce(p_result ->> 'attempt', '(none)') using errcode = 'check_violation';
    end if;
    if coalesce(p_result ->> 'quote_record_count', '') is distinct from '1' then
      raise exception 'Airtable holds % quote records for %; exactly one is required', coalesce(p_result ->> 'quote_record_count', 'an unknown number of'),
        o.payload ->> 'quote_number' using errcode = 'check_violation';
    end if;
    if jsonb_typeof(p_result -> 'quote_read_back') = 'object'   -- no read-back at all is refused by the core
       and coalesce(p_result -> 'quote_read_back' ->> 'status', '') not in (select label from state_machine_states where machine = 'quote' and state in ('SENT', 'ACCEPTED', 'LOST', 'EXPIRED')) then
      raise exception 'the Airtable quote record for % has Status "%", not a status of a sent quote', o.payload ->> 'quote_number',
        coalesce(p_result -> 'quote_read_back' ->> 'status', '') using errcode = 'check_violation';
    end if;
  end if;
  return wf_complete_side_effect_core(p_key, p_result);
end $_$;

--
-- Name: wf_complete_side_effect_core(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_complete_side_effect_core(p_key text, p_result jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  o outbox;
  v_existing text;
  v_run uuid;
  v_left int;
  v_ref text;
  v_expected jsonb;
  v_got jsonb;
  v_sub jsonb;
  v_drive_url text;
begin
  select * into o from outbox where idempotency_key = p_key for update;
  if not found then raise exception 'unknown side effect %', p_key using errcode = 'no_data_found'; end if;
  if o.status = 'DONE' then
    return jsonb_build_object('status', 'ALREADY_DONE', 'result', o.result);
  end if;
  if o.status <> 'DISPATCHING' then
    raise exception 'side effect % is %, not claimed', p_key, o.status using errcode = 'check_violation';
  end if;
  if coalesce((p_result ->> 'verified')::boolean, false) is not true then
    raise exception 'refusing to record % without read-back verification (verified=true)', p_key using errcode = 'check_violation';
  end if;
  v_ref := coalesce(o.payload ->> 'invoice_number', o.payload ->> 'project_number', o.payload ->> 'quote_number');

  if o.topic = 'drive.ensure_project_folder' then
    if coalesce(p_result ->> 'folder_id', '') = '' or coalesce(p_result ->> 'mime_type', '') <> 'application/vnd.google-apps.folder' then
      raise exception 'drive result needs folder_id and mime_type=application/vnd.google-apps.folder' using errcode = 'check_violation';
    end if;
    if coalesce(p_result ->> 'parent_id', '') = '' or coalesce((p_result ->> 'trashed')::boolean, true) then
      raise exception 'drive result needs parent_id and trashed=false from the read-back' using errcode = 'check_violation';
    end if;
    if p_result ->> 'name' is distinct from o.payload ->> 'folder_name' then
      raise exception 'drive folder name % does not match %', p_result ->> 'name', o.payload ->> 'folder_name' using errcode = 'check_violation';
    end if;
    if p_result -> 'app_properties' ->> 'roofops_project_id' is distinct from o.aggregate_id::text then
      raise exception 'drive folder is not tagged with project %', o.aggregate_id using errcode = 'check_violation';
    end if;
    -- Every requested subfolder, exactly once, each read back as a live folder inside the project folder.
    v_expected := coalesce(o.payload -> 'subfolders', '[]'::jsonb);
    select coalesce(jsonb_agg(s ->> 'name' order by s ->> 'name'), '[]') into v_got
      from jsonb_array_elements(coalesce(p_result -> 'subfolders', '[]'::jsonb)) s
     where coalesce(s ->> 'id', '') <> '' and s ->> 'parent_id' = p_result ->> 'folder_id'
       and s ->> 'mime_type' = 'application/vnd.google-apps.folder' and not coalesce((s ->> 'trashed')::boolean, true);
    if v_got <> (select coalesce(jsonb_agg(e order by e), '[]') from jsonb_array_elements_text(v_expected) e) then
      raise exception 'drive subfolders read back % do not match the required %', v_got, v_expected using errcode = 'check_violation';
    end if;

    select external_id into v_existing from external_links
     where provider = 'GOOGLE_DRIVE' and entity_type = 'project' and entity_id = o.aggregate_id and external_type = 'Folder';
    if v_existing is not null and v_existing <> p_result ->> 'folder_id' then
      raise exception 'project % already linked to Drive folder %, refusing a second folder %', v_ref, v_existing, p_result ->> 'folder_id'
        using errcode = 'unique_violation';
    end if;
    insert into external_links (provider, entity_type, entity_id, external_type, external_id, external_url, last_synced_at, verified_at)
    values ('GOOGLE_DRIVE', 'project', o.aggregate_id, 'Folder', p_result ->> 'folder_id', p_result ->> 'web_view_link', now(), now())
    on conflict (provider, entity_type, entity_id, external_type) do update set verified_at = now(), last_synced_at = now();
    for v_sub in select * from jsonb_array_elements(p_result -> 'subfolders') loop
      insert into external_links (provider, entity_type, entity_id, external_type, external_id, external_url, last_synced_at, verified_at)
      values ('GOOGLE_DRIVE', 'project', o.aggregate_id, 'Folder:' || (v_sub ->> 'name'), v_sub ->> 'id', v_sub ->> 'web_view_link', now(), now())
      on conflict (provider, entity_type, entity_id, external_type) do update set verified_at = now(), last_synced_at = now();
    end loop;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, external_reference, reason, correlation_id)
    values ('INTEGRATION', 'google-drive', 'drive.folder.link', 'project', o.aggregate_id, v_ref,
            p_result - 'verified', p_result ->> 'folder_id', 'Project folder and subfolders created and read back from Google Drive', o.correlation_id);

  elsif o.topic = 'airtable.project_writeback' then
    if coalesce(p_result ->> 'project_record_id', '') !~ '^rec[A-Za-z0-9]{14}$' then
      raise exception 'airtable result needs project_record_id (recXXXXXXXXXXXXXX)' using errcode = 'check_violation';
    end if;
    if p_result ->> 'roofops_id' is distinct from o.aggregate_id::text or p_result ->> 'project_number' is distinct from v_ref then
      raise exception 'airtable record read back does not carry project % / %', v_ref, o.aggregate_id using errcode = 'check_violation';
    end if;
    if o.payload ->> 'quote_airtable_record_id' is not null
       and not coalesce(p_result -> 'linked_quote_record_ids' ? (o.payload ->> 'quote_airtable_record_id'), false) then
      raise exception 'airtable project is not linked to quote record %', o.payload ->> 'quote_airtable_record_id' using errcode = 'check_violation';
    end if;
    select external_url into v_drive_url from external_links
     where provider = 'GOOGLE_DRIVE' and entity_type = 'project' and entity_id = o.aggregate_id and external_type = 'Folder';
    if v_drive_url is not null and p_result ->> 'drive_folder_url' is distinct from v_drive_url then
      raise exception 'airtable Drive Folder % does not match the verified folder %', p_result ->> 'drive_folder_url', v_drive_url using errcode = 'check_violation';
    end if;
    select external_id into v_existing from external_links
     where provider = 'AIRTABLE' and entity_type = 'project' and entity_id = o.aggregate_id and external_type = 'Record';
    if v_existing is not null and v_existing <> p_result ->> 'project_record_id' then
      raise exception 'project % already linked to Airtable record %, refusing a second record %', v_ref, v_existing, p_result ->> 'project_record_id'
        using errcode = 'unique_violation';
    end if;
    insert into external_links (provider, entity_type, entity_id, external_type, external_id, last_synced_at, verified_at)
    values ('AIRTABLE', 'project', o.aggregate_id, 'Record', p_result ->> 'project_record_id', now(), now())
    on conflict (provider, entity_type, entity_id, external_type) do update set verified_at = now(), last_synced_at = now();
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, external_reference, reason, correlation_id)
    values ('INTEGRATION', 'airtable', 'airtable.project.writeback', 'project', o.aggregate_id, v_ref,
            p_result - 'verified', p_result ->> 'project_record_id', 'Project record written to Airtable, linked to its quote and read back', o.correlation_id);
  elsif o.topic = 'xero.create_draft_invoice' then
    -- Only proof read back from the pinned Xero DEMO tenant is accepted, and it must describe exactly the approved draft.
    if coalesce(o.payload ->> 'xero_tenant_id', '') = '' or p_result ->> 'tenant_id' is distinct from o.payload ->> 'xero_tenant_id' then
      raise exception 'xero proof is from tenant %, not the pinned Demo Company tenant', p_result ->> 'tenant_id' using errcode = 'check_violation';
    end if;
    if p_result ->> 'organisation_class' is distinct from 'DEMO' then
      raise exception 'refusing: the Xero organisation is not a Demo Company (Class=%)', p_result ->> 'organisation_class' using errcode = 'check_violation';
    end if;
    if coalesce(p_result ->> 'invoice_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or coalesce(p_result ->> 'contact_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'xero proof needs InvoiceID and ContactID' using errcode = 'check_violation';
    end if;
    if p_result ->> 'invoice_number' is distinct from o.payload ->> 'xero_invoice_number' or p_result ->> 'reference' is distinct from o.payload ->> 'reference' then
      raise exception 'xero invoice %/% does not carry number % and reference %', p_result ->> 'invoice_number', p_result ->> 'reference',
        o.payload ->> 'xero_invoice_number', o.payload ->> 'reference' using errcode = 'check_violation';
    end if;
    if p_result ->> 'status' is distinct from 'DRAFT' or p_result ->> 'type' is distinct from 'ACCREC' then
      raise exception 'xero invoice must be an ACCREC DRAFT, read back %/%', p_result ->> 'type', p_result ->> 'status' using errcode = 'check_violation';
    end if;
    if coalesce((p_result ->> 'amount_paid')::numeric, -1) <> 0 or coalesce((p_result ->> 'sent_to_contact')::boolean, true) then
      raise exception 'xero invoice must be unpaid and unsent' using errcode = 'check_violation';
    end if;
    if p_result ->> 'contact_number' is distinct from o.payload ->> 'xero_contact_number' then
      raise exception 'xero invoice contact % is not %', p_result ->> 'contact_number', o.payload ->> 'xero_contact_number' using errcode = 'check_violation';
    end if;
    if (p_result ->> 'total')::numeric is distinct from (o.payload ->> 'amount_inc_gst')::numeric
       or (p_result ->> 'total_tax')::numeric is distinct from (o.payload ->> 'gst_amount')::numeric then
      raise exception 'xero total %/GST % does not match the approved % / %', p_result ->> 'total', p_result ->> 'total_tax',
        o.payload ->> 'amount_inc_gst', o.payload ->> 'gst_amount' using errcode = 'check_violation';
    end if;
    if p_result ->> 'currency' is distinct from 'AUD' or p_result ->> 'line_amount_types' is distinct from 'Inclusive' then
      raise exception 'xero invoice must be AUD, GST inclusive' using errcode = 'check_violation';
    end if;
    if coalesce((p_result ->> 'matching_invoices')::int, 0) <> 1 then
      raise exception 'expected exactly one Xero invoice numbered %, found %', o.payload ->> 'xero_invoice_number', p_result ->> 'matching_invoices'
        using errcode = 'unique_violation';
    end if;
    select external_id into v_existing from external_links
     where provider = 'XERO' and entity_type = 'invoice' and entity_id = o.aggregate_id and external_type = 'Invoice';
    if v_existing is not null and v_existing <> p_result ->> 'invoice_id' then
      -- AC-14C B2: a supervised replacement (generation >= 2) whose predecessor generation is superseded may move the
      -- one current link to the new InvoiceID; anything else still refuses a second link.
      if o.generation >= 2 and exists (select 1 from invoice_xero_draft_generations g
             where g.invoice_id = o.aggregate_id and g.generation = o.generation - 1 and g.superseded_at is not null) then
        update external_links set external_id = p_result ->> 'invoice_id',
               external_url = 'https://go.xero.com/AccountsReceivable/View.aspx?InvoiceID=' || (p_result ->> 'invoice_id'),
               last_synced_at = now(), verified_at = now()
         where provider = 'XERO' and entity_type = 'invoice' and entity_id = o.aggregate_id and external_type = 'Invoice';
      else
        raise exception 'invoice % already linked to Xero invoice %, refusing a second %', v_ref, v_existing, p_result ->> 'invoice_id'
          using errcode = 'unique_violation';
      end if;
    end if;
    select external_id into v_existing from external_links
     where provider = 'XERO' and entity_type = 'customer' and entity_id = (o.payload ->> 'customer_id')::uuid and external_type = 'Contact';
    if v_existing is not null and v_existing <> p_result ->> 'contact_id' then
      raise exception 'customer % is linked to Xero contact %, not %', o.payload ->> 'customer_number', v_existing, p_result ->> 'contact_id'
        using errcode = 'unique_violation';
    end if;
    insert into external_links (provider, entity_type, entity_id, external_type, external_id, external_url, last_synced_at, verified_at)
    values ('XERO', 'invoice', o.aggregate_id, 'Invoice', p_result ->> 'invoice_id',
            'https://go.xero.com/AccountsReceivable/View.aspx?InvoiceID=' || (p_result ->> 'invoice_id'), now(), now()),
           ('XERO', 'customer', (o.payload ->> 'customer_id')::uuid, 'Contact', p_result ->> 'contact_id',
            'https://go.xero.com/Contacts/View/' || (p_result ->> 'contact_id'), now(), now())
    on conflict (provider, entity_type, entity_id, external_type) do update set verified_at = now(), last_synced_at = now();
    update invoices set sync_status = 'SYNCED' where id = o.aggregate_id;
    update approvals set status = 'EXECUTED', executed_at = now(), execution_result = p_result - 'verified'
     where id = (select approval_id from invoices where id = o.aggregate_id);
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, external_reference, reason, correlation_id)
    values ('INTEGRATION', 'xero', 'xero.invoice.draft_created', 'invoice', o.aggregate_id, v_ref,
            p_result - 'verified', p_result ->> 'invoice_id',
            'DRAFT invoice ' || (p_result ->> 'invoice_number') || ' created in the Xero Demo Company and read back', o.correlation_id);
  elsif o.topic = 'airtable.quote_publish' then
    -- SALES-01: the customer, property and quote rows exist in Airtable (found or created by their RoofOps numbers), the
    -- quote row links to that customer and property, and each was read back carrying its number.
    if coalesce(p_result ->> 'quote_record_id', '') !~ '^rec[A-Za-z0-9]{14}$' or coalesce(p_result ->> 'customer_record_id', '') !~ '^rec[A-Za-z0-9]{14}$'
       or coalesce(p_result ->> 'property_record_id', '') !~ '^rec[A-Za-z0-9]{14}$' then
      raise exception 'airtable quote publish result needs quote_record_id, customer_record_id and property_record_id (recXXXXXXXXXXXXXX)' using errcode = 'check_violation';
    end if;
    if p_result ->> 'quote_number' is distinct from o.payload ->> 'quote_number' or p_result ->> 'customer_number' is distinct from o.payload ->> 'customer_number'
       or p_result ->> 'property_number' is distinct from o.payload ->> 'property_number' then
      raise exception 'airtable records read back do not carry quote % / customer % / property %', o.payload ->> 'quote_number',
        o.payload ->> 'customer_number', o.payload ->> 'property_number' using errcode = 'check_violation';
    end if;
    if not coalesce(p_result -> 'quote_customer_link_ids' ? (p_result ->> 'customer_record_id'), false)
       or not coalesce(p_result -> 'quote_property_link_ids' ? (p_result ->> 'property_record_id'), false) then
      raise exception 'airtable quote % is not linked to its customer and property records', o.payload ->> 'quote_number' using errcode = 'check_violation';
    end if;
    -- Sales reliability: the three records as Airtable holds them, read back by n8n 10 after writing (never the values
    -- it was asked to write): each record id, RoofOps ID and number; the site's owner link; the quote's links, version
    -- and amount, all equal to this hand-off's payload.
    if jsonb_typeof(p_result -> 'customer_read_back') is distinct from 'object' or jsonb_typeof(p_result -> 'property_read_back') is distinct from 'object'
       or jsonb_typeof(p_result -> 'quote_read_back') is distinct from 'object' then
      raise exception 'airtable quote publish result needs the customer, property and quote records read back from Airtable' using errcode = 'check_violation';
    end if;
    if p_result -> 'customer_read_back' ->> 'id' is distinct from p_result ->> 'customer_record_id'
       or p_result -> 'customer_read_back' ->> 'roofops_id' is distinct from o.payload ->> 'customer_id'
       or p_result -> 'customer_read_back' ->> 'number' is distinct from o.payload ->> 'customer_number' then
      raise exception 'the customer record read back from Airtable is not % (RoofOps ID %)', o.payload ->> 'customer_number', o.payload ->> 'customer_id' using errcode = 'check_violation';
    end if;
    if p_result -> 'property_read_back' ->> 'id' is distinct from p_result ->> 'property_record_id'
       or p_result -> 'property_read_back' ->> 'roofops_id' is distinct from o.payload ->> 'property_id'
       or p_result -> 'property_read_back' ->> 'number' is distinct from o.payload ->> 'property_number'
       or not coalesce(p_result -> 'property_read_back' -> 'owner_link_ids' ? (p_result ->> 'customer_record_id'), false) then
      raise exception 'the property record read back from Airtable is not % owned by %', o.payload ->> 'property_number', o.payload ->> 'customer_number' using errcode = 'check_violation';
    end if;
    if p_result -> 'quote_read_back' ->> 'id' is distinct from p_result ->> 'quote_record_id'
       or p_result -> 'quote_read_back' ->> 'roofops_id' is distinct from o.payload ->> 'quote_id'
       or p_result -> 'quote_read_back' ->> 'number' is distinct from o.payload ->> 'quote_number'
       or (p_result -> 'quote_read_back' ->> 'version')::numeric is distinct from (o.payload -> 'quote_fields' ->> 'fldEjEqlzE8Y0M1nf')::numeric
       or (p_result -> 'quote_read_back' ->> 'amount')::numeric is distinct from (o.payload -> 'quote_fields' ->> 'fldbfUE8DVh1Dwjfs')::numeric
       or not coalesce(p_result -> 'quote_read_back' -> 'customer_link_ids' ? (p_result ->> 'customer_record_id'), false)
       or not coalesce(p_result -> 'quote_read_back' -> 'property_link_ids' ? (p_result ->> 'property_record_id'), false) then
      raise exception 'the quote record read back from Airtable is not % version % for % with its links', o.payload ->> 'quote_number',
        o.payload -> 'quote_fields' ->> 'fldEjEqlzE8Y0M1nf', o.payload -> 'quote_fields' ->> 'fldbfUE8DVh1Dwjfs' using errcode = 'check_violation';
    end if;
    for v_sub in select * from jsonb_array_elements(jsonb_build_array(
        jsonb_build_object('entity', 'quote', 'id', o.payload ->> 'quote_id', 'rec', p_result ->> 'quote_record_id'),
        jsonb_build_object('entity', 'customer', 'id', o.payload ->> 'customer_id', 'rec', p_result ->> 'customer_record_id'),
        jsonb_build_object('entity', 'property', 'id', o.payload ->> 'property_id', 'rec', p_result ->> 'property_record_id'))) loop
      select external_id into v_existing from external_links
       where provider = 'AIRTABLE' and entity_type = v_sub ->> 'entity' and entity_id = (v_sub ->> 'id')::uuid and external_type = 'Record';
      if v_existing is not null and v_existing <> v_sub ->> 'rec' then
        raise exception '% % already linked to Airtable record %, refusing a second record %', v_sub ->> 'entity', v_sub ->> 'id', v_existing, v_sub ->> 'rec'
          using errcode = 'unique_violation';
      end if;
      insert into external_links (provider, entity_type, entity_id, external_type, external_id, last_synced_at, verified_at)
      values ('AIRTABLE', v_sub ->> 'entity', (v_sub ->> 'id')::uuid, 'Record', v_sub ->> 'rec', now(), now())
      on conflict (provider, entity_type, entity_id, external_type) do update set verified_at = now(), last_synced_at = now();
    end loop;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, external_reference, reason, correlation_id)
    values ('INTEGRATION', 'airtable', 'airtable.quote.published', 'quote', o.aggregate_id, v_ref,
            p_result - 'verified', p_result ->> 'quote_record_id', 'Quote, customer and property records in Airtable, linked and read back', o.correlation_id);
    -- A hand-off that failed earlier and was re-queued: its exception is answered (it has no workflow run to do it below).
    update workflow_exceptions set resolution_status = 'RESOLVED', resolved_at = now(), resolved_by_system = 'workflow:airtable.quote_publish',
           resolution_note = 'The quote, customer and property were added to Airtable and read back'
     where entity_type = 'quote' and entity_id = o.aggregate_id and resolution_status in ('OPEN', 'RETRY_QUEUED')
       and error_message like 'airtable.quote_publish:%';
  else
    raise exception 'unknown side-effect topic %', o.topic;
  end if;

  update outbox set status = 'DONE', dispatched_at = now(), locked_until = null, result = p_result where idempotency_key = p_key;
  perform wf_log_event(p_key || ':done:' || o.attempts, o.correlation_id, null, replace(o.topic, 'ensure_', '') || '.verified',
    case when o.topic = 'airtable.quote_publish' then 'quote' else 'project' end, o.aggregate_id, v_ref, 'INTEGRATION', o.topic, 'n8n', 'SUCCEEDED', null,
    jsonb_build_object('attempt', o.attempts, 'external_id', coalesce(p_result ->> 'folder_id', p_result ->> 'project_record_id', p_result ->> 'invoice_id', p_result ->> 'quote_record_id')), null);

  select id into v_run from workflow_runs where entity_id = o.aggregate_id order by started_at desc limit 1;
  if v_run is not null or o.topic <> 'airtable.quote_publish' then   -- only a quote hand-off has no workflow run; other topics keep the not-null guard
  insert into workflow_run_steps (run_id, attempt, seq, step_key, status, finished_at, detail)
  values (v_run, o.attempts, (select coalesce(max(seq), 0) + 1 from workflow_run_steps where run_id = v_run), o.topic, 'SUCCEEDED', now(),
          jsonb_build_object('attempt', o.attempts, 'external_id', coalesce(p_result ->> 'folder_id', p_result ->> 'project_record_id', p_result ->> 'invoice_id')));
  end if;
  select count(*) into v_left from outbox where aggregate_id = o.aggregate_id and status <> 'DONE';
  if v_left = 0 then
    update workflow_runs set status = 'SUCCEEDED', finished_at = now() where id = v_run;
    update workflow_exceptions set resolution_status = 'RESOLVED', resolved_at = now(), resolved_by_system = 'workflow:' || (select workflow_key from workflow_runs where id = v_run),
           resolution_note = 'Auto-resolved: side effect succeeded on retry'
     where workflow_run_id = v_run and resolution_status in ('OPEN','RETRY_QUEUED');
  end if;
  return jsonb_build_object('status', 'RECORDED', 'key', p_key, 'remaining_side_effects', v_left);
end $_$;

--
-- Name: wf_drive_call_decision(integer, jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_drive_call_decision(p_status integer, p_headers jsonb, p_body jsonb, p_attempt integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_max int := coalesce((select value::int from app_settings where key = 'drive.retry_max_attempts'), 4);
  v_base int := coalesce((select value::int from app_settings where key = 'drive.retry_base_seconds'), 15);
  v_cap int := coalesce((select value::int from app_settings where key = 'drive.retry_max_wait_seconds'), 120);
  v_status int := coalesce(p_status, 0); v_reason text := drive_error_reason(p_body); v_class text; v_ra text; v_wait int; v_files int;
begin
  if v_status = 200 then
    v_files := jsonb_array_length(case when jsonb_typeof(p_body -> 'files') = 'array' then p_body -> 'files' else '[]'::jsonb end);
    if v_files = 1 then
      return jsonb_build_object('action', 'ok', 'attempt', p_attempt, 'root_id', p_body #>> '{files,0,id}');
    end if;
    return jsonb_build_object('action', 'fail', 'retry', false, 'retryable', false, 'error_class', 'NOT_FOUND', 'attempts', p_attempt, 'http', v_status,
      'reason', format('The RoofOps root folder was found %s times in Google Drive (expected once): check the folder''s roofops_role=root property', v_files));
  end if;

  v_class := case
    when v_status = 429 or (v_status = 403 and v_reason in ('rateLimitExceeded', 'userRateLimitExceeded', 'RATE_LIMIT_EXCEEDED')) then 'RATE_LIMITED'
    when v_status = 503 then 'SERVICE_UNAVAILABLE'
    when v_status between 500 and 599 then 'UPSTREAM_5XX'
    when v_status = 0 then 'NETWORK' end;

  if v_class is null then   -- a refusal: retrying it within the run cannot help
    return jsonb_build_object('action', 'fail', 'retry', false, 'retryable', v_status = 403 and v_reason in ('dailyLimitExceeded', 'quotaExceeded'),
      'attempts', p_attempt, 'http', v_status, 'google_reason', v_reason,
      'error_class', case when v_status = 401 then 'AUTH_FAILURE' when v_status = 403 and v_reason in ('dailyLimitExceeded', 'quotaExceeded') then 'RATE_LIMITED'
                          when v_status = 403 then 'PERMISSION_DENIED' when v_status = 404 then 'NOT_FOUND' else 'UNKNOWN' end,
      'reason', case
        when v_status = 401 then 'Google Drive refused the RoofOps credential (HTTP 401): reconnect the "RoofOps Google Drive" credential in n8n'
        when v_status = 403 and v_reason in ('dailyLimitExceeded', 'quotaExceeded') then format('Google Drive daily quota is exhausted (HTTP 403 %s): Drive is checked again after the quota resets', v_reason)
        when v_status = 403 then format('Google Drive denied access (HTTP 403 %s): check that the "RoofOps Google Drive" credential can read the RoofOps root folder', coalesce(v_reason, 'forbidden'))
        when v_status = 404 then 'Google Drive answered 404 for the root folder search: check the RoofOps root folder'
        else format('Google Drive answered HTTP %s%s: not retried', v_status, coalesce(' ' || v_reason, '')) end);
  end if;

  if p_attempt >= v_max then
    return jsonb_build_object('action', 'fail', 'retry', false, 'retryable', true, 'error_class', v_class, 'attempts', p_attempt, 'http', v_status, 'google_reason', v_reason,
      'reason', format('Google Drive %s (HTTP %s%s) on all %s attempts; Drive folders were not verified this run and are checked again at the next run. '
                       'If this keeps happening at the scheduled time, give the "RoofOps Google Drive" credential its own Google Cloud OAuth client or move the schedule off the hour',
                       case v_class when 'RATE_LIMITED' then 'kept its rate limit' when 'NETWORK' then 'could not be reached' else 'kept failing' end,
                       v_status, coalesce(' ' || v_reason, ''), p_attempt));
  end if;

  -- Retry-After (seconds or an HTTP date) wins; otherwise base * 2^(attempt-1) plus up to one base of jitter. Both capped.
  select value into v_ra from jsonb_each_text(coalesce(p_headers, '{}'::jsonb)) where lower(key) = 'retry-after' limit 1;
  if v_ra ~ '^\s*\d+\s*$' then
    v_wait := v_ra::int;
  elsif v_ra is not null then
    begin v_wait := ceil(extract(epoch from (v_ra::timestamptz - now())))::int; exception when others then v_wait := null; end;
  end if;
  if v_wait is null then
    v_wait := v_base * (2 ^ (p_attempt - 1))::int + floor(random() * (v_base + 1))::int;
  end if;
  v_wait := least(v_cap, greatest(1, v_wait));
  return jsonb_build_object('action', 'retry', 'error_class', v_class, 'attempt', p_attempt, 'next_attempt', p_attempt + 1, 'wait_seconds', v_wait,
    'http', v_status, 'google_reason', v_reason, 'retry_after', v_ra);
end $_$;

--
-- Name: wf_fail_side_effect(text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_fail_side_effect(p_key text, p_error_class text, p_message text, p_http_status integer DEFAULT NULL::integer, p_retry_after_seconds integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o outbox;
  v_retryable boolean;
  v_max int := (select value::int from app_settings where key = 'wf.side_effect.max_attempts');
  v_delay int;
  v_run uuid;
  v_exc text;
  v_xero boolean;
  v_uncertain boolean := false;
  v_sync text;
begin
  select * into o from outbox where idempotency_key = p_key for update;
  if not found then raise exception 'unknown side effect %', p_key using errcode = 'no_data_found'; end if;
  if o.status <> 'DISPATCHING' then raise exception 'side effect % is %, not claimed', p_key, o.status using errcode = 'check_violation'; end if;
  select retryable into v_retryable from error_classes where code = p_error_class;
  if v_retryable is null then raise exception 'unknown error class %', p_error_class using errcode = 'foreign_key_violation'; end if;
  v_xero := o.topic = 'xero.create_draft_invoice';
  if v_xero then
    select sync_status into v_sync from invoices where id = o.aggregate_id;
    v_uncertain := case xero_failure_evidence(p_error_class, p_message, p_http_status)
                     when 'MAY_EXIST' then true when 'ABSENT' then false else v_sync = 'UNKNOWN' end;
  end if;

  select id into v_run from workflow_runs where entity_id = o.aggregate_id order by started_at desc limit 1;
  if v_retryable and o.attempts < v_max then
    v_delay := coalesce(p_retry_after_seconds, least(60, (2 ^ (o.attempts - 1))::int));   -- 1, 2, 4, 8 s … capped
    update outbox set status = 'FAILED', locked_until = null, next_attempt_at = now() + make_interval(secs => v_delay),
           last_error = left(p_message, 1000) where idempotency_key = p_key;
    insert into workflow_run_steps (run_id, attempt, seq, step_key, status, finished_at, http_status, error_class, retry_delay_ms, detail)
    values (v_run, o.attempts, (select coalesce(max(seq), 0) + 1 from workflow_run_steps where run_id = v_run), o.topic, 'FAILED', now(),
            p_http_status, p_error_class, v_delay * 1000, jsonb_build_object('message', left(p_message, 500)));
    update workflow_runs set status = 'RETRY_SCHEDULED', next_attempt_at = now() + make_interval(secs => v_delay),
           last_error_class = p_error_class, last_error_message = left(p_message, 500) where id = v_run;
    perform wf_log_event(p_key || ':retry:' || o.attempts, o.correlation_id, null, 'automation.retry_scheduled', 'project', o.aggregate_id,
      coalesce(o.payload ->> 'invoice_number', o.payload ->> 'project_number'), 'WORKFLOW', o.topic, 'n8n', 'FAILED', p_error_class,
      jsonb_build_object('attempt', o.attempts, 'retry_in_seconds', v_delay, 'http_status', p_http_status, 'message', left(p_message, 500)), null);
    if v_xero then
      update invoices set sync_status = case when v_uncertain then 'UNKNOWN' else 'PENDING' end
       where id = o.aggregate_id and sync_status is distinct from case when v_uncertain then 'UNKNOWN' else 'PENDING' end;
    end if;
    return jsonb_build_object('retry', true, 'retry_in_seconds', v_delay, 'attempt', o.attempts, 'max_attempts', v_max);
  end if;

  update outbox set status = 'FAILED', locked_until = null, next_attempt_at = 'infinity', last_error = left(p_message, 1000) where idempotency_key = p_key;
  update workflow_runs set status = 'DEAD_LETTERED', finished_at = now(), last_error_class = p_error_class, last_error_message = left(p_message, 500) where id = v_run;
  perform wf_log_event(p_key || ':failed:' || o.attempts, o.correlation_id, null, 'automation.failed', 'project', o.aggregate_id,
    coalesce(o.payload ->> 'invoice_number', o.payload ->> 'project_number'), 'WORKFLOW', o.topic, 'n8n', 'FAILED', p_error_class,
    jsonb_build_object('attempt', o.attempts, 'http_status', p_http_status, 'message', left(p_message, 500), 'may_exist_in_xero', v_uncertain), null);
  if v_xero and v_uncertain then
    -- Not "failed safely": the draft may exist. The approval stays executing until reconciliation settles it.
    update invoices set sync_status = 'UNKNOWN' where id = o.aggregate_id and sync_status is distinct from 'UNKNOWN';
    v_exc := wf_open_exception(v_run, null, o.aggregate_type, o.aggregate_id, coalesce(o.payload ->> 'invoice_number', o.payload ->> 'project_number'), 'AMBIGUOUS_WRITE',
      format('%s: %s: %s may already exist in Xero (the attempts could not prove it either way). It is not retried automatically: reconciliation looks it up by number and settles it, or a person decides. Last error: %s',
             o.topic, o.payload ->> 'invoice_number', o.payload ->> 'xero_invoice_number', left(p_message, 400)), o.attempts);
    return jsonb_build_object('retry', false, 'exception_number', v_exc, 'attempt', o.attempts, 'may_exist_in_xero', true,
      'reason', 'the Xero draft may exist: left UNKNOWN for reconciliation');
  end if;
  if v_xero then
    update invoices set sync_status = 'FAILED' where id = o.aggregate_id;
    update approvals set status = 'EXECUTION_FAILED', executed_at = now(),
           execution_result = jsonb_build_object('error_class', p_error_class, 'message', left(p_message, 500), 'attempts', o.attempts)
     where id = (select approval_id from invoices where id = o.aggregate_id);
  end if;
  v_exc := wf_open_exception(v_run, null, o.aggregate_type, o.aggregate_id, coalesce(o.payload ->> 'invoice_number', o.payload ->> 'project_number'), p_error_class,
    o.topic || ': ' || left(p_message, 500), o.attempts);
  return jsonb_build_object('retry', false, 'exception_number', v_exc, 'attempt', o.attempts,
    'reason', case when v_retryable then 'max attempts reached' else 'non-retryable error class' end);
end $$;

--
-- Name: wf_invoice_decide(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_invoice_decide(p_event jsonb, p_worker text DEFAULT 'n8n'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_res jsonb; v_event jsonb := p_event; v_payload jsonb := p_event -> 'payload';
  v_type text := p_event ->> 'event_type'; v_src text := p_event ->> 'source';
  v_cell text := p_event -> 'payload' ->> 'project_number'; v_rec text := p_event -> 'payload' ->> 'airtable_record_id';
  v_named text := nullif(p_event -> 'payload' ->> 'approval_number', ''); v_hash text := nullif(p_event -> 'payload' ->> 'payload_hash', '');
  v_at timestamptz; p projects; v_ap approvals; v_shown approval_presentations; v_amount text; v_prep_src text;
begin
  -- Only a well-formed decision is bound here; anything else gets the handler's own validation answer.
  if v_type in ('invoice.approved', 'invoice.rejected') and jsonb_typeof(v_payload) = 'object' and coalesce(v_cell, '') ~ '^PRJ-[0-9]{4}-[0-9]{4}$'
     and coalesce(v_src, '') <> '' and coalesce(p_event ->> 'actor_id', '') <> '' and coalesce(p_event ->> 'event_id', '') <> '' then
    if v_src = 'airtable' then
      -- 1. The project is the one whose Airtable record sent the decision, never the (editable) Project Number text.
      if coalesce(v_rec, '') = '' or airtable_project_for_record(v_rec) is null then
        return invoice_decision_refused(p_event, p_worker, null, 'NOT_FOUND',
          format('This Airtable row (%s) is not linked to a RoofOps project. Nothing was approved', coalesce(nullif(v_rec, ''), 'no record id')), null);
      end if;
      select * into p from projects where id = airtable_project_for_record(v_rec) for update;
      if p.project_number <> v_cell then
        return invoice_decision_refused(p_event, p_worker, p.id, 'RECONCILIATION_MISMATCH',
          format('This Airtable row is %s but its Project Number cell says %s. Nothing was approved; restore the Project Number and decide again', p.project_number, v_cell), null);
      end if;
      if v_payload ? 'project_uuid' and v_payload ->> 'project_uuid' is distinct from p.id::text then
        return invoice_decision_refused(p_event, p_worker, p.id, 'RECONCILIATION_MISMATCH',
          format('This Airtable row is %s but its RoofOps ID cell does not match. Nothing was approved; restore the RoofOps ID and decide again', p.project_number), null);
      end if;
    else
      select * into p from projects where project_number = v_cell for update;
      if p.id is not null and v_named is null then
        return invoice_decision_refused(p_event, p_worker, p.id, 'INVALID_STATE',
          format('A decision from %s must name the approval it decides. Nothing was approved', v_src), null);
      end if;
    end if;

    if p.id is not null then
      -- 2. The approval it decides: the one it names, else the one the handler would pick (pending first, newest).
      select * into v_ap from approvals a where a.action_type = 'CREATE_INVOICE' and a.entity_id = p.id and (v_named is null or a.approval_number = v_named)
       order by (a.status = 'PENDING') desc, a.created_at desc limit 1;
      if v_ap.id is not null and v_ap.status = 'PENDING' then
        if v_hash is not null and v_hash is distinct from v_ap.payload_hash then
          return invoice_decision_refused(p_event, p_worker, p.id, 'INVALID_STATE',
            format('The preview you decided is not %s as it stands now. Nothing was approved; prepare the preview again', v_ap.approval_number), v_ap.approval_number);
        end if;
        -- 3. From Airtable: only the exact preview 04 wrote to this row and read back, before the decision was made, and
        --    still shown on the row when the decision is processed.
        if v_src = 'airtable' then
          begin v_at := (p_event ->> 'occurred_at')::timestamptz; exception when others then v_at := null; end;
          v_amount := to_char((v_ap.action_payload ->> 'amount_inc_gst')::numeric, 'FM$999,999,990.00');
          select * into v_shown from approval_presentations where approval_id = v_ap.id and airtable_record_id = v_rec and verified;
          if v_shown.approval_id is null then
            select e.source into v_prep_src from automation_events e where 'approval:' || e.event_key = v_ap.idempotency_key;
            return invoice_decision_refused(p_event, p_worker, p.id, 'INVALID_STATE',
              case when v_prep_src is distinct from 'airtable' then
                format('%s (%s inc GST) was prepared in the RoofOps dashboard and has not been shown on this row. Nothing was approved; set Invoice Action = Prepare Xero draft invoice to show it, check it, then approve', v_ap.approval_number, v_amount)
              else
                format('%s (%s inc GST) was never confirmed on this row (its preview was not written to Airtable and read back). Nothing was approved; set Invoice Action = Prepare Xero draft invoice to show it, check it, then approve', v_ap.approval_number, v_amount)
              end, v_ap.approval_number);
          end if;
          if v_at is null or v_at <= v_shown.presented_at then
            return invoice_decision_refused(p_event, p_worker, p.id, 'INVALID_STATE',
              format('%s was shown on this row only after this decision was made. Nothing was approved; check the preview now shown and decide again', v_ap.approval_number), v_ap.approval_number);
          end if;
          if not (v_payload ? 'displayed_preview') or not invoice_preview_shows(v_payload ->> 'displayed_preview', v_ap) then
            return invoice_decision_refused(p_event, p_worker, p.id, 'INVALID_STATE',
              format('This row does not show %s (%s inc GST) exactly as prepared (it shows another preview or message, or the text was edited). Nothing was approved; set Invoice Action = Prepare Xero draft invoice to show it again, check it, then approve',
                     v_ap.approval_number, v_amount), v_ap.approval_number);
          end if;
        end if;
      end if;
      -- Bind the handler to exactly that approval (and that project).
      if v_ap.id is not null then
        v_event := jsonb_set(v_event, '{payload}', v_payload || jsonb_build_object('approval_number', v_ap.approval_number, 'project_number', p.project_number));
      end if;
    end if;
  else
    perform 1 from projects where project_number = v_cell for update;
  end if;

  v_res := wf_invoice_decide_core(v_event, p_worker);
  if v_res ->> 'outcome' = 'ALREADY_PROCESSED' and v_res ? 'invoice_id' then
    v_res := v_res || jsonb_build_object('xero_state', invoice_xero_state((v_res ->> 'invoice_id')::uuid));
  end if;
  return v_res;
end $_$;

--
-- Name: wf_invoice_decide_core(jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_invoice_decide_core(p_event jsonb, p_worker text DEFAULT 'n8n'::text, p_employee uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_draft jsonb; v_diff text;
  e record; v_type text := p_event ->> 'event_type'; v_prj text := p_event -> 'payload' ->> 'project_number';
  p projects; v_ap approvals; v_key text; v_claimed boolean; v_pe processed_events; v_emp employees;
  v_prev jsonb; v_hash text; v_inv invoices; v_run uuid; v_res jsonb; v_exc text; v_class text; v_msg text;
  v_tenant text := (select value from app_settings where key = 'xero.demo_tenant_id');
  v_line jsonb; v_gen int;
begin
  select * into e from wf_invoice_log_event(p_event, coalesce(nullif(v_type, ''), 'invoice.approved'), p_worker);
  if v_type not in ('invoice.approved', 'invoice.rejected') then
    e.issues := array_append(e.issues, 'event_type: must be invoice.approved or invoice.rejected'::text);
  end if;
  if array_length(e.issues, 1) > 0 then
    v_exc := wf_open_invoice_rejection(e.event_id, null, coalesce(v_prj, 'unknown'), 'VALIDATION_ERROR',
               'Invalid invoice decision event: ' || array_to_string(e.issues, '; '));
    update automation_events set status = 'REJECTED', error_class = 'VALIDATION_ERROR' where event_id = e.event_id;
    return jsonb_build_object('outcome', 'INVALID_EVENT', 'error_class', 'VALIDATION_ERROR', 'issues', to_jsonb(e.issues), 'exception_number', v_exc);
  end if;

  select * into p from projects where project_number = v_prj;
  if p.id is not null then
    select * into v_ap from approvals a where a.action_type = 'CREATE_INVOICE' and a.entity_id = p.id
       and (coalesce(p_event -> 'payload' ->> 'approval_number', '') = '' or a.approval_number = p_event -> 'payload' ->> 'approval_number')
     order by (a.status = 'PENDING') desc, a.created_at desc limit 1;
  end if;
  if p.id is null or v_ap.id is null then
    v_class := case when p.id is null then 'NOT_FOUND' else 'INVALID_STATE' end;
    v_msg := case when p.id is null then v_prj || ' does not exist' else 'No invoice preview to decide for ' || v_prj || '; prepare one first' end;
    v_exc := wf_open_invoice_rejection(e.event_id, p.id, v_prj, v_class, v_msg);
    update automation_events set status = 'REJECTED', error_class = v_class, metadata = metadata || jsonb_build_object('reason', v_msg) where event_id = e.event_id;
    return jsonb_build_object('outcome', 'INVALID_STATE', 'error_class', v_class, 'message', v_msg, 'exception_number', v_exc, 'project_number', v_prj);
  end if;

  -- One decision per approval, however many times (or ways) it is delivered.
  v_key := 'invoice.decision:' || v_ap.approval_number;
  insert into processed_events (consumer, idempotency_key, first_event_id, request_hash, status, locked_by, lease_expires_at)
  values ('invoice_decision@1', v_key, e.event_id, md5(v_ap.approval_number), 'PROCESSING', p_worker, now() + interval '5 minutes')
  on conflict do nothing returning true into v_claimed;
  if v_claimed is null then
    select * into v_pe from processed_events where consumer = 'invoice_decision@1' and idempotency_key = v_key for update;
    update processed_events set delivery_count = delivery_count + 1, last_seen_at = now() where consumer = v_pe.consumer and idempotency_key = v_key;
    update automation_events set status = 'DUPLICATE_IGNORED', error_class = 'DUPLICATE_EVENT', causation_id = v_pe.first_event_id,
           metadata = metadata || jsonb_build_object(
             'reason', case when e.redelivery then 'transport redelivery of the same event_id' else 'semantic duplicate: ' || v_ap.approval_number || ' was already decided' end,
             'delivery_count', v_pe.delivery_count + 1)
     where event_id = e.event_id;
    return coalesce(v_pe.result, '{}'::jsonb) || jsonb_build_object('outcome', 'ALREADY_PROCESSED', 'first_outcome', v_pe.result ->> 'outcome',
      'duplicate', true, 'delivery_count', v_pe.delivery_count + 1,
      'pending_side_effects', (select coalesce(jsonb_agg(jsonb_build_object('topic', topic, 'key', idempotency_key, 'status', status)), '[]')
                                 from outbox where aggregate_id = (v_pe.result ->> 'invoice_id')::uuid and status <> 'DONE'));
  end if;

  -- Authorisation: the approver is an active employee in an approving role: the one a dashboard session proved
  -- (p_employee, passed only by web_invoice_decide; no app role can call this core), else the Airtable user's mapping.
  if p_employee is not null then
    select emp.* into v_emp from employees emp where emp.id = p_employee and emp.is_active;
  else
    select emp.* into v_emp from employee_external_identities ei join employees emp on emp.id = ei.employee_id
     where ei.provider = 'AIRTABLE' and ei.external_id = p_event ->> 'actor_id' and emp.is_active;
  end if;
  if v_emp.id is null or not (v_emp.role = any (string_to_array((select value from app_settings where key = 'invoice.approver_roles'), ','))) then
    v_class := 'PERMISSION_DENIED';
    v_msg := case when p_employee is not null then format('%s is not an authorised invoice approver (%s)', p_event ->> 'actor_id', coalesce(v_emp.role, 'not active'))
             else format('Airtable user %s is not an authorised invoice approver (%s)', p_event ->> 'actor_id', coalesce(v_emp.role, 'not mapped to an employee')) end;
  elsif p_employee is null and v_type = 'invoice.approved' and v_ap.idempotency_key like 'approval:dashboard:prepare:%' then
    -- A preview a named employee prepared in the dashboard is approved there, by a different named person; never through
    -- the shared Airtable account, which would let its own requester approve it (review finding, 2026-10-15).
    v_class := 'PERMISSION_DENIED';
    v_msg := format('%s was prepared in the RoofOps dashboard by a named person, so a different person approves it there (Finance → Invoice approvals). The shared Airtable account cannot approve it', v_ap.approval_number);
  elsif v_ap.status <> 'PENDING' then
    v_class := 'INVALID_STATE'; v_msg := format('%s is %s; only a PENDING preview can be decided', v_ap.approval_number, v_ap.status);
  elsif v_ap.expires_at <= now() then
    update approvals set status = 'EXPIRED' where id = v_ap.id;
    v_class := 'INVALID_STATE'; v_msg := format('%s expired at %s; prepare a new preview', v_ap.approval_number, v_ap.expires_at);
  elsif v_type = 'invoice.approved' then
    v_prev := invoice_final_preview(p.id);
    v_hash := case when (v_prev ->> 'ok')::boolean then invoice_preview_hash(v_prev -> 'preview') end;
    if v_hash is distinct from v_ap.payload_hash then
      update approvals set status = 'CANCELLED', decision_reason = 'Stale: the invoice would differ from the approved preview' where id = v_ap.id;
      v_class := 'INVALID_STATE';
      v_msg := format('%s is stale: %s. Prepare a new preview', v_ap.approval_number, coalesce(v_prev ->> 'message', 'the amount or details changed since it was prepared'));
    elsif coalesce(v_tenant, '') = '' then
      v_class := 'INVALID_STATE'; v_msg := 'No Xero Demo Company tenant is pinned (app_settings xero.demo_tenant_id); refusing to queue a Xero write';
    end if;
  end if;

  if v_class is not null then
    delete from processed_events where consumer = 'invoice_decision@1' and idempotency_key = v_key;   -- a corrected retry may decide later
    v_exc := wf_open_invoice_rejection(e.event_id, p.id, v_prj, v_class, v_msg);
    update automation_events set status = 'REJECTED', error_class = v_class, metadata = metadata || jsonb_build_object('reason', v_msg) where event_id = e.event_id;
    return jsonb_build_object('outcome', case when v_class = 'PERMISSION_DENIED' then 'PERMISSION_DENIED' else 'INVALID_STATE' end,
      'error_class', v_class, 'message', v_msg, 'exception_number', v_exc, 'approval_number', v_ap.approval_number, 'project_number', v_prj);
  end if;

  if v_type = 'invoice.rejected' then
    update approvals set status = 'REJECTED', decided_by = v_emp.id, decided_at = now(),
           decision_reason = coalesce(nullif(p_event -> 'payload' ->> 'reason', ''), case when p_employee is not null then 'Rejected in the RoofOps dashboard' else 'Rejected in Airtable' end) where id = v_ap.id;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason, correlation_id)
    values ('USER', v_emp.employee_code, 'approval.reject', 'approval', v_ap.id, v_ap.approval_number,
            jsonb_build_object('status', 'PENDING'), jsonb_build_object('status', 'REJECTED'), 'Invoice preview rejected', e.correlation_id);
    v_res := jsonb_build_object('outcome', 'REJECTED_BY_APPROVER', 'approval_number', v_ap.approval_number, 'decided_by', v_emp.full_name);
  else
    -- Approve: the RoofOps invoice (one FINAL per project, ever) + ONE queued Xero side effect.
    update approvals set status = 'EXECUTING', decided_by = v_emp.id, decided_at = now() where id = v_ap.id;
    insert into invoices (invoice_number, project_id, customer_id, invoice_type, status, sync_status, line_amount_type,
                          issue_date, due_date, approval_id, approved_by, approved_at, idempotency_key)
    values (next_friendly_id('INV', extract(year from app_today())::int), p.id, p.customer_id, 'FINAL', 'APPROVED', 'PENDING', 'INCLUSIVE',
            (v_ap.action_payload ->> 'invoice_date')::date, (v_ap.action_payload ->> 'due_date')::date, v_ap.id, v_emp.id, now(),
            'invoice:final:' || p.id)
    returning * into v_inv;
    for v_line in select * from jsonb_array_elements(v_ap.action_payload -> 'lines') loop
      insert into invoice_lines (invoice_id, line_no, description, quantity, unit_price, variation_id, account_code)
      values (v_inv.id, (v_line ->> 'line_no')::int, v_line ->> 'description', (v_line ->> 'quantity')::numeric, (v_line ->> 'unit_amount')::numeric,
              nullif(v_line ->> 'variation_id', '')::uuid, v_ap.action_payload ->> 'xero_account_code');
    end loop;
    select * into v_inv from invoices where id = v_inv.id;   -- totals are derived by trigger from the lines
    if v_inv.total_inc_gst <> (v_ap.action_payload ->> 'amount_inc_gst')::numeric or v_inv.gst_amount <> (v_ap.action_payload ->> 'gst_amount')::numeric then
      raise exception 'invoice % totals % / GST % disagree with the approved preview % / %', v_inv.invoice_number, v_inv.total_inc_gst, v_inv.gst_amount,
        v_ap.action_payload ->> 'amount_inc_gst', v_ap.action_payload ->> 'gst_amount' using errcode = 'check_violation';
    end if;

    insert into workflow_runs (workflow_key, workflow_version, runner, trigger_event_id, correlation_id, idempotency_key,
                               entity_type, entity_id, business_reference, status, attempt_count, started_at)
    values ('project_to_invoice', (select value from app_settings where key = 'wf.project_to_invoice.version'), 'N8N', e.event_id, e.correlation_id,
            v_key, 'invoice', v_inv.id, v_inv.invoice_number, 'RUNNING', 1, now())
    returning id into v_run;
    -- AC-14C B1: this approval queues a generation, and the generation owns the keys. A first-time invoice gets
    -- generation 1 - the historic key formats, byte for byte - and the reissue facility (Part B2) queues the next one.
    v_gen := coalesce((select max(o.generation) from outbox o where o.topic = 'xero.create_draft_invoice' and o.aggregate_id = v_inv.id), 0) + 1;
    -- P2-H2: the Xero-facing payload is generated from the canonical invoice just created, by the same builder the
    -- reissue uses; it must agree with every value the approver saw in the preview.
    v_draft := xero_draft_payload(v_inv.id, v_tenant);
    select string_agg(d.key, ', ' order by d.key) into v_diff from jsonb_each(v_draft) d
     where v_ap.action_payload ? d.key and v_ap.action_payload -> d.key is distinct from d.value;
    if v_diff is not null then
      raise exception 'invoice % draft disagrees with the approved preview % on: %', v_inv.invoice_number, v_ap.approval_number, v_diff using errcode = 'check_violation';
    end if;
    insert into outbox (topic, aggregate_type, aggregate_id, correlation_id, idempotency_key, payload, generation)
    values ('xero.create_draft_invoice', 'invoice', v_inv.id, e.correlation_id, xero_draft_outbox_key(v_inv.id, v_gen),
      v_ap.action_payload || v_draft || jsonb_build_object(
        'approval_number', v_ap.approval_number, 'approved_by', v_emp.full_name,
        'xero_idempotency_key', xero_draft_provider_key(v_inv.id, v_gen)), v_gen);
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason, correlation_id, workflow_run_id)
    values ('USER', v_emp.employee_code, 'approval.approve', 'approval', v_ap.id, v_ap.approval_number,
            jsonb_build_object('status', 'PENDING'), jsonb_build_object('status', 'EXECUTING', 'payload_hash', v_ap.payload_hash),
            'Final invoice approved by ' || v_emp.full_name, e.correlation_id, v_run),
           ('WORKFLOW', 'project_to_invoice@1', 'invoice.create', 'invoice', v_inv.id, v_inv.invoice_number, null,
            jsonb_build_object('project', v_prj, 'type', 'FINAL', 'status', 'APPROVED', 'total_inc_gst', v_inv.total_inc_gst, 'gst', v_inv.gst_amount),
            'Created from approved preview ' || v_ap.approval_number, e.correlation_id, v_run);
    insert into workflow_run_steps (run_id, attempt, seq, step_key, status, finished_at, detail) values
      (v_run, 1, 1, 'validate_event', 'SUCCEEDED', now(), '{}'),
      (v_run, 1, 2, 'authorise_approver', 'SUCCEEDED', now(), jsonb_build_object('employee', v_emp.employee_code, 'role', v_emp.role)),
      (v_run, 1, 3, 'recheck_preview_hash', 'SUCCEEDED', now(), jsonb_build_object('payload_hash', v_ap.payload_hash)),
      (v_run, 1, 4, 'create_invoice', 'SUCCEEDED', now(), jsonb_build_object('invoice_number', v_inv.invoice_number, 'total_inc_gst', v_inv.total_inc_gst)),
      (v_run, 1, 5, 'queue_xero_draft', 'SUCCEEDED', now(), jsonb_build_object('key', xero_draft_outbox_key(v_inv.id, v_gen), 'generation', v_gen));
    perform wf_log_event(e.event_key || ':invoice.approved', e.correlation_id, e.event_id, 'invoice.created', 'invoice', v_inv.id,
      v_inv.invoice_number, 'WORKFLOW', 'project_to_invoice@1', 'postgres', 'SUCCEEDED', null,
      jsonb_build_object('approval', v_ap.approval_number, 'total_inc_gst', v_inv.total_inc_gst), null);
    v_res := jsonb_build_object('outcome', 'APPROVED', 'approval_number', v_ap.approval_number, 'decided_by', v_emp.full_name,
      'invoice_id', v_inv.id, 'invoice_number', v_inv.invoice_number, 'amount_inc_gst', v_inv.total_inc_gst, 'workflow_run_id', v_run,
      'xero_key', xero_draft_outbox_key(v_inv.id, v_gen), 'generation', v_gen, 'preview', v_ap.action_payload);
  end if;

  update automation_events set status = 'SUCCEEDED', metadata = metadata || jsonb_build_object('outcome', v_res ->> 'outcome') where event_id = e.event_id;
  v_res := v_res || jsonb_build_object('project_number', v_prj, 'project_id', p.id, 'event_key', e.event_key, 'duplicate', false);
  update processed_events set status = 'COMPLETED', completed_at = now(), result = v_res, lease_expires_at = null
   where consumer = 'invoice_decision@1' and idempotency_key = v_key;
  return v_res;
end $$;

--
-- Name: wf_invoice_log_event(jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_invoice_log_event(p_event jsonb, p_type text, p_worker text, OUT event_id uuid, OUT event_key text, OUT correlation_id uuid, OUT redelivery boolean, OUT first_event uuid, OUT issues text[]) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v_payload jsonb := p_event -> 'payload'; v_base text; v_n int; v_prj text := p_event -> 'payload' ->> 'project_number';
begin
  issues := '{}'; redelivery := false;
  event_key := p_event ->> 'event_id';
  if coalesce(event_key, '') = '' or length(event_key) > 200 then issues := array_append(issues, 'event_id: required, <=200 chars'::text); end if;
  if coalesce(p_event ->> 'event_type', '') <> p_type then issues := array_append(issues, ('event_type: must be ' || p_type)::text); end if;
  if coalesce(p_event ->> 'source', '') = '' then issues := array_append(issues, 'source: required'::text); end if;
  if coalesce(p_event ->> 'actor_id', '') = '' then issues := array_append(issues, 'actor_id: required (who asked)'::text); end if;
  if jsonb_typeof(v_payload) is distinct from 'object' then issues := array_append(issues, 'payload: required object'::text); end if;
  if coalesce(v_prj, '') !~ '^PRJ-[0-9]{4}-[0-9]{4}$' then issues := array_append(issues, 'payload.project_number: required, format PRJ-YYYY-NNNN'::text); end if;
  if v_payload ? 'project_uuid' and coalesce(v_payload ->> 'project_uuid', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    issues := array_append(issues, 'payload.project_uuid: must be a UUID when present'::text);
  end if;
  begin
    perform (p_event ->> 'occurred_at')::timestamptz;
    if p_event ->> 'occurred_at' is null then issues := array_append(issues, 'occurred_at: required'::text); end if;
  exception when others then issues := array_append(issues, 'occurred_at: must be an ISO-8601 timestamp'::text);
  end;
  event_key := coalesce(nullif(event_key, ''), 'invalid:' || md5(p_event::text));
  correlation_id := stable_uuid('correlation', coalesce(nullif(p_event ->> 'correlation_id', ''), event_key));
  v_base := event_key;
  loop
    insert into automation_events (event_id, event_key, correlation_id, causation_id, event_type, entity_type, entity_id,
      business_reference, actor_type, actor_id, source, workflow_version, occurred_at, status, metadata, payload)
    values (stable_uuid('event', event_key), event_key, correlation_id, first_event, p_type, 'project',
      (select id from projects where project_number = v_prj), v_prj, 'USER', p_event ->> 'actor_id',
      coalesce(p_event ->> 'source', 'unknown'), (select value from app_settings where key = 'wf.project_to_invoice.version'), now(),
      case when array_length(issues, 1) > 0 then 'REJECTED' else 'RECEIVED' end,
      jsonb_build_object('worker', p_worker, 'airtable_record_id', v_payload ->> 'airtable_record_id', 'transport_redelivery', redelivery,
                         'issues', to_jsonb(issues)), p_event)
    on conflict do nothing
    returning automation_events.event_id into event_id;
    exit when event_id is not null;
    redelivery := true;
    first_event := stable_uuid('event', v_base);
    select count(*) + 1 into v_n from automation_events where automation_events.event_key like v_base || ':redelivery:%';
    event_key := v_base || ':redelivery:' || v_n;
  end loop;
end $_$;

--
-- Name: wf_invoice_prepare(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_invoice_prepare(p_event jsonb, p_worker text DEFAULT 'n8n'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_res jsonb := wf_invoice_prepare_core(p_event, p_worker);
  v_inv uuid; v_ap approvals;
begin
  if v_res ->> 'outcome' = 'ALREADY_INVOICED' then
    select i.id into v_inv from invoices i join approvals a on a.id = i.approval_id where a.approval_number = v_res ->> 'approval_number';
    if v_inv is null then   -- already invoiced outside this approval flow (e.g. a FINAL invoice with no approval row)
      select i.id into v_inv from invoices i where i.invoice_type = 'FINAL'
         and i.project_id = (select id from projects where project_number = p_event -> 'payload' ->> 'project_number');
    end if;
    if v_inv is not null then v_res := v_res || jsonb_build_object('xero_state', invoice_xero_state(v_inv)); end if;
  end if;
  if v_res ->> 'outcome' in ('PREVIEW_READY', 'ALREADY_PENDING') then
    select * into v_ap from approvals where approval_number = v_res ->> 'approval_number';
    if v_ap.id is not null then v_res := v_res || jsonb_build_object('preview_marker', invoice_preview_marker(v_ap)); end if;
  end if;
  return v_res;
end $$;

--
-- Name: wf_invoice_prepare_core(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_invoice_prepare_core(p_event jsonb, p_worker text DEFAULT 'n8n'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  e record; v_key text; v_claimed boolean; v_pe processed_events; p projects; v_prev jsonb; v_prj text;
  v_ap approvals; v_num text; v_exc text; v_res jsonb; v_requester uuid;
begin
  select * into e from wf_invoice_log_event(p_event, 'invoice.prepare_requested', p_worker);
  v_prj := p_event -> 'payload' ->> 'project_number';
  if array_length(e.issues, 1) > 0 then
    v_exc := wf_open_invoice_rejection(e.event_id, null, coalesce(v_prj, 'unknown'), 'VALIDATION_ERROR',
               'Invalid invoice.prepare_requested event: ' || array_to_string(e.issues, '; '));
    return jsonb_build_object('outcome', 'INVALID_EVENT', 'error_class', 'VALIDATION_ERROR', 'issues', to_jsonb(e.issues), 'exception_number', v_exc);
  end if;

  -- Transport idempotency: the same delivery always gets the same answer.
  v_key := 'invoice.prepare:' || coalesce(e.first_event::text, e.event_id::text);
  insert into processed_events (consumer, idempotency_key, first_event_id, request_hash, status, locked_by, lease_expires_at)
  values ('invoice_prepare@1', v_key, coalesce(e.first_event, e.event_id), md5(p_event::text), 'PROCESSING', p_worker, now() + interval '5 minutes')
  on conflict do nothing returning true into v_claimed;
  if v_claimed is null then
    select * into v_pe from processed_events where consumer = 'invoice_prepare@1' and idempotency_key = v_key for update;
    update processed_events set delivery_count = delivery_count + 1, last_seen_at = now() where consumer = v_pe.consumer and idempotency_key = v_key;
    update automation_events set status = 'DUPLICATE_IGNORED', error_class = 'DUPLICATE_EVENT', causation_id = v_pe.first_event_id,
           metadata = metadata || jsonb_build_object('reason', 'transport redelivery of the same event_id') where event_id = e.event_id;
    return coalesce(v_pe.result, '{}'::jsonb) || jsonb_build_object('duplicate', true, 'delivery_count', v_pe.delivery_count + 1);
  end if;

  select * into p from projects where project_number = v_prj for update;
  if not found or (p_event -> 'payload' ? 'project_uuid' and (p_event -> 'payload' ->> 'project_uuid')::uuid <> p.id) then
    v_res := jsonb_build_object('outcome', 'INVALID_STATE', 'error_class', case when p.id is null then 'NOT_FOUND' else 'RECONCILIATION_MISMATCH' end,
      'message', case when p.id is null then v_prj || ' does not exist' else 'Airtable RoofOps ID does not match ' || v_prj end);
  else
    -- An open or completed request for this project wins over a new one: one invoice per project.
    select * into v_ap from approvals where action_type = 'CREATE_INVOICE' and entity_id = p.id
       and status in ('PENDING', 'APPROVED', 'EXECUTING', 'EXECUTED') order by created_at desc limit 1;
    if v_ap.id is not null and v_ap.status = 'PENDING' and v_ap.expires_at > now() then
      v_res := jsonb_build_object('outcome', 'ALREADY_PENDING', 'approval_number', v_ap.approval_number, 'preview', v_ap.action_payload,
                                  'message', 'Preview ' || v_ap.approval_number || ' is already waiting for approval');
    elsif v_ap.id is not null and v_ap.status in ('APPROVED', 'EXECUTING', 'EXECUTED') then
      v_res := jsonb_build_object('outcome', 'ALREADY_INVOICED', 'approval_number', v_ap.approval_number, 'preview', v_ap.action_payload,
                                  'invoice_number', (select invoice_number from invoices where approval_id = v_ap.id),
                                  'message', v_prj || ' was already approved for invoicing under ' || v_ap.approval_number);
    else
      if v_ap.id is not null then   -- a stale PENDING request past its expiry
        update approvals set status = 'EXPIRED' where id = v_ap.id;
      end if;
      v_prev := invoice_final_preview(p.id);
      if not (v_prev ->> 'ok')::boolean then
        v_res := jsonb_build_object('outcome', case when (v_prev ->> 'already_invoiced')::boolean then 'ALREADY_INVOICED' else 'INVALID_STATE' end,
                                    'error_class', v_prev ->> 'error_class', 'message', v_prev ->> 'message');
      else
        select ei.employee_id into v_requester from employee_external_identities ei where ei.provider = 'AIRTABLE' and ei.external_id = p_event ->> 'actor_id';
        v_num := next_friendly_id('APR', extract(year from app_today())::int);
        insert into approvals (approval_number, action_type, entity_type, entity_id, business_reference, requested_by_actor_type,
          requested_by_employee_id, required_permission, action_payload, payload_hash, expected_record_version, idempotency_key, expires_at)
        values (v_num, 'CREATE_INVOICE', 'project', p.id, p.project_number, 'USER', v_requester, 'invoice.approve',
          v_prev -> 'preview', invoice_preview_hash(v_prev -> 'preview'), p.record_version, 'approval:' || e.event_key,
          now() + make_interval(hours => (select value::int from app_settings where key = 'invoice.approval_ttl_hours')))
        returning * into v_ap;
        insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason, correlation_id)
        values ('USER', p_event ->> 'actor_id', 'invoice.preview_prepared', 'project', p.id, p.project_number,
                jsonb_build_object('approval', v_num, 'amount_inc_gst', v_prev -> 'preview' -> 'amount_inc_gst', 'payload_hash', v_ap.payload_hash),
                'Final invoice preview awaiting approval', e.correlation_id);
        perform wf_log_event(e.event_key || ':invoice.preview_prepared', e.correlation_id, e.event_id, 'invoice.preview_prepared', 'project', p.id,
          p.project_number, 'WORKFLOW', 'project_to_invoice@1', 'postgres', 'SUCCEEDED', null, jsonb_build_object('approval', v_num), null);
        v_res := jsonb_build_object('outcome', 'PREVIEW_READY', 'approval_number', v_num, 'preview', v_ap.action_payload,
                                    'payload_hash', v_ap.payload_hash, 'expires_at', v_ap.expires_at);
      end if;
    end if;
  end if;

  if v_res ->> 'outcome' = 'INVALID_STATE' then
    v_exc := wf_open_invoice_rejection(e.event_id, p.id, v_prj, v_res ->> 'error_class', v_res ->> 'message');
    v_res := v_res || jsonb_build_object('exception_number', v_exc);
    update automation_events set status = 'REJECTED', error_class = v_res ->> 'error_class', metadata = metadata || jsonb_build_object('reason', v_res ->> 'message')
     where event_id = e.event_id;
  else
    update automation_events set status = 'SUCCEEDED', metadata = metadata || jsonb_build_object('outcome', v_res ->> 'outcome') where event_id = e.event_id;
  end if;
  v_res := v_res || jsonb_build_object('project_number', v_prj, 'project_id', p.id, 'event_key', e.event_key, 'duplicate', false);
  update processed_events set status = 'COMPLETED', completed_at = now(), result = v_res, lease_expires_at = null
   where consumer = 'invoice_prepare@1' and idempotency_key = v_key;
  return v_res;
end $$;

--
-- Name: wf_invoice_preview_verified(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_invoice_preview_verified(p_event_key text, p_record_id text, p_readback text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_num text := substring(coalesce(p_readback, '') from 'PREVIEW (APR-[0-9]{4}-[0-9]{4}) · #'); v_ap approvals;
begin
  if v_num is null then return jsonb_build_object('recorded', false, 'reason', 'the row shows no invoice preview'); end if;
  select * into v_ap from approvals where approval_number = v_num;
  if v_ap.id is null or v_ap.status <> 'PENDING' then
    return jsonb_build_object('recorded', false, 'reason', v_num || ' is not a pending preview');
  end if;
  if not invoice_preview_shows(p_readback, v_ap) then
    return jsonb_build_object('recorded', false, 'reason', 'the row does not show ' || v_num || ' as prepared (marker or amount differs)');
  end if;
  if v_ap.entity_id is distinct from airtable_project_for_record(p_record_id) or not exists (
       select 1 from automation_events e join processed_events pe on pe.consumer = 'invoice_prepare@1' and pe.result ->> 'event_key' = e.event_key
        where e.event_key = p_event_key and e.event_type = 'invoice.prepare_requested' and e.source = 'airtable'
          and e.metadata ->> 'airtable_record_id' = p_record_id and pe.result ->> 'approval_number' = v_num) then
    return jsonb_build_object('recorded', false, 'reason', 'no Airtable Prepare on this row returned ' || v_num);
  end if;
  insert into approval_presentations (approval_id, airtable_record_id, event_key, verified, payload_hash)
  values (v_ap.id, p_record_id, p_event_key, true, v_ap.payload_hash)
  on conflict (approval_id, airtable_record_id) do update
    set verified = true, payload_hash = excluded.payload_hash, event_key = excluded.event_key,
        presented_at = case when approval_presentations.verified then approval_presentations.presented_at else now() end;
  return jsonb_build_object('recorded', true, 'approval_number', v_num);
end $$;

--
-- Name: wf_log_event(text, uuid, uuid, text, text, uuid, text, text, text, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_log_event(p_event_key text, p_correlation uuid, p_causation uuid, p_type text, p_entity_type text, p_entity_id uuid, p_business_ref text, p_actor_type text, p_actor_id text, p_source text, p_status text, p_error_class text, p_metadata jsonb, p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_id uuid := stable_uuid('event', p_event_key);
begin
  insert into automation_events (event_id, event_key, correlation_id, causation_id, event_type, entity_type, entity_id,
    business_reference, actor_type, actor_id, source, workflow_version, occurred_at, status, error_class, metadata, payload)
  values (v_id, p_event_key, p_correlation, p_causation, p_type, p_entity_type, p_entity_id, p_business_ref,
    p_actor_type, p_actor_id, p_source, (select value from app_settings where key = 'wf.quote_to_project.version'),
    now(), p_status, p_error_class, coalesce(p_metadata, '{}'::jsonb), p_payload)
  on conflict do nothing;   -- event_id is derived from event_key: a clash on either unique index means "already recorded"
  return v_id;
end $$;

--
-- Name: wf_open_exception(uuid, uuid, text, uuid, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_open_exception(p_run uuid, p_event uuid, p_entity_type text, p_entity_id uuid, p_ref text, p_class text, p_message text, p_attempts integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_num text;
begin
  select exception_number into v_num from workflow_exceptions
   where (p_run is not null and workflow_run_id = p_run and resolution_status in ('OPEN','RETRY_QUEUED'))
      or (p_run is null and event_id = p_event and resolution_status in ('OPEN','RETRY_QUEUED'))
   limit 1;
  if v_num is not null then
    update workflow_exceptions set attempt_count = greatest(attempt_count, p_attempts), last_attempt_at = now(),
           error_class = p_class, error_message = p_message
     where exception_number = v_num;
    return v_num;
  end if;
  v_num := next_friendly_id('EXC');
  insert into workflow_exceptions (exception_number, workflow_run_id, event_id, workflow_key, entity_type, entity_id,
    business_reference, error_class, error_message, retryable, attempt_count, first_failed_at, last_attempt_at)
  select v_num, p_run, p_event,
         coalesce((select workflow_key from workflow_runs where id = p_run),
                  case when p_entity_type in ('invoice', 'project_invoice') then 'project_to_invoice' else 'quote_to_project' end),
         p_entity_type, p_entity_id, p_ref, p_class, p_message, ec.retryable, p_attempts, now(), now()
  from error_classes ec where ec.code = p_class;
  return v_num;
end $$;

--
-- Name: wf_open_invoice_rejection(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_open_invoice_rejection(p_event uuid, p_project uuid, p_ref text, p_class text, p_message text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_num text;
begin
  perform pg_advisory_xact_lock(hashtext('invoice-rejection:' || coalesce(p_project::text, p_ref) || ':' || p_class));
  select exception_number into v_num from workflow_exceptions
   where workflow_key = 'project_to_invoice' and entity_type = 'project_invoice'
     and entity_id is not distinct from p_project and business_reference is not distinct from p_ref
     and error_class = p_class and error_message = p_message and resolution_status in ('OPEN', 'RETRY_QUEUED')
   order by first_failed_at limit 1;
  if v_num is not null then
    update workflow_exceptions set attempt_count = attempt_count + 1, last_attempt_at = now() where exception_number = v_num;
    return v_num;
  end if;
  return wf_open_exception(null, p_event, 'project_invoice', p_project, p_ref, p_class, p_message, 1);
end $$;

--
-- Name: wf_open_quote_rejection(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_open_quote_rejection(p_event uuid, p_quote uuid, p_ref text, p_class text, p_message text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_num text;
begin
  -- Serialise concurrent deliveries of the same rejection (overlapping webhook pings).
  perform pg_advisory_xact_lock(hashtext('quote-rejection:' || coalesce(p_quote::text, p_ref) || ':' || p_class));
  select exception_number into v_num from workflow_exceptions
   where workflow_key = 'quote_to_project' and entity_type = 'quote'
     and entity_id is not distinct from p_quote and business_reference is not distinct from p_ref
     and error_class = p_class and error_message = p_message and resolution_status in ('OPEN', 'RETRY_QUEUED')
   order by first_failed_at limit 1;
  if v_num is not null then
    update workflow_exceptions set attempt_count = attempt_count + 1, last_attempt_at = now() where exception_number = v_num;
    return v_num;
  end if;
  return wf_open_exception(null, p_event, 'quote', p_quote, p_ref, p_class, p_message, 1);
end $$;

--
-- Name: wf_open_sync_exception(text, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_open_sync_exception(p_workflow text, p_entity_type text, p_entity_id uuid, p_ref text, p_class text, p_message text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_num text;
begin
  perform pg_advisory_xact_lock(hashtext('sync-exception:' || coalesce(p_ref, '') || ':' || p_class || ':' || p_message));
  select exception_number into v_num from workflow_exceptions
   where workflow_key = p_workflow and business_reference is not distinct from p_ref and error_class = p_class and error_message = p_message
     and resolution_status in ('OPEN', 'RETRY_QUEUED') limit 1;
  if v_num is not null then
    update workflow_exceptions set attempt_count = attempt_count + 1, last_attempt_at = now() where exception_number = v_num;
    return v_num;
  end if;
  v_num := next_friendly_id('EXC');
  insert into workflow_exceptions (exception_number, workflow_key, entity_type, entity_id, business_reference, error_class, error_message,
                                   retryable, attempt_count, first_failed_at, last_attempt_at)
  select v_num, p_workflow, p_entity_type, p_entity_id, p_ref, p_class, p_message, ec.retryable, 1, now(), now() from error_classes ec where ec.code = p_class;
  return v_num;
end $$;

--
-- Name: wf_quote_accepted(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_quote_accepted(p_event jsonb, p_worker text DEFAULT 'n8n'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_issues text[] := '{}';
  v_event_key text := p_event ->> 'event_id';
  v_payload jsonb := p_event -> 'payload';
  v_quote_no text := v_payload ->> 'quote_id';
  v_version int;
  v_accepted_on date;
  v_corr uuid;
  v_event uuid;
  v_first_event uuid;
  v_key text;
  v_hash text;
  v_claimed boolean;
  v_pe processed_events;
  v_q quotes;
  v_latest quote_versions;
  v_project uuid;
  v_project_no text;
  v_pm uuid;
  v_task uuid;
  v_run uuid;
  v_exc text;
  v_result jsonb;
  v_class text;
  v_msg text;
  v_redelivery boolean := false;
  v_first automation_events;
  v_quote_rec text;
begin
  -- ---------- 1. schema validation (non-retryable) ----------
  if coalesce(v_event_key, '') = '' or length(v_event_key) > 200 then v_issues := array_append(v_issues, 'event_id: required, <=200 chars'::text); end if;
  if coalesce(p_event ->> 'event_type', '') <> 'quote.accepted' then v_issues := array_append(v_issues, 'event_type: must be quote.accepted'::text); end if;
  if coalesce(p_event ->> 'source', '') = '' then v_issues := array_append(v_issues, 'source: required'::text); end if;
  if jsonb_typeof(v_payload) is distinct from 'object' then v_issues := array_append(v_issues, 'payload: required object'::text); end if;
  if coalesce(v_quote_no, '') !~ '^Q-[0-9]{4}-[0-9]{4}$' then v_issues := array_append(v_issues, 'payload.quote_id: required, format Q-YYYY-NNNN'::text); end if;
  if jsonb_typeof(v_payload -> 'accepted_version') is distinct from 'number'
     or (v_payload ->> 'accepted_version') !~ '^[1-9][0-9]{0,3}$' then
    v_issues := array_append(v_issues, 'payload.accepted_version: required positive integer'::text);
  else
    v_version := (v_payload ->> 'accepted_version')::int;
  end if;
  if v_payload ? 'quote_uuid' and coalesce(v_payload ->> 'quote_uuid', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_issues := array_append(v_issues, 'payload.quote_uuid: must be a UUID when present'::text);
  end if;
  begin
    v_accepted_on := coalesce((v_payload ->> 'accepted_on')::date, app_today());
    if v_accepted_on > app_today() then v_issues := array_append(v_issues, 'payload.accepted_on: cannot be in the future'::text); end if;
  exception when others then v_issues := array_append(v_issues, 'payload.accepted_on: must be YYYY-MM-DD'::text);
  end;
  begin
    perform (p_event ->> 'occurred_at')::timestamptz;
    if p_event ->> 'occurred_at' is null then v_issues := array_append(v_issues, 'occurred_at: required'::text); end if;
  exception when others then v_issues := array_append(v_issues, 'occurred_at: must be an ISO-8601 timestamp'::text);
  end;

  v_corr := stable_uuid('correlation', coalesce(nullif(p_event ->> 'correlation_id', ''), v_event_key, gen_random_uuid()::text));

  if array_length(v_issues, 1) > 0 then
    v_event_key := coalesce(nullif(v_event_key, ''), 'invalid:' || md5(p_event::text));
    -- A redelivered invalid event is still just one rejection.
    if exists (select 1 from automation_events where event_key = v_event_key) then
      select exception_number into v_exc from workflow_exceptions where event_id = stable_uuid('event', v_event_key) limit 1;
      return jsonb_build_object('status', 'REJECTED', 'outcome', 'INVALID_EVENT', 'error_class', 'VALIDATION_ERROR', 'retryable', false,
                                'issues', to_jsonb(v_issues), 'exception_number', v_exc, 'redelivery', true, 'duplicate', true);
    end if;
    v_event := wf_log_event(v_event_key, v_corr, null, 'quote.accepted', 'quote', null, v_quote_no, 'INTEGRATION',
      p_event ->> 'actor_id', coalesce(p_event ->> 'source', 'unknown'), 'REJECTED', 'VALIDATION_ERROR',
      jsonb_build_object('issues', to_jsonb(v_issues), 'worker', p_worker), p_event);
    v_exc := wf_open_exception(null, v_event, 'quote', null, v_quote_no, 'VALIDATION_ERROR',
      'Invalid quote.accepted event: ' || array_to_string(v_issues, '; '), 1);
    return jsonb_build_object('status', 'REJECTED', 'outcome', 'INVALID_EVENT', 'error_class', 'VALIDATION_ERROR', 'retryable', false,
                              'issues', to_jsonb(v_issues), 'exception_number', v_exc);
  end if;

  -- ---------- 2. idempotency key = the business fact (ADR-002) ----------
  v_key := 'quote.accepted:' || v_quote_no || ':v' || v_version;
  v_hash := encode(sha256(convert_to(jsonb_build_object('quote_id', v_quote_no, 'accepted_version', v_version)::text, 'UTF8')), 'hex');

  -- Log the delivery. The unique event_key is the arbiter: if this event_id was already
  -- recorded (a transport redelivery, even a concurrent one), log it under a derived key
  -- instead, so the original event row is never relabelled.
  declare v_base text := v_event_key; v_n int;
  begin
    loop
      insert into automation_events (event_id, event_key, correlation_id, causation_id, event_type, entity_type, entity_id,
        business_reference, actor_type, actor_id, source, workflow_version, occurred_at, status, metadata, payload)
      values (stable_uuid('event', v_event_key), v_event_key, v_corr, v_first_event, 'quote.accepted', 'quote',
        (select id from quotes where quote_number = v_quote_no), v_quote_no, 'INTEGRATION', p_event ->> 'actor_id',
        p_event ->> 'source', (select value from app_settings where key = 'wf.quote_to_project.version'), now(), 'RECEIVED',
        jsonb_build_object('idempotency_key', v_key, 'worker', p_worker, 'airtable_record_id', v_payload ->> 'airtable_record_id',
                           'transport_redelivery', v_redelivery), p_event)
      on conflict do nothing   -- event_id is derived from event_key: a clash on either unique index means "already recorded"
      returning event_id into v_event;
      exit when v_event is not null;
      v_redelivery := true;
      v_first_event := stable_uuid('event', v_base);
      select count(*) + 1 into v_n from automation_events where event_key like v_base || ':redelivery:%';
      v_event_key := v_base || ':redelivery:' || v_n;
    end loop;
  end;

  -- AC-18: the first completed outcome of an event_id is final for that event_id. Only a delivery that committed left its
  -- event row (one that raised was rolled back, so it is judged again as new). A redelivery of a SUCCEEDED or
  -- DUPLICATE_IGNORED event gets the business fact's stored result below; a REJECTED one gets its own stored rejection
  -- here, without claiming the fact or judging it again against the quote as it is now (a Draft quote since moved to Sent
  -- made the same event_id create a project). A new event_id, a fresh Airtable change, is judged normally.
  if v_redelivery then
    select * into v_first from automation_events where event_key = p_event ->> 'event_id';
    if v_first.status = 'REJECTED' then
      -- A rejection recorded before this rule kept no outcome: it is rebuilt from its event row and its exception.
      v_result := coalesce(v_first.metadata -> 'result', jsonb_strip_nulls(jsonb_build_object('status', 'REJECTED',
        'outcome', case when v_first.metadata ? 'issues' then 'INVALID_EVENT' else 'INVALID_STATE' end, 'error_class', v_first.error_class,
        'retryable', false, 'message', v_first.metadata ->> 'reason', 'issues', v_first.metadata -> 'issues',
        'exception_number', (select x.exception_number from workflow_exceptions x
                              where x.event_id = v_first.event_id
                                 or (x.workflow_key = 'quote_to_project' and x.entity_type = 'quote' and x.business_reference = v_first.business_reference
                                     and x.error_class = v_first.error_class and x.error_message = v_first.metadata ->> 'reason')
                              order by (x.event_id is not distinct from v_first.event_id) desc, x.first_failed_at limit 1))))
        || jsonb_build_object('duplicate', true, 'redelivery', true);
      update automation_events set status = 'DUPLICATE_IGNORED', error_class = 'DUPLICATE_EVENT', causation_id = v_first.event_id,
             metadata = metadata || jsonb_build_object('reason', 'transport redelivery of the same event_id', 'first_outcome', 'REJECTED',
                                                        'exception_number', v_result ->> 'exception_number')
       where event_id = v_event;
      -- The delivery is counted on its open exception (as every rejected delivery is); a resolved one is left alone.
      update workflow_exceptions set attempt_count = attempt_count + 1, last_attempt_at = greatest(last_attempt_at, now())
       where exception_number = v_result ->> 'exception_number' and resolution_status in ('OPEN', 'RETRY_QUEUED');
      return v_result;
    end if;
  end if;

  insert into processed_events (consumer, idempotency_key, first_event_id, request_hash, status, locked_by, lease_expires_at)
  values ('quote_to_project@1', v_key, v_event, v_hash, 'PROCESSING', p_worker, now() + interval '5 minutes')
  on conflict do nothing
  returning true into v_claimed;

  if v_claimed is null then
    -- Someone already processed this business fact (their transaction has committed:
    -- a concurrent claimer blocks on the unique index until then).
    select * into v_pe from processed_events where consumer = 'quote_to_project@1' and idempotency_key = v_key for update;
    update processed_events set delivery_count = delivery_count + 1, last_seen_at = now() where consumer = v_pe.consumer and idempotency_key = v_key;
    update automation_events set status = 'DUPLICATE_IGNORED', error_class = 'DUPLICATE_EVENT', causation_id = v_pe.first_event_id,
           metadata = metadata || jsonb_build_object(
             'reason', case when v_redelivery then 'transport redelivery of the same event_id' else 'semantic duplicate: same quote and version already processed' end,
             'existing_project_number', v_pe.result ->> 'project_number', 'delivery_count', v_pe.delivery_count + 1)
     where event_id = v_event;
    return v_pe.result || jsonb_build_object('status', 'DUPLICATE', 'outcome', 'ALREADY_PROCESSED', 'duplicate', true, 'idempotency_key', v_key,
      'delivery_count', v_pe.delivery_count + 1,
      'pending_side_effects', (select coalesce(jsonb_agg(jsonb_build_object('topic', topic, 'key', idempotency_key, 'status', status) order by topic), '[]')
                                 from outbox where aggregate_id = (v_pe.result ->> 'project_id')::uuid and status <> 'DONE'));
  end if;

  -- ---------- 3. business validation ----------
  select * into v_q from quotes where quote_number = v_quote_no for update;
  if not found then
    v_class := 'NOT_FOUND'; v_msg := format('Quote %s does not exist', v_quote_no);
  else
    select * into v_latest from quote_versions where quote_id = v_q.id order by version_number desc limit 1;
    select external_id into v_quote_rec from external_links
     where provider = 'AIRTABLE' and entity_type = 'quote' and entity_id = v_q.id and external_type = 'Record' and verified_at is not null;
    if v_payload ? 'quote_uuid' and (v_payload ->> 'quote_uuid')::uuid <> v_q.id then
      -- The staff-facing record and the control layer disagree about which quote this is: never guess.
      v_class := 'RECONCILIATION_MISMATCH';
      v_msg := format('Event names %s but its RoofOps ID %s is not that quote', v_quote_no, v_payload ->> 'quote_uuid');
    elsif v_quote_rec is not null and coalesce(v_payload ->> 'airtable_record_id', '') not in ('', v_quote_rec) then
      -- AC-25: the acceptance came from another Airtable record than the quote's verified one (a duplicated or copied row
      -- carries the same Quote Number and RoofOps ID). An event that names no record is judged as before.
      v_class := 'RECONCILIATION_MISMATCH';
      v_msg := format('Acceptance came from Airtable record %s, but %s is Airtable record %s: accept the quote on its own record',
                      v_payload ->> 'airtable_record_id', v_quote_no, v_quote_rec);
    elsif v_q.status not in ('SENT', 'ACCEPTED') then
      v_class := 'INVALID_STATE'; v_msg := format('Quote %s is %s; only a SENT quote can be accepted', v_quote_no, v_q.status);
    elsif v_latest.version_number <> v_version then
      v_class := 'INVALID_STATE'; v_msg := format('Accepted version v%s is not the current version v%s of %s', v_version, v_latest.version_number, v_quote_no);
    elsif v_q.status = 'ACCEPTED' and v_q.accepted_version_id <> v_latest.id then
      v_class := 'INVALID_STATE'; v_msg := format('%s was accepted at a different version', v_quote_no);
    elsif v_q.status = 'SENT' and v_accepted_on < v_q.sent_on then
      -- AC-23: checked before the date is written (quotes_check4 raised there, and n8n 01's cursor stalled behind it). A date
      -- from Sent On to today is kept as given (back-dating in that range is an owner decision); a future one was refused
      -- as an invalid event above. The message leaves out the typed date: one open exception per quote for this reason.
      v_class := 'VALIDATION_ERROR';
      v_msg := format('Accepted On is before %s was sent (%s): an acceptance cannot predate its quote', v_quote_no, v_q.sent_on);
    end if;
  end if;
  if v_class is not null then
    -- Release the claim: a corrected event for the same fact may be processed later.
    delete from processed_events where consumer = 'quote_to_project@1' and idempotency_key = v_key;
    update automation_events set status = 'REJECTED', error_class = v_class, metadata = metadata || jsonb_build_object('reason', v_msg) where event_id = v_event;
    v_exc := wf_open_quote_rejection(v_event, v_q.id, v_quote_no, v_class, v_msg);
    v_result := jsonb_build_object('status', 'REJECTED', 'outcome', 'INVALID_STATE', 'error_class', v_class, 'retryable', false, 'message', v_msg, 'exception_number', v_exc);
    -- AC-18: kept on this event, so a redelivery of the same event_id returns this outcome (above).
    update automation_events set metadata = metadata || jsonb_build_object('result', v_result) where event_id = v_event;
    return v_result;
  end if;

  -- ---------- 4. accept the quote (state transition, audited) ----------
  if v_q.status = 'SENT' then
    update quotes set status = 'ACCEPTED', accepted_version_id = v_latest.id, accepted_on = v_accepted_on where id = v_q.id;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason, correlation_id)
    values ('INTEGRATION', coalesce(p_event ->> 'actor_id', p_event ->> 'source'), 'quote.accept', 'quote', v_q.id, v_quote_no,
            jsonb_build_object('status', v_q.status), jsonb_build_object('status', 'ACCEPTED', 'accepted_version', v_version, 'accepted_on', v_accepted_on),
            'Accepted in ' || (p_event ->> 'source'), v_corr);
  end if;

  -- ---------- 5. project, checklist, material-review task ----------
  -- PM with the fewest active projects (deterministic tie-break)
  select e.id into v_pm from employees e
    left join projects p on p.project_manager_id = e.id and p.status not in ('COMPLETED','CLOSED','CANCELLED')
   where e.role = 'PROJECT_MANAGER' and e.is_active
   group by e.id, e.employee_code order by count(p.id), e.employee_code limit 1;

  v_project_no := next_friendly_id('PRJ', extract(year from app_today())::int);
  insert into projects (project_number, quote_id, accepted_quote_version_id, customer_id, property_id, project_manager_id, status, created_by_event_id)
  values (v_project_no, v_q.id, v_latest.id, v_q.customer_id, v_q.property_id, v_pm, 'PLANNING', v_event)
  returning id into v_project;

  insert into workflow_runs (workflow_key, workflow_version, runner, trigger_event_id, correlation_id, idempotency_key,
                             entity_type, entity_id, business_reference, status, attempt_count, started_at)
  values ('quote_to_project', (select value from app_settings where key = 'wf.quote_to_project.version'), 'N8N', v_event, v_corr, v_key,
          'project', v_project, v_project_no, 'RUNNING', 1, now())
  returning id into v_run;

  insert into project_checklist_items (project_id, item_code, label, stage, sort_order) values
    (v_project, 'MATERIALS_REVIEWED',     'Materials reviewed and approved',            'PRE_START', 10),
    (v_project, 'SWMS_SIGNED',            'Safe Work Method Statement signed',          'PRE_START', 20),
    (v_project, 'COMPLETION_PHOTOS',      'Completion / compliance photos uploaded',    'COMPLETION', 30),
    (v_project, 'COMPLIANCE_CERTIFICATE', 'Compliance certificate issued',              'COMPLETION', 40),
    (v_project, 'FINAL_INVOICE_APPROVED', 'Final invoice approved',                     'INVOICING', 50);

  insert into tasks (project_id, task_type, title, description, assignee_id, due_on, dedupe_key, created_by_workflow_run_id)
  values (v_project, 'MATERIAL_REVIEW', 'Review materials for ' || v_project_no,
          'Confirm quantities against the accepted quote ' || v_quote_no || ' v' || v_version || ' and raise POs.',
          v_pm, app_today() + 2, 'material_review:' || v_project, v_run)
  returning id into v_task;

  -- ---------- 6. external side effects: queued, performed by n8n, recorded only with read-back proof ----------
  insert into outbox (topic, aggregate_type, aggregate_id, correlation_id, idempotency_key, payload) values
    ('drive.ensure_project_folder', 'project', v_project, v_corr, 'drive:project-folder:' || v_project,
      jsonb_build_object('project_id', v_project, 'project_number', v_project_no, 'quote_number', v_quote_no,
                         'folder_name', v_project_no || ' - ' || (select btrim(display_name) from customers where id = v_q.customer_id),
                         'root_folder_name', 'RoofOps Demo',
                         'subfolders', jsonb_build_array('01 Quote', '02 Site', '03 Materials', '04 Supplier', '05 Completion'))),
    ('airtable.project_writeback', 'project', v_project, v_corr, 'airtable:project-writeback:' || v_project,
      jsonb_build_object('project_id', v_project, 'project_number', v_project_no, 'quote_number', v_quote_no,
                         'status', 'Planning',
                         'project_manager', (select full_name from employees where id = v_pm),
                         'material_task', 'Review materials for ' || v_project_no || ' (due ' || (app_today() + 2)::text || ')',
                         -- Airtable record IDs come from verified links, never from names; the event's own record ID is the fallback.
                         'quote_airtable_record_id', coalesce(
                            (select external_id from external_links where provider = 'AIRTABLE' and entity_type = 'quote' and entity_id = v_q.id and verified_at is not null),
                            v_payload ->> 'airtable_record_id'),
                         'customer_airtable_record_id',
                            (select external_id from external_links where provider = 'AIRTABLE' and entity_type = 'customer' and entity_id = v_q.customer_id and verified_at is not null)));

  -- ---------- 7. event + audit records ----------
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason, correlation_id, workflow_run_id)
  values ('WORKFLOW', 'quote_to_project@1', 'project.create', 'project', v_project, v_project_no,
          jsonb_build_object('project_number', v_project_no, 'quote', v_quote_no, 'version', v_version, 'status', 'PLANNING',
                             'project_manager', (select full_name from employees where id = v_pm)),
          'Quote ' || v_quote_no || ' accepted', v_corr, v_run),
         ('WORKFLOW', 'quote_to_project@1', 'task.create', 'task', v_task, v_project_no,
          jsonb_build_object('task_type', 'MATERIAL_REVIEW', 'due_on', app_today() + 2), 'Material review requested', v_corr, v_run);

  update automation_events set status = 'SUCCEEDED', entity_id = v_q.id where event_id = v_event;
  perform wf_log_event(v_event_key || ':project.created', v_corr, v_event, 'project.created', 'project', v_project, v_project_no,
    'WORKFLOW', 'quote_to_project@1', 'postgres', 'SUCCEEDED', null, jsonb_build_object('quote', v_quote_no), null);
  perform wf_log_event(v_event_key || ':materials.review_requested', v_corr, v_event, 'materials.review_requested', 'project', v_project, v_project_no,
    'WORKFLOW', 'quote_to_project@1', 'postgres', 'SUCCEEDED', null, jsonb_build_object('task_id', v_task), null);

  insert into workflow_run_steps (run_id, attempt, seq, step_key, status, finished_at, detail) values
    (v_run, 1, 1, 'validate_event', 'SUCCEEDED', now(), '{}'),
    (v_run, 1, 2, 'claim_idempotency', 'SUCCEEDED', now(), jsonb_build_object('key', v_key)),
    (v_run, 1, 3, 'accept_quote', 'SUCCEEDED', now(), jsonb_build_object('previous_status', v_q.status)),
    (v_run, 1, 4, 'create_project', 'SUCCEEDED', now(), jsonb_build_object('project_number', v_project_no)),
    (v_run, 1, 5, 'create_checklist_and_task', 'SUCCEEDED', now(), jsonb_build_object('task_id', v_task)),
    (v_run, 1, 6, 'queue_side_effects', 'SUCCEEDED', now(), jsonb_build_object('topics', array['drive.ensure_project_folder','airtable.project_writeback']));

  v_result := jsonb_build_object('status', 'CREATED', 'outcome', 'CREATED', 'duplicate', false, 'project_id', v_project, 'project_number', v_project_no,
    'quote_number', v_quote_no, 'task_id', v_task, 'workflow_run_id', v_run, 'correlation_id', v_corr, 'idempotency_key', v_key,
    'side_effects', jsonb_build_array(
      jsonb_build_object('topic', 'drive.ensure_project_folder', 'key', 'drive:project-folder:' || v_project),
      jsonb_build_object('topic', 'airtable.project_writeback', 'key', 'airtable:project-writeback:' || v_project)));
  update processed_events set status = 'COMPLETED', completed_at = now(), result = v_result, lease_expires_at = null
   where consumer = 'quote_to_project@1' and idempotency_key = v_key;
  return v_result;
end $_$;

--
-- Name: wf_quote_publish_fail(text, text, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_quote_publish_fail(p_key text, p_error_class text, p_message text, p_http_status integer, p_retry_after_seconds integer, p_attempt integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o outbox; v_retryable boolean; v_delay int; v_exc text; v_ref text; v_msg text; v_late boolean;
  v_max int := coalesce((select value::int from app_settings where key = 'wf.side_effect.max_attempts'), 5);
begin
  select * into o from outbox where idempotency_key = p_key for update;
  if not found or o.topic <> 'airtable.quote_publish' then raise exception 'unknown quote hand-off %', p_key using errcode = 'no_data_found'; end if;
  select retryable into v_retryable from error_classes where code = p_error_class;
  if v_retryable is null then raise exception 'unknown error class %', p_error_class using errcode = 'foreign_key_violation'; end if;
  v_ref := o.payload ->> 'quote_number';
  v_late := o.status <> 'DISPATCHING' or p_attempt is distinct from o.attempts;
  if v_late then
    -- A late worker (its hand-off finished, stopped or held by a newer attempt): the hand-off is not touched. What it saw
    -- is logged; a duplicate Airtable record (AMBIGUOUS_WRITE) still needs a person, so it reaches the quote's exception.
    perform wf_log_event(p_key || ':late:' || coalesce(p_attempt::text, 'none') || ':' || p_error_class, o.correlation_id, null, 'automation.late_report',
      'quote', o.aggregate_id, v_ref, 'WORKFLOW', o.topic, 'n8n', 'FAILED', p_error_class,
      jsonb_build_object('reported_attempt', p_attempt, 'holding_attempt', o.attempts, 'handoff_status', o.status, 'message', left(p_message, 500)), null);
    if p_error_class <> 'AMBIGUOUS_WRITE' then
      return jsonb_build_object('retry', false, 'late', true, 'attempt', p_attempt, 'holding_attempt', o.attempts, 'status', o.status);
    end if;
    v_msg := format('%s: a late attempt (%s) of %s found more than one Airtable quote record; nothing was changed in Postgres. A person must keep one record and delete the others. Last error: %s',
             o.topic, coalesce(p_attempt::text, 'unknown'), v_ref, left(p_message, 400));
  elsif v_retryable and o.attempts < v_max then
    v_delay := coalesce(p_retry_after_seconds, least(900, 60 * (2 ^ (o.attempts - 1))::int));   -- 1, 2, 4, 8 minutes … capped at 15
    update outbox set status = 'FAILED', locked_until = null, next_attempt_at = now() + make_interval(secs => v_delay),
           last_error = left(p_message, 1000) where id = o.id;
    perform wf_log_event(p_key || ':retry:' || o.attempts, o.correlation_id, null, 'automation.retry_scheduled', 'quote', o.aggregate_id, v_ref,
      'WORKFLOW', o.topic, 'n8n', 'FAILED', p_error_class,
      jsonb_build_object('attempt', o.attempts, 'retry_in_seconds', v_delay, 'http_status', p_http_status, 'message', left(p_message, 500)), null);
    return jsonb_build_object('retry', true, 'retry_in_seconds', v_delay, 'attempt', o.attempts, 'max_attempts', v_max);
  else
    update outbox set status = 'FAILED', locked_until = null, next_attempt_at = 'infinity', last_error = left(p_message, 1000) where id = o.id;
    perform wf_log_event(p_key || ':failed:' || o.attempts, o.correlation_id, null, 'automation.failed', 'quote', o.aggregate_id, v_ref,
      'WORKFLOW', o.topic, 'n8n', 'FAILED', p_error_class,
      jsonb_build_object('attempt', o.attempts, 'http_status', p_http_status, 'message', left(p_message, 500)), null);
    v_msg := format('%s: %s was not added to Airtable after %s attempt(s) and is not retried; nothing was marked done. Fix the cause, then re-queue it (ops/requeue-quote-publish.sql). Last error: %s',
             o.topic, v_ref, o.attempts, left(p_message, 400));
  end if;
  -- One open exception per quote (20261017050000): a later failure updates that one.
  select exception_number into v_exc from workflow_exceptions
   where entity_type = 'quote' and entity_id = o.aggregate_id and resolution_status in ('OPEN', 'RETRY_QUEUED') and error_message like 'airtable.quote_publish:%'
   order by first_failed_at, exception_number limit 1 for update;
  if v_exc is not null then
    update workflow_exceptions set error_class = p_error_class, error_message = v_msg, attempt_count = greatest(attempt_count, o.attempts),
           last_attempt_at = now(), resolution_status = 'OPEN' where exception_number = v_exc;
  else
    v_exc := wf_open_exception(null, null, 'quote', o.aggregate_id, v_ref, p_error_class, v_msg, o.attempts);
  end if;
  return jsonb_build_object('retry', false, 'exception_number', v_exc, 'attempt', o.attempts, 'late', v_late,
    'reason', case when v_late then 'duplicate Airtable records seen by a late attempt' when v_retryable then 'max attempts reached' else 'non-retryable error class' end);
end $$;

--
-- Name: wf_quote_publish_next(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_quote_publish_next(p_worker text DEFAULT 'n8n:10'::text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('worker', p_worker, 'writes', coalesce(jsonb_agg(jsonb_build_object('key', o.idempotency_key, 'quote_number', o.payload ->> 'quote_number')), '[]'::jsonb))
    from (select * from outbox o where o.topic = 'airtable.quote_publish'
             and ((o.status in ('PENDING', 'FAILED') and o.next_attempt_at <= now())
                  or (o.status = 'DISPATCHING' and o.locked_until < now()))   -- a run that died holding it: its lease ran out
           order by o.created_at limit 1) o
$$;

--
-- Name: wf_reconcile_airtable(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_reconcile_airtable(p_run_key text, p_table_id text, p_records jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_run reconciliation_runs; v_res jsonb; c jsonb;
begin
  select * into v_run from reconciliation_runs where run_key = p_run_key;
  if v_run.scope is not null then
    if v_run.status <> 'RUNNING' then return jsonb_build_object('ok', false, 'table_id', p_table_id, 'reason', 'run ' || p_run_key || ' is not running'); end if;
    return reconcile_invoice_projection_reset(v_run, p_table_id, p_records);
  end if;
  -- AC-10: record the repairs this run hands to n8n 07, like every other RoofOps write.
  v_res := wf_reconcile_airtable_core(p_run_key, p_table_id, p_records);
  for c in select * from jsonb_array_elements(coalesce(v_res -> 'corrections', '[]'::jsonb)) loop
    perform airtable_record_writes('reconcile:' || p_run_key, p_table_id, c ->> 'id', c -> 'fields',
      (select y -> 'fields' from jsonb_array_elements(p_records) y where y ->> 'id' = c ->> 'id' limit 1), 'reconcile:' || p_run_key);
  end loop;
  return v_res;
end $$;

--
-- Name: wf_reconcile_airtable_core(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_reconcile_airtable_core(p_run_key text, p_table_id text, p_records jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_run reconciliation_runs; r record; e record; c field_contract; a jsonb; v_res jsonb; v_corr jsonb := '{}'::jsonb;
  v_checked int := 0; v_drift int := 0; v_records int := 0; v_ev jsonb; v_exc text; v_entity text;
  v_changed_at timestamptz; v_deferred int := 0; v_exp jsonb;
  v_read int; v_absent text[] := '{}'; v_mass text[] := '{}'; v_n int; v_table_name text;
begin
  select * into v_run from reconciliation_runs where run_key = p_run_key and status = 'RUNNING';
  if v_run.id is null then return jsonb_build_object('ok', false, 'reason', 'no running reconciliation ' || coalesce(p_run_key, '')); end if;
  select min(entity) into v_entity from field_contract where airtable_table_id = p_table_id;
  v_table_name := case v_entity when 'property' then 'Properties' when 'purchase_order' then 'Purchase Orders' else initcap(v_entity) || 's' end;

  -- Every date the read contains, as the business day it denotes.
  p_records := coalesce((select jsonb_agg(case when jsonb_typeof(x -> 'fields') = 'object' then jsonb_set(x, '{fields}', at_normalize_fields(x -> 'fields')) else x end)
                           from jsonb_array_elements(p_records) x), '[]'::jsonb);
  select count(*) into v_read from v_airtable_expected x join jsonb_array_elements(p_records) y on y ->> 'id' = x.record_id where x.table_id = p_table_id;

  -- Field-level guard 1: a field id missing from every record of the read, while RoofOps holds a value for it.
  if v_read > 0 then
    select coalesce(array_agg(fc.airtable_field_id), '{}') into v_absent from field_contract fc
     where fc.airtable_table_id = p_table_id and fc.reconcile in ('APPLY_VIA_HANDLER', 'REPAIR_AIRTABLE', 'PROJECTION')
       and not exists (select 1 from jsonb_array_elements(p_records) y where (y -> 'fields') ? fc.airtable_field_id)
       and exists (select 1 from v_airtable_expected x join jsonb_array_elements(p_records) y on y ->> 'id' = x.record_id
                    where x.table_id = p_table_id and at_norm(at_repair_value(x.expected -> fc.airtable_field_id)) is not null);
  end if;
  for c in select * from field_contract where airtable_field_id = any (v_absent) order by airtable_name loop
    v_exc := case when v_run.mode = 'repair' then wf_open_sync_exception('reconciliation', v_entity, null, 'Airtable ' || v_table_name || '.' || c.airtable_name,
      'SCHEMA_MISMATCH', format('Airtable %s field "%s" (%s) is missing from every record read. It was deleted, renamed or recreated in Airtable; RoofOps did not compare, change or write it. Restore the field (same id), or update the RoofOps field contract.',
                                v_table_name, c.airtable_name, c.airtable_field_id)) end;
    insert into reconciliation_findings (run_id, system, entity_type, field, classification, action, detail)
    values (v_run.id, 'AIRTABLE', v_entity, c.airtable_name, 'REQUIRES_HUMAN', case when v_exc is null then 'NONE_OBSERVE_ONLY' else 'EXCEPTION_OPENED' end,
            coalesce(v_exc || ': ', '') || 'field missing from every record read (not treated as staff edits)');
  end loop;

  -- Field-level guard 2: the same staff-editable field differs on many records at once. Only records unchanged since
  -- the run started count (the AC-01 rule): a legitimate bulk edit applied by the webhook after this read is not drift.
  for c in select * from field_contract where airtable_table_id = p_table_id and owner = 'AIRTABLE_EDIT' and not (airtable_field_id = any (v_absent)) loop
    select count(*) into v_n from v_airtable_expected x join jsonb_array_elements(p_records) y on y ->> 'id' = x.record_id
     where x.table_id = p_table_id and x.expected ? c.airtable_field_id and not at_matches(x.expected -> c.airtable_field_id, y -> 'fields' -> c.airtable_field_id)
       and not exists (select 1 from projects t where t.id = x.entity_id and t.updated_at > v_run.started_at)
       and not exists (select 1 from quotes t where t.id = x.entity_id and t.updated_at > v_run.started_at)
       and not exists (select 1 from purchase_orders t where t.id = x.entity_id and t.updated_at > v_run.started_at);
    if v_n >= 5 and v_n * 5 >= v_read then
      v_mass := v_mass || c.airtable_field_id;
      v_exc := case when v_run.mode = 'repair' then wf_open_sync_exception('reconciliation', v_entity, null, 'Airtable ' || v_table_name || '.' || c.airtable_name,
        'RECONCILIATION_MISMATCH', format('%s of %s Airtable %s records show a different "%s" in one read. That looks like a change to the field (format, time zone, bulk import), not individual staff edits, so RoofOps replayed none of them. Check the field in Airtable; genuine changes can be re-made record by record.',
                                          v_n, v_read, v_table_name, c.airtable_name)) end;
      insert into reconciliation_findings (run_id, system, entity_type, field, classification, action, detail)
      values (v_run.id, 'AIRTABLE', v_entity, c.airtable_name, 'REQUIRES_HUMAN', case when v_exc is null then 'NONE_OBSERVE_ONLY' else 'EXCEPTION_OPENED' end,
              format('%s%s of %s records differ in one read (not replayed)', coalesce(v_exc || ': ', ''), v_n, v_read));
    end if;
  end loop;

  -- Airtable records RoofOps does not know (created in Airtable) → a person decides.
  for r in select x ->> 'id' as rec from jsonb_array_elements(p_records) x
            where not exists (select 1 from external_links l where l.provider = 'AIRTABLE' and l.external_type = 'Record' and l.external_id = x ->> 'id')
  loop
    v_exc := case when v_run.mode = 'repair' then wf_open_sync_exception('reconciliation', v_entity, null, r.rec, 'RECONCILIATION_MISMATCH',
      format('Airtable %s record %s exists only in Airtable; RoofOps does not create records from Airtable. Delete it or recreate it through the supported flow.', v_entity, r.rec)) end;
    insert into reconciliation_findings (run_id, system, entity_type, external_id, classification, action, detail)
    values (v_run.id, 'AIRTABLE', v_entity, r.rec, 'UNKNOWN', case when v_exc is null then 'NONE_OBSERVE_ONLY' else 'EXCEPTION_OPENED' end, v_exc);
  end loop;

  -- Canonical records whose Airtable twin is gone.
  for e in select x.* from v_airtable_expected x where x.table_id = p_table_id
            and not exists (select 1 from jsonb_array_elements(p_records) y where y ->> 'id' = x.record_id)
  loop
    v_exc := case when v_run.mode = 'repair' then wf_open_sync_exception('reconciliation', e.entity_type, e.entity_id, e.business_key, 'EXTERNAL_MISSING',
      format('%s has no Airtable record any more (%s was deleted or moved). Staff cannot see it in Airtable.', e.business_key, e.record_id)) end;
    insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, classification, action, detail)
    values (v_run.id, 'AIRTABLE', e.entity_type, e.business_key, e.record_id, 'EXTERNAL_MISSING', case when v_exc is null then 'NONE_OBSERVE_ONLY' else 'EXCEPTION_OPENED' end, v_exc);
  end loop;

  for e in select x.*, y -> 'fields' as fields from v_airtable_expected x
             join jsonb_array_elements(p_records) y on y ->> 'id' = x.record_id where x.table_id = p_table_id
  loop
    v_records := v_records + 1;

    -- Is this read still evidence? Lock the canonical row, then check it has not changed since the run started (AC-01).
    v_changed_at := null;
    case e.entity_type
      when 'project' then select updated_at into v_changed_at from projects where id = e.entity_id for update;
      when 'quote' then select updated_at into v_changed_at from quotes where id = e.entity_id for update;
      when 'purchase_order' then select updated_at into v_changed_at from purchase_orders where id = e.entity_id for update;
      when 'customer' then select updated_at into v_changed_at from customers where id = e.entity_id for update;
      when 'property' then select updated_at into v_changed_at from properties where id = e.entity_id for update;
      when 'supplier' then select updated_at into v_changed_at from suppliers where id = e.entity_id for update;
      else null;
    end case;
    select x.expected into v_exp from v_airtable_expected x where x.table_id = p_table_id and x.record_id = e.record_id;
    if v_changed_at > v_run.started_at then
      for c in select * from field_contract where airtable_table_id = p_table_id and airtable_field_id in (select jsonb_object_keys(v_exp))
                   and not (airtable_field_id = any (v_absent))
                   and reconcile in ('APPLY_VIA_HANDLER', 'REPAIR_AIRTABLE', 'PROJECTION') order by (field_key = 'status') desc
      loop
        v_checked := v_checked + 1;
        a := e.fields -> c.airtable_field_id;
        if at_matches(v_exp -> c.airtable_field_id, a) then continue; end if;
        v_deferred := v_deferred + 1;
        insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, field, expected, actual, classification, action, detail)
        values (v_run.id, 'AIRTABLE', e.entity_type, e.business_key, e.record_id, c.airtable_name, at_norm(v_exp -> c.airtable_field_id), at_norm(a),
                'STALE_EVENT', 'NONE', 'RoofOps changed this record after the run read Airtable; the read is out of date and is re-checked next run');
      end loop;
      continue;
    end if;

    -- Record what Airtable showed (a field missing from the whole read was not observed).
    insert into airtable_observations (table_id, record_id, field_id, value, observed_at, source)
    select p_table_id, e.record_id, k.key, at_norm(e.fields -> k.key), now(), 'reconciliation' from jsonb_each(v_exp) k
     where not (k.key = any (v_absent))
    on conflict (table_id, record_id, field_id) do update set value = excluded.value, observed_at = excluded.observed_at, source = excluded.source;

    for c in select * from field_contract where airtable_table_id = p_table_id and airtable_field_id in (select jsonb_object_keys(v_exp))
                 and not (airtable_field_id = any (v_absent))
                 and reconcile in ('APPLY_VIA_HANDLER', 'REPAIR_AIRTABLE', 'PROJECTION') order by (field_key = 'status') desc
    loop
      v_checked := v_checked + 1;
      a := e.fields -> c.airtable_field_id;
      if at_matches(v_exp -> c.airtable_field_id, a) then continue; end if;
      v_drift := v_drift + 1;
      if c.airtable_field_id = any (v_mass) then continue; end if;   -- reported once for the field, above
      if c.owner = 'AIRTABLE_EDIT' then
        if e.entity_type = 'quote' and c.field_key = 'status' and at_norm(a) = 'Accepted' then
          v_exc := case when v_run.mode = 'repair' then wf_open_sync_exception('reconciliation', 'quote', e.entity_id, e.business_key, 'RECONCILIATION_MISMATCH',
            format('%s is Accepted in Airtable but RoofOps never received the acceptance. Set Status back to Sent, then to Accepted, to run the Quote → Project workflow.', e.business_key)) end;
          insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, field, expected, actual, classification, action, detail)
          values (v_run.id, 'AIRTABLE', 'quote', e.business_key, e.record_id, c.airtable_name, at_norm(v_exp -> c.airtable_field_id), at_norm(a),
                  'REQUIRES_HUMAN', case when v_exc is null then 'NONE_OBSERVE_ONLY' else 'EXCEPTION_OPENED' end, v_exc);
          continue;
        end if;
        if v_run.mode = 'observe' then
          insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, field, expected, actual, classification, action, detail)
          values (v_run.id, 'AIRTABLE', e.entity_type, e.business_key, e.record_id, c.airtable_name, at_norm(v_exp -> c.airtable_field_id), at_norm(a),
                  'SAFE_AUTO_REPAIR', 'NONE_OBSERVE_ONLY', 'Missed Airtable edit; a repair run replays it through the same validation');
          continue;
        end if;
        v_ev := jsonb_build_object('event_id', 'reconcile:' || p_run_key || ':' || e.record_id || ':' || c.airtable_field_id, 'source', 'reconciler',
                  'actor_id', 'reconciliation', 'occurred_at', v_run.started_at, 'table_id', p_table_id, 'record_id', e.record_id,
                  'changes', jsonb_build_object(c.airtable_field_id, jsonb_build_object('current', a)), 'current', e.fields);
        v_res := wf_airtable_change(v_ev, 'reconciler');
        v_corr := v_corr || jsonb_build_object(e.record_id, coalesce(v_corr -> e.record_id, '{}'::jsonb) || coalesce(v_res -> 'corrections', '{}'::jsonb));
        insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, field, expected, actual, classification, action, detail)
        values (v_run.id, 'AIRTABLE', e.entity_type, e.business_key, e.record_id, c.airtable_name, at_norm(v_exp -> c.airtable_field_id), at_norm(a),
                'SAFE_AUTO_REPAIR', case when jsonb_array_length(coalesce(v_res -> 'applied', '[]')) > 0 then 'APPLIED_TO_POSTGRES' else 'REJECTED_AND_REPAIRED' end,
                coalesce(v_res ->> 'note', v_res ->> 'outcome'));
      else
        insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, field, expected, actual, classification, action, detail)
        values (v_run.id, 'AIRTABLE', e.entity_type, e.business_key, e.record_id, c.airtable_name, at_norm(at_repair_value(v_exp -> c.airtable_field_id)), at_norm(a),
                case when c.reconcile = 'PROJECTION' or at_norm(a) is null then 'SAFE_AUTO_REPAIR' else 'UNAUTHORIZED_STATE' end,
                case when v_run.mode = 'repair' then 'REPAIRED_AIRTABLE' else 'NONE_OBSERVE_ONLY' end,
                case when c.reconcile = 'PROJECTION' then 'Airtable projection of canonical invoice state was stale'
                     when at_norm(a) is null then 'RoofOps value was never written to Airtable (missing projection)'
                     else c.airtable_name || ' is managed by RoofOps; edited in Airtable' end);
        if v_run.mode = 'repair' then
          v_corr := v_corr || jsonb_build_object(e.record_id, coalesce(v_corr -> e.record_id, '{}'::jsonb)
                     || jsonb_build_object(c.airtable_field_id, at_repair_value(v_exp -> c.airtable_field_id))
                     || coalesce((select jsonb_build_object(s.airtable_field_id, to_char(now() at time zone 'Australia/Brisbane', 'YYYY-MM-DD HH24:MI')
                                   || E'\n↺ ' || c.airtable_name || case when c.reconcile = 'PROJECTION' or at_norm(a) is null then ' refreshed from RoofOps.' else ' is managed by RoofOps; reverted by reconciliation.' end)
                                  from field_contract s where s.airtable_table_id = p_table_id and s.field_key = 'roofops_sync'), '{}'::jsonb));
        end if;
      end if;
    end loop;
  end loop;

  return jsonb_build_object('ok', true, 'table_id', p_table_id, 'records', v_records, 'fields_checked', v_checked, 'drift', v_drift,
    'rechecked_next_run', v_deferred,
    'suspect_fields', (select coalesce(jsonb_agg(airtable_name order by airtable_name), '[]'::jsonb) from field_contract where airtable_field_id = any (v_absent || v_mass)),
    'corrections', (select coalesce(jsonb_agg(jsonb_build_object('id', k, 'fields', v)), '[]'::jsonb) from jsonb_each(v_corr) as t(k, v) where v <> '{}'::jsonb));
end $$;

--
-- Name: wf_reconcile_drive_unavailable(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_reconcile_drive_unavailable(p_run_key text, p_decision jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_run reconciliation_runs; v_class text := coalesce(p_decision ->> 'error_class', 'UNKNOWN'); v_msg text; v_exc text;
begin
  select * into v_run from reconciliation_runs where run_key = p_run_key and status = 'RUNNING';
  if v_run.id is null then return jsonb_build_object('ok', false, 'reason', 'no running reconciliation ' || coalesce(p_run_key, '')); end if;
  if not exists (select 1 from error_classes where code = v_class) then v_class := 'UNKNOWN'; end if;
  -- A stable message per cause, so every run with the same cause updates the same exception.
  v_msg := case v_class
    when 'RATE_LIMITED' then 'Reconciliation could not check Google Drive: rate limited after retries. Drive folders were not verified; checked again at the next run'
    when 'SERVICE_UNAVAILABLE' then 'Reconciliation could not check Google Drive: service unavailable after retries. Drive folders were not verified; checked again at the next run'
    when 'UPSTREAM_5XX' then 'Reconciliation could not check Google Drive: server errors after retries. Drive folders were not verified; checked again at the next run'
    when 'NETWORK' then 'Reconciliation could not reach Google Drive after retries. Drive folders were not verified; checked again at the next run'
    else coalesce(p_decision ->> 'reason', 'Reconciliation could not check Google Drive') end;
  v_exc := wf_open_sync_exception('reconciliation', 'integration', null, 'GOOGLE_DRIVE', v_class, v_msg);
  update reconciliation_runs set summary = summary || jsonb_build_object('drive', jsonb_build_object('checked', 0, 'verified', 0, 'drift', 0, 'status', 'UNAVAILABLE',
           'error_class', v_class, 'reason', p_decision ->> 'reason', 'attempts', p_decision -> 'attempts', 'exception', v_exc))
   where id = v_run.id;
  insert into integration_health (service, ok, detail)
  values ('google_drive', false, jsonb_build_object('check', 'reconciliation ' || p_run_key, 'error_class', v_class, 'reason', p_decision ->> 'reason',
                                                    'http', p_decision -> 'http', 'google_reason', p_decision ->> 'google_reason', 'attempts', p_decision -> 'attempts', 'exception', v_exc));
  return jsonb_build_object('ok', true, 'exception_number', v_exc, 'error_class', v_class);
end $$;

--
-- Name: wf_reconcile_external(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_reconcile_external(p_run_key text, p_system text, p_results jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_limited jsonb; v_res jsonb; x record;
begin
  if p_system = 'XERO' then
    -- Existence, total and reference as before; then AC-14: the verified financial state of every linked invoice.
    v_res := wf_reconcile_external_core(p_run_key, p_system, p_results);
    if not coalesce((v_res ->> 'ok')::boolean, false) then return v_res; end if;
    return v_res || jsonb_build_object('settlement', xero_record_settlement(p_run_key, p_results));
  end if;
  if p_system <> 'DRIVE' then return wf_reconcile_external_core(p_run_key, p_system, p_results); end if;
  select coalesce(jsonb_agg(r), '[]'::jsonb) into v_limited from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) r
   where coalesce((r ->> 'http')::int, 0) = 429 or ((r ->> 'http')::int = 403 and r ->> 'reason' in ('rateLimitExceeded', 'userRateLimitExceeded'));
  v_res := wf_reconcile_external_core(p_run_key, p_system,
             (select coalesce(jsonb_agg(r), '[]'::jsonb) from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) r where not (v_limited @> jsonb_build_array(r))));
  if not coalesce((v_res ->> 'ok')::boolean, false) then return v_res; end if;
  if jsonb_array_length(v_limited) > 0 then
    perform wf_reconcile_drive_unavailable(p_run_key, jsonb_build_object('error_class', 'RATE_LIMITED', 'attempts', 1, 'http', v_limited -> 0 -> 'http',
      'reason', format('Google Drive rate-limited %s of the folder reads; those folders were not verified this run and are checked again at the next run', jsonb_array_length(v_limited))));
    return v_res || jsonb_build_object('unavailable', true, 'not_verified', jsonb_array_length(v_limited));
  end if;
  insert into integration_health (service, ok, detail)
  values ('google_drive', true, jsonb_build_object('check', 'reconciliation ' || p_run_key, 'verified', v_res -> 'verified', 'drift', v_res -> 'drift'));
  for x in select id, exception_number from workflow_exceptions
            where workflow_key = 'reconciliation' and business_reference = 'GOOGLE_DRIVE' and resolution_status in ('OPEN', 'RETRY_QUEUED') for update loop
    update workflow_exceptions set resolution_status = 'RESOLVED', resolved_at = now(), resolved_by_system = 'workflow:reconciliation',
           resolution_note = 'Google Drive checked successfully in ' || p_run_key where id = x.id;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
    values ('SYSTEM', 'workflow:reconciliation', 'exception.resolved', 'workflow_exception', x.id, x.exception_number,
            '{"resolution_status":"OPEN"}', '{"resolution_status":"RESOLVED"}', 'Google Drive checked successfully in ' || p_run_key);
  end loop;
  return v_res;
end $$;

--
-- Name: wf_reconcile_external_core(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_reconcile_external_core(p_run_key text, p_system text, p_results jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_run reconciliation_runs; x jsonb; v_class text; v_detail text; v_exc text; v_ok int := 0; v_bad int := 0;
begin
  select * into v_run from reconciliation_runs where run_key = p_run_key and status = 'RUNNING';
  if v_run.id is null or p_system not in ('DRIVE', 'XERO') then return jsonb_build_object('ok', false); end if;
  for x in select * from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) loop
    v_class := null;
    if p_system = 'DRIVE' then
      if coalesce((x ->> 'http')::int, 0) = 404 or (x ->> 'trashed')::boolean then
        v_class := 'EXTERNAL_MISSING'; v_detail := format('Drive folder for %s is %s', x ->> 'project_number', case when (x ->> 'trashed')::boolean then 'in the trash' else 'deleted' end);
      elsif coalesce((x ->> 'http')::int, 0) <> 200 then
        v_class := 'UNKNOWN'; v_detail := format('Drive folder for %s could not be read (HTTP %s)', x ->> 'project_number', x ->> 'http');
      elsif x ->> 'expected_parent' is not null and not coalesce((x -> 'parents') ? (x ->> 'expected_parent'), false) then
        v_class := 'REQUIRES_HUMAN'; v_detail := format('Drive folder for %s was moved out of the RoofOps root folder', x ->> 'project_number');
      end if;
    else
      if coalesce((x ->> 'http')::int, 0) = 404 or x ->> 'status' in ('DELETED', 'VOIDED') then
        v_class := 'EXTERNAL_MISSING'; v_detail := format('Xero invoice %s is %s', x ->> 'xero_invoice_number', coalesce(lower(x ->> 'status'), 'missing'));
      elsif coalesce((x ->> 'http')::int, 0) <> 200 then
        v_class := 'UNKNOWN'; v_detail := format('Xero invoice %s could not be read (HTTP %s)', x ->> 'xero_invoice_number', x ->> 'http');
      elsif (x ->> 'total')::numeric is distinct from (x ->> 'expected_total')::numeric or x ->> 'reference' is distinct from x ->> 'expected_reference' then
        v_class := 'REQUIRES_HUMAN'; v_detail := format('Xero invoice %s was edited in Xero (total %s vs approved %s, reference %s)',
                     x ->> 'xero_invoice_number', x ->> 'total', x ->> 'expected_total', x ->> 'reference');
      end if;
    end if;
    if v_class is null then
      v_ok := v_ok + 1;
      update external_links set last_synced_at = now()
       where provider = case p_system when 'DRIVE' then 'GOOGLE_DRIVE' else 'XERO' end and external_id = coalesce(x ->> 'folder_id', x ->> 'invoice_id');
    else
      v_bad := v_bad + 1;
      v_exc := case when v_run.mode = 'repair' then wf_open_sync_exception('reconciliation', case p_system when 'DRIVE' then 'project' else 'invoice' end, null,
                 coalesce(x ->> 'project_number', x ->> 'invoice_number'), case when v_class = 'EXTERNAL_MISSING' then 'EXTERNAL_MISSING' else 'RECONCILIATION_MISMATCH' end, v_detail) end;
      insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, classification, action, detail)
      values (v_run.id, p_system, case p_system when 'DRIVE' then 'project' else 'invoice' end, coalesce(x ->> 'project_number', x ->> 'invoice_number'),
              coalesce(x ->> 'folder_id', x ->> 'invoice_id'), v_class, case when v_exc is null then 'NONE_OBSERVE_ONLY' else 'EXCEPTION_OPENED' end, v_detail);
    end if;
  end loop;
  update reconciliation_runs set summary = summary || jsonb_build_object(lower(p_system), jsonb_build_object('checked', v_ok + v_bad, 'verified', v_ok, 'drift', v_bad))
   where id = v_run.id;
  return jsonb_build_object('ok', true, 'verified', v_ok, 'drift', v_bad);
end $$;

--
-- Name: wf_reconcile_finish(text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_reconcile_finish(p_run_key text, p_airtable jsonb DEFAULT '{}'::jsonb, p_webhooks jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_run reconciliation_runs; v_sum jsonb;
begin
  select * into v_run from reconciliation_runs where run_key = p_run_key and status = 'RUNNING';
  if v_run.id is null then return jsonb_build_object('ok', false, 'reason', 'no running reconciliation ' || coalesce(p_run_key, '')); end if;
  v_sum := v_run.summary || jsonb_build_object(
    'airtable', coalesce(p_airtable, '{}'::jsonb), 'webhooks', coalesce(p_webhooks, '[]'::jsonb),
    'findings', (select coalesce(jsonb_object_agg(classification || '/' || action, n), '{}'::jsonb)
                   from (select classification, action, count(*) n from reconciliation_findings where run_id = v_run.id group by 1, 2) s),
    'open_exceptions', (select count(*) from workflow_exceptions where resolution_status in ('OPEN', 'RETRY_QUEUED')),
    'dead_letters', (select count(*) from outbox where status = 'FAILED' and next_attempt_at = 'infinity'));
  update reconciliation_runs set status = 'COMPLETED', finished_at = now(), summary = v_sum where id = v_run.id;
  insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
  values ('SYSTEM', 'reconciliation', 'reconciliation.completed', 'reconciliation_run', v_run.id, v_run.run_key, v_sum, v_run.mode || ' run (' || v_run.trigger || ')');
  return jsonb_build_object('ok', true, 'run_key', v_run.run_key, 'mode', v_run.mode, 'summary', v_sum);
end $$;

--
-- Name: wf_reconcile_start(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_reconcile_start(p_trigger text, p_mode text DEFAULT 'repair'::text, p_token text DEFAULT NULL::text, p_scope jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_res jsonb; p projects; v_rec text;
begin
  if p_scope is null or jsonb_typeof(p_scope) = 'null' then
    return wf_reconcile_start_core(p_trigger, p_mode, p_token);
  end if;
  if p_scope ->> 'kind' is distinct from 'invoice_projection_reset' then
    return jsonb_build_object('started', false, 'reason', 'unknown reconciliation scope');
  end if;
  if p_trigger <> 'manual' or p_mode <> 'repair' then
    return jsonb_build_object('started', false, 'reason', 'a scoped run is a manual repair run (operator token)');
  end if;
  select * into p from projects where project_number = p_scope ->> 'project';
  select external_id into v_rec from external_links
   where provider = 'AIRTABLE' and entity_type = 'project' and external_type = 'Record' and entity_id = p.id order by verified_at desc nulls last limit 1;
  if p.id is null or v_rec is null then
    return jsonb_build_object('started', false, 'reason', coalesce(p_scope ->> 'project', 'no project') || ' has no linked Airtable row');
  end if;
  if exists (select 1 from approvals where entity_id = p.id and action_type = 'CREATE_INVOICE' and status = 'PENDING')
     or exists (select 1 from invoices where project_id = p.id and invoice_type = 'FINAL' and status <> 'VOIDED') then
    return jsonb_build_object('started', false, 'reason', p.project_number || ' has a preview in flight or an invoice: its Airtable invoice projection is not blank');
  end if;
  v_res := wf_reconcile_start_core(p_trigger, p_mode, p_token);   -- operator token, quota guard, the run row
  if not coalesce((v_res ->> 'started')::boolean, false) then return v_res; end if;
  update reconciliation_runs set scope = jsonb_build_object('kind', 'invoice_projection_reset', 'project', p.project_number, 'project_id', p.id, 'record_id', v_rec)
   where run_key = v_res ->> 'run_key';
  return v_res || jsonb_build_object('tables', jsonb_build_array('tblvUPIoebC3zoacv'),
                                     'scope', jsonb_build_object('kind', 'invoice_projection_reset', 'project', p.project_number));
end $$;

--
-- Name: wf_reconcile_start_core(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_reconcile_start_core(p_trigger text, p_mode text DEFAULT 'repair'::text, p_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_run reconciliation_runs; v_hash text := (select value from app_settings where key = 'reconcile.trigger_token_sha256');
begin
  if p_trigger not in ('schedule', 'manual') or p_mode not in ('observe', 'repair') then
    return jsonb_build_object('started', false, 'reason', 'trigger must be schedule|manual and mode observe|repair');
  end if;
  if p_trigger = 'manual' and (coalesce(v_hash, '') = '' or encode(sha256(convert_to(coalesce(p_token, ''), 'UTF8')), 'hex') <> v_hash) then
    return jsonb_build_object('started', false, 'reason', 'manual reconciliation needs the operator trigger token');
  end if;
  perform pg_advisory_xact_lock(hashtext('reconcile-start'));
  -- Protect the Airtable monthly quota: at most one run every 2 minutes.
  if exists (select 1 from reconciliation_runs where started_at > now() - interval '2 minutes') then
    return jsonb_build_object('started', false, 'reason', 'a reconciliation ran less than 2 minutes ago');
  end if;
  update reconciliation_runs set status = 'FAILED', finished_at = now(), summary = summary || '{"reason":"superseded (never finished)"}'
   where status = 'RUNNING';
  insert into reconciliation_runs (run_key, trigger, mode) values ('RECON-' || to_char(clock_timestamp() at time zone 'Australia/Brisbane', 'YYYYMMDD-HH24MISS') || '-' || substr(md5(random()::text), 1, 4), p_trigger, p_mode) returning * into v_run;
  return jsonb_build_object('started', true, 'run_key', v_run.run_key, 'mode', p_mode,
    'tables', (select jsonb_agg(distinct airtable_table_id) from field_contract where airtable_table_id is not null));
end $$;

--
-- Name: wf_reconcile_targets(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_reconcile_targets(p_run_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if exists (select 1 from reconciliation_runs where run_key = p_run_key and scope is not null) then
    return jsonb_build_object('drive', '[]'::jsonb, 'xero', '[]'::jsonb, 'xero_uncertain', '[]'::jsonb);
  end if;
  return coalesce(wf_reconcile_targets_core(p_run_key), '{}'::jsonb) || jsonb_build_object('xero_uncertain', coalesce((
    select jsonb_agg(jsonb_build_object('key', o.idempotency_key, 'invoice_number', i.invoice_number, 'project_number', p.project_number,
             'xero_invoice_number', o.payload ->> 'xero_invoice_number', 'reference', o.payload ->> 'reference', 'tenant_id', o.payload ->> 'xero_tenant_id')
             order by i.invoice_number)
      from invoices i join outbox o on o.aggregate_id = i.id and o.topic = 'xero.create_draft_invoice' join projects p on p.id = i.project_id
     where i.sync_status = 'UNKNOWN' and o.status not in ('DONE', 'DISPATCHING')   -- a write 05 holds is left to 05
       and o.id = (select c.id from outbox_current('xero.create_draft_invoice', i.id) c)   -- the current generation only
       and o.payload ->> 'xero_tenant_id' = (select nullif(value, '') from app_settings where key = 'xero.demo_tenant_id')
       and exists (select 1 from reconciliation_runs where run_key = p_run_key and status = 'RUNNING')), '[]'::jsonb));
end $$;

--
-- Name: wf_reconcile_targets_core(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_reconcile_targets_core(p_run_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'drive', coalesce((select jsonb_agg(jsonb_build_object('project_number', p.project_number, 'folder_id', l.external_id))
                       from external_links l join projects p on p.id = l.entity_id
                       where l.provider = 'GOOGLE_DRIVE' and l.entity_type = 'project' and l.external_type = 'Folder' and l.verified_at is not null), '[]'::jsonb),
    'xero', coalesce((select jsonb_agg(jsonb_build_object('invoice_number', i.invoice_number, 'project_number', p.project_number, 'invoice_id', l.external_id,
                        'tenant_id', (select value from app_settings where key = 'xero.demo_tenant_id'),
                        'xero_invoice_number', (select payload ->> 'xero_invoice_number' from outbox_current('xero.create_draft_invoice', i.id)),
                        'total', i.total_inc_gst, 'reference', p.project_number))
                      from external_links l join invoices i on i.id = l.entity_id join projects p on p.id = i.project_id
                      where l.provider = 'XERO' and l.external_type = 'Invoice' and l.verified_at is not null), '[]'::jsonb))
  where exists (select 1 from reconciliation_runs where run_key = p_run_key and status = 'RUNNING')
$$;

--
-- Name: wf_reconcile_xero_uncertain(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_reconcile_xero_uncertain(p_run_key text, p_results jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_run reconciliation_runs; x jsonb; o outbox; i invoices; v_pin text := (select nullif(value, '') from app_settings where key = 'xero.demo_tenant_id');
  v_num jsonb; v_live jsonb; v_other jsonb; d jsonb; v_outcome text; v_detail text; v_applied boolean; v_repair boolean;
  v_contact text; v_dead boolean; e record; v_items jsonb := '[]'; v_rec int := 0; v_abs int := 0; v_person int := 0; v_skip int := 0;
  v_superseded text[] := '{}'::text[];
begin
  select * into v_run from reconciliation_runs where run_key = p_run_key and status = 'RUNNING';
  if v_run.id is null then return jsonb_build_object('ok', false, 'reason', 'no running reconciliation ' || coalesce(p_run_key, '')); end if;
  v_repair := v_run.mode = 'repair';
  for x in select * from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) loop
    v_applied := false; v_detail := null; v_superseded := '{}'::text[];
    select * into o from outbox where idempotency_key = x ->> 'key' and topic = 'xero.create_draft_invoice' for update;
    select * into i from invoices where id = o.aggregate_id for update;
    if o.id is not null then v_superseded := xero_draft_superseded_ids(o.aggregate_id); end if;
    if o.id is null or i.id is null then
      v_outcome := 'UNKNOWN_KEY';
    elsif i.sync_status <> 'UNKNOWN' or o.status in ('DONE', 'DISPATCHING') then
      v_outcome := 'SKIPPED';                              -- already settled, or 05 is working on it right now
    elsif x ->> 'tenant_id' is distinct from o.payload ->> 'xero_tenant_id' or o.payload ->> 'xero_tenant_id' is distinct from v_pin then
      v_outcome := 'WRONG_TENANT';                         -- only a lookup in the bound, pinned tenant can settle it (AC-06)
      v_detail := format('%s: Xero was asked about %s in tenant %s, but the write is bound to %s and the pinned tenant is %s. Not settled; it stays uncertain. A person must check why',
        i.invoice_number, o.payload ->> 'xero_invoice_number', coalesce(left(x ->> 'tenant_id', 8) || '…', 'no tenant'),
        coalesce(left(o.payload ->> 'xero_tenant_id', 8) || '…', 'no tenant'), coalesce(left(v_pin, 8) || '…', 'none'));
      if v_repair then
        perform wf_open_sync_exception('reconciliation', 'invoice', i.id, i.invoice_number, 'PERMISSION_DENIED', v_detail);
        v_applied := true;
      end if;
      insert into reconciliation_findings (run_id, system, entity_type, entity_ref, classification, action, detail)
      values (v_run.id, 'XERO', 'invoice', i.invoice_number, 'UNAUTHORIZED_STATE', case when v_repair then 'EXCEPTION_OPENED' else 'NONE_OBSERVE_ONLY' end, v_detail);
    elsif coalesce((x ->> 'http_number')::int, (x ->> 'http')::int, 0) <> 200 or coalesce((x ->> 'http_reference')::int, (x ->> 'http')::int, 0) <> 200 then
      v_outcome := 'LOOKUP_FAILED';
    else
      select coalesce(jsonb_agg(y), '[]') into v_num from jsonb_array_elements(coalesce(x -> 'by_number', '[]')) y
       where y ->> 'InvoiceNumber' = o.payload ->> 'xero_invoice_number'
         and not (coalesce(y ->> 'InvoiceID', '') = any (v_superseded));
      select coalesce(jsonb_agg(y), '[]') into v_live from jsonb_array_elements(v_num) y where coalesce(y ->> 'Status', '') not in ('DELETED', 'VOIDED');
      select coalesce(jsonb_agg(y), '[]') into v_other from jsonb_array_elements(coalesce(x -> 'by_reference', '[]')) y
       where y ->> 'Reference' = o.payload ->> 'reference' and y ->> 'InvoiceNumber' is distinct from o.payload ->> 'xero_invoice_number'
         and coalesce(y ->> 'Status', '') not in ('DELETED', 'VOIDED')
         and not (coalesce(y ->> 'InvoiceID', '') = any (v_superseded));
      select external_id into v_contact from external_links
       where provider = 'XERO' and entity_type = 'customer' and entity_id = (o.payload ->> 'customer_id')::uuid and external_type = 'Contact';
      d := v_live -> 0;
      if jsonb_array_length(v_num) = 0 and jsonb_array_length(v_other) = 0 then
        v_outcome := 'PROVEN_ABSENT';
      elsif jsonb_array_length(v_num) = 1 and jsonb_array_length(v_live) = 1 and jsonb_array_length(v_other) = 0 and i.status <> 'VOIDED'
            and d ->> 'Reference' = o.payload ->> 'reference' and d ->> 'Type' = 'ACCREC' and d ->> 'Status' = 'DRAFT'
            and (d ->> 'Total')::numeric = (o.payload ->> 'amount_inc_gst')::numeric and (d ->> 'TotalTax')::numeric = (o.payload ->> 'gst_amount')::numeric
            and coalesce((d ->> 'AmountPaid')::numeric, -1) = 0
            and not coalesce((d ->> 'SentToContact')::boolean, false)   -- GET /Invoices omits it unless true (seen live); a DRAFT cannot be sent
            and d ->> 'CurrencyCode' = 'AUD' and d ->> 'LineAmountTypes' = 'Inclusive'
            and coalesce(d ->> 'InvoiceID', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            and coalesce(d -> 'Contact' ->> 'ContactID', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            and (v_contact is null or v_contact = d -> 'Contact' ->> 'ContactID')
            and not exists (select 1 from external_links where provider = 'XERO' and external_type = 'Invoice' and external_id = d ->> 'InvoiceID') then
        v_outcome := 'RECOVERED';
      else
        v_outcome := 'NEEDS_PERSON';
        v_detail := format('%s: reconciliation cannot tell which Xero invoice is RoofOps''s %s, so nothing was linked: %s with its number (%s), %s other live invoice(s) with reference %s%s. A person must check Xero (tenant %s…) and decide',
          i.invoice_number, o.payload ->> 'xero_invoice_number', jsonb_array_length(v_num),
          coalesce((select string_agg(coalesce(y ->> 'Status', '?') || ' ' || coalesce(y ->> 'Total', '?'), ', ') from jsonb_array_elements(v_num) y), 'none'),
          jsonb_array_length(v_other), o.payload ->> 'reference',
          case when jsonb_array_length(v_num) = 1 and jsonb_array_length(v_live) = 1 and jsonb_array_length(v_other) = 0 then ' (it differs from the approved draft)' else '' end,
          left(v_pin, 8));
      end if;
      v_dead := o.status = 'FAILED' and o.next_attempt_at = 'infinity';
      if v_repair and v_outcome = 'RECOVERED' then
        insert into external_links (provider, entity_type, entity_id, external_type, external_id, external_url, last_synced_at, verified_at)
        values ('XERO', 'invoice', o.aggregate_id, 'Invoice', d ->> 'InvoiceID', 'https://go.xero.com/AccountsReceivable/View.aspx?InvoiceID=' || (d ->> 'InvoiceID'), now(), now()),
               ('XERO', 'customer', (o.payload ->> 'customer_id')::uuid, 'Contact', d -> 'Contact' ->> 'ContactID',
                'https://go.xero.com/Contacts/View/' || (d -> 'Contact' ->> 'ContactID'), now(), now())
        on conflict (provider, entity_type, entity_id, external_type) do update set verified_at = now(), last_synced_at = now();
        update invoices set sync_status = 'SYNCED' where id = i.id;
        update outbox set status = 'DONE', dispatched_at = now(), locked_until = null,
               result = jsonb_build_object('recovered_by', p_run_key, 'tenant_id', x ->> 'tenant_id', 'invoice_id', d ->> 'InvoiceID', 'invoice_number', d ->> 'InvoiceNumber',
                 'reference', d ->> 'Reference', 'status', d ->> 'Status', 'total', d -> 'Total', 'total_tax', d -> 'TotalTax', 'contact_id', d -> 'Contact' ->> 'ContactID')
         where id = o.id;
        update approvals set status = 'EXECUTED', executed_at = now(), execution_result = jsonb_build_object('recovered_by', p_run_key, 'invoice_id', d ->> 'InvoiceID')
         where id = i.approval_id and status = 'EXECUTING';
        insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, external_reference, reason, correlation_id)
        values ('SYSTEM', 'workflow:reconciliation', 'xero.invoice.draft_recovered', 'invoice', i.id, i.invoice_number, jsonb_build_object('sync_status', 'UNKNOWN'),
                jsonb_build_object('sync_status', 'SYNCED', 'invoice_id', d ->> 'InvoiceID'), d ->> 'InvoiceID',
                format('Reconciliation %s found exactly one matching draft %s in the pinned Xero tenant and linked it', p_run_key, d ->> 'InvoiceNumber'), o.correlation_id);
        v_applied := true; v_rec := v_rec + 1;
      elsif v_repair and v_outcome = 'PROVEN_ABSENT' then
        if v_dead then
          update invoices set sync_status = 'FAILED' where id = i.id;
          update approvals set status = 'EXECUTION_FAILED', executed_at = now(),
                 execution_result = jsonb_build_object('proven_absent_by', p_run_key, 'message', 'no Xero draft exists; failed safely')
           where id = i.approval_id and status = 'EXECUTING';
          perform wf_open_sync_exception('project_to_invoice', 'invoice', i.id, i.invoice_number, 'INVALID_STATE',
            format('%s: failed safely. Reconciliation proved %s does not exist in Xero. It can be re-queued (ops/requeue-dead-lettered-side-effect.sql) or a person decides',
                   i.invoice_number, o.payload ->> 'xero_invoice_number'));
        else
          update invoices set sync_status = 'PENDING' where id = i.id;   -- the scheduled retry may go ahead (05 searches again first)
        end if;
        v_applied := true; v_abs := v_abs + 1;
      elsif v_repair and v_outcome = 'NEEDS_PERSON' then
        perform wf_open_sync_exception('reconciliation', 'invoice', i.id, i.invoice_number, 'RECONCILIATION_MISMATCH', v_detail);
        v_applied := true; v_person := v_person + 1;
      elsif v_outcome = 'NEEDS_PERSON' then
        v_person := v_person + 1;
      end if;
      if v_applied and v_outcome in ('RECOVERED', 'PROVEN_ABSENT') then
        -- The "may already exist" exception is answered either way.
        for e in select id, exception_number from workflow_exceptions
                  where (entity_id = i.id or business_reference = i.invoice_number) and error_class = 'AMBIGUOUS_WRITE' and resolution_status in ('OPEN', 'RETRY_QUEUED') for update loop
          update workflow_exceptions set resolution_status = 'RESOLVED', resolved_at = now(), resolved_by_system = 'workflow:reconciliation',
                 resolution_note = format('Reconciliation %s %s', p_run_key, case v_outcome when 'RECOVERED' then 'found and linked the draft' else 'proved the draft does not exist' end)
           where id = e.id;
          insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, reason)
          values ('SYSTEM', 'workflow:reconciliation', 'exception.resolved', 'workflow_exception', e.id, e.exception_number,
                  '{"resolution_status":"OPEN"}', '{"resolution_status":"RESOLVED"}',
                  format('Reconciliation %s settled uncertain Xero write %s: %s', p_run_key, i.invoice_number, lower(v_outcome)));
        end loop;
      end if;
      if not v_repair then
        v_outcome := case v_outcome when 'RECOVERED' then 'WOULD_RECOVER' when 'PROVEN_ABSENT' then 'WOULD_PROVE_ABSENT' else v_outcome end;
      end if;
      insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, classification, action, detail)
      values (v_run.id, 'XERO', 'invoice', i.invoice_number, d ->> 'InvoiceID',
              case when v_outcome in ('NEEDS_PERSON') then 'REQUIRES_HUMAN' else 'SAFE_AUTO_REPAIR' end,
              case when not v_repair then 'NONE_OBSERVE_ONLY' when v_outcome = 'NEEDS_PERSON' then 'EXCEPTION_OPENED' else 'APPLIED_TO_POSTGRES' end,
              coalesce(v_detail, format('Uncertain Xero write %s: %s', i.invoice_number, lower(v_outcome))));
    end if;
    if v_outcome in ('SKIPPED', 'UNKNOWN_KEY') then v_skip := v_skip + 1; end if;
    v_items := v_items || jsonb_build_object('invoice_number', coalesce(i.invoice_number, x ->> 'invoice_number'), 'outcome', v_outcome, 'applied', v_applied);
  end loop;
  update reconciliation_runs set summary = summary || jsonb_build_object('xero_uncertain', jsonb_build_object('checked', jsonb_array_length(coalesce(p_results, '[]'::jsonb)),
         'recovered', v_rec, 'proven_absent', v_abs, 'needs_person', v_person, 'skipped', v_skip)) where id = v_run.id;
  return jsonb_build_object('ok', true, 'checked', jsonb_array_length(coalesce(p_results, '[]'::jsonb)), 'recovered', v_rec, 'proven_absent', v_abs,
    'needs_person', v_person, 'skipped', v_skip, 'items', v_items);
end $_$;

--
-- Name: wf_record_health(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_record_health(p_checks jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare n int; v_tenant text := (select value from app_settings where key = 'xero.demo_tenant_id');
begin
  insert into integration_health (service, ok, latency_ms, detail)
  select x ->> 'service',
         coalesce((x ->> 'ok')::boolean, false)
           and (x ->> 'service' <> 'xero' or (coalesce(v_tenant, '') <> '' and coalesce(x -> 'detail' -> 'tenant_ids', '[]'::jsonb) ? v_tenant)),
         nullif(x ->> 'latency_ms', '')::int,
         case when x ->> 'service' = 'xero'
              then (coalesce(x -> 'detail', '{}'::jsonb) - 'tenant_ids')
                   || jsonb_build_object('pinned_demo_tenant_connected', coalesce(x -> 'detail' -> 'tenant_ids', '[]'::jsonb) ? coalesce(v_tenant, ''))
              else coalesce(x -> 'detail', '{}'::jsonb) end
    from jsonb_array_elements(p_checks) x
   where x ->> 'service' in ('airtable','airtable_webhooks','n8n','google_drive','xero','deepseek');
  get diagnostics n = row_count;
  insert into integration_health (service, ok, latency_ms, detail) values ('postgres', true, 0, '{"check":"wf_record_health write"}');
  delete from integration_health where checked_at < now() - interval '14 days';
  return jsonb_build_object('recorded', n + 1);
end $$;

--
-- Name: wf_reissue_dispatch(text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_reissue_dispatch(p_token text, p_invoice_number text, p_generation integer, p_worker text DEFAULT 'n8n'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_hash text := (select value from app_settings where key = 'reissue.dispatch_token_sha256');
  v_sel jsonb := jsonb_build_object('invoice_number', p_invoice_number, 'generation', p_generation);
  i invoices; g invoice_xero_draft_generations; o outbox; v_problem text;
  refuse constant text := '{"ok": false, "writes": []}';
begin
  if coalesce(v_hash, '') = '' or encode(sha256(convert_to(coalesce(p_token, ''), 'UTF8')), 'hex') <> v_hash then
    return refuse::jsonb || jsonb_build_object('code', 'TOKEN_REFUSED', 'detail', 'a reissue dispatch needs the operator token');
  end if;
  if coalesce(p_invoice_number, '') = '' or p_generation is null then
    return refuse::jsonb || jsonb_build_object('code', 'SELECTION_REQUIRED', 'selection', v_sel,
      'detail', 'a reissue dispatch names exactly one invoice number and generation');
  end if;
  if p_generation < 2 then
    return refuse::jsonb || jsonb_build_object('code', 'NOT_A_REISSUE', 'selection', v_sel, 'detail', 'generation 1 is dispatched by 04, never here');
  end if;
  select * into i from invoices where invoice_number = p_invoice_number;
  if i.id is null then
    return refuse::jsonb || jsonb_build_object('code', 'NOT_FOUND', 'selection', v_sel, 'detail', 'no invoice has that number');
  end if;
  select * into g from invoice_xero_draft_generations where invoice_id = i.id and superseded_at is null;
  if g.generation is distinct from p_generation then
    return refuse::jsonb || jsonb_build_object('code', 'NOT_CURRENT_GENERATION', 'selection', v_sel,
      'detail', format('the current generation of %s is %s', p_invoice_number, coalesce(g.generation::text, 'none')));
  end if;
  select * into o from outbox where idempotency_key = xero_draft_outbox_key(i.id, p_generation) and topic = 'xero.create_draft_invoice';
  if o.id is null then
    return refuse::jsonb || jsonb_build_object('code', 'NO_WRITE', 'selection', v_sel, 'detail', 'no draft write is queued for that generation');
  end if;
  if not (o.status = 'PENDING' or (o.status = 'FAILED' and o.next_attempt_at <> 'infinity')) or o.next_attempt_at > now() then
    return refuse::jsonb || jsonb_build_object('code', 'NOT_DUE', 'selection', v_sel,
      'detail', format('the write is %s%s', o.status, case when o.next_attempt_at = 'infinity' then ' (dead letter)' when o.next_attempt_at > now() then ' (not yet due)' else '' end));
  end if;
  v_problem := xero_reissue_proof(o);
  if v_problem is not null then
    return refuse::jsonb || jsonb_build_object('code', 'REISSUE_NOT_PROVEN', 'selection', v_sel, 'problem', v_problem, 'detail', v_problem);
  end if;
  return jsonb_build_object('ok', true, 'worker', p_worker, 'selection', v_sel,
    'writes', jsonb_build_array(jsonb_build_object('xero_key', o.idempotency_key, 'invoice_number', i.invoice_number, 'generation', o.generation)));
end $$;

--
-- Name: wf_webhook_check(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_webhook_check(p_hooks jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_expected text[] := string_to_array((select value from app_settings where key = 'airtable.expected_webhooks'), ',');
  u text; w jsonb; v_status jsonb := '[]'; v_drain jsonb := '[]'; v_refresh jsonb := '[]'; v_missing jsonb := '[]'; v_ok boolean := true;
  v_cursor bigint; v_next bigint; v_hours numeric;
begin
  foreach u in array v_expected loop
    select x into w from jsonb_array_elements(coalesce(p_hooks, '[]'::jsonb)) x where x ->> 'notificationUrl' = u limit 1;
    if w is null then
      v_missing := v_missing || to_jsonb(u); v_ok := false;
      v_status := v_status || jsonb_build_object('url', u, 'state', 'MISSING');
      continue;
    end if;
    v_cursor := wf_airtable_cursor(w ->> 'id');
    v_next := coalesce((w ->> 'cursorForNextPayload')::bigint, v_cursor);
    v_hours := extract(epoch from ((w ->> 'expirationTime')::timestamptz - now())) / 3600;
    if v_next > v_cursor then v_drain := v_drain || jsonb_build_object('id', w ->> 'id', 'url', u, 'unread', v_next - v_cursor); end if;
    if v_hours is null or v_hours < 72 then v_refresh := v_refresh || to_jsonb(w ->> 'id'); end if;
    if not coalesce((w ->> 'isHookEnabled')::boolean, false) or coalesce(v_hours, -1) <= 0
       or coalesce((w -> 'lastNotificationResult' ->> 'success')::boolean, true) = false then v_ok := false; end if;
    v_status := v_status || jsonb_build_object('url', u, 'id', w ->> 'id', 'enabled', (w ->> 'isHookEnabled')::boolean,
      'expires', w ->> 'expirationTime', 'hours_left', round(coalesce(v_hours, 0)), 'unread_payloads', greatest(v_next - v_cursor, 0),
      'last_notification_ok', (w -> 'lastNotificationResult' ->> 'success')::boolean,
      'last_notification_at', w -> 'lastNotificationResult' ->> 'completionTimestamp',
      'state', case when not coalesce((w ->> 'isHookEnabled')::boolean, false) then 'DISABLED' when coalesce(v_hours, -1) <= 0 then 'EXPIRED'
                    when v_next > v_cursor then 'BEHIND' else 'OK' end);
  end loop;
  insert into integration_health (service, ok, detail) values ('airtable_webhooks', v_ok, jsonb_build_object('hooks', v_status));
  return jsonb_build_object('ok', v_ok, 'hooks', v_status, 'drain', v_drain, 'refresh', v_refresh, 'missing', v_missing);
end $$;

--
-- Name: wf_xero_dispatch_next(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wf_xero_dispatch_next(p_worker text DEFAULT 'n8n'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r xero_dispatch_requests; i invoices; o outbox; v_problem jsonb; v_refused jsonb := '[]'::jsonb;
begin
  perform xero_dispatch_settle_claims();
  for n in 1..5 loop
    select * into r from xero_dispatch_requests where status = 'QUEUED' order by requested_at for update skip locked limit 1;
    if r.id is null then exit; end if;
    select * into i from invoices where id = r.invoice_id;
    v_problem := xero_dispatch_problem(i.invoice_number, r.generation, r.payload_sha256);
    if v_problem is null and not exists (select 1 from employees e where e.id = r.requested_by and e.is_active) then
      v_problem := jsonb_build_object('code', 'REQUESTER_INACTIVE', 'detail', 'the person who asked is no longer an active employee; ask again');
    end if;
    if v_problem is not null then
      update xero_dispatch_requests set status = 'REFUSED', closed_reason = v_problem ->> 'detail' where id = r.id;
      insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
      values ('SYSTEM', p_worker, 'xero.dispatch_refused', 'invoice', i.id, i.invoice_number,
              jsonb_build_object('generation', r.generation, 'code', v_problem ->> 'code'), v_problem ->> 'detail');
      v_refused := v_refused || jsonb_build_array(jsonb_build_object('invoice_number', i.invoice_number, 'code', v_problem ->> 'code'));
      r := null;
      continue;
    end if;
    select * into o from outbox where idempotency_key = r.xero_key;
    update xero_dispatch_requests set status = 'CLAIMED', claimed_by = p_worker, claimed_at = now(), attempts_at_claim = o.attempts where id = r.id;
    insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, after_state, reason)
    values ('SYSTEM', p_worker, 'xero.dispatch_started', 'invoice', i.id, i.invoice_number,
            jsonb_build_object('generation', r.generation, 'xero_key', r.xero_key), 'Staff request handed to 05');
    return jsonb_build_object('ok', true, 'refused', v_refused,
      'writes', jsonb_build_array(jsonb_build_object('xero_key', r.xero_key, 'invoice_number', i.invoice_number, 'generation', r.generation, 'request_id', r.id)));
  end loop;
  return jsonb_build_object('ok', true, 'refused', v_refused, 'writes', '[]'::jsonb);
end $$;

--
-- Name: xero_dispatch_problem(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_dispatch_problem(p_invoice_number text, p_generation integer, p_payload_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare i invoices; g invoice_xero_draft_generations; o outbox; v_ap approvals; v_p text;
begin
  select * into i from invoices where invoice_number = p_invoice_number;
  if i.id is null then return jsonb_build_object('code', 'NOT_FOUND', 'detail', format('no invoice %s', p_invoice_number)); end if;
  if i.status = 'VOIDED' then
    return jsonb_build_object('code', 'VOIDED', 'detail', format('%s is voided; a replacement goes through Invoice reissues', i.invoice_number));
  end if;
  select * into g from invoice_xero_draft_generations where invoice_id = i.id and superseded_at is null;
  if g.generation is distinct from p_generation then
    return jsonb_build_object('code', 'NOT_CURRENT_GENERATION', 'detail', format('the current Xero draft of %s is generation %s', i.invoice_number, coalesce(g.generation::text, 'none')));
  end if;
  select * into o from outbox where idempotency_key = xero_draft_outbox_key(i.id, p_generation) and topic = 'xero.create_draft_invoice';
  if o.id is null then return jsonb_build_object('code', 'NO_WRITE', 'detail', 'no Xero draft is queued for it'); end if;
  if o.status = 'DONE' then return jsonb_build_object('code', 'ALREADY_CREATED', 'detail', 'its Xero draft already exists'); end if;
  if i.sync_status = 'UNKNOWN' then
    return jsonb_build_object('code', 'UNCERTAIN', 'detail', 'Xero may already have created it; the next reconciliation checks Xero and records the answer. Do not send it again');
  end if;
  if o.status = 'DISPATCHING' and o.locked_until < now() then
    return jsonb_build_object('code', 'STUCK', 'detail', 'its creation started and never reported back, so Xero may have it; reconciliation checks Xero. Do not send it again');
  end if;
  if o.status = 'DISPATCHING' then return jsonb_build_object('code', 'IN_PROGRESS', 'detail', 'it is being created in Xero right now'); end if;
  if o.status = 'FAILED' and o.next_attempt_at = 'infinity' then
    return jsonb_build_object('code', 'STOPPED', 'detail', 'it stopped after repeated failures; see the open issue on Automation');
  end if;
  if o.next_attempt_at > now() then
    return jsonb_build_object('code', 'NOT_DUE', 'detail', format('it can be retried after %s', to_char(o.next_attempt_at at time zone 'Australia/Brisbane', 'DD Mon HH24:MI')));
  end if;
  if o.generation >= 2 then
    v_p := xero_reissue_proof(o);
    if v_p is not null then return jsonb_build_object('code', 'NOT_PROVEN', 'detail', v_p); end if;
    select a.* into v_ap from approvals a where a.id = g.approval_id;
  else
    select a.* into v_ap from approvals a where a.id = i.approval_id;
  end if;
  if v_ap.id is null or v_ap.status not in ('EXECUTING', 'EXECUTED') or v_ap.decided_by is null then
    return jsonb_build_object('code', 'NOT_APPROVED', 'detail', 'no approved decision is behind this draft');
  end if;
  if p_payload_sha256 is not null and p_payload_sha256 is distinct from xero_payload_sha256(o.payload) then
    return jsonb_build_object('code', 'PAYLOAD_CHANGED', 'detail', 'the draft changed since you looked at it; reload and check it again');
  end if;
  return null;
end $$;

--
-- Name: xero_dispatch_settle_claims(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_dispatch_settle_claims() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  update xero_dispatch_requests r set status = 'HANDED_OVER', closed_reason = 'taken by 05'
    from outbox o where r.status = 'CLAIMED' and o.idempotency_key = r.xero_key and (o.status = 'DONE' or o.attempts > coalesce(r.attempts_at_claim, 0));
  update xero_dispatch_requests r set status = 'EXPIRED', closed_reason = 'not taken by 05 in time; request it again'
   where r.status = 'CLAIMED' and r.claimed_at < now() - make_interval(mins => coalesce((select value::int from app_settings where key = 'xero.dispatch_claim_stale_minutes'), 15));
$$;

--
-- Name: xero_draft_generation_mirror(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_draft_generation_mirror() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_status text; v_xero_id text;
begin
  v_status := xero_draft_ledger_status(new.status, (select i.sync_status from invoices i where i.id = new.aggregate_id));
  if new.status = 'DONE' then
    v_xero_id := coalesce((select l.external_id from external_links l where l.provider = 'XERO' and l.external_type = 'Invoice'
                             and l.entity_id = new.aggregate_id and l.verified_at is not null), new.result ->> 'invoice_id');
  end if;
  update invoice_xero_draft_generations g
     set status = v_status, xero_invoice_id = coalesce(g.xero_invoice_id, v_xero_id),
         xero_invoice_number = coalesce(new.payload ->> 'xero_invoice_number', g.xero_invoice_number),
         tenant_id = coalesce(new.payload ->> 'xero_tenant_id', g.tenant_id), updated_at = now()
   where g.invoice_id = new.aggregate_id and g.generation = new.generation and g.status <> 'SUPERSEDED';
  return new;
end $$;

--
-- Name: xero_draft_generation_open(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_draft_generation_open() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare i invoices;
begin
  select * into i from invoices where id = new.aggregate_id;
  insert into invoice_xero_draft_generations (invoice_id, generation, status, outbox_idempotency_key, xero_invoice_number,
                                              tenant_id, approval_id, opened_by)
  values (new.aggregate_id, new.generation, xero_draft_ledger_status(new.status, i.sync_status), new.idempotency_key,
          new.payload ->> 'xero_invoice_number', new.payload ->> 'xero_tenant_id', i.approval_id,
          case when new.generation = 1 then 'workflow' else coalesce(new.payload ->> 'opened_by', 'operator') end)
  on conflict do nothing;
  return new;
end $$;

--
-- Name: xero_draft_generation_sync_mirror(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_draft_generation_sync_mirror() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare o outbox; v_status text;
begin
  select * into o from outbox_current('xero.create_draft_invoice', new.id);
  if o.id is null then return new; end if;
  v_status := xero_draft_ledger_status(o.status, new.sync_status);
  update invoice_xero_draft_generations g
     set status = v_status, updated_at = now()
   where g.invoice_id = new.id and g.generation = o.generation and g.status <> 'SUPERSEDED'
     and g.status is distinct from v_status;
  return new;
end $$;

--
-- Name: xero_draft_ledger_status(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_draft_ledger_status(p_outbox_status text, p_sync_status text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_sync_status = 'UNKNOWN' then 'UNKNOWN'
    when p_outbox_status = 'DONE' then 'CREATED'
    when p_outbox_status in ('PENDING', 'DISPATCHING') then p_outbox_status
    else 'FAILED' end
$$;

--
-- Name: xero_draft_outbox_key(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_draft_outbox_key(p_invoice uuid, p_generation integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when p_generation = 1 then 'xero:invoice:' || p_invoice::text
              else 'xero:invoice:' || p_invoice::text || ':g' || p_generation::text end
$$;

--
-- Name: xero_draft_payload(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_draft_payload(p_invoice uuid, p_tenant text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'invoice_id', i.id, 'invoice_number', i.invoice_number,
    'project_id', p.id, 'project_number', p.project_number, 'reference', p.project_number,
    'project_airtable_record_id', (select l.external_id from external_links l where l.provider = 'AIRTABLE' and l.entity_type = 'project'
                                     and l.entity_id = p.id and l.verified_at is not null),
    'customer_id', c.id, 'customer_number', c.customer_number, 'customer_name', btrim(c.display_name), 'customer_email', c.email,
    'xero_contact_number', (select value from app_settings where key = 'xero.contact_number_prefix') || c.customer_number,
    'xero_contact_name', btrim(c.display_name) || ' [' || c.customer_number || ']',
    'xero_invoice_number_prefix', (select value from app_settings where key = 'xero.invoice_number_prefix'),
    'xero_invoice_number', (select value from app_settings where key = 'xero.invoice_number_prefix') || i.invoice_number,
    'invoice_date', i.issue_date, 'due_date', i.due_date,
    'currency', 'AUD', 'line_amount_type', i.line_amount_type,
    'amount_inc_gst', i.total_inc_gst, 'gst_amount', i.gst_amount, 'amount_ex_gst', i.subtotal_ex_gst,
    'lines', gst_line_tax(coalesce((select jsonb_agg(jsonb_build_object('line_no', l.line_no, 'description', l.description, 'quantity', trim_scale(l.quantity),
                                                           'unit_amount', l.unit_price, 'variation_id', l.variation_id) order by l.line_no)
                         from invoice_lines l where l.invoice_id = i.id), '[]'::jsonb), i.gst_amount, i.gst_rate),
    'xero_account_code', coalesce((select min(l.account_code) from invoice_lines l where l.invoice_id = i.id),
                                  (select value from app_settings where key = 'xero.sales_account_code')),
    'xero_tax_type', (select value from app_settings where key = 'xero.sales_tax_type'),
    'xero_tenant_id', p_tenant, 'xero_tenant_name', (select value from app_settings where key = 'xero.demo_tenant_name'))
  from invoices i join projects p on p.id = i.project_id join customers c on c.id = i.customer_id
  where i.id = p_invoice
$$;

--
-- Name: xero_draft_progress(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_draft_progress(p_invoice uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare i invoices; o outbox; r xero_dispatch_requests; v_state text; v_req text; p projects; c customers;
begin
  select * into i from invoices where id = p_invoice;
  select * into o from outbox_current('xero.create_draft_invoice', p_invoice);
  if o.id is null then return null; end if;
  select * into p from projects where id = i.project_id;
  select * into c from customers where id = i.customer_id;
  select * into r from xero_dispatch_requests where xero_key = o.idempotency_key order by requested_at desc limit 1;
  v_state := case
    when i.status = 'VOIDED' then 'VOIDED'      -- its Xero document was voided or deleted (verified): never "in Xero"; see reissues
    when o.status = 'DONE' then 'CREATED'
    when i.sync_status = 'UNKNOWN' then 'UNCERTAIN'
    when o.status = 'DISPATCHING' and o.locked_until < now() then 'STUCK'   -- 05 never reported back: not "being created now"
    when o.status = 'DISPATCHING' then 'SENDING'
    when o.status = 'FAILED' and o.next_attempt_at = 'infinity' then 'STOPPED'
    when r.status = 'QUEUED' then 'QUEUED'
    when r.status = 'CLAIMED' and o.attempts <= coalesce(r.attempts_at_claim, 0) then 'STARTING'   -- not yet taken by 05
    when o.status = 'FAILED' and o.next_attempt_at > now() then 'RETRY_LATER'
    when o.status = 'FAILED' then 'FAILED'
    else 'READY_TO_SEND' end;
  select e.full_name into v_req from employees e where e.id = r.requested_by;
  return jsonb_build_object('invoice_number', i.invoice_number, 'project_number', p.project_number, 'customer', c.display_name,
    'amount_inc_gst', o.payload ->> 'amount_inc_gst', 'xero_invoice_number', o.payload ->> 'xero_invoice_number', 'generation', o.generation,
    'state', v_state, 'attempts', o.attempts, 'next_attempt_at', nullif(o.next_attempt_at, 'infinity'),
    'last_error', left(regexp_replace(coalesce(o.last_error, ''), '\s+', ' ', 'g'), 240), 'payload_sha256', xero_payload_sha256(o.payload),
    'xero_invoice_id', (select g.xero_invoice_id from invoice_xero_draft_generations g where g.invoice_id = i.id and g.superseded_at is null),
    'request', case when r.id is null then null else jsonb_build_object('status', r.status, 'requested_by', v_req, 'requested_at', r.requested_at,
      'reason', r.reason, 'closed_reason', r.closed_reason) end,
    'problem', xero_dispatch_problem(i.invoice_number, o.generation, null));
end $$;

--
-- Name: xero_draft_provider_key(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_draft_provider_key(p_invoice uuid, p_generation integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when p_generation = 1 then 'roofops-' || p_invoice::text
              else 'roofops-' || p_invoice::text || '-g' || p_generation::text end
$$;

--
-- Name: xero_draft_superseded_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_draft_superseded_ids(p_invoice uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(g.xero_invoice_id order by g.xero_invoice_id), '{}'::text[])
    from invoice_xero_draft_generations g
   where g.invoice_id = p_invoice and g.superseded_at is not null and g.xero_invoice_id is not null
$$;

--
-- Name: xero_failure_evidence(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_failure_evidence(p_class text, p_message text, p_http_status integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when lower(btrim(split_part(coalesce(p_message, ''), ':', 1))) in ('list connections', 'check tenant', 'read organisation', 'check organisation',
                                                                     'find contact', 'create contact', 'search by invoice number', 'search by reference') then 'NONE'
    when lower(btrim(split_part(coalesce(p_message, ''), ':', 1))) = 'create draft invoice' then
      -- Absent only on Xero's explicit refusal of the create request itself; nothing else proves it was not created.
      case when p_http_status between 400 and 499 and p_class not in ('TIMEOUT', 'NETWORK', 'UPSTREAM_5XX', 'SERVICE_UNAVAILABLE', 'UNKNOWN', 'AMBIGUOUS_WRITE')
           then 'ABSENT' else 'MAY_EXIST' end
    else 'MAY_EXIST'   -- reconcile, read back invoice, recount invoices, verify read-back, record xero draft, or unrecognised
  end
$$;

--
-- Name: xero_payload_sha256(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_payload_sha256(p jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$ select encode(sha256(convert_to(p::text, 'UTF8')), 'hex') $$;

--
-- Name: xero_pin_change_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_pin_change_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_old text; v_new text; v_open text;
begin
  if coalesce(new.key, old.key) <> 'xero.demo_tenant_id' then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  v_old := case when tg_op = 'INSERT' then null else old.value end;
  v_new := case when tg_op = 'DELETE' then null else new.value end;
  if coalesce(v_old, '') <> coalesce(v_new, '') then
    -- Waits for claims in progress; claims wait for this change until it commits.
    perform pg_advisory_xact_lock(hashtextextended('roofops:xero.demo_tenant_id', 0));
    if coalesce(v_old, '') <> '' then
      select string_agg(i.invoice_number || ' (' || case when i.sync_status = 'UNKNOWN' then 'ambiguous: it may already exist in Xero'
                                                          when o.status = 'DISPATCHING' then 'being written'
                                                          when o.status = 'PENDING' then 'queued'
                                                          else 'retry scheduled' end || ')', ', ' order by i.invoice_number)
        into v_open
        from outbox o join invoices i on i.id = o.aggregate_id
       where o.topic = 'xero.create_draft_invoice' and o.payload ->> 'xero_tenant_id' = v_old
         and ((o.status <> 'DONE' and not (o.status = 'FAILED' and o.next_attempt_at = 'infinity')) or i.sync_status = 'UNKNOWN');
      if v_open is not null then
        raise exception 'The pinned Xero tenant %… cannot be changed or cleared while a Xero write for it is not finished: %. Let it finish or fail for good first (reconcile an ambiguous one)',
          left(v_old, 8), v_open using errcode = 'check_violation';
      end if;
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;

--
-- Name: xero_record_settlement(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_record_settlement(p_run_key text, p_results jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_run reconciliation_runs; x jsonb; d jsonb; i invoices; v_link text; v_bound text; v_pin text := (select nullif(value, '') from app_settings where key = 'xero.demo_tenant_id');
  v_verdict text; v_settle text; v_target text; v_path text[]; v_step text; v_detail text; v_obs uuid; v_repair boolean; v_rank jsonb := '{"APPROVED":0,"ISSUED":1,"PARTIALLY_PAID":2,"PAID":3}';
  v_counts jsonb := '{}'::jsonb; v_applied int := 0; v_regressed int := 0; v_from text; v_observed xero_invoice_observations;
begin
  select * into v_run from reconciliation_runs where run_key = p_run_key and status = 'RUNNING';
  if v_run.id is null then return jsonb_build_object('ok', false); end if;
  v_repair := v_run.mode = 'repair';
  for x in select * from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) loop
    select inv.* into i from invoices inv join external_links l on l.entity_id = inv.id and l.provider = 'XERO' and l.external_type = 'Invoice'
     where l.external_id = x ->> 'invoice_id' for update of inv;
    continue when i.id is null;
    v_link := x ->> 'invoice_id';
    v_bound := (select payload ->> 'xero_tenant_id' from outbox_current('xero.create_draft_invoice', i.id));
    d := coalesce(x -> 'xero', '{}'::jsonb);
    v_settle := null; v_detail := null;
    if x ->> 'tenant_id' is null or v_bound is null or x ->> 'tenant_id' <> v_bound or v_bound is distinct from v_pin then
      v_verdict := 'WRONG_TENANT';
      v_detail := format('%s was read in Xero tenant %s, but its write is bound to %s and the pinned tenant is %s; that read is not trusted',
        i.invoice_number, coalesce(left(x ->> 'tenant_id', 8) || '…', 'none'), coalesce(left(v_bound, 8) || '…', 'none'), coalesce(left(v_pin, 8) || '…', 'none'));
    elsif coalesce((x ->> 'http')::int, 0) <> 200 then
      v_verdict := 'LOOKUP_FAILED';
      v_detail := format('%s could not be read from Xero (%s); nothing is assumed', i.invoice_number, coalesce('HTTP ' || (x ->> 'http'), x ->> 'error', 'no answer'));
    elsif d ->> 'InvoiceID' is distinct from v_link or d ->> 'Type' is distinct from 'ACCREC'
          or d ->> 'InvoiceNumber' is distinct from x ->> 'xero_invoice_number' or (d ->> 'Total')::numeric is distinct from i.total_inc_gst then
      v_verdict := 'MISMATCH';
      v_detail := format('%s: Xero returned %s %s %s total %s, not the linked invoice %s %s total %s', i.invoice_number,
        coalesce(d ->> 'Type', '?'), coalesce(d ->> 'InvoiceNumber', '?'), coalesce(d ->> 'InvoiceID', '?'), coalesce(d ->> 'Total', '?'),
        x ->> 'xero_invoice_number', v_link, i.total_inc_gst);
    else
      v_settle := xero_settlement(d ->> 'Status', (d ->> 'Total')::numeric, (d ->> 'AmountDue')::numeric, (d ->> 'AmountPaid')::numeric, (d ->> 'AmountCredited')::numeric);
      v_verdict := case when v_settle is null then 'INCONSISTENT' else 'VERIFIED' end;
      if v_settle is null then
        v_detail := format('%s: Xero says %s with total %s, paid %s, credited %s, due %s; that does not add up, so nothing is assumed', i.invoice_number,
          d ->> 'Status', d ->> 'Total', d ->> 'AmountPaid', coalesce(d ->> 'AmountCredited', '0'), d ->> 'AmountDue');
      end if;
    end if;
    insert into xero_invoice_observations (invoice_id, run_id, tenant_id, bound_tenant_id, xero_invoice_id, http_status, verdict, xero_status, total,
      amount_due, amount_paid, amount_credited, fully_paid_on, xero_updated, payments, settlement, detail)
    values (i.id, v_run.id, x ->> 'tenant_id', v_bound, v_link, (x ->> 'http')::int, v_verdict, d ->> 'Status', (d ->> 'Total')::numeric,
      (d ->> 'AmountDue')::numeric, (d ->> 'AmountPaid')::numeric, coalesce((d ->> 'AmountCredited')::numeric, case when v_verdict = 'VERIFIED' then 0 end),
      case when d ->> 'FullyPaidOnDate' ~ '^\d{4}-\d{2}-\d{2}' then left(d ->> 'FullyPaidOnDate', 10)::date end, d ->> 'UpdatedDateUTC',
      (select jsonb_agg(jsonb_build_object('payment_id', y ->> 'PaymentID', 'amount', y -> 'Amount', 'date', y ->> 'Date', 'status', y ->> 'Status'))
         from jsonb_array_elements(coalesce(d -> 'Payments', '[]'::jsonb)) y), v_settle, v_detail)
    on conflict (invoice_id, run_id) do nothing
    returning id into v_obs;
    continue when v_obs is null;                         -- this run already recorded this invoice
    v_counts := jsonb_set(v_counts, array[lower(v_verdict)], to_jsonb(coalesce((v_counts ->> lower(v_verdict))::int, 0) + 1));
    if v_verdict = 'WRONG_TENANT' then
      insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, classification, action, detail)
      values (v_run.id, 'XERO', 'invoice', i.invoice_number, v_link, 'UNAUTHORIZED_STATE', case when v_repair then 'EXCEPTION_OPENED' else 'NONE_OBSERVE_ONLY' end, v_detail);
      if v_repair then perform wf_open_sync_exception('reconciliation', 'invoice', i.id, i.invoice_number, 'PERMISSION_DENIED', v_detail); end if;
    elsif v_verdict in ('MISMATCH', 'INCONSISTENT') then
      insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, classification, action, detail)
      values (v_run.id, 'XERO', 'invoice', i.invoice_number, v_link, 'REQUIRES_HUMAN', case when v_repair then 'EXCEPTION_OPENED' else 'NONE_OBSERVE_ONLY' end, v_detail);
      if v_repair then perform wf_open_sync_exception('reconciliation', 'invoice', i.id, i.invoice_number, 'RECONCILIATION_MISMATCH', v_detail); end if;
    end if;
    -- Apply: verified, a settled write (AC-04: never UNKNOWN/PENDING), and a state RoofOps can follow.
    continue when v_verdict <> 'VERIFIED' or i.sync_status <> 'SYNCED';
    -- AC-14C: a deletion is a void only when no money ever moved on the invoice, here or in Xero. Otherwise a person
    -- decides: RoofOps must not write the invoice off while a payment or a credit exists somewhere.
    if v_settle = 'DELETED' then
      select * into v_observed from xero_invoice_observations where id = v_obs;
      if v_observed.amount_paid is null or v_observed.amount_paid <> 0 or coalesce(v_observed.amount_credited, 0) <> 0
         or exists (select 1 from payments where invoice_id = i.id) then
        v_detail := format('%s was deleted in Xero, but money moved on it (Xero paid %s, credited %s; %s local payment row(s)); it is not voided without a person: check the customer account first',
          i.invoice_number, coalesce(v_observed.amount_paid::text, 'unknown'), coalesce(v_observed.amount_credited::text, '0'),
          (select count(*) from payments where invoice_id = i.id));
        insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, classification, action, detail)
        values (v_run.id, 'XERO', 'invoice', i.invoice_number, v_link, 'REQUIRES_HUMAN', case when v_repair then 'EXCEPTION_OPENED' else 'NONE_OBSERVE_ONLY' end, v_detail);
        if v_repair then perform wf_open_sync_exception('reconciliation', 'invoice', i.id, i.invoice_number, 'RECONCILIATION_MISMATCH', v_detail); end if;
        continue;
      end if;
    end if;
    v_target := xero_settlement_status(v_settle);
    continue when v_target is null or v_target = i.status;
    v_path := case
      when v_target = 'VOIDED' and i.status in ('APPROVED', 'ISSUED') then array['VOIDED']
      when i.status = 'VOIDED' or v_target = 'VOIDED' then null
      when state_transition_allowed('invoice', i.status, v_target) then array[v_target]
      when i.status = 'APPROVED' and v_target in ('PARTIALLY_PAID', 'PAID') then array['ISSUED', v_target]
    end;
    if v_path is null then
      v_detail := format('%s is %s in RoofOps but Xero verified %s (%s); RoofOps cannot follow that change, a person must check',
        i.invoice_number, i.status, d ->> 'Status', lower(replace(v_settle, '_', ' ')));
      insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, classification, action, detail)
      values (v_run.id, 'XERO', 'invoice', i.invoice_number, v_link, 'REQUIRES_HUMAN', case when v_repair then 'EXCEPTION_OPENED' else 'NONE_OBSERVE_ONLY' end, v_detail);
      if v_repair then perform wf_open_sync_exception('reconciliation', 'invoice', i.id, i.invoice_number, 'RECONCILIATION_MISMATCH', v_detail); end if;
      continue;
    end if;
    v_detail := format('%s: Xero verified %s (due %s); RoofOps shows %s', i.invoice_number, lower(replace(v_settle, '_', ' ')), coalesce(d ->> 'AmountDue', '?'), i.status);
    if not v_repair then
      insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, classification, action, detail)
      values (v_run.id, 'XERO', 'invoice', i.invoice_number, v_link, 'SAFE_AUTO_REPAIR', 'NONE_OBSERVE_ONLY', v_detail || '; a repair run applies it');
      continue;
    end if;
    v_from := i.status;
    foreach v_step in array v_path loop
      update invoices set status = v_step,
        issue_date = case when v_step in ('ISSUED', 'PARTIALLY_PAID', 'PAID') then coalesce(issue_date, case when d ->> 'Date' ~ '^\d{4}-\d{2}-\d{2}' then left(d ->> 'Date', 10)::date end, app_today()) else issue_date end,
        due_date = case when v_step in ('ISSUED', 'PARTIALLY_PAID', 'PAID') then coalesce(due_date, case when d ->> 'DueDate' ~ '^\d{4}-\d{2}-\d{2}' then left(d ->> 'DueDate', 10)::date end,
                     coalesce(issue_date, app_today()) + (select value::int from app_settings where key = 'invoice.payment_terms_days')) else due_date end,
        voided_reason = case when v_step <> 'VOIDED' then voided_reason
                             when v_settle = 'DELETED' then format('Deleted in Xero (verified by reconciliation %s)', p_run_key)
                             else format('Voided in Xero (verified by reconciliation %s)', p_run_key) end
      where id = i.id;
      insert into audit_events (actor_type, actor_id, action, entity_type, entity_id, business_reference, before_state, after_state, external_reference, reason)
      values ('SYSTEM', 'workflow:reconciliation', 'invoice.xero_settlement_applied', 'invoice', i.id, i.invoice_number,
              jsonb_build_object('status', i.status), jsonb_build_object('status', v_step, 'xero_status', d ->> 'Status', 'amount_due', d -> 'AmountDue',
                'amount_paid', d -> 'AmountPaid', 'observation', v_obs), v_link,
              format('Reconciliation %s: Xero verified %s in tenant %s', p_run_key, lower(replace(v_settle, '_', ' ')), left(x ->> 'tenant_id', 8) || '…'));
      i.status := v_step;
    end loop;
    v_applied := v_applied + 1;
    insert into reconciliation_findings (run_id, system, entity_type, entity_ref, external_id, classification, action, detail)
    values (v_run.id, 'XERO', 'invoice', i.invoice_number, v_link, 'SAFE_AUTO_REPAIR', 'APPLIED_TO_POSTGRES', v_detail || '; applied');
    if v_target <> 'VOIDED' and (v_rank ->> v_target)::int < (v_rank ->> v_from)::int then   -- a payment reversed in Xero
      v_regressed := v_regressed + 1;
      perform wf_open_sync_exception('reconciliation', 'invoice', i.id, i.invoice_number, 'RECONCILIATION_MISMATCH',
        format('%s went back to %s: Xero now shows %s (due %s), so a payment was reversed or removed in Xero. A person must check with the customer%s',
          i.invoice_number, v_target, d ->> 'Status', d ->> 'AmountDue',
          case when (select status from projects where id = i.project_id) = 'CLOSED' then '; the project is already Closed' else '' end));
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'verdicts', v_counts, 'applied', v_applied, 'regressed', v_regressed);
end $$;

--
-- Name: xero_reissue_proof(public.outbox); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_reissue_proof(o public.outbox) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare g invoice_xero_draft_generations; a approvals; i invoices;
begin
  if o.topic is distinct from 'xero.create_draft_invoice' or o.generation < 2 then return null; end if;
  select * into g from invoice_xero_draft_generations where invoice_id = o.aggregate_id and generation = o.generation;
  if g.invoice_id is null then return format('generation %s has no draft-generation ledger row', o.generation); end if;
  if g.superseded_at is not null then return format('generation %s was superseded', o.generation); end if;
  if g.outbox_idempotency_key is distinct from o.idempotency_key then
    return format('generation %s is ledgered under %s, not %s', o.generation, g.outbox_idempotency_key, o.idempotency_key);
  end if;
  select * into a from approvals where id = g.approval_id;
  if a.id is null or a.action_type <> 'REISSUE_INVOICE' or a.entity_id <> o.aggregate_id or a.status <> 'EXECUTED' then
    return format('generation %s is not bound to an executed reissue approval (%s)', o.generation, coalesce(a.approval_number || ' ' || a.status, 'none'));
  end if;
  if a.action_payload -> 'draft' is null or not (o.payload @> (a.action_payload -> 'draft'))
     or o.payload ->> 'reissue_preview_hash' is distinct from a.payload_hash or o.payload ->> 'approval_number' is distinct from a.approval_number then
    return format('generation %s payload is not the approved draft of %s', o.generation, a.approval_number);
  end if;
  if not exists (select 1 from invoice_xero_draft_generations p where p.invoice_id = o.aggregate_id and p.generation = o.generation - 1 and p.superseded_at is not null) then
    return format('generation %s is still live', o.generation - 1);
  end if;
  select * into i from invoices where id = o.aggregate_id;
  if i.status <> 'APPROVED' or i.approval_id is distinct from a.id then
    return format('%s is %s on %s, not APPROVED on %s', i.invoice_number, i.status,
      coalesce((select approval_number from approvals where id = i.approval_id), 'no approval'), a.approval_number);
  end if;
  return null;
end $$;

--
-- Name: xero_settlement(text, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_settlement(p_status text, p_total numeric, p_due numeric, p_paid numeric, p_credited numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when p_status = 'VOIDED' then 'VOIDED'
    when p_status = 'DELETED' then 'DELETED'
    when p_total is null or p_due is null or p_paid is null or p_due < 0 or p_paid < 0 or coalesce(p_credited, 0) < 0
      or p_paid + coalesce(p_credited, 0) + p_due <> p_total then null
    when p_status in ('DRAFT', 'SUBMITTED') and p_paid = 0 and coalesce(p_credited, 0) = 0 then 'NOT_ISSUED'
    when p_status = 'AUTHORISED' and p_due = p_total then 'UNPAID'
    when p_status = 'AUTHORISED' and p_due > 0 and p_due < p_total then 'PARTIALLY_PAID'
    when p_status = 'PAID' and p_due = 0 then 'PAID'
  end
$$;

--
-- Name: xero_settlement_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_settlement_status(p_settlement text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p_settlement when 'NOT_ISSUED' then 'APPROVED' when 'UNPAID' then 'ISSUED' when 'PARTIALLY_PAID' then 'PARTIALLY_PAID'
                           when 'PAID' then 'PAID' when 'VOIDED' then 'VOIDED' when 'DELETED' then 'VOIDED' end
$$;

--
-- Name: xero_write_tenant_is_fixed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_write_tenant_is_fixed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception 'The Xero tenant of % is fixed when it is approved (%…): it cannot be changed to %', old.idempotency_key,
    left(old.payload ->> 'xero_tenant_id', 8), coalesce(new.payload ->> 'xero_tenant_id', 'none') || case when new.topic is distinct from old.topic then ' / topic ' || new.topic else '' end
    using errcode = 'check_violation';
end $$;

--
-- Name: xero_write_tenant_problem(public.outbox, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xero_write_tenant_problem(o public.outbox, p_pin text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when coalesce(o.payload ->> 'xero_tenant_id', '') = '' then
      format('%s: Xero write stopped. It carries no Xero tenant, so RoofOps never sends it. A person decides what happens to it',
             o.payload ->> 'invoice_number')
    when coalesce(p_pin, '') = '' then
      format('%s: Xero write stopped. It was approved for Xero tenant %s…, but no Xero tenant is pinned now (app_settings xero.demo_tenant_id is empty). '
             'RoofOps never sends it to another tenant. Pin %s… again to let it continue, or a person decides what happens to it',
             o.payload ->> 'invoice_number', left(o.payload ->> 'xero_tenant_id', 8), left(o.payload ->> 'xero_tenant_id', 8))
    when p_pin <> o.payload ->> 'xero_tenant_id' then
      format('%s: Xero write stopped. It was approved for Xero tenant %s…, but the pinned tenant is now %s…. '
             'RoofOps never sends it to another tenant. Pin %s… again to let it continue, or a person decides what happens to it',
             o.payload ->> 'invoice_number', left(o.payload ->> 'xero_tenant_id', 8), left(p_pin, 8), left(o.payload ->> 'xero_tenant_id', 8))
  end
$$;

