    CONSTRAINT automation_events_check CHECK (((status <> ALL (ARRAY['FAILED'::text, 'DUPLICATE_IGNORED'::text])) OR (error_class IS NOT NULL))),
    CONSTRAINT automation_events_event_type_check CHECK ((event_type ~ '^[a-z_]+(\.[a-z_]+)+$'::text)),
    CONSTRAINT automation_events_status_check CHECK ((status = ANY (ARRAY['RECEIVED'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'DUPLICATE_IGNORED'::text, 'REJECTED'::text, 'INFO'::text])))
);

