    legal_name text,
    abn text,
    email text,
    phone text,
    phone_normalised text GENERATED ALWAYS AS (NULLIF(regexp_replace(COALESCE(phone, ''::text), '[^0-9]'::text, ''::text, 'g'::text), ''::text)) STORED,
    preferred_contact text,
