--
-- Name: invoices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.invoices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    invoice_number text NOT NULL,
    project_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    record_origin text DEFAULT 'ROOFOPS'::text NOT NULL,
    invoice_type text,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    sync_status text DEFAULT 'NOT_SYNCED'::text NOT NULL,
    line_amount_type text DEFAULT 'INCLUSIVE'::text NOT NULL,
    gst_rate numeric(5,4) DEFAULT 0.1000 NOT NULL,
    subtotal_ex_gst numeric(12,2) DEFAULT 0 NOT NULL,
    gst_amount numeric(12,2) DEFAULT 0 NOT NULL,
    total_inc_gst numeric(12,2) DEFAULT 0 NOT NULL,
    issue_date date,
    due_date date,
    approval_id uuid,
    approved_by uuid,
    approved_at timestamp with time zone,
    idempotency_key text,
    voided_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    record_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT invoices_check CHECK (
CASE line_amount_type
    WHEN 'EXCLUSIVE'::text THEN ((gst_amount = round((subtotal_ex_gst * gst_rate), 2)) AND (total_inc_gst = (subtotal_ex_gst + gst_amount)))
    WHEN 'INCLUSIVE'::text THEN ((gst_amount = round(((total_inc_gst * gst_rate) / ((1)::numeric + gst_rate)), 2)) AND (subtotal_ex_gst = (total_inc_gst - gst_amount)))
    ELSE ((gst_amount = (0)::numeric) AND (total_inc_gst = subtotal_ex_gst))
END),
    CONSTRAINT invoices_check1 CHECK (((due_date IS NULL) OR (issue_date IS NULL) OR (due_date >= issue_date))),
    CONSTRAINT invoices_check2 CHECK (((record_origin = 'IMPORT'::text) OR (status = ANY (ARRAY['DRAFT'::text, 'PENDING_APPROVAL'::text, 'VOIDED'::text])) OR ((approved_by IS NOT NULL) AND (approved_at IS NOT NULL)))),
    CONSTRAINT invoices_check3 CHECK (((status <> ALL (ARRAY['ISSUED'::text, 'PARTIALLY_PAID'::text, 'PAID'::text])) OR ((issue_date IS NOT NULL) AND (due_date IS NOT NULL)))),
    CONSTRAINT invoices_check4 CHECK (((status <> 'VOIDED'::text) OR (voided_reason IS NOT NULL))),
    CONSTRAINT invoices_invoice_type_check CHECK ((invoice_type = ANY (ARRAY['DEPOSIT'::text, 'PROGRESS'::text, 'FINAL'::text, 'VARIATION'::text]))),
    CONSTRAINT invoices_line_amount_type_check CHECK ((line_amount_type = ANY (ARRAY['EXCLUSIVE'::text, 'INCLUSIVE'::text, 'NO_TAX'::text]))),
    CONSTRAINT invoices_record_origin_check CHECK ((record_origin = ANY (ARRAY['ROOFOPS'::text, 'IMPORT'::text]))),
    CONSTRAINT invoices_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'PENDING_APPROVAL'::text, 'APPROVED'::text, 'ISSUED'::text, 'PARTIALLY_PAID'::text, 'PAID'::text, 'VOIDED'::text]))),
    CONSTRAINT invoices_sync_status_check CHECK ((sync_status = ANY (ARRAY['NOT_SYNCED'::text, 'PENDING'::text, 'SYNCED'::text, 'FAILED'::text, 'UNKNOWN'::text])))
);

