--
-- Name: purchase_orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.purchase_orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    po_number text NOT NULL,
    supplier_id uuid NOT NULL,
    project_id uuid,
    record_origin text DEFAULT 'ROOFOPS'::text NOT NULL,
    origin text DEFAULT 'MANUAL'::text NOT NULL,
    source_supplier_quote_id uuid,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    line_amount_type text DEFAULT 'EXCLUSIVE'::text NOT NULL,
    gst_rate numeric(5,4) DEFAULT 0.1000 NOT NULL,
    subtotal_ex_gst numeric(12,2) DEFAULT 0 NOT NULL,
    gst_amount numeric(12,2) DEFAULT 0 NOT NULL,
    total_inc_gst numeric(12,2) DEFAULT 0 NOT NULL,
    po_date date DEFAULT CURRENT_DATE NOT NULL,
    required_by date,
    expected_delivery_date date,
    supplier_reference text,
    approval_id uuid,
    approved_by uuid,
    approved_at timestamp with time zone,
    sent_at timestamp with time zone,
    acknowledged_at timestamp with time zone,
    cancelled_reason text,
    idempotency_key text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    record_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT purchase_orders_check CHECK (
CASE line_amount_type
    WHEN 'EXCLUSIVE'::text THEN ((gst_amount = round((subtotal_ex_gst * gst_rate), 2)) AND (total_inc_gst = (subtotal_ex_gst + gst_amount)))
    WHEN 'INCLUSIVE'::text THEN ((gst_amount = round(((total_inc_gst * gst_rate) / ((1)::numeric + gst_rate)), 2)) AND (subtotal_ex_gst = (total_inc_gst - gst_amount)))
    ELSE ((gst_amount = (0)::numeric) AND (total_inc_gst = subtotal_ex_gst))
END),
    CONSTRAINT purchase_orders_check1 CHECK (((expected_delivery_date IS NULL) OR (expected_delivery_date >= po_date))),
    CONSTRAINT purchase_orders_check2 CHECK (((record_origin = 'IMPORT'::text) OR (status = ANY (ARRAY['DRAFT'::text, 'PENDING_APPROVAL'::text, 'CANCELLED'::text])) OR ((approved_by IS NOT NULL) AND (approved_at IS NOT NULL)))),
    CONSTRAINT purchase_orders_check3 CHECK (((record_origin = 'IMPORT'::text) OR (status <> ALL (ARRAY['SENT'::text, 'ACKNOWLEDGED'::text, 'PARTIALLY_DELIVERED'::text, 'DELIVERED'::text])) OR (sent_at IS NOT NULL))),
    CONSTRAINT purchase_orders_check4 CHECK (((record_origin = 'IMPORT'::text) OR (status <> 'ACKNOWLEDGED'::text) OR (acknowledged_at IS NOT NULL))),
    CONSTRAINT purchase_orders_check5 CHECK (((status <> 'CANCELLED'::text) OR (cancelled_reason IS NOT NULL))),
    CONSTRAINT purchase_orders_line_amount_type_check CHECK ((line_amount_type = ANY (ARRAY['EXCLUSIVE'::text, 'INCLUSIVE'::text, 'NO_TAX'::text]))),
    CONSTRAINT purchase_orders_origin_check CHECK ((origin = ANY (ARRAY['MANUAL'::text, 'AI_DRAFT'::text, 'SUPPLIER_QUOTE'::text, 'LEGACY'::text]))),
    CONSTRAINT purchase_orders_record_origin_check CHECK ((record_origin = ANY (ARRAY['ROOFOPS'::text, 'IMPORT'::text]))),
    CONSTRAINT purchase_orders_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'PENDING_APPROVAL'::text, 'APPROVED'::text, 'SENT'::text, 'ACKNOWLEDGED'::text, 'PARTIALLY_DELIVERED'::text, 'DELIVERED'::text, 'CANCELLED'::text])))
);

