--
-- Name: v_accepted_quotes_without_project; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_accepted_quotes_without_project AS
 SELECT q.id,
    q.quote_number,
    q.accepted_on,
    c.display_name AS customer_name,
    (public.app_today() - q.accepted_on) AS days_since_accepted
   FROM (public.quotes q
     JOIN public.customers c ON ((c.id = q.customer_id)))
  WHERE ((q.status = 'ACCEPTED'::text) AND (NOT (EXISTS ( SELECT 1
           FROM public.projects p
          WHERE (p.quote_id = q.id)))));

