--
-- Name: v_state_drift; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_state_drift AS
 SELECT x.table_id,
    x.entity_type,
    x.entity_id,
    x.business_key,
    x.record_id,
    c.airtable_name AS field,
    c.owner,
    public.at_norm(public.at_repair_value((x.expected -> c.airtable_field_id))) AS canonical_value,
    o.value AS airtable_value,
    o.observed_at,
    o.source
   FROM ((public.v_airtable_expected x
     JOIN public.field_contract c ON (((c.airtable_table_id = x.table_id) AND (x.expected ? c.airtable_field_id) AND (c.reconcile = ANY (ARRAY['APPLY_VIA_HANDLER'::text, 'REPAIR_AIRTABLE'::text, 'PROJECTION'::text])))))
     JOIN public.airtable_observations o ON (((o.table_id = x.table_id) AND (o.record_id = x.record_id) AND (o.field_id = c.airtable_field_id))))
  WHERE (NOT public.at_matches((x.expected -> c.airtable_field_id), to_jsonb(o.value)));

--
-- Name: v_consistency; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_consistency AS
 WITH run AS (
         SELECT reconciliation_runs.id,
            reconciliation_runs.run_key,
            reconciliation_runs.trigger,
            reconciliation_runs.mode,
            reconciliation_runs.status,
            reconciliation_runs.started_at,
            reconciliation_runs.finished_at,
            reconciliation_runs.summary
           FROM public.reconciliation_runs
          WHERE (reconciliation_runs.status = 'COMPLETED'::text)
          ORDER BY reconciliation_runs.finished_at DESC
         LIMIT 1
        ), f AS (
         SELECT f.id,
            f.run_id,
            f.system,
            f.entity_type,
            f.entity_ref,
            f.external_id,
            f.field,
            f.expected,
            f.actual,
            f.classification,
            f.action,
            f.detail,
            f.created_at
           FROM (public.reconciliation_findings f
             JOIN run ON ((run.id = f.run_id)))
        )
 SELECT 'AIRTABLE'::text AS system,
    (COALESCE(( SELECT sum(((t.value ->> 'records'::text))::integer) AS sum
           FROM run,
            LATERAL jsonb_array_elements(COALESCE(((run.summary -> 'airtable'::text) -> 'tables'::text), '[]'::jsonb)) t(value)), (0)::bigint))::integer AS checked,
    (( SELECT count(DISTINCT f.external_id) AS count
           FROM f
          WHERE ((f.system = 'AIRTABLE'::text) AND (f.classification <> 'STALE_EVENT'::text))))::integer AS drift_found,
    (( SELECT count(DISTINCT f.external_id) AS count
           FROM f
          WHERE ((f.system = 'AIRTABLE'::text) AND (f.action = ANY (ARRAY['APPLIED_TO_POSTGRES'::text, 'REJECTED_AND_REPAIRED'::text, 'REPAIRED_AIRTABLE'::text])))))::integer AS repaired,
    (( SELECT count(*) AS count
           FROM f
          WHERE ((f.system = 'AIRTABLE'::text) AND (f.classification = ANY (ARRAY['REQUIRES_HUMAN'::text, 'EXTERNAL_MISSING'::text, 'UNKNOWN'::text])))))::integer AS needs_person,
    (( SELECT count(DISTINCT v_state_drift.record_id) AS count
           FROM public.v_state_drift))::integer AS drift_now,
    (( SELECT count(*) AS count
           FROM public.external_links
          WHERE ((external_links.provider = 'AIRTABLE'::text) AND (external_links.external_type = 'Record'::text))))::integer AS linked,
    ( SELECT run.finished_at
           FROM run) AS checked_at
UNION ALL
 SELECT 'GOOGLE_DRIVE'::text AS system,
    COALESCE(( SELECT (((run.summary -> 'drive'::text) ->> 'checked'::text))::integer AS int4
           FROM run), 0) AS checked,
    COALESCE(( SELECT (((run.summary -> 'drive'::text) ->> 'drift'::text))::integer AS int4
           FROM run), 0) AS drift_found,
    0 AS repaired,
    (( SELECT count(*) AS count
           FROM f
          WHERE (f.system = 'DRIVE'::text)))::integer AS needs_person,
    NULL::integer AS drift_now,
    (( SELECT count(*) AS count
           FROM public.external_links
          WHERE ((external_links.provider = 'GOOGLE_DRIVE'::text) AND (external_links.entity_type = 'project'::text) AND (external_links.external_type = 'Folder'::text) AND (external_links.verified_at IS NOT NULL))))::integer AS linked,
    ( SELECT run.finished_at
           FROM run) AS checked_at
UNION ALL
 SELECT 'XERO'::text AS system,
    COALESCE(( SELECT (((run.summary -> 'xero'::text) ->> 'checked'::text))::integer AS int4
           FROM run), 0) AS checked,
    COALESCE(( SELECT (((run.summary -> 'xero'::text) ->> 'drift'::text))::integer AS int4
           FROM run), 0) AS drift_found,
    0 AS repaired,
    (( SELECT count(*) AS count
           FROM f
          WHERE (f.system = 'XERO'::text)))::integer AS needs_person,
    NULL::integer AS drift_now,
    (( SELECT count(*) AS count
           FROM public.external_links
          WHERE ((external_links.provider = 'XERO'::text) AND (external_links.external_type = 'Invoice'::text) AND (external_links.verified_at IS NOT NULL))))::integer AS linked,
    ( SELECT run.finished_at
           FROM run) AS checked_at;

--
-- Name: v_dashboard_customer_directory; Type: VIEW; Schema: public; Owner: -
--

