 SELECT customer_number,
    display_name,
    customer_type,
    email,
    phone,
    record_version
   FROM public.customers
  WHERE (status = 'ACTIVE'::text);

--
-- Name: workflow_exceptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_exceptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    exception_number text NOT NULL,
    record_origin text DEFAULT 'ROOFOPS'::text NOT NULL,
    workflow_run_id uuid,
    event_id uuid,
    workflow_key text NOT NULL,
    entity_type text,
    entity_id uuid,
    business_reference text,
    error_class text NOT NULL,
    error_message text NOT NULL,
    retryable boolean NOT NULL,
    attempt_count integer NOT NULL,
    first_failed_at timestamp with time zone NOT NULL,
    last_attempt_at timestamp with time zone NOT NULL,
    resolution_status text DEFAULT 'OPEN'::text NOT NULL,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    resolution_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_by_system text,
    CONSTRAINT workflow_exceptions_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT workflow_exceptions_check CHECK ((last_attempt_at >= first_failed_at)),
    CONSTRAINT workflow_exceptions_check2 CHECK (((resolution_status <> 'IGNORED'::text) OR (resolution_note IS NOT NULL))),
    CONSTRAINT workflow_exceptions_record_origin_check CHECK ((record_origin = ANY (ARRAY['ROOFOPS'::text, 'IMPORT'::text]))),
    CONSTRAINT workflow_exceptions_resolution_actor_check CHECK (((record_origin = 'IMPORT'::text) OR ((resolution_status = ANY (ARRAY['RESOLVED'::text, 'IGNORED'::text])) = (((resolved_by IS NOT NULL) OR (resolved_by_system IS NOT NULL)) AND (resolved_at IS NOT NULL))))),
    CONSTRAINT workflow_exceptions_resolution_status_check CHECK ((resolution_status = ANY (ARRAY['OPEN'::text, 'RETRY_QUEUED'::text, 'RESOLVED'::text, 'IGNORED'::text])))
);

--
-- Name: v_dashboard_exception_sources; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_exception_sources AS
 SELECT x.exception_number,
    e.source,
    e.event_type,
    e.occurred_at,
    NULLIF(COALESCE(((e.payload -> 'payload'::text) ->> 'airtable_record_id'::text), (e.payload ->> 'airtable_record_id'::text)), ''::text) AS airtable_record_id,
    "left"(NULLIF(COALESCE(((e.payload -> 'payload'::text) ->> 'quote_id'::text), ((e.payload -> 'payload'::text) ->> 'project_number'::text)), ''::text), 40) AS named_record
   FROM (public.workflow_exceptions x
     JOIN public.automation_events e ON ((e.event_id = x.event_id)));

--
-- Name: v_dashboard_exceptions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_exceptions AS
 SELECT w.exception_number,
    w.workflow_key,
    w.error_class,
    w.error_message,
    w.retryable,
    w.attempt_count,
    w.resolution_status,
    w.first_failed_at,
    w.last_attempt_at,
    w.resolved_at,
    w.resolution_note,
    w.business_reference,
    COALESCE(p.project_number, pq.project_number) AS project_number
   FROM (((public.workflow_exceptions w
     LEFT JOIN public.projects p ON (((p.id = w.entity_id) OR (p.project_number = w.business_reference))))
     LEFT JOIN public.quotes q ON ((q.quote_number = w.business_reference)))
     LEFT JOIN public.projects pq ON ((pq.quote_id = q.id)));

--
-- Name: xero_invoice_observations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.xero_invoice_observations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    invoice_id uuid NOT NULL,
    run_id uuid NOT NULL,
    observed_at timestamp with time zone DEFAULT now() NOT NULL,
    tenant_id text,
    bound_tenant_id text,
    xero_invoice_id text,
    http_status integer,
    verdict text NOT NULL,
    xero_status text,
    total numeric(12,2),
    amount_due numeric(12,2),
    amount_paid numeric(12,2),
    amount_credited numeric(12,2),
    fully_paid_on date,
    xero_updated text,
    payments jsonb,
    settlement text,
    detail text,
    CONSTRAINT xero_invoice_observations_check CHECK (((verdict = 'VERIFIED'::text) = (settlement IS NOT NULL))),
    CONSTRAINT xero_invoice_observations_settlement_check CHECK ((settlement = ANY (ARRAY['NOT_ISSUED'::text, 'UNPAID'::text, 'PARTIALLY_PAID'::text, 'PAID'::text, 'VOIDED'::text, 'DELETED'::text]))),
    CONSTRAINT xero_invoice_observations_verdict_check CHECK ((verdict = ANY (ARRAY['VERIFIED'::text, 'LOOKUP_FAILED'::text, 'WRONG_TENANT'::text, 'MISMATCH'::text, 'INCONSISTENT'::text])))
);

--
-- Name: v_dashboard_invoice_xero_history; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_invoice_xero_history AS
 SELECT p.project_number,
    i.invoice_number,
    g.generation,
    g.status,
    (g.superseded_at IS NULL) AS is_current,
    g.xero_invoice_id,
    g.xero_invoice_number,
    g.created_at,
    g.superseded_at,
    ( SELECT o.xero_status
           FROM public.xero_invoice_observations o
          WHERE ((o.xero_invoice_id = g.xero_invoice_id) AND (o.verdict = 'VERIFIED'::text))
          ORDER BY o.observed_at DESC
         LIMIT 1) AS xero_status_verified,
    ap.approval_number,
    ap.action_type AS approval_kind,
    NULLIF(btrim(re.full_name), ''::text) AS requested_by,
    NULLIF(btrim(de.full_name), ''::text) AS approved_by,
    ap.decided_at AS approved_at
   FROM (((((public.invoice_xero_draft_generations g
     JOIN public.invoices i ON ((i.id = g.invoice_id)))
     JOIN public.projects p ON ((p.id = i.project_id)))
     LEFT JOIN public.approvals ap ON ((ap.id = g.approval_id)))
     LEFT JOIN public.employees re ON ((re.id = ap.requested_by_employee_id)))
     LEFT JOIN public.employees de ON ((de.id = ap.decided_by)));

--
-- Name: v_invoice_balances; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_invoice_balances AS
 SELECT i.id,
    i.invoice_number,
    i.project_id,
    p.project_number,
    i.customer_id,
    c.display_name AS customer_name,
    i.status,
    i.sync_status,
    i.issue_date,
    i.due_date,
    i.total_inc_gst,
    COALESCE(xv.paid, pay.paid, (0)::numeric) AS amount_paid,
        CASE
            WHEN (i.status = 'VOIDED'::text) THEN (0)::numeric
            ELSE COALESCE(xv.due, (i.total_inc_gst - COALESCE(pay.paid, (0)::numeric)))
        END AS outstanding,
    ((i.status <> 'VOIDED'::text) AND (i.status = ANY (ARRAY['ISSUED'::text, 'PARTIALLY_PAID'::text])) AND (i.due_date < public.app_today()) AND (COALESCE(xv.due, (i.total_inc_gst - COALESCE(pay.paid, (0)::numeric))) > (0)::numeric)) AS is_overdue,
    GREATEST((public.app_today() - i.due_date), 0) AS days_past_due
   FROM ((((public.invoices i
     JOIN public.projects p ON ((p.id = i.project_id)))
     JOIN public.customers c ON ((c.id = i.customer_id)))
     LEFT JOIN ( SELECT payments.invoice_id,
            sum(payments.amount) AS paid
           FROM public.payments
          GROUP BY payments.invoice_id) pay ON ((pay.invoice_id = i.id)))
     LEFT JOIN LATERAL ( SELECT (o.amount_paid + o.amount_credited) AS paid,
            o.amount_due AS due
           FROM public.xero_invoice_observations o
          WHERE ((o.invoice_id = i.id) AND (o.verdict = 'VERIFIED'::text) AND (o.settlement <> 'DELETED'::text) AND (o.xero_invoice_id = ( SELECT l.external_id
                   FROM public.external_links l
                  WHERE ((l.provider = 'XERO'::text) AND (l.external_type = 'Invoice'::text) AND (l.entity_id = i.id)))))
          ORDER BY o.observed_at DESC, o.id DESC
         LIMIT 1) xv ON (true));

--
-- Name: v_purchase_order_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_purchase_order_status AS
 SELECT po.id,
    po.po_number,
    po.project_id,
    p.project_number,
    po.supplier_id,
    s.name AS supplier_name,
    po.status,
    po.po_date,
    po.expected_delivery_date,
    po.subtotal_ex_gst,
    po.total_inc_gst,
    (po.status = ANY (ARRAY['ACKNOWLEDGED'::text, 'PARTIALLY_DELIVERED'::text, 'DELIVERED'::text])) AS supplier_acknowledged,
    (po.status = ANY (ARRAY['APPROVED'::text, 'SENT'::text, 'ACKNOWLEDGED'::text, 'PARTIALLY_DELIVERED'::text])) AS is_open_commitment,
    ((po.status = 'SENT'::text) AND (public.business_days_between(COALESCE((po.sent_at)::date, po.po_date), public.app_today()) > ( SELECT (app_settings.value)::integer AS value
           FROM public.app_settings
          WHERE (app_settings.key = 'supplier_ack_sla_business_days'::text)))) AS ack_overdue
   FROM ((public.purchase_orders po
     JOIN public.suppliers s ON ((s.id = po.supplier_id)))
     LEFT JOIN public.projects p ON ((p.id = po.project_id)));

--
-- Name: v_project_risk; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_project_risk AS
 WITH base AS (
         SELECT p_1.id,
            p_1.project_number,
            p_1.quote_id,
            p_1.accepted_quote_version_id,
            p_1.customer_id,
            p_1.property_id,
            p_1.project_manager_id,
            p_1.status,
            p_1.planned_start_date,
            p_1.planned_completion_date,
            p_1.actual_start_date,
            p_1.actual_completion_date,
            p_1.pm_risk_flag,
            p_1.delay_reason,
            p_1.on_hold_reason,
            p_1.cancellation_reason,
            p_1.created_by_event_id,
            p_1.created_at,
            p_1.updated_at,
            p_1.record_version,
            (p_1.status <> ALL (ARRAY['COMPLETED'::text, 'CLOSED'::text, 'CANCELLED'::text])) AS is_active,
            public.app_today() AS today
           FROM public.projects p_1
        ), signals AS (
         SELECT b.id,
            (b.is_active AND (b.actual_start_date IS NULL) AND (b.planned_start_date < b.today)) AS start_missed,
            (b.is_active AND (b.planned_completion_date < b.today)) AS completion_overdue,
            (b.is_active AND (b.actual_start_date IS NULL) AND (EXISTS ( SELECT 1
                   FROM public.purchase_orders po
                  WHERE ((po.project_id = b.id) AND (po.status = ANY (ARRAY['DRAFT'::text, 'PENDING_APPROVAL'::text, 'APPROVED'::text, 'SENT'::text])) AND (po.expected_delivery_date > b.planned_start_date))))) AS materials_after_start,
            (b.is_active AND (b.actual_start_date IS NULL) AND (EXISTS ( SELECT 1
                   FROM public.purchase_orders po
                  WHERE ((po.project_id = b.id) AND (po.status = 'ACKNOWLEDGED'::text) AND (po.expected_delivery_date > b.planned_start_date))))) AS supplier_delivery_late,
            (b.is_active AND (EXISTS ( SELECT 1
                   FROM public.v_purchase_order_status v
                  WHERE ((v.project_id = b.id) AND v.ack_overdue)))) AS supplier_ack_overdue,
            (b.is_active AND (b.pm_risk_flag = 'HIGH'::text)) AS pm_flagged
           FROM base b
        )
 SELECT p.id,
    p.project_number,
    p.status,
    p.project_manager_id,
    e.full_name AS project_manager,
    c.display_name AS customer_name,
    ((pr.address_line1 || ', '::text) || pr.suburb) AS site_address,
    p.planned_start_date,
    p.planned_completion_date,
    p.actual_start_date,
    (p.status <> ALL (ARRAY['COMPLETED'::text, 'CLOSED'::text, 'CANCELLED'::text])) AS is_active,
    (s.start_missed OR s.completion_overdue) AS is_delayed,
    s.start_missed,
    s.completion_overdue,
    s.materials_after_start,
    s.supplier_delivery_late,
    s.supplier_ack_overdue,
    s.pm_flagged,
    p.delay_reason,
    array_remove(ARRAY[
        CASE
            WHEN s.start_missed THEN 'START_DATE_PASSED'::text
            ELSE NULL::text
        END,
        CASE
            WHEN s.completion_overdue THEN 'PAST_PLANNED_COMPLETION'::text
            ELSE NULL::text
        END,
        CASE
            WHEN s.materials_after_start THEN 'MATERIALS_DUE_AFTER_START'::text
            ELSE NULL::text
        END,
        CASE
            WHEN s.supplier_delivery_late THEN 'SUPPLIER_DELIVERY_AFTER_START'::text
            ELSE NULL::text
        END,
        CASE
            WHEN s.supplier_ack_overdue THEN 'SUPPLIER_ACK_OVERDUE'::text
            ELSE NULL::text
        END,
        CASE
            WHEN s.pm_flagged THEN 'PM_FLAGGED'::text
            ELSE NULL::text
        END], NULL::text) AS risk_reasons,
        CASE
            WHEN (s.start_missed OR s.completion_overdue OR s.materials_after_start OR s.supplier_delivery_late OR s.supplier_ack_overdue OR s.pm_flagged) THEN 'HIGH'::text
            ELSE 'LOW'::text
        END AS risk_level,
    ((p.planned_start_date >= public.app_today()) AND (p.planned_start_date <= (public.app_today() + 7))) AS starts_within_7_days,
    ((p.planned_start_date >= ((date_trunc('week'::text, (public.app_today())::timestamp with time zone) + '7 days'::interval))::date) AND (p.planned_start_date <= ((date_trunc('week'::text, (public.app_today())::timestamp with time zone) + '13 days'::interval))::date)) AS starts_next_week
   FROM ((((public.projects p
     JOIN signals s ON ((s.id = p.id)))
     JOIN public.customers c ON ((c.id = p.customer_id)))
     JOIN public.properties pr ON ((pr.id = p.property_id)))
     LEFT JOIN public.employees e ON ((e.id = p.project_manager_id)));

--
-- Name: v_projects_waiting_on_materials; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_projects_waiting_on_materials AS
 SELECT r.project_number,
    r.status,
    r.planned_start_date,
    po.po_number,
    po.status AS po_status,
    po.expected_delivery_date,
    po.supplier_name
   FROM (public.v_project_risk r
     JOIN public.v_purchase_order_status po ON ((po.project_id = r.id)))
  WHERE (r.is_active AND (r.actual_start_date IS NULL) AND (po.status = ANY (ARRAY['DRAFT'::text, 'PENDING_APPROVAL'::text, 'APPROVED'::text, 'SENT'::text, 'ACKNOWLEDGED'::text, 'PARTIALLY_DELIVERED'::text])));

--
-- Name: v_dashboard_projects; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_projects AS
 WITH final_inv AS (
         SELECT DISTINCT ON (i.project_id) i.project_id,
            i.id AS invoice_id,
            i.invoice_number,
            i.status,
            i.sync_status,
            i.total_inc_gst
           FROM public.invoices i
          WHERE ((i.invoice_type = 'FINAL'::text) AND (i.status <> 'VOIDED'::text))
          ORDER BY i.project_id, i.created_at DESC
        ), pending_approval AS (
         SELECT DISTINCT ON (a.entity_id) a.entity_id AS project_id,
            a.approval_number,
            ((a.action_payload ->> 'amount_inc_gst'::text))::numeric(12,2) AS amount_inc_gst,
            a.expires_at
           FROM public.approvals a
          WHERE ((a.action_type = 'CREATE_INVOICE'::text) AND (a.status = 'PENDING'::text) AND (a.expires_at > now()))
          ORDER BY a.entity_id, a.created_at DESC
        ), readiness AS (
         SELECT p_1.id AS project_id,
            public.invoice_final_preview(p_1.id) AS x
           FROM public.projects p_1
          WHERE (p_1.status = 'COMPLETED'::text)
        ), po AS (
         SELECT v.project_id,
            count(*) AS n,
            count(*) FILTER (WHERE (v.status = 'DELIVERED'::text)) AS delivered,
            count(*) FILTER (WHERE (v.status = 'PARTIALLY_DELIVERED'::text)) AS part_delivered,
            count(*) FILTER (WHERE (v.status = 'ACKNOWLEDGED'::text)) AS confirmed,
            count(*) FILTER (WHERE (v.status = 'SENT'::text)) AS sent,
            count(*) FILTER (WHERE (v.status = ANY (ARRAY['DRAFT'::text, 'PENDING_APPROVAL'::text, 'APPROVED'::text]))) AS in_preparation,
            bool_or(v.ack_overdue) AS ack_overdue,
            max(v.expected_delivery_date) FILTER (WHERE (v.status <> ALL (ARRAY['DELIVERED'::text, 'CANCELLED'::text]))) AS latest_open_eta
           FROM public.v_purchase_order_status v
          WHERE ((v.project_id IS NOT NULL) AND (v.status <> 'CANCELLED'::text))
          GROUP BY v.project_id
        ), bal AS (
         SELECT v_invoice_balances.project_id,
            count(*) AS invoices,
            bool_or(v_invoice_balances.is_overdue) AS has_overdue,
            COALESCE(sum(v_invoice_balances.outstanding) FILTER (WHERE (v_invoice_balances.status = ANY (ARRAY['ISSUED'::text, 'PARTIALLY_PAID'::text]))), (0)::numeric) AS outstanding
           FROM public.v_invoice_balances
          GROUP BY v_invoice_balances.project_id
        ), exc AS (
         SELECT p_1.id AS project_id,
            count(*) AS open_exceptions
           FROM ((public.projects p_1
             JOIN public.quotes q_1 ON ((q_1.id = p_1.quote_id)))
             JOIN public.workflow_exceptions w ON (((w.resolution_status = ANY (ARRAY['OPEN'::text, 'RETRY_QUEUED'::text])) AND ((w.entity_id = p_1.id) OR ((w.business_reference = p_1.project_number) OR (w.business_reference = q_1.quote_number))))))
          GROUP BY p_1.id
        ), overbill AS (
         SELECT p_1.id AS project_id,
            public.project_over_billing(p_1.id) AS x
           FROM public.projects p_1
        ), left_after_final AS (
         SELECT p_1.id AS project_id,
            public.project_left_to_bill_after_final(p_1.id) AS x
           FROM public.projects p_1
        )
 SELECT p.id,
    p.project_number,
    p.status,
    r.is_active,
    c.customer_number,
    btrim(c.display_name) AS customer_name,
    c.customer_type,
    r.site_address,
    r.project_manager,
    q.quote_number,
    qv.version_number AS quote_version,
    qv.total_inc_gst AS quote_total_inc_gst,
    q.job_type,
    q.accepted_on,
    p.planned_start_date,
    p.planned_completion_date,
    p.actual_start_date,
    p.actual_completion_date,
    r.risk_level,
    r.risk_reasons,
    p.delay_reason,
        CASE
            WHEN (NOT r.is_active) THEN 'JOB_COMPLETE'::text
            WHEN (po.n IS NULL) THEN
            CASE
                WHEN (EXISTS ( SELECT 1
                   FROM public.tasks t
                  WHERE ((t.project_id = p.id) AND (t.task_type = 'MATERIAL_REVIEW'::text) AND (t.status = 'OPEN'::text)))) THEN 'REVIEW_PENDING'::text
                ELSE 'NOT_ORDERED'::text
            END
            WHEN po.ack_overdue THEN 'CONFIRMATION_OVERDUE'::text
            WHEN (po.delivered = po.n) THEN 'DELIVERED'::text
            WHEN (po.part_delivered > 0) THEN 'PART_DELIVERED'::text
            WHEN (po.sent > 0) THEN 'AWAITING_CONFIRMATION'::text
            WHEN (po.in_preparation > 0) THEN 'ORDER_IN_PREPARATION'::text
            ELSE 'CONFIRMED'::text
        END AS material_status,
    (EXISTS ( SELECT 1
           FROM public.v_projects_waiting_on_materials w
          WHERE (w.project_number = p.project_number))) AS waiting_on_materials,
    po.latest_open_eta AS material_eta,
    COALESCE(po.n, (0)::bigint) AS purchase_orders,
        CASE
            WHEN (ob.x IS NOT NULL) THEN 'OVER_BILLED'::text
            WHEN (fi.invoice_id IS NOT NULL) THEN
            CASE fi.sync_status
                WHEN 'SYNCED'::text THEN 'XERO_DRAFT_CREATED'::text
                WHEN 'PENDING'::text THEN 'CREATING_IN_XERO'::text
                WHEN 'UNKNOWN'::text THEN 'CHECKING_WITH_XERO'::text
                WHEN 'FAILED'::text THEN 'XERO_FAILED_SAFELY'::text
                ELSE 'FINAL_INVOICED'::text
            END
            WHEN (pa.approval_number IS NOT NULL) THEN 'AWAITING_APPROVAL'::text
            WHEN ((rd.x ->> 'ok'::text))::boolean THEN 'READY_TO_INVOICE'::text
            WHEN ((rd.x ->> 'error_class'::text) = 'ARITHMETIC_MISMATCH'::text) THEN 'FULLY_INVOICED'::text
            WHEN (rd.x IS NOT NULL) THEN 'NOT_READY'::text
            WHEN bal.has_overdue THEN 'PAYMENT_OVERDUE'::text
            WHEN (bal.invoices > 0) THEN 'PROGRESS_INVOICED'::text
            ELSE 'NOT_YET_DUE'::text
        END AS invoice_status,
        CASE
            WHEN (ob.x IS NOT NULL) THEN (ob.x ->> 'message'::text)
            WHEN (lf.x IS NOT NULL) THEN (lf.x ->> 'message'::text)
            WHEN ((rd.x IS NOT NULL) AND (NOT ((rd.x ->> 'ok'::text))::boolean) AND ((rd.x ->> 'error_class'::text) <> 'ARITHMETIC_MISMATCH'::text) AND (fi.invoice_id IS NULL)) THEN (rd.x ->> 'message'::text)
            ELSE NULL::text
        END AS invoice_blocker,
    COALESCE(fi.total_inc_gst, pa.amount_inc_gst, (((rd.x -> 'preview'::text) ->> 'amount_inc_gst'::text))::numeric(12,2)) AS invoice_amount_inc_gst,
    fi.invoice_number AS final_invoice_number,
    fi.sync_status AS final_invoice_sync,
    xi.external_id AS xero_invoice_id,
        CASE
            WHEN (xi.external_id IS NOT NULL) THEN (( SELECT app_settings.value
               FROM public.app_settings
              WHERE (app_settings.key = 'xero.invoice_number_prefix'::text)) || fi.invoice_number)
            ELSE NULL::text
        END AS xero_invoice_number,
    pa.approval_number AS pending_approval_number,
    COALESCE(bal.outstanding, (0)::numeric) AS outstanding_inc_gst,
    COALESCE(bal.has_overdue, false) AS has_overdue_invoice,
    COALESCE(exc.open_exceptions, (0)::bigint) AS open_exceptions,
    drive.external_url AS drive_folder_url,
    at.external_id AS airtable_record_id,
    COALESCE(((r.is_active AND (r.risk_level = 'HIGH'::text)) OR (COALESCE(exc.open_exceptions, (0)::bigint) > 0) OR COALESCE(bal.has_overdue, false) OR (pa.approval_number IS NOT NULL) OR (fi.sync_status = ANY (ARRAY['UNKNOWN'::text, 'FAILED'::text])) OR (ob.x IS NOT NULL) OR (lf.x IS NOT NULL)), false) AS needs_attention,
    COALESCE(( SELECT x.last_source_at
           FROM public.external_field_versions x
          WHERE ((x.entity_type = 'project'::text) AND (x.entity_id = p.id) AND (x.field_key = 'status'::text))), p.updated_at) AS status_changed_at,
    ao.value AS airtable_status_seen,
    ao.observed_at AS airtable_status_seen_at,
    (( SELECT count(*) AS count
           FROM public.v_state_drift s
          WHERE ((s.entity_type = 'project'::text) AND (s.entity_id = p.id))))::integer AS drift_fields,
    ( SELECT max(reconciliation_runs.finished_at) AS max
           FROM public.reconciliation_runs
          WHERE (reconciliation_runs.status = 'COMPLETED'::text)) AS last_reconciled_at
   FROM ((((((((((((((((public.projects p
     JOIN public.v_project_risk r ON ((r.id = p.id)))
     JOIN public.customers c ON ((c.id = p.customer_id)))
     JOIN public.quotes q ON ((q.id = p.quote_id)))
     LEFT JOIN public.quote_versions qv ON ((qv.id = p.accepted_quote_version_id)))
     LEFT JOIN po ON ((po.project_id = p.id)))
     LEFT JOIN final_inv fi ON ((fi.project_id = p.id)))
     LEFT JOIN pending_approval pa ON ((pa.project_id = p.id)))
     LEFT JOIN readiness rd ON ((rd.project_id = p.id)))
     LEFT JOIN overbill ob ON ((ob.project_id = p.id)))
     LEFT JOIN left_after_final lf ON ((lf.project_id = p.id)))
     LEFT JOIN bal ON ((bal.project_id = p.id)))
     LEFT JOIN exc ON ((exc.project_id = p.id)))
     LEFT JOIN public.external_links xi ON (((xi.provider = 'XERO'::text) AND (xi.entity_type = 'invoice'::text) AND (xi.external_type = 'Invoice'::text) AND (xi.entity_id = fi.invoice_id) AND (xi.verified_at IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
           FROM public.invoice_xero_draft_generations g
          WHERE ((g.invoice_id = fi.invoice_id) AND (g.superseded_at IS NULL) AND ((g.status <> 'CREATED'::text) OR (g.xero_invoice_id IS DISTINCT FROM xi.external_id)))))))))
     LEFT JOIN public.external_links drive ON (((drive.provider = 'GOOGLE_DRIVE'::text) AND (drive.entity_type = 'project'::text) AND (drive.external_type = 'Folder'::text) AND (drive.entity_id = p.id) AND (drive.verified_at IS NOT NULL))))
     LEFT JOIN public.external_links at ON (((at.provider = 'AIRTABLE'::text) AND (at.entity_type = 'project'::text) AND (at.external_type = 'Record'::text) AND (at.entity_id = p.id))))
     LEFT JOIN public.airtable_observations ao ON (((ao.table_id = 'tblvUPIoebC3zoacv'::text) AND (ao.record_id = at.external_id) AND (ao.field_id = 'fldi2Qwz1dAh2tcTE'::text))));

--
-- Name: v_dashboard_kpis; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_kpis AS
 SELECT public.app_today() AS as_of,
    count(*) FILTER (WHERE is_active) AS active_projects,
    count(*) FILTER (WHERE (is_active AND (risk_level = 'HIGH'::text))) AS projects_at_risk,
    count(*) FILTER (WHERE waiting_on_materials) AS awaiting_materials,
    count(*) FILTER (WHERE (invoice_status = 'READY_TO_INVOICE'::text)) AS ready_to_invoice,
    count(*) FILTER (WHERE (invoice_status = 'AWAITING_APPROVAL'::text)) AS awaiting_invoice_approval,
    ( SELECT count(*) AS count
           FROM public.workflow_exceptions
          WHERE (workflow_exceptions.resolution_status = ANY (ARRAY['OPEN'::text, 'RETRY_QUEUED'::text]))) AS open_exceptions
   FROM public.v_dashboard_projects;

--
-- Name: v_dashboard_leads; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_leads AS
 SELECT l.lead_number,
    l.status,
    l.source,
    l.contact_name,
    l.phone,
    l.email,
    l.property_address_text,
    l.notes,
    l.lost_reason,
    l.received_at,
    l.contacted_at,
    l.record_version,
    c.customer_number,
    c.display_name AS customer_name,
    pr.property_number,
    concat_ws(', '::text, pr.address_line1, pr.suburb, ((pr.state || ' '::text) || pr.postcode)) AS site,
    cb.full_name AS created_by_name,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('inspection_number', i.inspection_number, 'status', i.status, 'inspector', ie.full_name, 'scheduled_for', to_char((i.scheduled_for AT TIME ZONE 'Australia/Brisbane'::text), 'YYYY-MM-DD"T"HH24:MI'::text), 'inspected_on', i.inspected_on, 'roof_type', i.roof_type, 'roof_area_sqm', i.roof_area_sqm, 'pitch_degrees', i.pitch_degrees, 'measurement_method', i.measurement_method, 'findings', i.findings, 'record_version', i.record_version) ORDER BY i.created_at) AS jsonb_agg
           FROM (public.inspections i
             LEFT JOIN public.employees ie ON ((ie.id = i.inspector_id)))
          WHERE (i.lead_id = l.id)), '[]'::jsonb) AS inspections,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('quote_number', q.quote_number, 'status', q.status, 'record_version', q.record_version) ORDER BY q.created_at) AS jsonb_agg
           FROM public.quotes q
          WHERE (q.lead_id = l.id)), '[]'::jsonb) AS quotes,
    ( SELECT p.project_number
           FROM (public.quotes q
             JOIN public.projects p ON ((p.quote_id = q.id)))
          WHERE (q.lead_id = l.id)
         LIMIT 1) AS project_number
   FROM (((public.leads l
     LEFT JOIN public.customers c ON ((c.id = l.customer_id)))
     LEFT JOIN public.properties pr ON ((pr.id = l.property_id)))
     LEFT JOIN public.employees cb ON ((cb.id = l.created_by)));

--
-- Name: v_dashboard_ops_roles; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_ops_roles AS
 SELECT ( SELECT app_settings.value
           FROM public.app_settings
          WHERE (app_settings.key = 'schedule.planner_roles'::text)) AS planner_roles,
    ( SELECT app_settings.value
           FROM public.app_settings
          WHERE (app_settings.key = 'task.manager_roles'::text)) AS task_manager_roles;

--
-- Name: xero_dispatch_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.xero_dispatch_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    invoice_id uuid NOT NULL,
    generation integer NOT NULL,
    xero_key text NOT NULL,
    payload_sha256 text NOT NULL,
    requested_by uuid NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    reason text NOT NULL,
    status text DEFAULT 'QUEUED'::text NOT NULL,
    attempts_at_claim integer,
    claimed_by text,
    claimed_at timestamp with time zone,
    closed_reason text,
    CONSTRAINT xero_dispatch_requests_generation_check CHECK ((generation >= 1)),
    CONSTRAINT xero_dispatch_requests_status_check CHECK ((status = ANY (ARRAY['QUEUED'::text, 'CLAIMED'::text, 'HANDED_OVER'::text, 'REFUSED'::text, 'EXPIRED'::text])))
);

--
-- Name: TABLE xero_dispatch_requests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.xero_dispatch_requests IS 'Staff requests to send one queued xero.create_draft_invoice write; taken by n8n 09 (wf_xero_dispatch_next), which runs 05';

--
-- Name: v_dashboard_ops_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_ops_status AS
 WITH xw AS (
         SELECT o.id,
            o.topic,
            o.aggregate_type,
            o.aggregate_id,
            o.correlation_id,
            o.idempotency_key,
            o.payload,
            o.status,
            o.attempts,
            o.next_attempt_at,
            o.locked_until,
            o.last_error,
            o.created_at,
            o.dispatched_at,
            o.result,
            o.generation
           FROM public.outbox o
          WHERE ((o.topic = 'xero.create_draft_invoice'::text) AND (o.generation = ( SELECT max(x.generation) AS max
                   FROM public.outbox x
                  WHERE ((x.topic = o.topic) AND (x.aggregate_id = o.aggregate_id)))))
        ), rec AS (
         SELECT max(reconciliation_runs.finished_at) AS at
           FROM public.reconciliation_runs
          WHERE (reconciliation_runs.status = 'COMPLETED'::text)
        ), probe AS (
         SELECT max(integration_health.checked_at) AS at
           FROM public.integration_health
        ), ap AS (
         SELECT count(*) AS n,
            min(approvals.created_at) AS oldest
           FROM public.approvals
          WHERE ((approvals.status = 'PENDING'::text) AND (approvals.expires_at > now()))
        ), queued AS (
         SELECT count(*) AS n,
            min(xero_dispatch_requests.requested_at) AS oldest
           FROM public.xero_dispatch_requests
          WHERE (xero_dispatch_requests.status = 'QUEUED'::text)
        ), last_claim AS (
         SELECT max(xero_dispatch_requests.claimed_at) AS at
           FROM public.xero_dispatch_requests
        ), unsent AS (
         SELECT count(*) AS n,
            min(xw.created_at) AS oldest
           FROM (xw
             JOIN public.invoices i ON ((i.id = xw.aggregate_id)))
          WHERE ((xw.status = 'PENDING'::text) AND (i.status <> 'VOIDED'::text) AND (i.sync_status <> 'UNKNOWN'::text) AND (xw.created_at < (now() - '00:10:00'::interval)) AND (NOT (EXISTS ( SELECT 1
                   FROM public.xero_dispatch_requests r
                  WHERE ((r.xero_key = xw.idempotency_key) AND (r.status = ANY (ARRAY['QUEUED'::text, 'CLAIMED'::text])))))))
        ), stuck AS (
         SELECT count(*) AS n,
            min(xw.locked_until) AS oldest
           FROM xw
          WHERE ((xw.status = 'DISPATCHING'::text) AND (xw.locked_until < now()))
        ), unsure AS (
         SELECT count(*) AS n,
            min(invoices.updated_at) AS oldest
           FROM public.invoices
          WHERE (invoices.sync_status = 'UNKNOWN'::text)
        ), stopped AS (
         SELECT count(*) AS n,
            min(xw.created_at) AS oldest
           FROM xw
          WHERE ((xw.status = 'FAILED'::text) AND (xw.next_attempt_at = 'infinity'::timestamp with time zone))
        ), retrying AS (
         SELECT count(*) AS n,
            min(xw.next_attempt_at) AS oldest
           FROM xw
          WHERE ((xw.status = 'FAILED'::text) AND (xw.next_attempt_at <> 'infinity'::timestamp with time zone))
        ), exc AS (
         SELECT count(*) AS n,
            min(workflow_exceptions.first_failed_at) AS oldest
           FROM public.workflow_exceptions
          WHERE (workflow_exceptions.resolution_status = ANY (ARRAY['OPEN'::text, 'RETRY_QUEUED'::text]))
        )
 SELECT 1 AS ord,
    'reconciliation'::text AS key,
    'Last full check of Airtable, Drive and Xero (nightly)'::text AS label,
        CASE
            WHEN (rec.at IS NULL) THEN 'unknown'::text
            WHEN (rec.at < (now() - '26:00:00'::interval)) THEN 'stale'::text
            ELSE 'ok'::text
        END AS state,
    NULL::bigint AS count,
    rec.at AS since,
        CASE
            WHEN (rec.at IS NULL) THEN 'No full check has completed yet'::text
            WHEN (rec.at < (now() - '26:00:00'::interval)) THEN 'The nightly check is overdue'::text
            ELSE 'Completed on schedule'::text
        END AS detail
   FROM rec
UNION ALL
 SELECT 2 AS ord,
    'health_probe'::text AS key,
    'Last automatic health check (every 30 minutes)'::text AS label,
        CASE
            WHEN (probe.at IS NULL) THEN 'unknown'::text
            WHEN (probe.at < (now() - '00:45:00'::interval)) THEN 'stale'::text
            ELSE 'ok'::text
        END AS state,
    NULL::bigint AS count,
    probe.at AS since,
        CASE
            WHEN (probe.at IS NULL) THEN 'No health check has run yet'::text
            WHEN (probe.at < (now() - '00:45:00'::interval)) THEN 'Overdue: the automation engine may be down'::text
            ELSE 'Running'::text
        END AS detail
   FROM probe
UNION ALL
 SELECT 3 AS ord,
    'approvals'::text AS key,
    'Invoices and reissues waiting for approval'::text AS label,
        CASE
            WHEN (ap.n = 0) THEN 'ok'::text
            WHEN (ap.oldest < (now() - '48:00:00'::interval)) THEN 'attention'::text
            ELSE 'info'::text
        END AS state,
    ap.n AS count,
    ap.oldest AS since,
        CASE
            WHEN (ap.n = 0) THEN 'Nothing waiting'::text
            WHEN (ap.oldest < (now() - '48:00:00'::interval)) THEN 'One has waited more than 2 days'::text
            ELSE 'Waiting for a second person'::text
        END AS detail
   FROM ap
UNION ALL
 SELECT 4 AS ord,
    'xero_queue'::text AS key,
    'Xero drafts waiting for automation to pick them up'::text AS label,
        CASE
            WHEN (queued.n = 0) THEN 'ok'::text
            WHEN ((queued.oldest < (now() - '00:05:00'::interval)) AND ((last_claim.at IS NULL) OR (last_claim.at < (now() - '00:05:00'::interval)))) THEN 'problem'::text
            ELSE 'info'::text
        END AS state,
    queued.n AS count,
    queued.oldest AS since,
        CASE
            WHEN (queued.n = 0) THEN 'Nothing waiting'::text
            WHEN ((queued.oldest < (now() - '00:05:00'::interval)) AND ((last_claim.at IS NULL) OR (last_claim.at < (now() - '00:05:00'::interval)))) THEN 'Nothing picked up for over 5 minutes: the staff dispatch automation (n8n 09) may be off'::text
            ELSE 'Sent one a minute, oldest first'::text
        END AS detail
   FROM queued,
    last_claim
UNION ALL
 SELECT 5 AS ord,
    'xero_unsent'::text AS key,
    'Approved invoices not sent to Xero'::text AS label,
        CASE
            WHEN (unsent.n = 0) THEN 'ok'::text
            ELSE 'attention'::text
        END AS state,
    unsent.n AS count,
    unsent.oldest AS since,
        CASE
            WHEN (unsent.n = 0) THEN 'None'::text
            ELSE 'Approved, but no request to send them is waiting (it was refused or never picked up). Finance → Xero drafts says why; a Finance or Admin person sends them'::text
        END AS detail
   FROM unsent
UNION ALL
 SELECT 6 AS ord,
    'xero_stuck'::text AS key,
    'Xero drafts stuck while being created'::text AS label,
        CASE
            WHEN (stuck.n = 0) THEN 'ok'::text
            ELSE 'problem'::text
        END AS state,
    stuck.n AS count,
    stuck.oldest AS since,
        CASE
            WHEN (stuck.n = 0) THEN 'None'::text
            ELSE 'A creation started and never reported back; reconciliation checks Xero'::text
        END AS detail
   FROM stuck
UNION ALL
 SELECT 7 AS ord,
    'xero_uncertain'::text AS key,
    'Xero drafts with an unclear outcome'::text AS label,
        CASE
            WHEN (unsure.n = 0) THEN 'ok'::text
            ELSE 'problem'::text
        END AS state,
    unsure.n AS count,
    unsure.oldest AS since,
        CASE
            WHEN (unsure.n = 0) THEN 'None'::text
            ELSE 'Xero may or may not have them; they are not sent again until reconciliation answers'::text
        END AS detail
   FROM unsure
UNION ALL
 SELECT 8 AS ord,
    'xero_stopped'::text AS key,
    'Xero drafts stopped after repeated failures'::text AS label,
        CASE
            WHEN (stopped.n = 0) THEN 'ok'::text
            ELSE 'problem'::text
        END AS state,
    stopped.n AS count,
    stopped.oldest AS since,
        CASE
            WHEN (stopped.n = 0) THEN 'None'::text
            ELSE 'See the issue on Automation'::text
        END AS detail
   FROM stopped
UNION ALL
 SELECT 9 AS ord,
    'xero_retrying'::text AS key,
    'Xero drafts that failed and can be sent again'::text AS label,
        CASE
            WHEN (retrying.n = 0) THEN 'ok'::text
            ELSE 'attention'::text
        END AS state,
    retrying.n AS count,
    retrying.oldest AS since,
        CASE
            WHEN (retrying.n = 0) THEN 'None'::text
            ELSE 'Finance → Xero drafts shows the reason and when to retry'::text
        END AS detail
   FROM retrying
UNION ALL
 SELECT 10 AS ord,
    'exceptions'::text AS key,
    'Issues waiting for a person'::text AS label,
        CASE
            WHEN (exc.n = 0) THEN 'ok'::text
            WHEN (exc.oldest < (now() - '7 days'::interval)) THEN 'attention'::text
            ELSE 'info'::text
        END AS state,
    exc.n AS count,
    exc.oldest AS since,
        CASE
            WHEN (exc.n = 0) THEN 'None'::text
            ELSE 'See Automation'::text
        END AS detail
   FROM exc;

--
-- Name: v_dashboard_pre_start_blocked; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_pre_start_blocked AS
 SELECT p.project_number,
    c.display_name AS customer_name,
    p.status,
    p.planned_start_date,
    e.full_name AS project_manager,
    array_agg(ci.label ORDER BY ci.sort_order) AS open_items
   FROM (((public.projects p
     JOIN public.customers c ON ((c.id = p.customer_id)))
     JOIN public.project_checklist_items ci ON (((ci.project_id = p.id) AND (ci.stage = 'PRE_START'::text) AND ci.is_required AND (ci.status <> ALL (ARRAY['DONE'::text, 'WAIVED'::text, 'NOT_APPLICABLE'::text])))))
     LEFT JOIN public.employees e ON ((e.id = p.project_manager_id)))
  WHERE ((p.actual_start_date IS NULL) AND (p.status = ANY (ARRAY['PLANNING'::text, 'MATERIALS_PENDING'::text, 'SCHEDULED'::text, 'ON_HOLD'::text])))
  GROUP BY p.project_number, c.display_name, p.status, p.planned_start_date, e.full_name;

--
-- Name: v_dashboard_products; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_products AS
 SELECT product_code,
    name,
    category,
    unit
   FROM public.products
  WHERE is_active;

--
-- Name: v_dashboard_project_checklist; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_project_checklist AS
 SELECT p.project_number,
    'CHECKLIST'::text AS kind,
    ci.stage,
    ci.label AS title,
        CASE
            WHEN (ci.status <> 'OPEN'::text) THEN ci.status
            WHEN ((ci.item_code = 'MATERIALS_REVIEWED'::text) AND (mr.completed_on IS NOT NULL) AND (p.actual_start_date IS NOT NULL)) THEN 'DONE'::text
            WHEN ((ci.item_code = 'FINAL_INVOICE_APPROVED'::text) AND (fa.decided_on IS NOT NULL)) THEN 'DONE'::text
            ELSE ci.status
        END AS status,
    ci.is_required,
    COALESCE(ci.completed_on,
        CASE
            WHEN ((ci.item_code = 'MATERIALS_REVIEWED'::text) AND (p.actual_start_date IS NOT NULL)) THEN mr.completed_on
            WHEN (ci.item_code = 'FINAL_INVOICE_APPROVED'::text) THEN fa.decided_on
            ELSE NULL::date
        END) AS done_on,
    NULL::date AS due_on,
    NULL::text AS assignee,
    ci.sort_order
   FROM (((public.project_checklist_items ci
     JOIN public.projects p ON ((p.id = ci.project_id)))
     LEFT JOIN LATERAL ( SELECT (max(COALESCE(t.completed_at, t.updated_at)))::date AS completed_on
           FROM public.tasks t
          WHERE ((t.project_id = p.id) AND (t.task_type = 'MATERIAL_REVIEW'::text) AND (t.status = 'DONE'::text) AND (NOT (EXISTS ( SELECT 1
                   FROM public.tasks o
                  WHERE ((o.project_id = p.id) AND (o.task_type = 'MATERIAL_REVIEW'::text) AND (o.status = ANY (ARRAY['OPEN'::text, 'IN_PROGRESS'::text])))))))) mr ON (true))
     LEFT JOIN LATERAL ( SELECT (max(a.decided_at))::date AS decided_on
           FROM (public.invoices i
             JOIN public.approvals a ON ((a.id = i.approval_id)))
          WHERE ((i.project_id = p.id) AND (i.invoice_type = 'FINAL'::text) AND (i.status <> 'VOIDED'::text) AND (a.status = ANY (ARRAY['EXECUTING'::text, 'EXECUTED'::text])))) fa ON (true))
UNION ALL
 SELECT p.project_number,
    'TASK'::text AS kind,
    t.task_type AS stage,
    t.title,
    t.status,
    true AS is_required,
    NULL::date AS done_on,
    t.due_on,
    e.full_name AS assignee,
    0 AS sort_order
   FROM ((public.tasks t
     JOIN public.projects p ON ((p.id = t.project_id)))
     LEFT JOIN public.employees e ON ((e.id = t.assignee_id)));

--
-- Name: v_dashboard_project_timeline; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_project_timeline AS
 WITH refs AS (
         SELECT p.project_number,
            q.quote_number,
            (((ARRAY[p.id, p.quote_id] || COALESCE(( SELECT array_agg(i.id) AS array_agg
                   FROM public.invoices i
                  WHERE (i.project_id = p.id)), '{}'::uuid[])) || COALESCE(( SELECT array_agg(a.id) AS array_agg
                   FROM public.approvals a
                  WHERE (a.entity_id = p.id)), '{}'::uuid[])) || COALESCE(( SELECT array_agg(t.id) AS array_agg
                   FROM public.tasks t
                  WHERE (t.project_id = p.id)), '{}'::uuid[])) AS ids,
            ((ARRAY[p.project_number, q.quote_number] || COALESCE(( SELECT array_agg(i.invoice_number) AS array_agg
                   FROM public.invoices i
                  WHERE (i.project_id = p.id)), '{}'::text[])) || COALESCE(( SELECT array_agg(a.approval_number) AS array_agg
                   FROM public.approvals a
                  WHERE (a.entity_id = p.id)), '{}'::text[])) AS numbers
           FROM (public.projects p
             JOIN public.quotes q ON ((q.id = p.quote_id)))
        )
 SELECT r.project_number,
    'EVENT'::text AS source,
    ae.occurred_at,
    ae.event_type AS kind,
    ae.status,
    ae.error_class,
    COALESCE(emp.full_name, eemp.full_name, ae.actor_id) AS actor,
    ae.business_reference AS reference,
    (ae.metadata ->> 'reason'::text) AS reason,
    ae.external_reference,
    ae.source AS channel
   FROM ((((refs r
     JOIN public.automation_events ae ON (((ae.entity_id = ANY (r.ids)) OR (ae.business_reference = ANY (r.numbers)))))
     LEFT JOIN public.employees emp ON ((emp.employee_code = ae.actor_id)))
     LEFT JOIN public.employee_external_identities ei ON ((ei.external_id = ae.actor_id)))
     LEFT JOIN public.employees eemp ON ((eemp.id = ei.employee_id)))
UNION ALL
 SELECT r.project_number,
    'AUDIT'::text AS source,
    au.occurred_at,
    au.action AS kind,
    NULL::text AS status,
    NULL::text AS error_class,
    COALESCE(emp.full_name, eemp.full_name, au.actor_display, au.actor_id) AS actor,
    au.business_reference AS reference,
    au.reason,
    au.external_reference,
    au.actor_type AS channel
   FROM ((((refs r
     JOIN public.audit_events au ON (((au.entity_id = ANY (r.ids)) OR (au.business_reference = ANY (r.numbers)))))
     LEFT JOIN public.employees emp ON ((emp.employee_code = au.actor_id)))
     LEFT JOIN public.employee_external_identities ei ON ((ei.external_id = au.actor_id)))
     LEFT JOIN public.employees eemp ON ((eemp.id = ei.employee_id)));

--
-- Name: v_dashboard_quotes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_quotes AS
 SELECT q.quote_number,
    q.status,
    q.job_type,
    q.created_on,
    q.sent_on,
    q.valid_until,
    q.accepted_on,
    q.lost_reason,
    q.record_version,
    l.lead_number,
    c.customer_number,
    c.display_name AS customer_name,
    pr.property_number,
    concat_ws(', '::text, pr.address_line1, pr.suburb, ((pr.state || ' '::text) || pr.postcode)) AS site,
    e.full_name AS estimator,
    qv.version_number,
    qv.line_amount_type,
    qv.subtotal_ex_gst,
    qv.gst_amount,
    qv.total_inc_gst,
    qv.scope_summary,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('line_no', ln.line_no, 'line_kind', ln.line_kind, 'product_code', pd.product_code, 'description', ln.description, 'quantity', ln.quantity, 'unit', ln.unit, 'unit_price', ln.unit_price, 'line_amount', ln.line_amount) ORDER BY ln.line_no) AS jsonb_agg
           FROM (public.quote_version_lines ln
             LEFT JOIN public.products pd ON ((pd.id = ln.product_id)))
          WHERE (ln.quote_version_id = qv.id)), '[]'::jsonb) AS lines,
    ( SELECT
                CASE
                    WHEN ((o.status = 'FAILED'::text) AND (o.next_attempt_at = 'infinity'::timestamp with time zone)) THEN 'STOPPED'::text
                    WHEN (o.status = 'FAILED'::text) THEN 'RETRYING'::text
                    ELSE o.status
                END AS status
           FROM public.outbox o
          WHERE ((o.topic = 'airtable.quote_publish'::text) AND (o.aggregate_id = q.id))
          ORDER BY COALESCE((((o.payload -> 'quote_fields'::text) ->> 'fldEjEqlzE8Y0M1nf'::text))::integer, 0) DESC, o.created_at DESC, o.id DESC
         LIMIT 1) AS airtable_handoff,
    ( SELECT o.last_error
           FROM public.outbox o
          WHERE ((o.topic = 'airtable.quote_publish'::text) AND (o.aggregate_id = q.id))
          ORDER BY COALESCE((((o.payload -> 'quote_fields'::text) ->> 'fldEjEqlzE8Y0M1nf'::text))::integer, 0) DESC, o.created_at DESC, o.id DESC
         LIMIT 1) AS airtable_handoff_error,
    ((EXISTS ( SELECT 1
           FROM public.external_links x
          WHERE ((x.provider = 'AIRTABLE'::text) AND (x.entity_type = 'quote'::text) AND (x.entity_id = q.id) AND (x.verified_at IS NOT NULL)))) AND (COALESCE(( SELECT o.status
           FROM public.outbox o
          WHERE ((o.topic = 'airtable.quote_publish'::text) AND (o.aggregate_id = q.id))
          ORDER BY COALESCE((((o.payload -> 'quote_fields'::text) ->> 'fldEjEqlzE8Y0M1nf'::text))::integer, 0) DESC, o.created_at DESC, o.id DESC
         LIMIT 1), 'DONE'::text) = 'DONE'::text)) AS in_airtable,
    ( SELECT p.project_number
           FROM public.projects p
          WHERE (p.quote_id = q.id)) AS project_number
   FROM (((((public.quotes q
     JOIN public.customers c ON ((c.id = q.customer_id)))
     JOIN public.properties pr ON ((pr.id = q.property_id)))
     JOIN LATERAL ( SELECT v.id,
            v.quote_id,
            v.version_number,
            v.line_amount_type,
            v.gst_rate,
            v.subtotal_ex_gst,
            v.gst_amount,
            v.total_inc_gst,
            v.scope_summary,
            v.created_by,
            v.created_at
           FROM public.quote_versions v
          WHERE (v.quote_id = q.id)
          ORDER BY v.version_number DESC
         LIMIT 1) qv ON (true))
     LEFT JOIN public.leads l ON ((l.id = q.lead_id)))
     LEFT JOIN public.employees e ON ((e.id = q.estimator_id)));

--
-- Name: v_dashboard_sales_roles; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_sales_roles AS
 SELECT ( SELECT app_settings.value
           FROM public.app_settings
          WHERE (app_settings.key = 'sales.roles'::text)) AS sales_roles,
    ( SELECT app_settings.value
           FROM public.app_settings
          WHERE (app_settings.key = 'customer.correction_roles'::text)) AS correction_roles;

--
-- Name: v_dashboard_site_visits; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_site_visits AS
 SELECT j.job_number,
    p.project_number,
    c.display_name AS customer_name,
    concat_ws(', '::text, pr.address_line1, pr.suburb) AS site,
    pm.full_name AS project_manager,
    j.job_type,
    j.status,
    j.scheduled_start,
    j.scheduled_end,
    j.actual_start,
    j.actual_end,
    j.notes,
    j.status_reason,
    j.record_version,
    ((j.scheduled_start AT TIME ZONE 'Australia/Brisbane'::text))::date AS visit_date,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('code', e.employee_code, 'name', e.full_name, 'crew_role', a.crew_role) ORDER BY (a.crew_role = 'LEADING_HAND'::text) DESC, e.full_name) AS jsonb_agg
           FROM (public.job_assignments a
             JOIN public.employees e ON ((e.id = a.employee_id)))
          WHERE (a.job_id = j.id)), '[]'::jsonb) AS crew
   FROM (((((public.jobs j
     JOIN public.projects p ON ((p.id = j.project_id)))
     JOIN public.customers c ON ((c.id = p.customer_id)))
     LEFT JOIN public.quotes q ON ((q.id = p.quote_id)))
     LEFT JOIN public.properties pr ON ((pr.id = q.property_id)))
     LEFT JOIN public.employees pm ON ((pm.id = p.project_manager_id)));

--
-- Name: v_dashboard_staff; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_staff AS
 SELECT employee_code,
    full_name,
    role
   FROM public.employees
  WHERE (is_active AND (role <> 'VIEWER'::text));

--
-- Name: v_dashboard_tasks; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dashboard_tasks AS
 SELECT t.task_number,
    p.project_number,
    t.task_type,
    t.title,
    t.description,
    t.status,
    t.due_on,
    t.status_note,
    t.record_version,
    ae.employee_code AS assignee_code,
    ae.full_name AS assignee_name,
    ce.full_name AS created_by_name,
    t.created_at,
    t.completed_at,
    ((t.status = ANY (ARRAY['OPEN'::text, 'IN_PROGRESS'::text])) AND (t.due_on < public.app_today())) AS overdue
   FROM (((public.tasks t
     LEFT JOIN public.projects p ON ((p.id = t.project_id)))
     LEFT JOIN public.employees ae ON ((ae.id = t.assignee_id)))
     LEFT JOIN public.employees ce ON ((ce.id = t.created_by)))
  WHERE (t.task_number IS NOT NULL);

--
-- Name: v_quote_conversion; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_quote_conversion AS
 SELECT COALESCE(lead_source, 'ALL'::text) AS lead_source,
    count(*) FILTER (WHERE (status = 'ACCEPTED'::text)) AS accepted,
    count(*) FILTER (WHERE (status = 'LOST'::text)) AS lost,
    count(*) FILTER (WHERE (status = 'EXPIRED'::text)) AS expired,
    count(*) FILTER (WHERE (status = ANY (ARRAY['DRAFT'::text, 'SENT'::text]))) AS open,
    round(((count(*) FILTER (WHERE (status = 'ACCEPTED'::text)))::numeric / (NULLIF(count(*) FILTER (WHERE (status = ANY (ARRAY['ACCEPTED'::text, 'LOST'::text, 'EXPIRED'::text]))), 0))::numeric), 4) AS conversion_rate
   FROM public.quotes q
  GROUP BY GROUPING SETS ((lead_source), ());

--
-- Name: v_executive_kpis; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_executive_kpis AS
 SELECT public.app_today() AS as_of,
    ( SELECT count(*) AS count
           FROM public.projects
          WHERE (projects.status <> ALL (ARRAY['COMPLETED'::text, 'CLOSED'::text, 'CANCELLED'::text]))) AS active_projects,
    ( SELECT count(*) AS count
           FROM public.quotes
          WHERE (quotes.status = 'SENT'::text)) AS quotes_awaiting_decision,
    ( SELECT v_quote_conversion.conversion_rate
           FROM public.v_quote_conversion
          WHERE (v_quote_conversion.lead_source = 'ALL'::text)) AS quote_conversion_rate,
    ( SELECT count(*) AS count
           FROM public.v_project_risk
          WHERE (v_project_risk.is_active AND (v_project_risk.risk_level = 'HIGH'::text))) AS projects_at_risk,
    ( SELECT count(*) AS count
           FROM public.v_project_risk
          WHERE v_project_risk.is_delayed) AS projects_delayed,
    ( SELECT count(DISTINCT v_projects_waiting_on_materials.project_number) AS count
           FROM public.v_projects_waiting_on_materials) AS projects_waiting_on_materials,
    ( SELECT COALESCE(sum(purchase_orders.total_inc_gst), (0)::numeric) AS "coalesce"
           FROM public.purchase_orders
          WHERE (purchase_orders.status = ANY (ARRAY['APPROVED'::text, 'SENT'::text, 'ACKNOWLEDGED'::text, 'PARTIALLY_DELIVERED'::text]))) AS open_po_value_inc_gst,
    ( SELECT count(*) AS count
           FROM public.v_invoice_balances
          WHERE v_invoice_balances.is_overdue) AS overdue_invoices,
    ( SELECT COALESCE(sum(v_invoice_balances.outstanding), (0)::numeric) AS "coalesce"
           FROM public.v_invoice_balances
          WHERE v_invoice_balances.is_overdue) AS overdue_amount,
    ( SELECT count(*) AS count
           FROM public.workflow_exceptions
          WHERE (workflow_exceptions.resolution_status = ANY (ARRAY['OPEN'::text, 'RETRY_QUEUED'::text]))) AS open_automation_exceptions,
    ( SELECT count(*) AS count
           FROM public.v_accepted_quotes_without_project) AS accepted_quotes_without_project;

--
-- Name: v_integration_activity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_integration_activity AS
 SELECT automation_events.source AS channel,
    max(automation_events.recorded_at) AS last_event_at,
    (count(*) FILTER (WHERE (automation_events.recorded_at > (now() - '24:00:00'::interval))))::integer AS events_24h,
    (count(*) FILTER (WHERE ((automation_events.recorded_at > (now() - '24:00:00'::interval)) AND (automation_events.status = ANY (ARRAY['FAILED'::text, 'REJECTED'::text])))))::integer AS problems_24h
   FROM public.automation_events
  WHERE (automation_events.source = ANY (ARRAY['airtable'::text, 'reconciler'::text, 'roofops-dashboard'::text]))
  GROUP BY automation_events.source
UNION ALL
 SELECT 'airtable-pings'::text AS channel,
    max(airtable_ping_checks.checked_at) AS last_event_at,
    (count(*) FILTER (WHERE (airtable_ping_checks.checked_at > (now() - '24:00:00'::interval))))::integer AS events_24h,
    (count(*) FILTER (WHERE ((airtable_ping_checks.checked_at > (now() - '24:00:00'::interval)) AND (airtable_ping_checks.verdict <> 'VALID'::text))))::integer AS problems_24h
   FROM public.airtable_ping_checks
 HAVING (count(*) > 0);

--
-- Name: v_open_duplicate_customers; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_open_duplicate_customers AS
 SELECT m.id,
    a.customer_number AS customer_a,
    b.customer_number AS customer_b,
    m.match_score,
    m.match_reasons
   FROM ((public.customer_match_candidates m
     JOIN public.customers a ON ((a.id = m.customer_id)))
     JOIN public.customers b ON ((b.id = m.candidate_customer_id)))
  WHERE (m.status = 'OPEN'::text);

