   FROM (public.projects p
     JOIN public.project_checklist_items ci ON ((ci.project_id = p.id)))
  WHERE ((p.status = ANY (ARRAY['COMPLETED'::text, 'CLOSED'::text])) AND (ci.stage = 'COMPLETION'::text) AND ci.is_required AND (ci.status <> ALL (ARRAY['DONE'::text, 'WAIVED'::text, 'NOT_APPLICABLE'::text])));

