--
-- Name: v_reconciliation_findings_latest; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_reconciliation_findings_latest AS
 SELECT system,
    entity_type,
    entity_ref,
    external_id,
    field,
    expected,
    actual,
    classification,
    action,
    detail,
    created_at
   FROM public.reconciliation_findings f
  WHERE (run_id = ( SELECT reconciliation_runs.id
           FROM public.reconciliation_runs
          WHERE (reconciliation_runs.status = 'COMPLETED'::text)
          ORDER BY reconciliation_runs.finished_at DESC
         LIMIT 1));

--
-- Name: v_reconciliation_latest; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_reconciliation_latest AS
 SELECT run_key,
    trigger,
    mode,
    status,
    started_at,
    finished_at,
    summary,
    ( SELECT count(*) AS count
           FROM public.reconciliation_findings f
          WHERE (f.run_id = r.id)) AS findings,
    ( SELECT count(*) AS count
           FROM public.reconciliation_findings f
          WHERE ((f.run_id = r.id) AND (f.classification = ANY (ARRAY['REQUIRES_HUMAN'::text, 'EXTERNAL_MISSING'::text, 'UNKNOWN'::text])))) AS needs_person
   FROM public.reconciliation_runs r
  WHERE (status = 'COMPLETED'::text)
  ORDER BY finished_at DESC
 LIMIT 1;

--
-- Name: v_system_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_system_health AS
 WITH latest AS (
         SELECT DISTINCT ON (integration_health.service) integration_health.service,
            integration_health.ok,
            integration_health.latency_ms,
            integration_health.detail,
            integration_health.checked_at
           FROM public.integration_health
          ORDER BY integration_health.service, integration_health.checked_at DESC
        ), last_ok AS (
         SELECT integration_health.service,
            max(integration_health.checked_at) AS last_ok_at
           FROM public.integration_health
          WHERE integration_health.ok
          GROUP BY integration_health.service
        ), fails AS (
         SELECT h.service,
            count(*) AS consecutive_failures
           FROM public.integration_health h
          WHERE ((NOT h.ok) AND (h.checked_at > COALESCE(( SELECT max(o_1.checked_at) AS max
                   FROM public.integration_health o_1
                  WHERE ((o_1.service = h.service) AND o_1.ok)), '-infinity'::timestamp with time zone)))
          GROUP BY h.service
        )
 SELECT s.service,
    l.ok,
    l.latency_ms,
    l.detail,
    l.checked_at,
    o.last_ok_at,
    COALESCE(f.consecutive_failures, (0)::bigint) AS consecutive_failures,
    (EXTRACT(epoch FROM (now() - l.checked_at)))::integer AS age_seconds
   FROM (((( VALUES ('postgres'::text), ('airtable'::text), ('airtable_webhooks'::text), ('n8n'::text), ('google_drive'::text), ('xero'::text), ('deepseek'::text)) s(service)
     LEFT JOIN latest l ON ((l.service = s.service)))
     LEFT JOIN last_ok o ON ((o.service = s.service)))
     LEFT JOIN fails f ON ((f.service = s.service)));

