-- Name: variations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.variations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    variation_number text NOT NULL,
    project_id uuid NOT NULL,
    description text NOT NULL,
    amount_inc_gst numeric(12,2) NOT NULL,
    status text DEFAULT 'PROPOSED'::text NOT NULL,
    customer_approved_at timestamp with time zone,
    approved_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    record_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT variations_check CHECK (((status <> ALL (ARRAY['APPROVED'::text, 'INVOICED'::text])) OR ((customer_approved_at IS NOT NULL) AND (approved_by IS NOT NULL)))),
    CONSTRAINT variations_status_check CHECK ((status = ANY (ARRAY['PROPOSED'::text, 'APPROVED'::text, 'REJECTED'::text, 'INVOICED'::text])))
);

--
-- Name: workflow_run_steps; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_run_steps (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid NOT NULL,
    attempt integer NOT NULL,
    seq integer NOT NULL,
    step_key text NOT NULL,
    status text NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    http_status integer,
    error_class text,
    retry_delay_ms integer,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT workflow_run_steps_attempt_check CHECK ((attempt >= 1)),
    CONSTRAINT workflow_run_steps_status_check CHECK ((status = ANY (ARRAY['STARTED'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'SKIPPED'::text])))
);

--
-- Name: workflow_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workflow_key text NOT NULL,
    workflow_version text NOT NULL,
    runner text NOT NULL,
    trigger_event_id uuid,
    correlation_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    entity_type text,
    entity_id uuid,
    business_reference text,
    status text DEFAULT 'QUEUED'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    next_attempt_at timestamp with time zone,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    last_error_class text,
    last_error_message text,
    output jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    record_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT workflow_runs_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT workflow_runs_check CHECK ((attempt_count <= max_attempts)),
    CONSTRAINT workflow_runs_check1 CHECK (((status <> 'RETRY_SCHEDULED'::text) OR (next_attempt_at IS NOT NULL))),
    CONSTRAINT workflow_runs_check2 CHECK (((finished_at IS NULL) OR (started_at IS NULL) OR (finished_at >= started_at))),
    CONSTRAINT workflow_runs_max_attempts_check CHECK ((max_attempts >= 1)),
    CONSTRAINT workflow_runs_runner_check CHECK ((runner = ANY (ARRAY['LOCAL'::text, 'N8N'::text]))),
    CONSTRAINT workflow_runs_status_check CHECK ((status = ANY (ARRAY['QUEUED'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'RETRY_SCHEDULED'::text, 'FAILED'::text, 'DEAD_LETTERED'::text, 'CANCELLED'::text])))
);

